  PRIMARY KEY (`id`),
  KEY `article_views_article_id_ip_address_index` (`article_id`,`ip_address`),
  CONSTRAINT `article_views_article_id_foreign` FOREIGN KEY (`article_id`) REFERENCES `articles` (`id`) ON DELETE CASCADE
