-- ----------------------------
-- Table structure for articles
-- ----------------------------
DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `source_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `summary` text DEFAULT NULL,
  `content` longtext NOT NULL,
  `image_url` varchar(191) DEFAULT NULL,
  `image_path` varchar(191) DEFAULT NULL,
  `image_alt` varchar(191) DEFAULT NULL,
  `thumbnail_path` varchar(191) DEFAULT NULL,
  `original_url` varchar(191) NOT NULL,
  `author` varchar(191) DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `views_count` int(11) NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_published` tinyint(1) NOT NULL DEFAULT 1,
  `ai_confidence_score` double(8,2) DEFAULT NULL,
  `ai_metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`ai_metadata`)),
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `articles_slug_unique` (`slug`),
  UNIQUE KEY `articles_original_url_unique` (`original_url`),
  KEY `articles_category_id_index` (`category_id`),
  KEY `articles_source_id_index` (`source_id`),
  KEY `articles_published_at_index` (`published_at`),
  KEY `articles_is_featured_index` (`is_featured`),
  FULLTEXT KEY `articles_title_content_fulltext` (`title`,`content`),
  CONSTRAINT `articles_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `articles_source_id_foreign` FOREIGN KEY (`source_id`) REFERENCES `sources` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=193 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ----------------------------
-- Records of articles
-- ----------------------------
INSERT INTO `articles` (`id`, `category_id`, `source_id`, `title`, `slug`, `summary`, `content`, `image_url`, `image_path`, `image_alt`, `thumbnail_path`, `original_url`, `author`, `published_at`, `views_count`, `is_featured`, `is_published`, `ai_confidence_score`, `ai_metadata`, `tags`, `created_at`, `updated_at`) VALUES
('100', '8', '1', 'Việt Nam sẽ đào tạo 5.000 nhân lực phát triển trò chơi điện tử giáo dục lịch sử', 'viet-nam-se-dao-tao-5000-nhan-luc-phat-trien-tro-choi-dien-tu-giao-duc-lich-su', 'Phó thủ tướng Nguyễn Hòa Bình cho biết Chính phủ sẽ tổ chức chương trình đào tạo chuyên sâu 5.000 nhân lực phát triển trò chơi điện tử phục vụ giáo dục lịch sử Việt Nam.', 'Phó thủ tướng Nguyễn Hòa Bình cho biết Chính phủ sẽ tổ chức chương trình đào tạo chuyên sâu 5.000 nhân lực phát triển trò chơi điện tử phục vụ giáo dục lịch sử Việt Nam.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/2473888839144139162-1772003722-2045-4497-1772004088.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=RQmQ76LX1RzFzy2Z_1LsWA', NULL, NULL, NULL, 'https://vnexpress.net/viet-nam-se-dao-tao-5-000-nhan-luc-phat-trien-tro-choi-dien-tu-giao-duc-lich-su-5043966.html', NULL, '2026-02-25 17:06:05', '0', '0', '0', '0.4', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Gi\\u00e1o D\\u1ee5c\":8,\"Th\\u1eddi S\\u1ef1\":3,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:27', '2026-02-25 10:06:27'),
('101', '5', '1', 'Công ty mẹ TikTok được định giá 550 tỷ USD', 'cong-ty-me-tiktok-duoc-dinh-gia-550-ty-usd', 'General Atlantic đang bán cổ phần tại ByteDance, định giá công ty mẹ TikTok ở mức 550 tỷ USD.', 'General Atlantic đang bán cổ phần tại ByteDance, định giá công ty mẹ TikTok ở mức 550 tỷ USD.', 'https://i1-kinhdoanh.vnecdn.net/2026/02/25/bytedance-1772011676-177201171-3380-8937-1772011790.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=DV0s1khTKstT3UkuF2IS4Q', NULL, NULL, NULL, 'https://vnexpress.net/cong-ty-me-tiktok-duoc-dinh-gia-550-ty-usd-5044033.html', NULL, '2026-02-25 17:00:00', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Gi\\u1ea3i Tr\\u00ed\":4,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:27', '2026-02-25 10:06:27'),
('102', '1', '1', 'Vì sao tiền mãn kinh có thể xuất hiện ở tuổi 30?', 'vi-sao-tien-man-kinh-co-the-xuat-hien-o-tuoi-30', 'Di truyền, bệnh nền và rối loạn nội tiết có thể làm tăng nguy cơ suy buồng trứng sớm, trong khi căng thẳng, môi trường góp phần khiến triệu chứng xuất hiện từ tuổi 30.', 'Di truyền, bệnh nền và rối loạn nội tiết có thể làm tăng nguy cơ suy buồng trứng sớm, trong khi căng thẳng, môi trường góp phần khiến triệu chứng xuất hiện từ tuổi 30.', 'https://i1-suckhoe.vnecdn.net/2026/02/25/293c2a87df904005a7f6e239e26963-5310-9864-1771994701.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=3HWEntlNHyx9Csnji-b9uQ', NULL, NULL, NULL, 'https://vnexpress.net/vi-sao-tien-man-kinh-co-the-xuat-hien-o-tuoi-30-5043919.html', NULL, '2026-02-25 17:00:00', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":1,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:28', '2026-02-25 10:06:28'),
('103', '7', '1', 'Các món canh cá chua được yêu thích sau Tết', 'cac-mon-canh-ca-chua-duoc-yeu-thich-sau-tet', 'Sau những ngày Tết nhiều thịt mỡ, giò chả, mâm cơm gia đình trở nên cân bằng, nhẹ bụng hơn khi có thêm bát canh cá nấu chua thanh dịu.', 'Sau những ngày Tết nhiều thịt mỡ, giò chả, mâm cơm gia đình trở nên cân bằng, nhẹ bụng hơn khi có thêm bát canh cá nấu chua thanh dịu.', 'https://i1-giadinh.vnecdn.net/2026/02/25/5-canh-ca-nau-mang-chua-177201-4788-9397-1772013117.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=NDzi6EMJ7Kk6mEvJEVTuOA', NULL, NULL, NULL, 'https://vnexpress.net/cac-mon-canh-ca-chua-duoc-yeu-thich-sau-tet-5044058.html', NULL, '2026-02-25 16:52:27', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"S\\u1ee9c Kh\\u1ecfe\":1,\"\\u0110\\u1eddi S\\u1ed1ng\":1,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:28', '2026-02-25 10:06:28'),
('104', '1', '1', 'Con trai bầu Hiển ứng cử đại biểu Hội đồng nhân dân TP Hà Nội', 'con-trai-bau-hien-ung-cu-dai-bieu-hoi-dong-nhan-dan-tp-ha-noi', 'Đỗ Vinh Quang 31 tuổi, con trai ông Đỗ Quang Hiển, nằm trong danh sách 205 người ứng cử đại biểu HĐND TP Hà Nội nhiệm kỳ 2026-2031.', 'Đỗ Vinh Quang 31 tuổi, con trai ông Đỗ Quang Hiển, nằm trong danh sách 205 người ứng cử đại biểu HĐND TP Hà Nội nhiệm kỳ 2026-2031.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/oVinhQuang-1772010815-4274-1772011067.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=jIZrZI3uX0STmoPqtixFAQ', NULL, NULL, NULL, 'https://vnexpress.net/con-trai-bau-hien-ung-cu-dai-bieu-hoi-dong-nhan-dan-tp-ha-noi-5044030.html', NULL, '2026-02-25 16:42:34', '0', '0', '0', '0.15', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":3,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:28', '2026-02-25 10:06:28'),
('105', '1', '1', 'Công ty tài sản số liên quan VPBank sắp tăng vốn lên 10.000 tỷ đồng', 'cong-ty-tai-san-so-lien-quan-vpbank-sap-tang-von-len-10000-ty-dong', 'CAEX, công ty tài sản số liên quan VPBank, đang hoàn tất thủ tục nâng vốn lên 10.000 tỷ đồng để đủ điều kiện thí điểm sàn giao dịch.', 'CAEX, công ty tài sản số liên quan VPBank, đang hoàn tất thủ tục nâng vốn lên 10.000 tỷ đồng để đủ điều kiện thí điểm sàn giao dịch.', 'https://i1-kinhdoanh.vnecdn.net/2026/02/25/KCM0011412091681787249-1772006-6798-7006-1772006682.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=Gpy4eBYymIQLhLMVLy5KXQ', NULL, NULL, NULL, 'https://vnexpress.net/cong-ty-tai-san-so-lien-quan-vpbank-sap-tang-von-len-10-000-ty-dong-5043996.html', NULL, '2026-02-25 16:38:29', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:28', '2026-02-25 10:06:28'),
('106', '1', '1', 'F-16 Thổ Nhĩ Kỳ lao xuống cao tốc, phát nổ', 'f-16-tho-nhi-ky-lao-xuong-cao-toc-phat-no', 'Tiêm kích F-16 gặp nạn ngay sau khi cất cánh ở miền tây Thổ Nhĩ Kỳ, khiến phi công thiệt mạng.', 'Tiêm kích F-16 gặp nạn ngay sau khi cất cánh ở miền tây Thổ Nhĩ Kỳ, khiến phi công thiệt mạng.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/5563187178137269083a-177200977-9548-7360-1772012100.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=hPZd5KwvFj_AGa-c3uFQmw', NULL, NULL, NULL, 'https://vnexpress.net/f-16-tho-nhi-ky-lao-xuong-cao-toc-phat-no-5044028.html', NULL, '2026-02-25 16:35:45', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:29', '2026-02-25 10:06:29'),
('107', '3', '1', 'Vàng mini \'lên ngôi\' dịp vía Thần Tài năm nay', 'vang-mini-len-ngoi-dip-via-than-tai-nam-nay', 'Trong bối cảnh nguồn cung hạn chế, nhiều doanh nghiệp đẩy mạnh vàng mini dưới 1 chỉ đáp ứng nhu cầu \"lấy may\" của người dân dịp vía Thần Tài.', 'Trong bối cảnh nguồn cung hạn chế, nhiều doanh nghiệp đẩy mạnh vàng mini dưới 1 chỉ đáp ứng nhu cầu \"lấy may\" của người dân dịp vía Thần Tài.', 'https://i1-kinhdoanh.vnecdn.net/2026/02/25/unknown-4-1772006079-4815-1772-3591-9015-1772012077.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=MIkvxck3Flr459u8Wr3opA', NULL, NULL, NULL, 'https://vnexpress.net/vang-mini-len-ngoi-dip-via-than-tai-nam-nay-5043980.html', NULL, '2026-02-25 16:30:49', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":1,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:29', '2026-02-25 10:06:29'),
('108', '10', '1', 'Mong anh sống lành mạnh, có trách nhiệm, ưu tiên gia đình', 'mong-anh-song-lanh-manh-co-trach-nhiem-uu-tien-gia-dinh', 'Mình mong một gia đình nhỏ ấm áp, nơi cả hai cùng vun vén, cùng nuôi dạy con cái và hướng đến cuộc sống ngày một tốt đẹp hơn.', 'Mình mong một gia đình nhỏ ấm áp, nơi cả hai cùng vun vén, cùng nuôi dạy con cái và hướng đến cuộc sống ngày một tốt đẹp hơn.', 'https://s1.vnecdn.net/vnexpress/restruct/i/v9784/logo_default.jpg', NULL, NULL, NULL, 'https://vnexpress.net/mong-anh-song-lanh-manh-co-trach-nhiem-uu-tien-gia-dinh-5043831.html', NULL, '2026-02-25 16:19:28', '0', '0', '0', '0.3', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"\\u0110\\u1eddi S\\u1ed1ng\":6,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:29', '2026-02-25 10:06:29'),
('109', '2', '1', 'Mình sẽ tổ chức lễ hằng thuận nhẹ nhàng và đầm ấm, em nhé', 'minh-se-to-chuc-le-hang-thuan-nhe-nhang-va-dam-am-em-nhe', 'Anh là một phật tử và góc nhìn nhân sinh của anh là nhân quả, luôn hướng thiện và gắng sống tử tế, đạo đức.', 'Anh là một phật tử và góc nhìn nhân sinh của anh là nhân quả, luôn hướng thiện và gắng sống tử tế, đạo đức.', 'https://s1.vnecdn.net/vnexpress/restruct/i/v9784/logo_default.jpg', NULL, NULL, NULL, 'https://vnexpress.net/minh-se-to-chuc-le-hang-thuan-nhe-nhang-va-dam-am-em-nhe-5043828.html', NULL, '2026-02-25 16:11:55', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":1,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:29', '2026-02-25 10:06:29'),
('110', '1', '2', 'Giám đốc Sở Nông nghiệp và Môi trường Hà Nội làm Chánh văn phòng Điều phối Nông thôn mới Trung ương', 'giam-doc-so-nong-nghiep-va-moi-truong-ha-noi-lam-chanh-van-phong-dieu-phoi-nong-thon-moi-trung-uong', '\r\n                Thứ trưởng Bộ Nông nghiệp và Môi trường Nguyễn Hoàng Hiệp trao quyết định của Bộ trưởng Bộ Nông nghiệp và Môi trường cho ông Nguyễn Xuân Đại (bên trái) và ông Ngô Trường Sơn - Ảnh: N...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/nguyen-xuan-dai--17720072117461805888584.jpg\" id=\"img_208621021650968576\" w=\"1151\" h=\"762\" alt=\"Sở nông nghiệp - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208621021650968576\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nguyen-xuan-dai--17720072117461805888584.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1151\" height=\"762\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Thứ trưởng Bộ Nông nghiệp và Môi trường Nguyễn Hoàng Hiệp trao quyết định của Bộ trưởng Bộ Nông nghiệp và Môi trường cho ông Nguyễn Xuân Đại (bên trái) và ông Ngô Trường Sơn - Ảnh: NGUYỄN THỦY</p></figcaption></figure><p>Ngày 25-2, Bộ Nông nghiệp và Môi trường tổ chức hội nghị công bố quyết định của Bộ trưởng Bộ Nông nghiệp và Môi trường về công tác cán bộ. </p><p>Tại hội nghị, Vụ trưởng Vụ Tổ chức cán bộ Phạm Tân Tuyến đã công bố quyết định của Bộ trưởng Bộ Nông nghiệp và Môi trường về việc điều động, bổ nhiệm ông Ngô Trường Sơn, Chánh Văn phòng Điều phối Nông thôn mới Trung ương giữ chức Phó vụ trưởng Vụ Kế hoạch - Tài chính.</p><p>Điều động và bổ nhiệm ông Nguyễn Xuân Đại, Giám đốc Sở Nông nghiệp và Môi trường Hà Nội giữ chức Chánh Văn phòng Điều phối Nông thôn mới Trung ương.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"16/01/2026 16:39\" data-id=\"20260116160937045\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/1/16/ngoc-dieptto-17685573817091853615207-54-308-1229-2188-crop-17685574169141413886509.png\" data-url=\"/ong-dang-ngoc-diep-lam-thu-truong-bo-nong-nghiep-va-moi-truong-20260116160937045.htm\" data-title=\"Ông Đặng Ngọc Điệp làm Thứ trưởng Bộ Nông nghiệp và Môi trường\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/1/16/ngoc-dieptto-17685573817091853615207-54-308-1229-2188-crop-17685574169141413886509.png\" alt=\"Giám đốc Sở Nông nghiệp và Môi trường Hà Nội làm Chánh văn phòng Điều phối Nông thôn mới Trung ương - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Ông Đặng Ngọc Điệp làm Thứ trưởng Bộ Nông nghiệp và Môi trườngĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Trao quyết định cho ông Đại và ông Sơn, Thứ trưởng Bộ Nông nghiệp và Môi trường Nguyễn Hoàng Hiệp cho biết ông Ngô Trường Sơn là cán bộ được đào tạo bài bản, đã trải qua nhiều vị trí công tác quan trọng, từng tham gia tham mưu chiến lược ở cấp bộ, có kinh nghiệm trong lĩnh vực kế hoạch, tài chính và quản lý phát triển ngành. </p><p>Việc điều động, bổ nhiệm ông Sơn vào vị trí Phó vụ trưởng Vụ Kế hoạch - Tài chính được kỳ vọng sẽ tăng cường năng lực tham mưu chiến lược cho bộ trong giai đoạn mới.</p><p>Đối với tân Chánh Văn phòng Điều phối Nông thôn mới Trung ương, ông Hiệp đánh giá ông Đại là cán bộ trưởng thành từ thực tiễn địa phương, từng giữ nhiều vị trí quản lý quan trọng trong ngành nông nghiệp, đặc biệt có nhiều đóng góp trong xây dựng nông thôn mới và phát triển sản phẩm nông nghiệp của thủ đô Hà Nội. </p><p>Những kinh nghiệm thực tiễn này được kỳ vọng sẽ giúp ông Đại hoàn thành tốt nhiệm vụ trên cương vị mới. </p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/13/jrjgtb-17709565396931744077965-249-697-926-1780-crop-17709619142941695931652.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Giám đốc Sở Nông nghiệp và Môi trường Hà Nội làm Chánh văn phòng Điều phối Nông thôn mới Trung ương - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Ông Bùi Duy Cường làm Giám đốc Sở Nông nghiệp và Môi trường Hà Nội<p class=\"VCObjectBoxRelatedNewsItemSapo\">Ông Bùi Duy Cường (sinh năm 1973) - Bí thư Đảng ủy xã Sóc Sơn - được điều động, phân công giữ chức Giám đốc Sở Nông nghiệp và Môi trường Hà Nội.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/nguyen-xuan-dai-17720072117461805888584-125-90-663-950-crop-17720072716811559450303.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/giam-doc-so-nong-nghiep-va-moi-truong-ha-noi-lam-chanh-van-phong-dieu-phoi-nong-thon-moi-trung-uong-20260225152133398.htm', NULL, '2026-02-25 15:57:08', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":21,\"Kinh Doanh\":3,\"Th\\u1ebf Gi\\u1edbi\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:30', '2026-02-25 10:06:30'),
('111', '1', '2', 'Thủ tướng Nhật bị chỉ trích vì tặng quà 190 USD cho 300 nghị sĩ', 'thu-tuong-nhat-bi-chi-trich-vi-tang-qua-190-usd-cho-300-nghi-si', '\r\n                Thủ tướng Nhật Bản Takaichi Sanae tham dự phiên họp toàn thể Hạ viện tại Quốc hội ở Tokyo ngày 25-2 - Ảnh: AFPTheo Hãng tin AFP ngày 25-2, Thủ tướng Nhật Bản Takaichi Sanae viết tron...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/afp2026022598v22crv1highresjapanpolitics-1772006766196766415822.jpg\" id=\"img_208619808925437952\" w=\"2560\" h=\"1707\" alt=\"Nhật Bản - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208619808925437952\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/afp2026022598v22crv1highresjapanpolitics-1772006766196766415822.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Thủ tướng Nhật Bản Takaichi Sanae tham dự phiên họp toàn thể Hạ viện tại Quốc hội ở Tokyo ngày 25-2 - Ảnh: AFP</p></figcaption></figure><p>Theo Hãng tin AFP ngày 25-2, Thủ tướng Nhật Bản Takaichi Sanae viết trong một bài đăng trên X rằng, mỗi nghị sĩ được quyền chọn một món quà từ danh mục (catalog) \"như một lời cảm ơn vì thành công của họ trong cuộc bầu cử đầy khó khăn\", đồng thời khẳng định không sử dụng tiền thuế của người dân.</p><p>Bà cho biết chi phí mỗi phần quà, bao gồm vận chuyển và thuế, khoảng 30.000 yen (tương đương 190 USD) và được chi trả từ quỹ chính trị của một chi bộ LDP tại tỉnh Nara do bà đứng đầu.</p><p>Thủ tướng cũng viết bà hy vọng các món quà này \"sẽ hữu ích cho công việc lập pháp trong tương lai\" của các nghị sĩ.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"23/02/2026 12:00\" data-id=\"20260223110739283\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/23/6ac3b83f-4bc0-47ea-a097-ca15f136-17718189301351440293434-50-0-800-1200-crop-17718197160982030371006.jpg\" data-url=\"/nhat-ban-giam-gio-lam-nhung-da-thuc-su-thoat-lam-viec-den-chet-20260223110739283.htm\" data-title=\"Nhật Bản giảm giờ làm, nhưng đã thực sự thoát ‘làm việc đến chết’?\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/23/6ac3b83f-4bc0-47ea-a097-ca15f136-17718189301351440293434-50-0-800-1200-crop-17718197160982030371006.jpg\" alt=\"Thủ tướng Takaichi bị chỉ trích vì tặng quà 190 USD cho hàng trăm nghị sĩ - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Nhật Bản giảm giờ làm, nhưng đã thực sự thoát ‘làm việc đến chết’?ĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Tuy nhiên động thái này nhanh chóng làm dấy lên lo ngại trong dư luận khi gợi nhớ đến bê bối \"quỹ đen\" từng làm rung chuyển Đảng LDP năm 2023, khiến Thủ tướng khi đó Fumio Kishida phải rời chức, đồng thời thổi bùng sự phẫn nộ của cử tri.</p><p>Vụ việc cũng dẫn đến hệ quả là liên minh do người kế nhiệm Shigeru Ishiba lãnh đạo đã mất đa số ở cả hai viện quốc hội vào năm ngoái.</p><p>Lãnh đạo đảng đối lập chính, ông Junya Ogawa, nhận định thông tin về danh mục quà tặng này \"có thể khiến người dân đặt câu hỏi: \'Thủ tướng Takaichi, cả bà cũng vậy sao?\'\", đồng thời nhấn mạnh bà sẽ phải chịu trách nhiệm nghiêm ngặt trước công chúng.</p><p>Theo luật tài trợ chính trị của Nhật Bản, cá nhân không được quyên góp trực tiếp cho các ứng viên tranh cử chức vụ công, nhưng các đảng phái và chi bộ địa phương được phép thực hiện các khoản chi từ quỹ chính trị.</p><p>Trang <i>Bunshun Online</i> cho biết catalog quà tặng xuất phát từ cửa hàng bách hóa Kintetsu nổi tiếng - nơi khách hàng có thể trả trước 34.000 yen để người nhận catalog lựa chọn một món quà như xe đạp, hải sản cao cấp hoặc kỳ nghỉ tại khách sạn sang trọng.</p><p>Trước đó, ông Ishiba cũng từng bị chỉ trích vì bị cáo buộc tặng phiếu quà trị giá 100.000 yen cho 15 nghị sĩ Hạ viện khóa đầu trong một bữa tối, dù cho biết chi phí được trả bằng tiền cá nhân.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/18/nhattto-17714060807451168751907-0-0-1342-2147-crop-17714061230991517825486.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Thủ tướng Takaichi bị chỉ trích vì tặng quà 190 USD cho hàng trăm nghị sĩ - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Thủ tướng Nhật Bản Takaichi Sanae tái đắc cử sau kỳ bầu cử lịch sử<p class=\"VCObjectBoxRelatedNewsItemSapo\">Bà Takaichi Sanae sẽ ưu tiên thắt chặt an ninh quốc gia và thúc đẩy các chính sách kinh tế mạnh mẽ, nhằm giảm bớt gánh nặng lạm phát cho người dân.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/afp2026022598v22crv1highresjapanpolitics-1772006766196766415822-0-0-1600-2560-crop-17720070576321581847564.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/thu-tuong-nhat-bi-chi-trich-vi-tang-qua-190-usd-cho-300-nghi-si-2026022515224764.htm', NULL, '2026-02-25 15:55:00', '1', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":22,\"Th\\u1ebf Gi\\u1edbi\":8,\"Kinh Doanh\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:30', '2026-02-25 10:25:03'),
('112', '2', '2', 'Diêm dân Ninh Thuận cũ vui khi muối được mùa được giá', 'diem-dan-ninh-thuan-cu-vui-khi-muoi-duoc-mua-duoc-gia', '\r\n                Diêm dân ở cánh đồng muối Khánh Nhơn nhộn nhịp thu hoạch muối đầu xuân - Ảnh: ĐỨC CƯỜNGSáng 25-2 (tức mùng 9 tháng giêng Bính Ngọ), dọc các cánh đồng muối ven biển ở vùng Ninh Thuận...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-17719940763001520188552.jpeg\" id=\"img_208591264532094976\" w=\"2560\" h=\"1707\" alt=\"Diêm dân Ninh Thuận cũ vui khi muối được mùa được giá - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208591264532094976\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-17719940763001520188552.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Diêm dân ở cánh đồng muối Khánh Nhơn nhộn nhịp thu hoạch muối đầu xuân - Ảnh: ĐỨC CƯỜNG</p></figcaption></figure><p>Sáng 25-2 (tức mùng 9 tháng giêng Bính Ngọ), dọc các cánh đồng muối ven biển ở vùng Ninh Thuận cũ (nay là tỉnh Khánh Hòa), tiếng cào muối xen lẫn tiếng nói cười của diêm dân khi muối vừa được mùa vừa được giá.</p><h2><b>Diêm dân phấn khởi</b></h2><p>Đang tất bật thu hoạch 1,6ha muối ở cánh đồng muối Khánh Nhơn (xã Vĩnh Hải), diêm dân Đặng Lơ (64 tuổi) phấn khởi cho biết đã lâu lắm rồi bà con mới đón một vụ muối \"dễ thở\" như vậy. Hiện ruộng muối của gia đình ông được thương lái mua tận ruộng với giá 1,2 triệu đồng/tấn.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"15/04/2024 11:31\" data-id=\"20240411134633541\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2024/4/15/anh-1-17131467111381379666256-35-408-1030-2000-crop-17131467223511090652561.jpg\" data-url=\"/nang-thieu-da-dot-thit-nuoc-man-boc-hoi-bong-rat-diem-dan-van-cao-muoi-20240411134633541.htm\" data-title=\"Nắng thiêu da đốt thịt, nước mặn bốc hơi bỏng rát, diêm dân vẫn cào muối\"><h4 class=\"kbwscwlrl-title\">Nắng thiêu da đốt thịt, nước mặn bốc hơi bỏng rát, diêm dân vẫn cào muối</h4></li></ul><p>\"Có năm làm cả tháng, muối chất đầy bờ mà thương lái trả giá thấp 500.000 đồng/tấn, không đủ tiền công. Ngược lại năm nay họ đến tận ruộng hỏi mua, giá ổn định nên diêm dân chúng tôi rất mừng\" - ông Lơ nói.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-17719940763351399476197.jpeg\" id=\"img_208591130476695552\" w=\"2560\" h=\"1707\" alt=\"Diêm dân Ninh Thuận cũ vui khi muối được mùa được giá - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208591130476695552\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-17719940763351399476197.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Diêm dân Nguyễn Văn Vẹn (66 tuổi) phấn khởi thu hoạch muối - Ảnh: ĐỨC CƯỜNG</p></figcaption></figure><p>Ông Trần Thanh - Giám đốc Hợp tác xã Sản xuất kinh doanh dịch vụ muối Khánh Nhơn (xã Vĩnh Hải) - cho biết so với những năm trước thì giá muối năm nay đang ở mức cao so với nhiều năm.</p><p>\"Hiện giá thu mua muối nền đất tại ruộng dao động 1 - 1,3 triệu đồng mỗi tấn. Muối trải bạt nhỉnh hơn ở mức 1,3 - 1,5 triệu đồng/tấn. So với những năm trước, đây là mức giá cao và ít biến động, giúp người làm muối yên tâm sản xuất\" - ông Thanh cho hay.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-17719940763721805633983.jpeg\" id=\"img_208591621905670144\" w=\"2560\" h=\"1707\" alt=\"Diêm dân Ninh Thuận cũ vui khi muối được mùa được giá - Ảnh 3.\" title=\"\" rel=\"lightbox\" photoid=\"208591621905670144\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-17719940763721805633983.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nhân công của thương lái thuê đến thu mua muối tận ruộng cho diêm dân - Ảnh: ĐỨC CƯỜNG</p></figcaption></figure><p>Không chỉ giá tăng, việc thu mua muối cũng diễn ra thuận lợi hơn. Nhiều thương lái cho nhân công đến tận ruộng thu mua nên bà con yên tâm sản xuất. Theo tính toán của diêm dân, với mức giá 1-1,3 triệu đồng mỗi tấn, sau khi trừ chi phí thì mỗi tấn muối sau khi thu hoạch diêm dân sẽ thu được 600.000 - 900.000 đồng/tấn.</p><h2><b>Hy vọng trúng mùa</b></h2><p>Điều khiến diêm dân phấn khởi hơn cả là năng suất muối năm nay tăng khoảng gấp rưỡi so với mọi năm. Có hộ cho biết chỉ trong một thời gian ngắn đã thu hoạch được lượng muối bằng gần cả vụ trước.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-17719940764181921503294.jpeg\" id=\"img_208591488310796288\" w=\"2560\" h=\"1707\" alt=\"Diêm dân - Ảnh 4.\" title=\"\" rel=\"lightbox\" photoid=\"208591488310796288\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-17719940764181921503294.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Diêm dân Đặng Lơ (trước) phấn khởi cào muối đang kết tinh trắng xóa - Ảnh: ĐỨC CƯỜNG</p></figcaption></figure><p>Diêm dân Nguyễn Văn Vẹn ở thôn Khánh Nhơn (xã Vĩnh Hải) cho hay từ trước Tết đến nay thời tiết có nắng kéo dài, độ mặn cao nên nhiều ruộng muối đạt sản lượng vượt dự kiến. </p><p>Thời gian muối kết tinh cũng được rút ngắn. Trung bình từ 5 -7 ngày diêm dân sẽ cào muối 1 lần. Sản lượng 1ha muối vào khoảng 13 - 15 tấn/một lần cào (tăng 3-4 tấn so với mọi năm), 1 tháng có thể cào muối 4-5 lần tùy ruộng.</p><p>Nhiều thương lái thu mua muối cho biết muối vùng Ninh Thuận cũ có chất lượng tốt nên được thị trường ưa chuộng. Đặc biệt, muối ở các cánh đồng muối Nhơn Hải, Đầm Vua (xã Vĩnh Hải), Tri Hải, Phương Hải (xã Ninh Hải) có độ mặn đặc trưng riêng so với muối ở các vùng khác.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-1771994076443237381808.jpeg\" id=\"img_208591562690486272\" w=\"2560\" h=\"1440\" alt=\"Diêm dân - Ảnh 5.\" title=\"\" rel=\"lightbox\" photoid=\"208591562690486272\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-1771994076443237381808.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1440\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Cánh đồng muối Khánh Nhơn, Đầm Vua nằm liền kề nhau ở thôn Khánh Nhơn, xã Vĩnh Hải - Ảnh: ĐỨC CƯỜNG</p></figcaption></figure><p>Hạt muối nơi đây có sự pha trộn giữa độ mặn từ nước biển và độ mặn từ nước nhiễm mặn lấy từ giếng khoan, cho ra những hạt muối xốp trên bề mặt, có vị đậm mà thanh.</p><p>\"Hiện thương lái khắp các tỉnh đã có đơn đặt hàng muối của hợp tác xã. Hy vọng năm mới giá muối ổn định để diêm dân yên tâm giữ nghề muối truyền thống\" - ông Trần Thanh cho hay.</p>                 <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/tto/i/s626/2015/10/28/604203fa.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Muối đầu năm ‘được mùa, được giá’, diêm dân vùng Ninh Thuận cũ phấn khởi - Ảnh 6.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Mặn hơn muối và câu chuyện của diêm dân<p class=\"VCObjectBoxRelatedNewsItemSapo\">TTO - Bộ phim truyền hình 38 tập <em>Mặn hơn muối </em>phát sóng lúc 20g từ thứ hai đến thứ năm hằng tuần trên kênh HTV7, bắt đầu từ ngày 28-10.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/img0638-1771993104333380995947-63-0-1663-2560-crop-1771993384501388170743.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/diem-dan-ninh-thuan-cu-vui-khi-muoi-duoc-mua-duoc-gia-20260225112641459.htm', NULL, '2026-02-25 15:50:58', '0', '0', '0', '0.25', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":5,\"Kinh Doanh\":2,\"\\u0110\\u1eddi S\\u1ed1ng\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:31', '2026-02-25 10:06:31'),
('113', '10', '1', 'Chung Lệ Đề và chồng con ăn Tết ở Việt Nam', 'chung-le-de-va-chong-con-an-tet-o-viet-nam', 'Diễn viên gốc Việt Chung Lệ Đề cùng gia đình chồng và các con về Việt Nam đón năm mới, nghỉ dưỡng.', 'Diễn viên gốc Việt Chung Lệ Đề cùng gia đình chồng và các con về Việt Nam đón năm mới, nghỉ dưỡng.', 'https://i1-giaitri.vnecdn.net/2026/02/25/top3-1772009591-9120-1772009780.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=EpshrbyR6U9s_7P-jHsxeQ', NULL, NULL, NULL, 'https://vnexpress.net/chung-le-de-va-chong-con-an-tet-o-viet-nam-5044013.html', NULL, '2026-02-25 16:06:19', '0', '0', '0', '0.1', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"\\u0110\\u1eddi S\\u1ed1ng\":2,\"Gi\\u1ea3i Tr\\u00ed\":1,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:31', '2026-02-25 10:06:31'),
('114', '3', '2', 'Đề xuất mức thu phí  5 đoạn tuyến đường cao tốc Bắc - Nam', 'de-xuat-muc-thu-phi-5-doan-tuyen-duong-cao-toc-bac-nam', '\r\n                Cao tốc quốc lộ 45 - Nghi Sơn là một trong 5 đoạn tuyến đường cao tốc do Nhà nước đầu tư được đề xuất mức phí chi tiết - Ảnh: PHÙNG NHẬT QUANGTheo Cục Đường bộ Việt Nam, ngày 24-5-20...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/cao-toc-quoc-lo-45-nghi-son-17719996432882009759508.jpg\" id=\"img_208605151499345920\" w=\"1254\" h=\"754\" alt=\"đường cao tốc - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208605151499345920\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/cao-toc-quoc-lo-45-nghi-son-17719996432882009759508.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1254\" height=\"754\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Cao tốc quốc lộ 45 - Nghi Sơn là một trong 5 đoạn tuyến đường cao tốc do Nhà nước đầu tư được đề xuất mức phí chi tiết - Ảnh: PHÙNG NHẬT QUANG</p></figcaption></figure><p>Theo Cục Đường bộ Việt Nam, ngày 24-5-2025 bộ trưởng Bộ Xây dựng đã phê duyệt đề án khai thác tài sản kết cấu hạ tầng giao thông đường bộ các đoạn tuyến đường cao tốc Mai Sơn - quốc lộ 45, quốc lộ 45 - Nghi Sơn, Nghi Sơn - Diễn Châu, Vĩnh Hảo - Phan Thiết, Phan Thiết - Dầu Giây thuộc đường cao tốc Bắc - Nam phía Đông.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-1771999889412758500127.png\" id=\"img_208605122549010432\" w=\"1673\" h=\"884\" alt=\"Đề xuất mức thu phí  5 đoạn tuyến đường cao tốc Bắc - Nam - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208605122549010432\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-1771999889412758500127.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1673\" height=\"884\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Mức phí 3  đoạn tuyến cao tốc: Mai Sơn - quốc lộ 45, quốc lộ 45 - Nghi Sơn,  Nghi Sơn - Diễn Châu do Cục Đường bộ đề xuất</p></figcaption></figure><p>Trên cơ sở báo các của các khu quản lý đường bộ, Cục Đường bộ Việt Nam đã rà soát, tổng hợp mức thu phí đường cao tốc đối với phương tiện lưu thông trên các đoạn tuyến, tuyến đường cao tốc đã được Bộ Xây dựng phê duyệt đề án khai thác tài sản kết cấu hạ tầng giao thông đường bộ.</p><p>Theo đó, cao tốc Mai Sơn - quốc lộ 45 có chiều dài tính phí thực tế là 61,02km, với mức phí cao nhất với xe nhóm 1 (xe dưới 12 chỗ, xe tải có tải trọng dưới 2 tấn, các loại xe buýt chở khách công cộng) là 54.909 đồng; mức phí cao nhất với xe nhóm 5 (xe tải có tải trọng từ 18 tấn trở lên, xe chở container 40 feet trở lên) là 219.636 đồng.</p><p>Cao tốc quốc lộ 45 - Nghi Sơn có chiều dài tính phí là 45,018km, sẽ có mức phí cao nhất với xe nhóm 1 là 40.516 đồng, xe nhóm 5 là 162.065 đồng.</p><p>Cao tốc Nghi Sơn - Diễn Châu chiều dài tính phí 50,45km, sẽ có mức phí cao nhất với xe nhóm 1 là 45.405 đồng, xe nhóm 5 là 181.620 đồng.</p><p>Cao tốc Vĩnh Hảo - Phan Thiết có chiều dài tính phí 100,618km, sẽ có mức phí cao nhất với xe nhóm 1 là 90.555 đồng, xe nhóm 5 là 362.225 đồng.</p><p>Cao tốc Phan Thiết - Dầu Giây có chiều dài tính phí 99km, sẽ có mức phí cao nhất với xe nhóm 1 là 128.700 đồng, xe nhóm 5 là 518.800 đồng.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"12/01/2026 16:53\" data-id=\"20260112162318122\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/1/12/thu-phi-cao-toc-17682093065541823199814.png\" data-url=\"/du-kien-thu-phi-5-doan-tuyen-cao-toc-bac-nam-tu-cuoi-thang-2-2026-20260112162318122.htm\" data-title=\"Dự kiến thu phí 5 đoạn tuyến cao tốc Bắc - Nam từ cuối tháng 2-2026\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/1/12/thu-phi-cao-toc-17682093065541823199814.png\" alt=\"Đề xuất mức thu phí  5 đoạn tuyến đường cao tốc Bắc - Nam - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Dự kiến thu phí 5 đoạn tuyến cao tốc Bắc - Nam từ cuối tháng 2-2026ĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Như vậy các đoạn tuyến cao tốc: Mai Sơn - quốc lộ 45, quốc lộ 45 - Nghi Sơn, Nghi Sơn - Diễn Châu, Vĩnh Hảo - Phan Thiết có 4 làn xe nhưng chưa có làn dừng xe khẩn cấp liên tục có mức phí 900 đồng/PCU/km (PCU là đơn vị quy đổi theo xe con).</p><p>Còn cao tốc Phan Thiết - Dầu Giây là đường cao tốc có 4 làn xe đầy đủ (4 làn xe chạy và 2 làn dừng khẩn cấp liên tục) nên mức phi là 1.300 đồng/PCU/km.</p><p>Các trạm thu phí trên 5 đoạn tuyến cao tốc trên sẽ thực hiện thu phí điện tử không dừng (ETC) với số tiền tính theo số km xe lăn bánh thực tế.</p><p>Mức phí trên 5 đoạn tuyến cao tốc do Nhà nước đầu tư từ 900 - 1.300 đồng/km, thấp hơn mức thu phí của các tuyến đường cao tốc đầu tư theo hợp đồng BOT đang thu phí với mức bình quân 1.721 đồng/PCU/km.</p><p>Để có cơ sở triển khai thu phí sử dụng đường cao tốc sau khi các tuyến, đoạn tuyến cao tốc đáp ứng các điều kiện nghị định số 130/2024/NĐ-CP của Chính phủ quy định về thu phí sử dụng đường bộ cao tốc đối với phương tiện lưu thông trên tuyến đường bộ cao tốc thuộc sở hữu toàn dân do Nhà nước đại diện chủ sở hữu và trực tiếp quản lý, khai thác, Cục Đường bộ đề nghị Bộ Xây dựng:</p><p>Chấp thuận, phê duyệt mức thu phí sử dụng đường bộ cao tốc đối với phương tiện lưu thông trên 5 đoạn tuyến đường cao tốc Mai Sơn - quốc lộ 45, quốc lộ 45 - Nghi Sơn, Nghi Sơn - Diễn Châu, Vĩnh Hảo - Phan Thiết, Phan Thiết - Dầu Giây. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/bieu-phi-2-17720000701841142604788.png\" id=\"img_208606046331035648\" w=\"1325\" h=\"917\" alt=\"Đề xuất mức thu phí  5 đoạn tuyến đường cao tốc Bắc - Nam - Ảnh 4.\" title=\"\" rel=\"lightbox\" photoid=\"208606046331035648\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/bieu-phi-2-17720000701841142604788.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1325\" height=\"917\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Mức phí 2 đoạn tuyến cao tốc Vĩnh Hảo - Phan Thiết, Phan Thiết - Dầu Giây do Cục Đường bộ đề xuất</p></figcaption></figure><p>Giao Cục Đường bộ Việt Nam căn cứ mức phí được phê duyệt, thực hiện công khai mức thu, phương thức thu, đối tượng nộp, miễn, giảm và văn bản quy định thu phí tại địa điểm thu và công khai trên trang/Cổng thông tin điện tử của tổ chức thu phí theo quy định của pháp luật phí, lệ phí.</p>                                      <h2><b>Đường cao tốc do Nhà nước đầu tư thu phí khi đạt những điều kiện nào?</b></h2><p>Điều 3, nghị định số 130/2024/NĐ-CP của Chính phủ quy định điều kiện thực hiện việc thu phí sử dụng đường cao tốc thuộc sở hữu toàn dân do Nhà nước đại diện chủ sở hữu và trực tiếp quản lý, khai thác được triển khai thu phí phải đáp ứng các điều kiện sau:</p><p>  Được thiết kế, đầu tư xây dựng theo quy chuẩn, tiêu chuẩn kỹ thuật về đường cao tốc và các quy chuẩn, tiêu chuẩn kỹ thuật khác có liên quan.  </p><p> - Hoàn thành bàn giao, đưa vào khai thác theo quy định của Luật Đường bộ, quy định của pháp luật về xây dựng và quy định khác của pháp luật có liên quan.</p><p>- Có đề án khai thác tài sản được người có thẩm quyền phê duyệt theo quy định của pháp luật về quản lý, sử dụng tài sản công.</p><p>- Đường cao tốc đã được quyết định chủ trương đầu tư trước ngày Luật Đường bộ có hiệu lực thi hành, khi đưa vào khai thác mà chưa đáp ứng quy định tại khoản 1 Điều 45, khoản 2 Điều 47 của Luật Đường bộ thì việc thu phí sẽ được triển khai thực hiện sau khi hoàn thành việc xây dựng, lắp đặt hạ tầng trạm thu phí, thiết bị phục vụ việc thu phí; các công trình dịch vụ công tại trạm dừng nghỉ; cơ sở hạ tầng kỹ thuật, thiết bị công nghệ để quản lý, điều hành giao thông và có đề án khai thác tài sản được người có thẩm quyền phê duyệt theo quy định của pháp luật về quản lý, sử dụng tài sản công.</p>                                  <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/8/20/thu-phi-cao-toc-1755678054922561904439-0-0-794-1270-crop-17556781310861007908373.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Đề xuất mức thu phí  5 đoạn tuyến đường cao tốc Bắc - Nam - Ảnh 5.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Thu phí 13 đoạn tuyến đường cao tốc Bắc - Nam phía Đông từ quý 1 năm 2026<p class=\"VCObjectBoxRelatedNewsItemSapo\">Dự kiến chậm nhất trong quý 1-2026 việc thu phí đường cao tốc do nhà nước đầu tư sẽ thực hiện trên 13 đoạn tuyến đường cao tốc Bắc - Nam phía Đông.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/cao-toc-quoc-lo-45-nghi-son-17719996432882009759508-0-6-754-1212-crop-1772000145040702299363.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/de-xuat-muc-thu-phi-5-doan-tuyen-duong-cao-toc-bac-nam-20260225132638568.htm', NULL, '2026-02-25 15:45:00', '0', '0', '0', '0.15', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":3,\"Th\\u1eddi S\\u1ef1\":3,\"Th\\u1ebf Gi\\u1edbi\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:31', '2026-02-25 10:06:31'),
('115', '1', '1', 'Mình tính chuyện lâu dài anh nhé', 'minh-tinh-chuyen-lau-dai-anh-nhe', 'Em hiền lành, vui vẻ, biết suy nghĩ, biết trước biết sau, không được khôn khéo vì tính tình thẳng thắn nhưng tâm thiện lành.', 'Em hiền lành, vui vẻ, biết suy nghĩ, biết trước biết sau, không được khôn khéo vì tính tình thẳng thắn nhưng tâm thiện lành.', 'https://s1.vnecdn.net/vnexpress/restruct/i/v9784/logo_default.jpg', NULL, NULL, NULL, 'https://vnexpress.net/minh-tinh-chuyen-lau-dai-anh-nhe-5043824.html', NULL, '2026-02-25 15:58:48', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:31', '2026-02-25 10:06:31'),
('116', '10', '1', 'Đà Nẵng duyệt giá đất dự án Làng Vân hơn 15 triệu đồng mỗi m2', 'da-nang-duyet-gia-dat-du-an-lang-van-hon-15-trieu-dong-moi-m2', 'UBND TP Đà Nẵng vừa phê duyệt giá đất tại dự án Khu phức hợp du lịch và đô thị nghỉ dưỡng Làng Vân, với giá cao nhất 15,4 triệu đồng mỗi m2.', 'UBND TP Đà Nẵng vừa phê duyệt giá đất tại dự án Khu phức hợp du lịch và đô thị nghỉ dưỡng Làng Vân, với giá cao nhất 15,4 triệu đồng mỗi m2.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/lang-van-7917-1733214158-17720-6558-6696-1772005775.webp?w=1200&h=0&q=100&dpr=1&fit=crop&s=4lG9FCvrigkTXbpBZsMVsg', NULL, NULL, NULL, 'https://vnexpress.net/da-nang-duyet-gia-dat-du-an-lang-van-hon-15-trieu-dong-moi-m2-5043982.html', NULL, '2026-02-25 15:58:17', '0', '0', '0', '0.1', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"\\u0110\\u1eddi S\\u1ed1ng\":2,\"Th\\u1eddi S\\u1ef1\":1,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:32', '2026-02-25 10:06:32'),
('117', '4', '1', 'Những doanh nhân tuổi teen kiếm bộn tiền nhờ AI', 'nhung-doanh-nhan-tuoi-teen-kiem-bon-tien-nho-ai', 'Nhờ các công cụ AI, ngày càng nhiều thiếu niên lập công ty công nghệ và gọi vốn hàng triệu USD ngay khi còn ngồi trên ghế nhà trường.', 'Nhờ các công cụ AI, ngày càng nhiều thiếu niên lập công ty công nghệ và gọi vốn hàng triệu USD ngay khi còn ngồi trên ghế nhà trường.', 'https://i1-giadinh.vnecdn.net/2026/02/25/screen-shot-2026-02-25-at-13-3-8176-2858-1772002229.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=bNa_X3JpJAw19a6YkgrL5w', NULL, NULL, NULL, 'https://vnexpress.net/nhung-doanh-nhan-tuoi-teen-kiem-bon-tien-nho-ai-5043959.html', NULL, '2026-02-25 15:57:22', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"C\\u00f4ng Ngh\\u1ec7\":1,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:32', '2026-02-25 10:06:32'),
('118', '2', '1', 'Những khoảnh khắc ấn tượng trong buổi đọc Thông điệp Liên bang của ông Trump', 'nhung-khoanh-khac-an-tuong-trong-buoi-doc-thong-diep-lien-bang-cua-ong-trump', '\n\n\n\n\n\n\n\n\n \n\n\n\n\n\n\nTổng thống Donald Trump tối 24/2 đến phòng họp Hạ viện Mỹ để đọc Thông điệp Liên bang đầu tiên trong nhiệm kỳ thứ hai, giữa lúc ông đang đối mặt áp lực trong nhiều vấn đề chính...', '\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy lazy-blur\" src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AP26056078184105-1772004740.jpg?w=220&amp;h=0&amp;q=80&amp;dpr=1&amp;fit=crop&amp;s=v5PFfZiDPgUancjqoYSDTw\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AP26056078184105-1772004740.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=lHwNp24iFEfPzBu6ffIfYg\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Tổng thống Donald Trump tối 24/2 đến phòng họp Hạ viện Mỹ để đọc Thông điệp Liên bang đầu tiên trong nhiệm kỳ thứ hai, giữa lúc ông đang đối mặt áp lực trong nhiều vấn đề chính sách và tỷ lệ ủng hộ sụt giảm.</p>\n<p class=\"Normal\">Ông xuất hiện trong sự chào đón nồng nhiệt từ phần lớn nghị sĩ có mặt. Tổng thống Mỹ vừa đi vừa bắt tay, hỏi chuyện mọi người, trong đó có nghị sĩ còn xin chụp ảnh selfie cùng ông.</p> \n\n\n<p class=\"Normal\">Tổng thống Donald Trump tối 24/2 đến phòng họp Hạ viện Mỹ để đọc Thông điệp Liên bang đầu tiên trong nhiệm kỳ thứ hai, giữa lúc ông đang đối mặt áp lực trong nhiều vấn đề chính sách và tỷ lệ ủng hộ sụt giảm.</p>\n<p class=\"Normal\">Ông xuất hiện trong sự chào đón nồng nhiệt từ phần lớn nghị sĩ có mặt. Tổng thống Mỹ vừa đi vừa bắt tay, hỏi chuyện mọi người, trong đó có nghị sĩ còn xin chụp ảnh selfie cùng ông.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy lazy-blur\" src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/2026-02-25T023309Z-1714405054-RC2QSJARN95X-RTRMADP-3-USA-TRUMP-CONGRESS-1772003920.jpg?w=220&amp;h=0&amp;q=80&amp;dpr=1&amp;fit=crop&amp;s=MPSnKRPbtiPv-DpKoD5vRQ\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/2026-02-25T023309Z-1714405054-RC2QSJARN95X-RTRMADP-3-USA-TRUMP-CONGRESS-1772003920.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Tbu-0KUw8Anw9XmP13nkKg\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Hạ nghị sĩ Dân chủ Al Green đứng gần đường ông Trump đi qua, giơ tấm biển với dòng chữ \"Người da đen không phải vượn\". Ông Green dường như ám chỉ video đăng trên tài khoản mạng xã hội của Tổng thống Trump trước đó, trong đó có hình cựu tổng thống Barack Obama và cựu đệ nhất phu nhân Michelle Obama ghép vào thân vượn.</p>\n<p class=\"Normal\">Ông Green sau đó bị đưa khỏi khán phòng.</p>\n<p class=\"Normal\">Nghị sĩ Al Green hồi năm ngoái cũng bị yêu cầu rời khỏi phòng họp Hạ viện Mỹ trong lúc Tổng thống Trump phát biểu, sau khi ông đứng dậy và vung cây gậy của mình về phía ông chủ Nhà Trắng.</p> \n\n\n<p class=\"Normal\">Hạ nghị sĩ Dân chủ Al Green đứng gần đường ông Trump đi qua, giơ tấm biển với dòng chữ \"Người da đen không phải vượn\". Ông Green dường như ám chỉ video đăng trên tài khoản mạng xã hội của Tổng thống Trump trước đó, trong đó có hình cựu tổng thống Barack Obama và cựu đệ nhất phu nhân Michelle Obama ghép vào thân vượn.</p>\n<p class=\"Normal\">Ông Green sau đó bị đưa khỏi khán phòng.</p>\n<p class=\"Normal\">Nghị sĩ Al Green hồi năm ngoái cũng bị yêu cầu rời khỏi phòng họp Hạ viện Mỹ trong lúc Tổng thống Trump phát biểu, sau khi ông đứng dậy và vung cây gậy của mình về phía ông chủ Nhà Trắng.</p> \n\n\n\n\n\n\n<img class=\"thumb-above-video\" style=\"padding-bottom: 0; height: auto; aspect-ratio: 1280/720; max-height: min(90svh, 90vh); max-width: min(1100px, 100%); margin-left: auto; margin-right: auto; position:absolute; left: 0; top: 0\" src=\"https://iv1.vnecdn.net/vnexpress/images/web/2026/02/25/nhung-phat-bieu-dang-chu-y-cua-ong-trump-trong-thong-diep-li-1772004102.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=MfCG3bSZA5iaTeJfg6TUfg\" alt=\"Những phát biểu đáng chú ý của ông Trump trong Thông điệp Liên bang\">\n\n \n \n\n\n\n\n\n\n\n\n\n\n\n\nNhững phát biểu đáng chú ý của ông Trump trong Thông điệp Liên bang\n\n\n\n\n\n<p class=\"Normal\">Những tuyên bố đáng chú ý của ông Trump trong Thông điệp Liên bang tối 24/2. Video:<em> NBC News, White House</em></p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AP26056081345641-1772004740.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=6DlQDK9aUxba-iHHjguDHg\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Tổng thống Mỹ mở đầu bài phát biểu với tuyên bố nước Mỹ đã trở lại, lớn mạnh, tốt đẹp, giàu có hơn và hùng mạnh hơn bao giờ hết. \"Đây là thời kỳ hoàng kim của nước Mỹ\", ông nói.</p>\n<p class=\"Normal\">Ông Trump liên tục ca ngợi những thành tựu của chính quyền Mỹ trong các lĩnh vực như kinh tế và đảm bảo an ninh biên giới, đồng thời chỉ trích người tiền nhiệm Joe Biden.</p> \n\n\n<p class=\"Normal\">Tổng thống Mỹ mở đầu bài phát biểu với tuyên bố nước Mỹ đã trở lại, lớn mạnh, tốt đẹp, giàu có hơn và hùng mạnh hơn bao giờ hết. \"Đây là thời kỳ hoàng kim của nước Mỹ\", ông nói.</p>\n<p class=\"Normal\">Ông Trump liên tục ca ngợi những thành tựu của chính quyền Mỹ trong các lĩnh vực như kinh tế và đảm bảo an ninh biên giới, đồng thời chỉ trích người tiền nhiệm Joe Biden.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AFP-20260225-98UM338-v4-HighRes-DonaldTrumpGivesTheStateOfTheUnionAddressToCong-1772003924.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=3aBJNZl4lqG0SNcPPAhVmg\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Các con của Tổng thống Trump lắng nghe bố phát biểu.</p> \n\n\n<p class=\"Normal\">Các con của Tổng thống Trump lắng nghe bố phát biểu.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AP26056143247982-1772003925.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=hYhaXeKSJvvz3gC89lmt5Q\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Ông Trump khen ngợi con rể Jared Kushner (đứng giữa, hàng sau) cùng đặc phái viên Mỹ Steve Witkoff vì hoàn thành nhiệm vụ trong đàm phán thỏa thuận ngừng bắn ở Dải Gaza.</p> \n\n\n<p class=\"Normal\">Ông Trump khen ngợi con rể Jared Kushner (đứng giữa, hàng sau) cùng đặc phái viên Mỹ Steve Witkoff vì hoàn thành nhiệm vụ trong đàm phán thỏa thuận ngừng bắn ở Dải Gaza.</p> \n\n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AP26056093418724-1772003927.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=6knLSHstaRiIsyaDa6F7tw\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Trong số những người được ông Trump khen ngợi có các vận động viên đội tuyển khúc côn cầu nam vừa giành huy chương vàng ở Olympic Mùa Đông 2026. Họ xuất hiện và giơ cao huy chương trong tiếng vỗ tay vang dội. </p>\n<p class=\"Normal\">Ông Trump thông báo sẽ trao Huân chương Tự do của Tổng thống, phần thưởng dân sự cao quý nhất của Mỹ, cho thủ môn Connor Hellebuyck và nhấn mạnh vận động viên này \"rất xứng đáng\".</p> \n\n\n<p class=\"Normal\">Trong số những người được ông Trump khen ngợi có các vận động viên đội tuyển khúc côn cầu nam vừa giành huy chương vàng ở Olympic Mùa Đông 2026. Họ xuất hiện và giơ cao huy chương trong tiếng vỗ tay vang dội. </p>\n<p class=\"Normal\">Ông Trump thông báo sẽ trao Huân chương Tự do của Tổng thống, phần thưởng dân sự cao quý nhất của Mỹ, cho thủ môn Connor Hellebuyck và nhấn mạnh vận động viên này \"rất xứng đáng\".</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AFP-20260225-98UM9EU-v3-HighRes-DonaldTrumpGivesTheStateOfTheUnionAddressToCong-1772003922.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=zMU8VPziNL3LGC7ev7Nu1g\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Các nghị sĩ liên tục đứng lên vỗ tay ủng hộ trong bài phát biểu của Tổng thống Trump.</p> \n\n\n<p class=\"Normal\">Các nghị sĩ liên tục đứng lên vỗ tay ủng hộ trong bài phát biểu của Tổng thống Trump.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AFP-20260225-98UP7MB-v1-HighRes-DonaldTrumpGivesTheStateOfTheUnionAddressToCong-1772004729.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=tRt2qOObXEFU3XI3LFUTXg\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Trái với sự nhiệt tình của phe Cộng hòa, nhiều nghị sĩ Dân chủ tỏ rõ thái độ phản đối khi ông Trump phát biểu.</p>\n<p class=\"Normal\">Có thời điểm Tổng thống Trump đề nghị tất cả nhà lập pháp trong khán phòng đứng dậy nếu họ đồng ý rằng \"nhiệm vụ đầu tiên của chính phủ Mỹ là bảo vệ công dân Mỹ, chứ không phải người nhập cư bất hợp pháp\", cũng như kêu gọi khôi phục ngân sách cho Bộ An ninh Nội địa.</p>\n<p class=\"Normal\">Toàn bộ nghị sĩ Cộng hòa đứng dậy, trong khi nhiều thành viên đảng Dân chủ không làm theo. \"Các vị nên thấy xấu hổ khi không đứng lên\", ông Trump nói.</p>\n<p class=\"Normal\">\"Các ông đã giết hại người Mỹ\", nghị sĩ Dân chủ Ilhan Omar đáp trả.</p> \n\n\n<p class=\"Normal\">Trái với sự nhiệt tình của phe Cộng hòa, nhiều nghị sĩ Dân chủ tỏ rõ thái độ phản đối khi ông Trump phát biểu.</p>\n<p class=\"Normal\">Có thời điểm Tổng thống Trump đề nghị tất cả nhà lập pháp trong khán phòng đứng dậy nếu họ đồng ý rằng \"nhiệm vụ đầu tiên của chính phủ Mỹ là bảo vệ công dân Mỹ, chứ không phải người nhập cư bất hợp pháp\", cũng như kêu gọi khôi phục ngân sách cho Bộ An ninh Nội địa.</p>\n<p class=\"Normal\">Toàn bộ nghị sĩ Cộng hòa đứng dậy, trong khi nhiều thành viên đảng Dân chủ không làm theo. \"Các vị nên thấy xấu hổ khi không đứng lên\", ông Trump nói.</p>\n<p class=\"Normal\">\"Các ông đã giết hại người Mỹ\", nghị sĩ Dân chủ Ilhan Omar đáp trả.</p> \n\n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AP26056101277076-1772004523.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=IIvwQMX-orIvHs83hVRouQ\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Bài phát biểu Thông điệp Liên bang của Tổng thống Trump kéo dài 108 phút, lâu nhất kể từ khi các buổi đọc Thông điệp Liên bang được phát sóng ở Mỹ năm 1964 và vượt kỷ lục 1 tiếng 28 phút 49 giây do cựu tổng thống Bill Clinton thiết lập năm 2000.</p>\n<p class=\"Normal\">Bài phát biểu của ông Trump trước quốc hội Mỹ hồi năm ngoái cũng kéo dài 1 tiếng 29 phút 32 giây, lập kỷ lục về thời lượng về bài phát biểu thường niên trước quốc hội.</p> \n\n\n<p class=\"Normal\">Bài phát biểu Thông điệp Liên bang của Tổng thống Trump kéo dài 108 phút, lâu nhất kể từ khi các buổi đọc Thông điệp Liên bang được phát sóng ở Mỹ năm 1964 và vượt kỷ lục 1 tiếng 28 phút 49 giây do cựu tổng thống Bill Clinton thiết lập năm 2000.</p>\n<p class=\"Normal\">Bài phát biểu của ông Trump trước quốc hội Mỹ hồi năm ngoái cũng kéo dài 1 tiếng 29 phút 32 giây, lập kỷ lục về thời lượng về bài phát biểu thường niên trước quốc hội.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-vnexpress.vnecdn.net/2026/02/25/AP26056162799224-1772004611.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=heQu6KyCpGzRL5Lp8i5_6g\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Kết thúc bài phát biểu, ông Trump rời đi với vẻ mặt tươi cười trong sự ủng hộ từ các nghị sĩ. Hạ nghị sĩ Cộng hòa Kat Cammack còn chạy lại xin chụp ảnh cùng ông.</p> \n\n\n<p class=\"Normal\">Kết thúc bài phát biểu, ông Trump rời đi với vẻ mặt tươi cười trong sự ủng hộ từ các nghị sĩ. Hạ nghị sĩ Cộng hòa Kat Cammack còn chạy lại xin chụp ảnh cùng ông.</p> \n\n\n<p class=\"Normal\" style=\"text-align:right;\"><strong>Ngọc Ánh </strong>(Ảnh: <em>AP, AFP, Reuters</em>)</p>	\n<ul class=\"list-news hidden\" data-campaign=\"Box-Related\"><li data-id=\"5043909\">Quan điểm đối nội, đối ngoại của ông Trump trong Thông điệp Liên bang\n\n\n\n\n</li><li data-id=\"5043946\">Những tuyên bố đáng chú ý của ông Trump trong Thông điệp Liên bang\n\n\n\n\n</li></ul>\n', 'https://i1-vnexpress.vnecdn.net/2026/02/25/2026-02-25T023309Z-1714405054-RC2QSJARN95X-RTRMADP-3-USA-TRUMP-CONGRESS-1772003920.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=Tbu-0KUw8Anw9XmP13nkKg', NULL, NULL, NULL, 'https://vnexpress.net/nhung-khoanh-khac-an-tuong-trong-buoi-doc-thong-diep-lien-bang-cua-ong-trump-5043975.html', NULL, '2026-02-25 15:51:51', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":44,\"Th\\u1eddi S\\u1ef1\":6,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:32', '2026-02-25 10:06:32'),
('119', '1', '1', 'Nguy kịch vì thói quen 20 năm \'mở mắt ra là uống rượu\'', 'nguy-kich-vi-thoi-quen-20-nam-mo-mat-ra-la-uong-ruou', 'Thói quen \"mở mắt ra là uống rượu\" suốt 20 năm khiến người đàn ông 50 tuổi nôn ồ ạt cả lít máu, đối mặt với nguy cơ tử vong do suy đa tạng.', 'Thói quen \"mở mắt ra là uống rượu\" suốt 20 năm khiến người đàn ông 50 tuổi nôn ồ ạt cả lít máu, đối mặt với nguy cơ tử vong do suy đa tạng.', 'https://i1-suckhoe.vnecdn.net/2026/02/25/639442006-944675961551635-8145-3516-2710-1772009383.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=5ZvPmKNY04peXTp3iaR9jg', NULL, NULL, NULL, 'https://vnexpress.net/nguy-kich-vi-thoi-quen-20-nam-mo-mat-ra-la-uong-ruou-5043849.html', NULL, '2026-02-25 15:50:55', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:32', '2026-02-25 10:06:32'),
('120', '2', '2', 'Đề xuất đường thơ ở TP.HCM', 'de-xuat-duong-tho-o-tphcm', '\r\n                               Thơ của nhà thơ Chế Lan Viên được chọn thiết kế đặt ở đường thơ trong Ngày thơ Việt Nam 2026 tại TP.HCMNgày thơ Việt Nam 2026 tại TP.HCM do Hội Nhà văn TP.HCM tổ chức,...', '\r\n                               <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/chelanvien-1772005712915318966718.jpg\" id=\"img_208619377182658560\" w=\"1280\" h=\"984\" alt=\"đường thơ - Ảnh 1.\" title=\"Đề xuất đường thơ ở TP.HCM - Ảnh 1.\" rel=\"lightbox\" photoid=\"208619377182658560\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/chelanvien-1772005712915318966718.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1280\" height=\"984\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Thơ của nhà thơ Chế Lan Viên được chọn thiết kế đặt ở đường thơ trong Ngày thơ Việt Nam 2026 tại TP.HCM</p></figcaption></figure><p>Ngày thơ Việt Nam 2026 tại TP.HCM do Hội Nhà văn TP.HCM tổ chức, mang chủ đề <i>Tiếng gọi đô thị mới</i>. Ngày thơ diễn ra trong ba ngày 27, 28-2 và 1-3 ở địa chỉ 81 Trần Quốc Thảo, phường Xuân Hòa, TP.HCM.</p>     <h2><b>Đường thơ mang lại những giá trị văn hóa</b></h2>     <p>Năm nay là năm thứ tư ban tổ chức duy trì đường thơ trong các hoạt động của Ngày thơ Việt Nam. Chủ tịch Hội Nhà văn TP.HCM Trịnh Bích Ngân tiếc là không gian tổ chức khá hẹp nên chỉ có thể làm 12 poster thơ để đặt trên đường thơ.</p>     <p>Đây là thơ được chọn lọc từ những bài thơ tiêu biểu của 12 tác giả trong thời kỳ đổi mới như Chế Lan Viên, Đỗ Nam Cao, Lê Xuân Đố, Nguyễn Thái Sơn... </p><figure class=\"VCSortableInPreviewMode alignLeft\" type=\"Photo\" style=\"\" data-style=\"align-left\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-17720058812901414657946.jpeg\" id=\"img_208619920065257472\" w=\"2560\" h=\"3075\" alt=\"đường thơ - Ảnh 2.\" title=\"Đề xuất đường thơ ở TP.HCM - Ảnh 2.\" rel=\"lightbox\" photoid=\"208619920065257472\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-17720058812901414657946.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"3075\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Bà Trịnh Bích Ngân mong muốn có một đường thơ ở TP.HCM - Ảnh: LINH ĐOAN</p></figcaption></figure><p>Những người thực hiện tốn khá nhiều công sức từ quá trình chọn thơ, thiết kế thơ, in ấn làm poster…, tuy nhiên theo bà Ngân, chỉ để trưng bày vài ngày rồi dẹp thì rất uổng.</p>     <p>Bà Ngân mong chúng ta có sự tính toán, chẳng hạn ở con phố nào thật đẹp của TP.HCM được làm đường thơ dành cho người dân và du khách thì rất hay. </p>     <p>\"Tại sao chúng ta lại không làm? Ví dụ thơ Nguyễn Trãi, Nguyễn Du, Hồ Xuân Hương, Nguyễn Đình Chiểu…, nhiều tác phẩm của họ đã trở thành kiệt tác văn hóa của thế giới. </p>     <p>Chúng ta có thể thiết kế những bài thơ thành song ngữ tiếng Việt dịch ra tiếng Anh, Pháp, Hàn hoặc Trung, sẽ góp thêm phần giới thiệu di sản văn hóa đến công chúng và du khách\" - bà Ngân nhấn mạnh.</p>     <p>Bà Ngân bảo cái này không khó, nhưng nếu làm được thì rất hữu ích. Chỉ cần du khách thuộc bài thơ nào đó của Nguyễn Du, Nguyễn Đình Chiểu… thì chúng ta đã góp phần khôi phục một phần văn hóa đôi khi mình lãng quên, đôi khi chưa có điều kiện để người ta tiếp cận.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/nguyenthaison-17720059323461481850203.jpg\" id=\"img_208619837541076992\" w=\"1098\" h=\"886\" alt=\"đường thơ - Ảnh 3.\" title=\"Đề xuất đường thơ ở TP.HCM - Ảnh 3.\" rel=\"lightbox\" photoid=\"208619837541076992\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nguyenthaison-17720059323461481850203.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1098\" height=\"886\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Bài thơ của nhà thơ Nguyễn Thái Sơn được thiết kế đặt ở đường thơ</p></figcaption></figure>     <h2><b>Tiếng gọi từ trái tim</b></h2>     <p>Trao đổi với báo chí sáng 25-2, ban tổ chức cho biết năm 2026 kỷ niệm 50 năm Sài Gòn được đặt tên TP.HCM, kỷ niệm 40 năm đất nước đổi mới, mà TP.HCM được xem như điển hình. Không chỉ đổi mới kinh tế, TP.HCM cũng là mảnh đất đổi mới về sáng tác văn học nghệ thuật, trong đó có nhiều thành tựu đổi mới thi ca.</p>     <p>Sau sáp nhập, TP.HCM đã trở thành siêu đô thị, hội viên Hội Nhà văn TP.HCM cũng tăng lên khoảng 600 nên chắc chắn sẽ có  nhiều thay đổi. </p>     <p><i>Tiếng gọi đô thị mới</i> không chỉ mới liên quan đến địa danh mà còn hàm ý là tiếng gọi trái tim, tiếng gọi văn chương, con người văn nghệ sĩ trong giai đoạn mới biết hòa chung nhịp đập cộng đồng, có trách nhiệm với xã hội, với sự phát triển của TP.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"13/02/2025 06:51\" data-id=\"2025021306433499\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/2/13/namlanthu23voichudetoquocbaylen233838180stand-1739403480887-1739403481028511634632-42-0-458-665-crop-17394036770361561814387-0-39-355-606-crop-17394090370231627653136.jpg\" data-url=\"/ong-nguyen-trong-nghia-giong-hoi-trong-khai-mac-ngay-tho-viet-nam-to-quoc-bay-len-2025021306433499.htm\" data-title=\"Ông Nguyễn Trọng Nghĩa gióng hồi trống khai mạc Ngày Thơ Việt Nam \'Tổ quốc bay lên\'\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/2/13/namlanthu23voichudetoquocbaylen233838180stand-1739403480887-1739403481028511634632-42-0-458-665-crop-17394036770361561814387-0-39-355-606-crop-17394090370231627653136.jpg\" alt=\"Đề xuất đường thơ ở TP.HCM - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Ông Nguyễn Trọng Nghĩa gióng hồi trống khai mạc Ngày Thơ Việt Nam \'Tổ quốc bay lên\'ĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul>     <p>Trong khuôn khổ ngày thơ sẽ có tọa đàm <i>Đô thị thi ca</i> diễn ra lúc 9h ngày 27-2, trao đổi về đặc trưng thơ TP.HCM. </p>     <p>Đồng thời kiến nghị các giải pháp đưa thơ phổ cập công chúng và chuyển ngữ quốc tế. Tọa đàm quy tụ nhiều gương mặt quen thuộc của nhiều thế hệ sáng tác và nghiên cứu thơ. </p>     <p>Triển lãm thơ dịch <i>Cây tâm hồn</i> bắt đầu từ sáng 28-2, giới thiệu các tác phẩm thơ được dịch sang tiếng Anh, tiếng Pháp, tiếng Trung, tiếng Hàn, tiếng Nhật…  Bên cạnh đó là chương trình giao lưu với các dịch giả.</p>     <p>Hội trại thơ giới thiệu 36 trại thơ của các câu lạc bộ trên địa bàn TP.HCM, bao gồm cả các câu lạc bộ trên địa bàn Bình Dương cũ và Bà Rịa - Vũng Tàu cũ. </p>     <p>Hội trại diễn ra từ chiều 28-2 đến hết ngày 1-3. Có giao lưu giữa các câu lạc bộ, trao giải cho các trại thơ ấn tượng và những tiết mục biểu diễn ấn tượng.</p>     <p>Chương trình thơ nhạc <i>Tiếng gọi đô thị mới</i> diễn ra sáng Chủ nhật 1-3, trình diễn các tác phẩm thơ và ca khúc phổ thơ. Chương trình do Nhà hát kịch TP.HCM phối hợp dàn dựng, có sự góp mặt của các ca sĩ Thanh Ngọc, Quốc Đại, Phạm Khánh Ngọc, Lam Tuyền, nhóm Lạc Việt…</p>     <p>Sau ngày thơ, ban tổ chức cũng mở ra cuộc thi thơ chủ đề <i>Tiếng gọi đô thị mới</i>.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/2022/2/15/2624030108961665144120857570058984730788139n-1644900220412488253588-crop-1644900458954793557203.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Đề xuất đường thơ ở TP.HCM - Ảnh 5.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Ngày thơ Việt Nam: Chúng ta chất vấn thơ quá nhiều, hãy để thơ chất vấn chúng ta<p class=\"VCObjectBoxRelatedNewsItemSapo\">TTO - TS Nguyễn Thanh Tâm cho rằng lâu nay chúng ta cứ chất vấn thơ quá nhiều, rằng thơ có ích lợi gì, vậy thì hãy để thơ chất vấn chúng ta, rằng người đọc có đọc được thơ không. Còn TS Trần Ngọc Hiếu đòi cho thơ có ‘quyền được ương bướng’.</p>     <p>     </p><p>     </p><p>   </p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/bichngan-1772005823023246593417-105-0-1705-2560-crop-1772006203532214525924.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/de-xuat-duong-tho-o-tphcm-20260225151332353.htm', NULL, '2026-02-25 15:41:46', '0', '0', '0', '0.3', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":6,\"Th\\u1eddi S\\u1ef1\":6,\"Gi\\u1ea3i Tr\\u00ed\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:32', '2026-02-25 10:06:32'),
('121', '3', '1', 'Chứng khoán đứt chuỗi tăng 5 phiên liên tiếp', 'chung-khoan-dut-chuoi-tang-5-phien-lien-tiep', 'Áp lực chốt lời xuất hiện trên diện rộng sau chuỗi tăng 5 phiên liên tục khiến VN-Index giảm gần 7 điểm, về 1.860 điểm.', 'Áp lực chốt lời xuất hiện trên diện rộng sau chuỗi tăng 5 phiên liên tục khiến VN-Index giảm gần 7 điểm, về 1.860 điểm.', 'https://i1-kinhdoanh.vnecdn.net/2026/02/25/CG2A9235-3695-1772008559.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=S6p1ll60qvXN4Ox9bcqctw', NULL, NULL, NULL, 'https://vnexpress.net/chung-khoan-dut-chuoi-tang-5-phien-lien-tiep-5044018.html', NULL, '2026-02-25 15:49:54', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":4,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:32', '2026-02-25 10:06:32'),
('122', '8', '1', 'Bốn nhóm không phải bồi hoàn nếu du học không về', 'bon-nhom-khong-phai-boi-hoan-neu-du-hoc-khong-ve', 'Du học sinh diện ngân sách không về nước hoặc bỏ việc giữa chừng sẽ được miễn bồi hoàn nếu gặp vấn đề sức khỏe, do bất khả kháng hoặc được điều động, luân chuyển.', 'Du học sinh diện ngân sách không về nước hoặc bỏ việc giữa chừng sẽ được miễn bồi hoàn nếu gặp vấn đề sức khỏe, do bất khả kháng hoặc được điều động, luân chuyển.', 'https://i1-vnexpress.vnecdn.net/2026/02/24/screen-shot-2026-02-24-at-15-1-2608-2060-1771920803.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=WvxLeo0mpNlmlEQYRIkIFg', NULL, NULL, NULL, 'https://vnexpress.net/bon-nhom-khong-phai-boi-hoan-neu-du-hoc-khong-ve-5043573.html', NULL, '2026-02-25 15:45:33', '0', '0', '0', '0.25', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Gi\\u00e1o D\\u1ee5c\":5,\"Kinh Doanh\":1,\"S\\u1ee9c Kh\\u1ecfe\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:33', '2026-02-25 10:06:33'),
('123', '9', '2', 'Công an Đồng Nai bắt người chồng mưu sát vợ rồi trốn về Cà Mau', 'cong-an-dong-nai-bat-nguoi-chong-muu-sat-vo-roi-tron-ve-ca-mau', '\r\n                Lê Văn Thương - nghi phạm mưu sát vợ rồi tạo hiện trường giả nạn nhân bị điện giật - Ảnh: Công an phường Bình PhướcNgày 25-2, Công an phường Bình Phước, tỉnh Đồng Nai vừa triệt phá t...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/le-van-thuong-1772006593368976788319.jpg\" id=\"img_208619723119616000\" w=\"1500\" h=\"1000\" alt=\"Đồng Nai - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208619723119616000\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/le-van-thuong-1772006593368976788319.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1500\" height=\"1000\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Lê Văn Thương - nghi phạm mưu sát vợ rồi tạo hiện trường giả nạn nhân bị điện giật - Ảnh: Công an phường Bình Phước</p></figcaption></figure><p>Ngày 25-2, Công an phường Bình Phước, tỉnh Đồng Nai vừa triệt phá thành công vụ mưu sát vợ bằng lưới điện, bắt khẩn cấp Lê Văn Thương (53 tuổi, quê Cà Mau) để điều tra về hành vi giết người.</p><p>Trước đó, ngày 9-2, Công an phường Bình Phước tiếp nhận tin báo về việc bà Q.T.Th. (46 tuổi, vợ của Thương) bị điện giật nguy kịch, đang cấp cứu tại Bệnh viện 175 (TP.HCM).</p><p>Quá trình khám nghiệm hiện trường tại phòng trọ nơi vợ chồng Thương ở thuộc khu phố Tiến Hưng 3, phường Bình Phước, lực lượng công an phát hiện nhiều dấu hiệu bất thường, dấu vết xáo trộn và có biểu hiện dàn dựng.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"22/10/2025 13:39\" data-id=\"20251022104506121\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/10/22/bui-ngoc-tuyen-17611044948941460290868-42-0-1433-2226-crop-1761104559225437723991-208-188-1250-1856-crop-17611155248171963239460.jpg\" data-url=\"/chong-sat-hai-vo-vi-bo-nha-di-may-thang-khong-ve-voi-2-con-20251022104506121.htm\" data-title=\"Chồng sát hại vợ vì bỏ nhà đi mấy tháng không về với 2 con\"><h4 class=\"kbwscwlrl-title\">Chồng sát hại vợ vì bỏ nhà đi mấy tháng không về với 2 con</h4></li><li class=\"kbwscwlrl\" data-date=\"05/05/2025 17:39\" data-id=\"20250505170137737\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/5/5/anh-tin-nong-17414432839852104062649-0-10-617-997-crop-17464392568851320878228.jpg\" data-url=\"/tam-giu-vo-de-dieu-tra-vu-nguoi-chong-nghi-bi-sat-hai-trong-dem-20250505170137737.htm\" data-title=\"Tạm giữ vợ để điều tra vụ người chồng nghi bị sát hại trong đêm\"><h4 class=\"kbwscwlrl-title\">Tạm giữ vợ để điều tra vụ người chồng nghi bị sát hại trong đêm</h4></li></ul><p>Hơn nữa, Thương đột ngột rời khỏi bệnh viện khiến gia đình bà Th. nghi ngờ không phải tai nạn điện.</p><p>Trước tính chất nghiêm trọng của vụ việc, Công an phường Bình Phước khẩn trương tổ chức lực lượng truy tìm và xác định Thương đã trốn về quê.</p><p>Với quyết tâm bắt giữ nghi phạm gây án, Công an phường Bình Phước vượt hàng trăm cây số phối hợp với Công an xã Khánh An (Cà Mau) xác minh vị trí của Thương. </p><p>Lực lượng công an đã bắt giữ, di lý Thương từ Cà Mau về trụ sở Công an phường Bình Phước làm việc.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/day-dien-vat-chung-17720068055612095263543.jpg\" id=\"img_208620167527096320\" w=\"1500\" h=\"1000\" alt=\"Đồng Nai - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208620167527096320\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/day-dien-vat-chung-17720068055612095263543.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1500\" height=\"1000\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Dây diện vật chứng thu giữ được tại phòng trọ của vợ chồng Lê Văn Thương đang ở - Ảnh: Công an phường Bình Phước</p></figcaption></figure><p>Tại cơ quan công an, ban đầu Thương không nhận việc mưu sát vợ mà cho rằng bà Th. bị tai nạn do dây điện hở.</p><p>Tuy nhiên trước các chứng cứ thu thập được cùng quá trình đấu tranh kiên trì, Thương đã thừa nhận hành vi cố ý dùng dây điện tác động vào vợ trong lúc nạn nhân đang ngủ, sau đó tạo hiện trường giả để che giấu.</p><p>Công an phường Bình Phước hiện đã bàn giao nghi phạm cùng toàn bộ hồ sơ, tang vật cho Cơ quan cảnh sát điều tra Công an tỉnh Đồng Nai điều tra, xử lý theo thẩm quyền.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/12/27/830888782b47a419fd56-1766835994113778432696-49-0-730-1089-crop-17668362471511968198227.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Công an Đồng Nai bắt người chồng mưu sát vợ rồi trốn về Cà Mau - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Điều tra nghi án chồng giết vợ và con gái nhỏ rồi tự sát<p class=\"VCObjectBoxRelatedNewsItemSapo\">Sơ bộ, cơ quan công an xác định người chồng 32 tuổi đã sát hại vợ và con gái tại nhà riêng, sau đó cũng tử vong.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/le-van-thuong-1772006593368976788319-32-0-970-1500-crop-17720068484481089911605.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/cong-an-dong-nai-bat-nguoi-chong-muu-sat-vo-roi-tron-ve-ca-mau-20260225151013245.htm', NULL, '2026-02-25 15:24:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":32,\"Th\\u1ebf Gi\\u1edbi\":4,\"S\\u1ee9c Kh\\u1ecfe\":3},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:33', '2026-02-25 10:06:33'),
('124', '9', '1', 'Vụ chìm tàu trên hồ Thác Bà: Tàu khách chở quá tải, không nhường đường', 'vu-chim-tau-tren-ho-thac-ba-tau-khach-cho-qua-tai-khong-nhuong-duong', 'Tàu số hiệu YB-0876H được chở tối đa 12 người nhưng thực tế chở 23, không nhường đường cho phương tiện trọng tải lớn hơn dẫn đến va chạm, làm 6 người tử vong.', 'Tàu số hiệu YB-0876H được chở tối đa 12 người nhưng thực tế chở 23, không nhường đường cho phương tiện trọng tải lớn hơn dẫn đến va chạm, làm 6 người tử vong.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/2542883888910214992-1772005991-3248-6554-1772011020.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=hnl03qbqNyfH2VA5V-UMRA', NULL, NULL, NULL, 'https://vnexpress.net/vu-chim-tau-tren-ho-thac-ba-tau-khach-cho-qua-tai-khong-nhuong-duong-5043985.html', NULL, '2026-02-25 15:45:12', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":1,\"Gi\\u1ea3i Tr\\u00ed\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:33', '2026-02-25 10:06:33'),
('125', '2', '1', 'Thủ tướng Nhật Bản vướng rắc rối vì tặng quà cho hơn 300 nghị sĩ', 'thu-tuong-nhat-ban-vuong-rac-roi-vi-tang-qua-cho-hon-300-nghi-si', 'Thủ tướng Nhật Bản Sanae Takaichi gây nghi ngại khi tặng quà chúc mừng cho hơn 300 nghị sĩ đảng cầm quyền, mỗi món có giá khoảng 190 USD.', 'Thủ tướng Nhật Bản Sanae Takaichi gây nghi ngại khi tặng quà chúc mừng cho hơn 300 nghị sĩ đảng cầm quyền, mỗi món có giá khoảng 190 USD.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/afp-20260224-ar-20260224103615-3938-4400-1772004910.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=3_K6hIsmFvziowKqwEKsVA', NULL, NULL, NULL, 'https://vnexpress.net/thu-tuong-nhat-ban-vuong-rac-roi-vi-tang-qua-cho-hon-300-nghi-si-5043960.html', NULL, '2026-02-25 15:43:11', '0', '0', '0', '0.25', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":5,\"Th\\u1eddi S\\u1ef1\":5,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:33', '2026-02-25 10:06:33'),
('126', '1', '2', 'Bộ Nông nghiệp và Môi trường lập đường dây nóng tiếp nhận thông tin vi phạm về đất đai', 'bo-nong-nghiep-va-moi-truong-lap-duong-day-nong-tiep-nhan-thong-tin-vi-pham-ve-dat-dai', '\r\n                Trụ sở Bộ Nông nghiệp và Môi trường - Ảnh: C.TUỆBộ trưởng Bộ Nông nghiệp và Môi trường Trần Đức Thắng đã ký ban hành Quyết định số 633 về việc tổ chức tiếp nhận, xử lý thông tin phản...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/screen-shot-2026-02-25-at-142438-17720043653731866074467.png\" id=\"img_208614748547993600\" w=\"1756\" h=\"1192\" alt=\"Bộ Nông nghiệp và Môi trường lập đường dây nóng tiếp nhận thông tin vi phạm về đất đai - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208614748547993600\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/screen-shot-2026-02-25-at-142438-17720043653731866074467.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1756\" height=\"1192\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Trụ sở Bộ Nông nghiệp và Môi trường - Ảnh: C.TUỆ</p></figcaption></figure><p>Bộ trưởng Bộ Nông nghiệp và Môi trường Trần Đức Thắng đã ký ban hành Quyết định số 633 về việc tổ chức tiếp nhận, xử lý thông tin phản ánh của tổ chức, cá nhân đối với các hành vi vi phạm pháp luật trong quản lý và sử dụng đất đai.</p><p>Theo Bộ Nông nghiệp và Môi trường, trong trường hợp thông tin thuộc thẩm quyền địa phương, không quá 5 ngày làm việc kể từ khi tiếp nhận Cục Quản lý đất đai sẽ có văn bản đề nghị UBND cấp tỉnh, Sở Nông nghiệp và Môi trường hoặc UBND cấp xã nơi có vụ việc kiểm tra, xác minh, xử lý.</p><p>Bộ Nông nghiệp và Môi trường cho biết người dân, tổ chức có thể phản ánh thông qua 3 phương thức gồm số điện thoại 0243.629.0196 trong giờ hành chính các ngày làm việc, gửi văn bản trực tiếp hoặc qua bưu điện đến trụ sở bộ (tại số 10 Tôn Thất Thuyết, phường Cầu Giấy, Hà Nội) và phản ánh thông qua trục liên thông văn bản quốc gia.</p><p>Theo đó, nhóm hành vi được tiếp nhận xử lý như các vi phạm về hồ sơ, mốc địa giới hành chính; lập, điều chỉnh, phê duyệt quy hoạch, kế hoạch sử dụng đất; thu hồi đất, bồi thường, hỗ trợ, tái định cư; giao đất, cho thuê đất, chuyển mục đích sử dụng đất; đăng ký, cấp giấy chứng nhận, trưng dụng đất, tài chính đất đai, trình tự, thủ tục hành chính về đất đai…</p><p>Ngoài ra các hành vi như lấn, chiếm đất; hủy hoại đất; sử dụng đất sai mục đích; không đăng ký đất đai; chuyển nhượng, thế chấp không đủ điều kiện; không đưa đất vào sử dụng theo tiến độ cũng sẽ được tiếp nhận để xử lý.</p>                                      <h2>Trong trường hợp cần thiết Cục Quản lý đất đai sẽ đề xuất kiểm tra, thanh tra</h2><p>Bộ Nông nghiệp và Môi trường giao Cục Quản lý đất đai tổ chức tiếp nhận thông tin trên phạm vi cả nước.</p><p>Trong trường hợp cần thiết Cục Quản lý đất đai tiến hành xác minh thông tin, quyết định hoặc đề xuất cơ quan có thẩm quyền quyết định kiểm tra, thanh tra để giải quyết theo quy định của pháp luật.</p>                                  <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/z615709-17719856069811603269039-7-0-757-1200-crop-1771985634617760591579.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Bộ Nông nghiệp và Môi trường lập đường dây nóng tiếp nhận thông tin vi phạm về đất đai - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Ông Nguyễn Thanh Nghị: Ngay trong 2026, xây dựng, ban hành Luật Đất đai sửa đổi<p class=\"VCObjectBoxRelatedNewsItemSapo\">Ông Nguyễn Thanh Nghị nêu rõ lần đầu tiên nội hàm kinh tế nhà nước được xác định một cách đầy đủ, có hệ thống trong một nghị quyết chuyên đề, làm rõ vị trí và mở rộng phạm vi của khu vực này.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/screen-shot-2026-02-25-at-142438-17720043653731866074467-66-0-1164-1756-crop-1772004399575949703157.png', NULL, NULL, NULL, 'https://tuoitre.vn/bo-nong-nghiep-va-moi-truong-lap-duong-day-nong-tiep-nhan-thong-tin-vi-pham-ve-dat-dai-20260225143047362.htm', NULL, '2026-02-25 15:23:05', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":15,\"Th\\u1ebf Gi\\u1edbi\":12,\"Ph\\u00e1p Lu\\u1eadt\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:33', '2026-02-25 10:06:33'),
('127', '2', '2', 'Sun PhuQuoc Airways mở đường bay Hà Nội, TP.HCM - Đà Nẵng, kết nối trung tâm di sản miền Trung', 'sun-phuquoc-airways-mo-duong-bay-ha-noi-tphcm-da-nang-ket-noi-trung-tam-di-san-mien-trung', '\r\n                Máy bay Sun PhuQuoc Airways đáp xuống sân bay Đà Nẵng - Ảnh: KHẢI ĐĂNGLúc 6h15, chuyến bay thương mại đầu tiên của Sun PhuQuoc Airways khởi hành từ sân bay Nội Bài (Hà Nội) đi Đà Nẵn...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/tau-bay-spa-ha-canh-da-nang-1772005564660697301570.jpg\" id=\"img_208617259883319296\" w=\"2560\" h=\"1489\" alt=\"Sun PhuQuoc Airways  - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208617259883319296\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/tau-bay-spa-ha-canh-da-nang-1772005564660697301570.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1489\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Máy bay Sun PhuQuoc Airways đáp xuống sân bay Đà Nẵng - Ảnh: KHẢI ĐĂNG</p></figcaption></figure><p>Lúc 6h15, chuyến bay thương mại đầu tiên của Sun PhuQuoc Airways khởi hành từ sân bay Nội Bài (Hà Nội) đi Đà Nẵng.</p><p>Đến 10h30, chuyến bay từ Tân Sơn Nhất (TP.HCM) cũng cất cánh, đưa những hành khách đầu tiên đến thành phố biển miền Trung.</p><p>Theo Sun PhuQuoc Airways, việc mở đường bay Hà Nội, TP.HCM kết nối Đà Nẵng giúp mở rộng lựa chọn về giờ bay, dịch vụ, đồng thời tăng cường kết nối giữa các trung tâm kinh tế, du lịch lớn.</p><p>Theo kế hoạch, từ ngày 25-2 chặng Hà Nội - Đà Nẵng được khai thác 2 chuyến/ngày và sẽ tăng lên 4 chuyến/ngày từ ngày 1-3.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/tau-bay-spa-ha-canh-da-nang-1-1772005619945620064937.jpg\" id=\"img_208617376669519872\" w=\"2560\" h=\"1706\" alt=\"Sun PhuQuoc Airways mở đường bay Hà Nội, TP.HCM - Đà Nẵng, kết nối trung tâm di sản miền Trung - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208617376669519872\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/tau-bay-spa-ha-canh-da-nang-1-1772005619945620064937.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Khách từ Hà Nội tới sân bay Đà Nẵng ngày 25-2 - Ảnh: KHẢI ĐĂNG</p></figcaption></figure><p>Đường bay TP.HCM - Đà Nẵng duy trì 2 chuyến/ngày ngay khi mở bán. Tiếp đó, từ ngày 15-3, hãng dự kiến đưa vào khai thác đường bay Đà Nẵng - Phú Quốc.</p><p>Sự hiện diện của Sun PhuQuoc Airways tại Đà Nẵng giúp kết nối nguồn khách tới các điểm vui chơi, giải trí lớn tại miền Trung. </p><p>Đặc biệt, Lễ hội Pháo hoa quốc tế Đà Nẵng (DIFF 2026) dự kiến khai mạc cuối tháng 5 với sự tham gia của 10 đội thi hứa hẹn thu hút đông đảo du khách trong và ngoài nước.</p><p>Tính đến cuối tháng 2, Sun PhuQuoc Airways sở hữu 10 tàu bay. Mới đây, hãng ký hợp đồng mua 40 tàu bay thân rộng Boeing 787-9 Dreamliner, tạo nền tảng mở rộng các đường bay xuyên lục địa trong thời gian tới.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/10/15/may-bay-sun-17605417592571863519766-0-91-1543-2560-crop-17605417661662086289515.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Sun PhuQuoc Airways mở đường bay Hà Nội, TP.HCM - Đà Nẵng, kết nối trung tâm di sản miền Trung - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Sun Group chính thức ra mắt Hãng hàng không Sun PhuQuoc Airways<p class=\"VCObjectBoxRelatedNewsItemSapo\">Tối 15-10, tại Hà Nội, Tập đoàn Sun Group tổ chức lễ ra mắt Hãng hàng không Sun PhuQuoc Airways, mở ra mô hình “hàng không nghỉ dưỡng” đầu tiên tại Việt Nam, kết nối Phú Quốc với du khách toàn cầu.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/tau-bay-spa-ha-canh-da-nang-1-1772005619945620064937-0-0-1600-2560-crop-177200572498012854704.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/sun-phuquoc-airways-mo-duong-bay-ha-noi-tp-hcm-da-nang-ket-noi-trung-tam-di-san-mien-trung-20260225145053589.htm', NULL, '2026-02-25 15:10:00', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":4,\"Kinh Doanh\":2,\"\\u0110\\u1eddi S\\u1ed1ng\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:34', '2026-02-25 10:06:34'),
('128', '3', '2', 'Tăng tốc bằng công nghệ: ngân hàng MBV bước vào ‘chế độ số’', 'tang-toc-bang-cong-nghe-ngan-hang-mbv-buoc-vao-che-do-so', '\r\n                                   Khách hàng giao dịch tại quầy của Ngân hàng Việt Nam Hiện Đại (MBV) - Ảnh: DNCC       Công nghệ là ‘nhịp thở’ của vận hành Sự thay đổi của ngân hàng MBV được thể h...', '\r\n                     <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/23/photo-1771841784969-17718417851321467114214.jpg\" type=\"photo\" class=\"\" w=\"1430\" h=\"953\" photoid=\"208274093660659712\" rel=\"lightbox\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/23/photo-1771841784969-17718417851321467114214.jpg\" width=\"1430\" height=\"953\" alt=\"Tăng tốc bằng công nghệ: ngân hàng MBV bước vào ‘chế độ số’ - Ảnh 1.\" title=\"\" fetchpriority=\"high\">              <p data-placeholder=\"Nhập tác giả\">Khách hàng giao dịch tại quầy của Ngân hàng Việt Nam Hiện Đại (MBV) - Ảnh: DNCC</p>       <h2>Công nghệ là ‘nhịp thở’ của vận hành</h2> <p>Sự thay đổi của ngân hàng MBV được thể hiện rõ qua hạ tầng vận hành thông minh và hiệu quả hơn sau quá trình làm mới toàn diện. </p> <p>Là thành viên trẻ trong hệ sinh thái MB Group, ngân hàng tận dụng tối đa lợi thế công nghệ và tiềm lực tài chính từ tập đoàn để tạo ra bước tiến khác biệt. </p> <p>Việc chuyển đổi hệ thống nhận diện thương hiệu từ ngày 1-3-2025 không chỉ làm mới hình ảnh, mà còn mở ra một chương phát triển mới, định vị MBV là ngân hàng năng động, hiện đại và gần gũi hơn với người dùng.</p> <p>Trên nền tảng đó, MBV tập trung thay mới toàn bộ Core Banking, xây dựng hệ thống xử lý giao dịch theo thời gian thực, nhanh và an toàn. </p> <p>Song song, 50 hệ thống nghiệp vụ từ tín dụng, thanh toán đến quản trị rủi ro được tái cấu trúc đồng bộ, hình thành kiến trúc công nghệ liền mạch, giàu dữ liệu. </p> <p>Thời điểm ‘go-live’ của MBV Bank và MBV Biz trở thành bước hoàn thiện quan trọng, đưa toàn bộ quá trình chuyển đổi vào vận hành thực tế và mang đến trải nghiệm số thống nhất, mượt mà cho cả khách hàng cá nhân lẫn doanh nghiệp.</p> <h2>Những con số ấn tượng</h2> <p>Sau một năm chuyển mình mạnh mẽ, những nỗ lực đổi mới của MBV đã chuyển hóa rõ nét thành kết quả thực tế trong năm 2025. Tổng tài sản của ngân hàng ghi nhận mức bứt tốc ấn tượng 172% so với cùng kỳ, tạo tiền đề vững chắc cho quy mô hoạt động trong giai     đoạn mới.</p> <p>Đáng chú ý, ngay trong năm đầu tiên sau khi tái thiết, MBV đã sớm báo lãi, một kết quả minh chứng cho hiệu quả vận hành và chiến lược kinh doanh đúng đắn. Song hành cùng tốc độ tăng trưởng là sự kỷ luật trong quản trị rủi ro khi tỉ lệ nợ xấu tự thân được     kiểm soát chặt chẽ dưới mức 1%. </p> <p>Những con số này không chỉ khẳng định năng lực tài chính ổn định mà còn củng cố niềm tin cho khách hàng và đối tác về một lộ trình phát triển bền vững của MBV.</p> <h2>Kích hoạt 2026: Phát triển trên nền tảng số hóa</h2> <p>Bước vào năm 2026, MBV vận hành với tư thế của một ngân hàng số đúng nghĩa: nền tảng công nghệ hiện đại, quy trình tinh gọn và dữ liệu làm trung tâm cho mọi quyết định. </p> <p>Khách hàng trở thành điểm khởi đầu của thiết kế sản phẩm, trong khi quản trị rủi ro được thiết lập như lớp bảo vệ đa tầng, bảo đảm tăng trưởng đi cùng kiểm soát. </p> <p>Trên nền tảng đó, các sản phẩm và chương trình ưu đãi được triển khai theo hướng gia tăng lợi ích thực chất. </p> <p>Với thông điệp ‘Rinh quà sang, đón Tết an khang’, từ nay đến 28/02/2026, khách hàng gửi tiết kiệm tại quầy hoặc qua ngân hàng số MBV Bank không chỉ tối ưu dòng tiền mà còn có cơ hội sở hữu quà tặng trị giá hàng tỉ đồng như: ô tô VinFast VF8, VF3 cùng     nhiều chuyến du lịch đẳng cấp được trao định kỳ.</p>   <p>Tham khảo ưu đãi cho khách hàng gửi tiết kiệm tại: <i>https://www.mbv.com.vn/tin-tuc/UuDaiSinhNhatMBV</i></p>                      <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/23/photo-1771841786039-1771841786182297910263.jpg\" type=\"photo\" class=\"\" w=\"579\" h=\"579\" photoid=\"208273785503895552\" alt=\"\" title=\"\" loading=\"lazy\" width=\"579\" height=\"579\">                              <p data-placeholder=\"Nhập chú thích ảnh\">MBV triển khai nhiều chương trình khuyến mại hấp dẫn cho Khách hàng gửi tiền - Ảnh: DNCC</p>                               <p>Mỗi bước đi của MBV trong năm 2026 sẽ là sự giao thoa giữa công nghệ tiên phong và sự thấu hiểu sâu sắc nhu cầu thị trường, để mang lại cho khách hàng những sản phẩm, dịch vụ tài chính giá trị và thiết thực.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/23/photo-1771841784969-17718417851321467114214-43-0-937-1430-crop-1771841887647990348608.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/tang-toc-bang-cong-nghe-ngan-hang-mbv-buoc-vao-che-do-so-20260223172353609.htm', NULL, '2026-02-25 15:00:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":15,\"C\\u00f4ng Ngh\\u1ec7\":7,\"Th\\u1ebf Gi\\u1edbi\":3},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:34', '2026-02-25 10:06:34'),
('130', '2', '2', 'Rước lộc dịp Thần Tài 2026 với các sản phẩm vàng độc đáo', 'ruoc-loc-dip-than-tai-2026-voi-cac-san-pham-vang-doc-dao', '\r\n                                    Blindbox vàng 99,99% Mã Tiến Đắc Lộc với hình thức ‘xé túi mù’ - Ảnh: DNCC          Trong đó, PNJ là một trong những thương hiệu sớm định hình xu hướng khi liên t...', '\r\n                                    <p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/11/photo-1770801478520-1770801478850577627856.jpg\" type=\"photo\" class=\"\" w=\"938\" h=\"493\" photoid=\"206092413969588224\" rel=\"lightbox\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/11/photo-1770801478520-1770801478850577627856.jpg\" width=\"938\" height=\"493\" alt=\"thần tài - Ảnh 1.\" title=\"\" fetchpriority=\"high\"></p><p data-placeholder=\"Nhập chú thích ảnh\">Blindbox vàng 99,99% Mã Tiến Đắc Lộc với hình thức ‘xé túi mù’ - Ảnh: DNCC</p>          <p>Trong đó, PNJ là một trong những thương hiệu sớm định hình xu hướng khi liên tục giới thiệu các dòng sản phẩm gắn liền với hình ảnh linh vật ngựa cùng thiết kế độc đáo, khả năng ứng dụng linh hoạt song hành với giá trị tích lũy bền vững.</p><p>Năm 2026 là năm Bính Ngọ theo âm lịch, do đó hình tượng ngựa tự nhiên trở thành biểu tượng chủ đạo. Tuy nhiên, sự xuất hiện dày đặc của linh vật này trong các thiết kế vàng năm nay không chỉ đơn thuần vì yếu tố tuổi. </p><p>Theo đó, hình tượng linh vật ngựa \'phủ sóng\' trong các thiết kế vàng PNJ dịp Thần Tài 2026 còn đại diện cho tinh thần chuyển mình, tiến bước và hành động chủ động \'rước lộc\', tự tay mang may mắn về nhà, khởi đầu cho một năm mới rực rỡ. Cùng điểm qua những phiên bản ngựa vàng đang \'gây sốt\'.</p><h2>Blindbox vàng 99,99% Mã Tiến Đắc Lộc</h2><p>Nhằm gia tăng yếu tố trải nghiệm trong loạt sản phẩm, khuyến khích người mua tiếp cận theo cách mới mẻ hơn, PNJ giới thiệu Blindbox vàng 99,99% Mã Tiến Đắc Lộc với hình thức \'xé túi mù\' độc đáo, nơi yếu tố bất ngờ được kết hợp hài hòa với giá trị tích lũy bền vững.</p><p>Để mỗi lần \'khui hộp\' trở thành khoảnh khắc đầy háo hức, công ty đã thiết kế 5 phiên bản khác nhau để khách hàng sưu tầm: Mã Tấn An Khang - Tượng trưng sức khỏe; Mã Kiến Công Danh - Tượng trưng sự nghiệp; Mã Chiêu Phú Quý - Tượng trưng tài lộc, Mã Kết Hồng Duyên - Tượng trưng tình duyên và Secret với hình tượng Ngựa Chín Hồng Mao quý hiếm. …</p><p>Thêm vào đó, miếng vàng còn được tạo hình theo dáng túi tiền - biểu tượng cất giữ những mong ước đầu năm, như một lời chúc sức khỏe, tài lộc, tình duyên và sự nghiệp hanh thông gửi đến người sở hữu.</p><h2>Vàng mini 99,99% Tiểu Lộc Đại Phát phiên bản Mã Nhi</h2><p>Vàng mini 99,99% Tiểu Lộc Đại Phát trọng lượng 0,3 chỉ được ép seal mỏng nhẹ, hình ảnh chú ngựa đáng yêu với đường nét tròn đầy, mềm mại sẽ là bạn đồng hành lý tưởng, cùng bạn sải bước đón năm mới hanh thông. </p><p>Bên cạnh phiên bản Mã Nhi, PNJ giới thiệu thiệu nhiều thiết kế mới từ các biểu tượng quen thuộc của mùa xuân như con Lân, bánh chưng, bao lì xì, làm đẹp mang đến cảm giác gần gũi và đúng tinh thần Tết.</p>     <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/11/photo-1770801479586-1770801479858144302542.jpg\" type=\"photo\" class=\"\" w=\"938\" h=\"938\" photoid=\"206092415810887680\" rel=\"lightbox\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/11/photo-1770801479586-1770801479858144302542.jpg\" width=\"938\" height=\"938\" alt=\"thần tài - Ảnh 2.\" title=\"\" loading=\"lazy\"><p data-placeholder=\"Nhập tác giả\">Vàng mini 99,99% Tiểu Lộc Đại Phát sẽ cùng bạn sải bước đón năm mới rực rỡ - Ảnh: DNCC</p>          <h2>Charm vàng đa năng 24K (99,9%) Mã Nhi Rước Lộc</h2>     <p>Một sản phẩm khác trong dòng vàng trải nghiệm - Charm vàng đa năng 24K (99,9%) Mã Nhi Rước Lộc có thiết kế vàng nhỏ gọn, hiện đại của công ty cũng ghi nhận phản hồi tích cực từ khách hàng. </p><p>Lấy cảm hứng từ linh vật Ngựa năm 2026, sản phẩm được chế tác tinh xảo, trau chuốt đến từng chi tiết để linh hoạt biến hóa với nhiều vai trò: từ việc có thể sử dụng như món trang sức là charm vòng tay, mề dây chuyền đến móc điện thoại, bag charm cực trendy… </p><p>Một vật phẩm nhỏ xinh nhưng chứa đựng cả lời chúc may mắn đầu năm lẫn giá trị tích lũy bền vững, đủ để khiến bất kỳ ai cũng muốn sở hữu như cách cầu may, giữ lộc bên mình trong năm mới.</p>     <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/11/photo-1770801480521-1770801480641288412809.jpg\" type=\"photo\" class=\"\" w=\"695\" h=\"695\" photoid=\"206092417784307712\" rel=\"lightbox\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/11/photo-1770801480521-1770801480641288412809.jpg\" width=\"695\" height=\"695\" alt=\"thần tài - Ảnh 3.\" title=\"\" loading=\"lazy\"><p data-placeholder=\"Nhập tác giả\">Charm vàng đa năng 24K (99,9%) Mã Nhi Rước Lộc - Ảnh: DNCC</p>          <h2>Bộ sưu tập trang sức vàng 99% Turning Gold</h2>     <p>Song song đó, bộ sưu tập trang sức vàng 99% Turning Gold với ba hình tượng ngựa, hồ ly và bướm mang tinh thần trẻ trung, chủ động cũng góp phần mở rộng trải nghiệm tích lũy vàng, hướng đến nhóm khách hàng có nhu cầu kết hợp giữa làm đẹp và tích lũy. </p>     <p>Không đơn thuần là tài sản để dành, các sản phẩm vàng giờ đây còn dẫn dắt phong cách, phản ánh tinh thần chuyển mình, hành động và sẵn sàng bứt phá của năm Bính Ngọ.</p>     <p>Điểm nhấn của BST là thiết kế có hình tượng Horsie - chú ngựa luôn bản lĩnh và chủ động tiến về phía trước, đồng hành cùng bạn trên hành trình chinh phục mục tiêu năm Bính Ngọ 2026.</p>     <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/11/photo-1770801481529-1770801481638982551838.jpg\" type=\"photo\" class=\"\" w=\"489\" h=\"695\" photoid=\"206092419462029312\" rel=\"lightbox\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/11/photo-1770801481529-1770801481638982551838.jpg\" width=\"489\" height=\"695\" alt=\"thần tài - Ảnh 4.\" title=\"\" loading=\"lazy\"><p data-placeholder=\"Nhập tác giả\">Bộ trang sức Horsie cùng bạn khám phá phiên bản rực rỡ nhất của bản thân - Ảnh: DNCC</p>          <p>Xem thêm thông tin và hình ảnh sản phẩm tại đây https://www.pnj.com.vn/</p>   \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/11/photo-1770801478520-1770801478850577627856-0-3-493-792-crop-177080155633757389464.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/ruoc-loc-dip-than-tai-2026-voi-cac-san-pham-vang-doc-dao-20260211162114739.htm', NULL, '2026-02-25 15:00:00', '0', '0', '0', '0.25', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":5,\"\\u0110\\u1eddi S\\u1ed1ng\":3,\"S\\u1ee9c Kh\\u1ecfe\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:35', '2026-02-25 10:06:35'),
('132', '4', '2', 'Nhật Bản ra mắt nhà sư robot có thể tư vấn chuyện tâm linh', 'nhat-ban-ra-mat-nha-su-robot-co-the-tu-van-chuyen-tam-linh', '\r\n                Giáo sư tại Đại học Kyoto Seiji Kumagai đứng cạnh một robot nhà sư hình người ở Kyoto, miền tây Nhật Bản ngày 24-2 - Ảnh: Kyodo NewsTại buổi trình diễn ở một ngôi chùa hôm 24-2, robo...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/img7ad6dba277ea0d5609d8594436d25ae3930271-17720041817311193737618.jpg\" id=\"img_208614664818352128\" w=\"1270\" h=\"1622\" alt=\"robot - Ảnh 1.\" title=\"Nhật Bản ra mắt robot ‘nhà sư AI’ có thể tư vấn chuyện tâm linh - Ảnh 1.\" rel=\"lightbox\" photoid=\"208614664818352128\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/img7ad6dba277ea0d5609d8594436d25ae3930271-17720041817311193737618.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1270\" height=\"1622\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Giáo sư tại Đại học Kyoto Seiji Kumagai đứng cạnh một robot nhà sư hình người ở Kyoto, miền tây Nhật Bản ngày 24-2 - Ảnh: Kyodo News</p></figcaption></figure><p>Tại buổi trình diễn ở một ngôi chùa hôm 24-2, robot tên Buddharoid mặc áo xám giản dị, chắp tay theo tư thế cầu nguyện và di chuyển trước sự chứng kiến của các phóng viên.</p><p>Một phóng viên trẻ của Đài NHK đã trò chuyện với \"nhà sư\" này, thừa nhận bản thân hay suy nghĩ và lo lắng quá nhiều.</p><p>Với giọng trầm ấm, robot này đáp rằng: \"Phật giáo dạy rằng không nên mù quáng chạy theo suy nghĩ hay hành động vội vàng. Điều cần thiết là làm dịu tâm trí và buông bỏ chính ý nghĩ đó\".</p><p>Theo Hãng tin AFP, robot này được phát triển bởi nhóm của giáo sư Seiji Kumagai thuộc Viện Nghiên cứu tương lai nhân loại, Đại học Kyoto.</p><p>Theo giới thiệu, Buddharoid được tích hợp phiên bản nâng cấp \"BuddhaBotPlus\", sử dụng các mô hình AI từ OpenAI và một số đơn vị khác.</p><p>Hệ thống AI được huấn luyện dựa trên những kinh điển Phật giáo chuyên sâu, cho phép trả lời nhiều câu hỏi, kể cả các vấn đề nhạy cảm mà nhiều người còn e ngại khi chia sẻ trực tiếp với con người.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"02/01/2026 14:26\" data-id=\"20260102113505406\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/1/2/g-enrobotic-toothbrush-17673283681001993030705-43-0-683-1024-crop-1767328382194322876295.jpg\" data-url=\"/nhat-ban-ra-mat-robot-danh-rang-gium-con-nguoi-20260102113505406.htm\" data-title=\"Nhật Bản ra mắt robot đánh răng... giùm con người\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/1/2/g-enrobotic-toothbrush-17673283681001993030705-43-0-683-1024-crop-1767328382194322876295.jpg\" alt=\"Nhật Bản ra mắt robot ‘nhà sư AI’ có thể tư vấn chuyện tâm linh - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Nhật Bản ra mắt robot đánh răng... giùm con ngườiĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Phần mềm này được cài đặt lên robot hình người \"Unitree G1\" do Trung Quốc sản xuất, tạo nên một \"nhà sư AI\" có khả năng vừa trò chuyện vừa thực hiện các cử động giống con người.</p><p>Trước đó, Đại học Kyoto từng giới thiệu robot không sử dụng AI tên Mindar để thuyết giảng. Tuy nhiên Buddharoid được xem là bước tiến mới khi kết hợp AI và robot hình người, vừa có thể đối thoại tâm linh, vừa thể hiện sự hiện diện vật lý tại các không gian tôn giáo.</p><p>Phía trường đại học cho biết các vấn đề đạo đức liên quan đến việc ứng dụng AI trong tôn giáo cần tiếp tục thảo luận. Tuy vậy trong bối cảnh dân số Nhật Bản già hóa và thiếu hụt lao động, robot hình người được kỳ vọng có thể đảm nhận một số nghi lễ do các tu sĩ thực hiện.</p><p>Theo nhận định của trường, việc đưa robot vào lĩnh vực tôn giáo có thể tạo ra một \"sự chuyển đổi mang tính bước ngoặt\" trong văn hóa tín ngưỡng tương lai.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/1/31/robot-17698415357141813619516-1-116-1080-1843-crop-1769842009328681862397.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Nhật Bản ra mắt robot ‘nhà sư AI’ có thể tư vấn chuyện tâm linh - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Tesla khoe robot AI giống người đến \'khó phân biệt\', tính sản xuất 1 triệu con mỗi năm<p class=\"VCObjectBoxRelatedNewsItemSapo\">Tập đoàn Tesla của tỉ phú Elon Musk không ngần ngại bày tỏ tham vọng biến robot AI thành sản phẩm phổ thông, khẳng định \'ai cũng muốn\' sở hữu 1 con.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/img7ad6dba277ea0d5609d8594436d25ae3930271-17720041817311193737618-77-0-871-1270-crop-1772004362804218372995.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/nhat-ban-ra-mat-nha-su-robot-co-the-tu-van-chuyen-tam-linh-20260225142927194.htm', NULL, '2026-02-25 14:59:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"C\\u00f4ng Ngh\\u1ec7\":20,\"Th\\u1ebf Gi\\u1edbi\":10,\"Gi\\u00e1o D\\u1ee5c\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:35', '2026-02-25 10:06:35'),
('133', '2', '3', 'Quảng Trị: Học sinh lớp 4 giao nộp cá thể rái cá quý hiếm', 'quang-tri-hoc-sinh-lop-4-giao-nop-ca-the-rai-ca-quy-hiem', '\n\n                                        \n\n                                                                                Ngày 25.2, thông tin từ Trạm Kiểm lâm Đakrông (Quảng Trị) cho biết đơn vị vừ...', '\n\n                                        \n\n                                                                                <p data-id-seo=\"paragraphs-0\">Ngày 25.2, thông tin từ Trạm Kiểm lâm Đakrông (Quảng Trị) cho biết đơn vị vừa tiếp nhận một cá thể rái cá quý hiếm từ một học sinh trên địa bàn phát hiện được.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/z75630780083484d62fa2910c0f15bd1ac15aaebf50a65-17720101399751381361740.jpg\" id=\"img_208622467752873984\" w=\"2560\" h=\"1920\" alt=\"Quảng Trị: Học sinh lớp 4 giao nộp cá thể rái cá quý hiếm- Ảnh 1.\" title=\"Quảng Trị: Học sinh lớp 4 giao nộp cá thể rái cá quý hiếm- Ảnh 1.\" rel=\"lightbox\" photoid=\"208622467752873984\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/z75630780083484d62fa2910c0f15bd1ac15aaebf50a65-17720101399751381361740.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1920\" data-id-seo=\"image-0\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/z75630780083484d62fa2910c0f15bd1ac15aaebf50a65-17720101399751381361740.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/z75630780083484d62fa2910c0f15bd1ac15aaebf50a65-17720101399751381361740.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Xiếc phát hiện cá thể rái cá bên bờ suối</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: B.H</p></figure><p data-id-seo=\"paragraphs-3\">Trước đó, em Hồ Văn Xiếc (học sinh lớp 4C, Trường Tiểu học Tà Long) trong lúc dạo chơi đã phát hiện cá thể rái cá bên bờ suối trong tình trạng sức khỏe yếu.</p><p data-id-seo=\"paragraphs-4\">Xiếc sau đó đã mang cá thể rái cá về và báo cáo với Ban giám hiệu Trường Tiểu học Tà Long để liên hệ lực lượng kiểm lâm tiến hành tiếp nhận và chăm sóc. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/base64-17720102324431374626166.jpeg\" id=\"img_208622467885858816\" w=\"2560\" h=\"1920\" alt=\"Quảng Trị: Học sinh lớp 4 giao nộp cá thể rái cá quý hiếm- Ảnh 2.\" title=\"Quảng Trị: Học sinh lớp 4 giao nộp cá thể rái cá quý hiếm- Ảnh 2.\" rel=\"lightbox\" photoid=\"208622467885858816\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/base64-17720102324431374626166.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1920\" data-id-seo=\"image-1\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/base64-17720102324431374626166.jpeg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/base64-17720102324431374626166.jpeg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Em Hồ Văn Xiếc bàn giao cá thể rái cá cho lực lượng chức năng</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: B.H</p></figure><p data-id-seo=\"paragraphs-7\">Sau khi tiếp nhận, lực lượng chức năng xác định cá thể rái cá là loài quý hiếm thuộc nhóm IB - động vật quý hiếm được bảo vệ theo quy định của pháp luật.</p><p data-id-seo=\"paragraphs-8\">Hiện Trạm Kiểm lâm Đakrông chuyển cá thể rái cá cho trung tâm cứu hộ gần nhất để chăm sóc, hồi phục sức khỏe trước khi thả về lại môi trường tự nhiên. Đồng thời cũng đã biểu dương về ý thức, việc làm tốt của em Hồ Văn Xiếc.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/z75630780083484d62fa2910c0f15bd1ac15aaebf50a65-17720101399751381361740-197-0-1797-2560-crop-1772010339772434615541.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/quang-tri-hoc-sinh-lop-4-giao-nop-ca-the-rai-ca-quy-hiem-185260225160906321.htm', NULL, '2026-02-25 17:04:00', '0', '0', '0', '0.45', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":9,\"Gi\\u00e1o D\\u1ee5c\":7,\"S\\u1ee9c Kh\\u1ecfe\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:35', '2026-02-25 10:06:35'),
('134', '5', '2', 'Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình lọ lem, tổng tài trong Vì mẹ anh phán chia tay', 'vo-dien-gia-huy-tam-trieu-dang-ke-chuyen-tinh-lo-lem-tong-tai-trong-vi-me-anh-phan-chia-tay', '\r\n                Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình yêu tổng tài - lọ lem trong phim Vì mẹ anh phán chia tay - Ảnh: ĐPCCTuy nhiên, khán giả xem phim hiện nay ngày càng khó tính, liệu công...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-17720020702561226532163.jpeg\" id=\"img_208609813404078080\" w=\"2048\" h=\"1364\" alt=\"Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình lọ lem, tổng tài trong Vì mẹ anh phán chia tay - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208609813404078080\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-17720020702561226532163.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2048\" height=\"1364\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình yêu tổng tài - lọ lem trong phim <i>Vì mẹ anh phán chia tay</i> - Ảnh: ĐPCC</p></figcaption></figure><p class=\"\">Tuy nhiên, khán giả xem phim hiện nay ngày càng khó tính, liệu công thức ngôn tình này có còn đủ sức giúp <i>Vì mẹ anh phán chia tay</i> thu hút người xem. </p><h2 class=\"\">Chuyện tình tréo ngoe trong <i>Vì mẹ anh phán chia tay</i></h2><p class=\"\">Thuộc thể loại lãng mạn - hài hước, <i>Vì mẹ anh phán chia tay</i> dài 16 tập do đạo diễn Vũ Khắc Tuận thực hiện, xoay quanh thiếu gia \"tinh ranh\" Triệu Phú (Võ Điền Gia Huy). Vì muốn tránh cuộc hôn nhân sắp đặt theo lời \"bề trên\", anh giả bị liệt. </p><p class=\"\">Trớ trêu thay, người chăm sóc anh lại là Thanh Tâm (Tam Triều Dâng), là oan gia từ thời đi học cách đây 10 năm. Từ những va chạm đầy mâu thuẫn, cả hai dần nảy sinh tình cảm và cùng nhau vượt qua định kiến.</p><p class=\"\">Khi teaser<i> Vì mẹ anh phán chia tay</i> tung ra, bối cảnh thời học sinh cho thấy một cuộc đụng độ hài hước giữa lớp trưởng Thanh Tâm và Triệu Phú khá căng thẳng, thậm chí đã có lời ước \"Cầu trời cho đừng gặp lại\". Vậy mà sau một thời gian cả hai tái ngộ nhau trong hoàn cảnh trớ trêu, kéo theo những xáo trộn. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/vi-me-anh-phan-chia-tayphotobyvieon-8-17720020161091187819332.png\" id=\"img_208609815041953792\" w=\"2000\" h=\"1333\" alt=\"Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình lọ lem, tổng tài trong Vì mẹ anh phán chia tay - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208609815041953792\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/vi-me-anh-phan-chia-tayphotobyvieon-8-17720020161091187819332.png\" type=\"photo\" style=\"max-width:100%;\" width=\"2000\" height=\"1333\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\"><i>Vì mẹ anh phán chia tay</i> có sự tham gia của diễn viên Hồng Ánh, Lan Hương, phát sóng lúc 20h thứ sáu, thứ bảy trên VieON từ ngày 13-3</p></figcaption></figure><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">Teaser phim <i>Vì mẹ anh phán chia tay</i></p><p class=\"\">Lần đầu đóng cặp, Võ Điền Gia Huy và Lê Tam Triều Dâng được kỳ vọng tạo nên \"phản ứng hóa học\" mới mẻ.</p><p class=\"\">Triều Dâng cũng hài hước chia sẻ trên Facebook: \"Hóa ra yêu một người thì dễ, nhưng để ở cạnh một người thật lâu thì khó đến thế\". Còn Võ Điền Gia Huy hài hước viết rằng \"phim cũng lãng mạn và yêu đương bất chấp lắm\".</p><h2 class=\"\">Mô típ hoàng tử - lọ lem làm sao để công thức cũ, cảm xúc mới?</h2><p class=\"\">Đã có thời mô típ \"hoàng tử - lọ lem\" phủ sóng màn ảnh nhỏ châu Á. Đó là thành công các phim Hàn Quốc <i>Ngôi nhà hạnh phúc, Thư ký kim sao thế?, Hạ cánh nơi anh, Hẹn hò chốn công sở</i>. </p>TIN LIÊN QUAN<ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"03/01/2026 15:22\" data-id=\"20260103104216455\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/1/3/tan-hien-read-only-1767411022056195094194-442-0-1254-1299-crop-1767411655384269111476.jpg\" data-url=\"/phim-truyen-hinh-viet-2026-van-se-nhoc-nhan-keo-khan-gia-20260103104216455.htm\" data-title=\"Phim truyền hình Việt 2026: Vẫn sẽ nhọc nhằn kéo khán giả\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/1/3/tan-hien-read-only-1767411022056195094194-442-0-1254-1299-crop-1767411655384269111476.jpg\" alt=\"Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình lọ lem, tổng tài trong Vì mẹ anh phán chia tay - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title\">Phim truyền hình Việt 2026: Vẫn sẽ nhọc nhằn kéo khán giả</h4></li></ul><p class=\"\">Sức hấp dẫn các phim cho thấy sự bền bỉ của dòng phim ngôn tình lãng mạn theo công thức này.</p><p class=\"\">Tại Việt Nam, khán giả cũng từng yêu thích những câu chuyện tình \"tổng tài - lọ lem\" như <i>Tình yêu và tham vọng, Mối tình đầu của tôi </i>hay như <i>Hương vị tình thân</i>.</p><p class=\"\">Đạo diễn Vũ Khắc Tuận cũng chia sẻ anh tham khảo nhiều \"siêu phẩm\" Hàn Quốc để học hỏi tinh thần làm phim trẻ trung, hiện đại. Trong đó, <i>Ngôi nhà hạnh phúc</i> là phim có mô típ gần gũi, dù đã ra mắt cách đây hơn 20 năm.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/base64-1772002283204150959283.png\" id=\"img_208610124821913600\" w=\"2000\" h=\"1333\" alt=\"Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình lọ lem, tổng tài trong Vì mẹ anh phán chia tay - Ảnh 4.\" title=\"\" rel=\"lightbox\" photoid=\"208610124821913600\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/base64-1772002283204150959283.png\" type=\"photo\" style=\"max-width:100%;\" width=\"2000\" height=\"1333\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Tam Triều Dâng vai Thanh Tâm trong<i> Vì mẹ anh phán chia tay</i> - Ảnh: ĐPCC</p></figcaption></figure><p class=\"\">Dẫu vậy, một thực tế là trong bối cảnh \"gu\" xem phim hiện nay có nhiều thay đổi, yếu tố \"tổng tài - lọ lem\" có lẽ chưa đủ gây tò mò. Khán giả đòi hỏi kịch bản phải có nhiều chi tiết khác mới mẻ hợp lý và đặc biệt là diễn xuất của các diễn viên phải thuyết phục. Ở thể loại này, \"phản ứng hóa học\" giữa hai diễn viên chính đóng vai trò quyết định thành bại.</p><p class=\"\">Với sự kết hợp mới mẻ của Võ Điền Gia Huy và Tam Triều Dâng, liệu họ có thể thổi làn gió mới vào mô típ quen thuộc của phim <i>Vì mẹ anh phán chia tay</i> được kỳ vọng? Liệu chuyện tình oan gia ngõ hẹp này có đủ sức tạo thêm một cơn sốt ngôn tình tổng tài - lọ lem trên màn ảnh Việt?</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/phim-177198703347139401882-4-0-641-1020-crop-17719870775221420800594.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Võ Điền Gia Huy, Tam Triều Dâng kể chuyện tình lọ lem, tổng tài trong Vì mẹ anh phán chia tay - Ảnh 5.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Phim truyền hình khởi động sau Tết: Rộn ràng nhưng nhiều trăn trở<p class=\"VCObjectBoxRelatedNewsItemSapo\">Sau kỳ nghỉ Tết, từ mùng 6 nhiều đoàn phim truyền hình trở lại trường quay.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/vi-me-anh-phan-chia-tayphotobyvieon-11-1772002016103637564886-151-312-1052-1754-crop-1772002311081727083820.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/vo-dien-gia-huy-tam-trieu-dang-ke-chuyen-tinh-lo-lem-tong-tai-trong-vi-me-anh-phan-chia-tay-20260225140416133.htm', NULL, '2026-02-25 14:54:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Gi\\u1ea3i Tr\\u00ed\":27,\"Th\\u1ebf Gi\\u1edbi\":9,\"\\u0110\\u1eddi S\\u1ed1ng\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:36', '2026-02-25 10:06:36'),
('135', '1', '3', 'Con trai bầu Hiển ứng cử đại biểu HĐND TP.Hà Nội', 'con-trai-bau-hien-ung-cu-dai-bieu-hdnd-tpha-noi', '\n\n                                        \n\n                                                                                Chiều 25.2, Ban thường trực Ủy ban Mặt trận tổ quốc Việt Nam TP.Hà Nội tổ ch...', '\n\n                                        \n\n                                                                                <p data-id-seo=\"paragraphs-0\">Chiều 25.2, Ban thường trực Ủy ban Mặt trận tổ quốc Việt Nam TP.Hà Nội tổ chức hội nghị gặp mặt các ứng viên đại biểu Quốc hội (ĐBQH) khóa XVI và đại biểu HĐND TP.Hà Nội nhiệm kỳ 2026 - 2031.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/hdnd-tp-ha-noi-17720098727181784737802.jpg\" id=\"img_208621905014456320\" w=\"2560\" h=\"1707\" alt=\"Con trai bầu Hiển ứng cử đại biểu HĐND TP.Hà Nội- Ảnh 1.\" title=\"Con trai bầu Hiển ứng cử đại biểu HĐND TP.Hà Nội- Ảnh 1.\" rel=\"lightbox\" photoid=\"208621905014456320\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/hdnd-tp-ha-noi-17720098727181784737802.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" data-id-seo=\"image-0\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/hdnd-tp-ha-noi-17720098727181784737802.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/hdnd-tp-ha-noi-17720098727181784737802.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Chủ tịch HĐND TP.Hà Nội, Chủ tịch Ủy ban Bầu cử TP.Hà Nội Phùng Thị Hồng Hà phát biểu tại hội nghị</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: KHẮC HIẾU</p></figure><p data-id-seo=\"paragraphs-3\">Phát biểu tại hội nghị, Chủ tịch HĐND TP.Hà Nội, Chủ tịch Ủy ban Bầu cử TP.Hà Nội Phùng Thị Hồng Hà cho biết, Ủy ban Bầu cử thành phố đã công bố danh sách chính thức các ứng viên sau ba vòng hiệp thương dân chủ, công khai, minh bạch.</p><p data-id-seo=\"paragraphs-4\">Tổng cộng có 54 người ứng cử ĐBQH, trong đó 39 người do Hà Nội giới thiệu, và 205 người ứng cử đại biểu HĐND thành phố.</p><p data-id-seo=\"paragraphs-5\">Theo thống kê, đối với HĐND TP.Hà Nội, trong 205 ứng viên có 149 người có trình độ sau đại học (60,1%), 107 nữ ứng viên (43,1%), 84 người dưới 40 tuổi, 34 người ngoài Đảng và 50 người tái cử.</p><p data-id-seo=\"paragraphs-6\">Bà Phùng Thị Hồng Hà cho rằng hội nghị không chỉ là buổi gặp mặt mà còn là diễn đàn cập nhật thông tin phát triển kinh tế - xã hội, định hướng chiến lược của Thủ đô, qua đó giúp ứng viên xây dựng nội dung vận động bầu cử sát thực tiễn. Bà cũng lưu ý, vận động bầu cử không chỉ là quyền mà còn là trách nhiệm chính trị to lớn trước Đảng và nhân dân.</p><p data-id-seo=\"paragraphs-7\">Do đó, các ứng viên cần tuân thủ Hiến pháp và pháp luật; thực hiện vận động bầu cử một cách dân chủ, bình đẳng, lành mạnh và đúng mực; không phô trương hình thức, không hứa hẹn vượt thẩm quyền, không làm ảnh hưởng đến uy tín của các tổ chức, cá nhân khác; giữ gìn đoàn kết, tôn trọng lẫn nhau giữa các ứng cử viên, hướng tới mục tiêu phục vụ nhân dân.</p><p data-id-seo=\"paragraphs-8\">\"Thông qua tiếp xúc, cử tri ứng cử được hiểu hơn đời sống thực tiễn, những băn khoăn, kỳ vọng và mong muốn của người dân. Đó chính là hành trang quan trọng nếu sau này được bầu làm đại biểu\", bà Hà nói.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/con-trai-bau-hien-1772009877539909188753.jpg\" id=\"img_208621910763802624\" w=\"2560\" h=\"1707\" alt=\"Con trai bầu Hiển ứng cử đại biểu HĐND TP.Hà Nội- Ảnh 2.\" title=\"Con trai bầu Hiển ứng cử đại biểu HĐND TP.Hà Nội- Ảnh 2.\" rel=\"lightbox\" photoid=\"208621910763802624\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/con-trai-bau-hien-1772009877539909188753.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" data-id-seo=\"image-1\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/con-trai-bau-hien-1772009877539909188753.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/con-trai-bau-hien-1772009877539909188753.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Ông Đỗ Vinh Quang tham dự hội nghị chiều 25.2</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: KHẮC HIẾU</p></figure><p data-id-seo=\"paragraphs-11\">Theo Quyết định số 50/QĐ-UBBC của Ủy ban Bầu cử TP.Hà Nội, toàn thành phố có 205 ứng viên tại 31 đơn vị bầu cử để lựa chọn 125 đại biểu HĐND nhiệm kỳ mới.</p><p data-id-seo=\"paragraphs-12\">Trong đó, ông Đỗ Vinh Quang (31 tuổi; cư trú tại P.Cửa Nam, Hà Nội) ứng cử tại đơn vị bầu cử số 30, gồm các xã Mê Linh, Yên Lãng, Tiến Thắng và Quang Minh. Đơn vị này có 7 ứng viên, dự kiến bầu 4 đại biểu.</p><p data-id-seo=\"paragraphs-13\">Ông Đỗ Vinh Quang là con trai thứ 2 của ông Đỗ Quang Hiển (bầu Hiển), nhà sáng lập T&amp;T Group, đồng thời là Chủ tịch HĐQT Ngân hàng TMCP Sài Gòn - Hà Nội (SHB). Ông Quang có trình độ thạc sĩ quản trị tài chính.</p><p data-id-seo=\"paragraphs-14\">Ông Quang hiện là Phó chủ tịch HĐQT kiêm Phó tổng giám đốc T&amp;T Group, đồng thời giữ vai trò Phó chủ tịch Hiệp hội Doanh nghiệp nhỏ và vừa TP.Hà Nội.</p><p data-id-seo=\"paragraphs-15\">Song song đó, ông Quang hiện đảm nhiệm vị trí quản lý tại nhiều doanh nghiệp như: Chủ tịch CLB Bóng đá Hà Nội - HanoiFC (từ 2019), Chủ tịch HĐQT Vietravel Airlines (từ 2025)…</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/con-trai-bau-hien-1772009877539909188753-0-0-1600-2560-crop-17720099405952007415149.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/con-trai-bau-hien-ung-cu-dai-bieu-hdnd-tpha-noi-18526022516005765.htm', NULL, '2026-02-25 17:01:00', '1', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":17,\"Kinh Doanh\":5,\"Th\\u1ebf Gi\\u1edbi\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:36', '2026-02-25 10:35:25'),
('136', '3', '2', 'Thỏ ơi!! thu 300 tỉ đồng sau 9 ngày', 'tho-oi-thu-300-ti-dong-sau-9-ngay', '\r\n                Trấn Thành tung bộ ảnh chụp cùng dàn diễn viên chính của Thỏ ơi!! gồm Ly Ly, Pháo, Văn Mai Hương, Quốc Anh, Vĩnh Đam - Ảnh: FBNVTheo số liệu của The Box Office Vietnam, Thỏ ơi!! đang...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/64034044215179494030286578361289661967455561n-1772003336349607675970.jpg\" id=\"img_208612893083525120\" w=\"1406\" h=\"2048\" alt=\"Thỏ ơi - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208612893083525120\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/64034044215179494030286578361289661967455561n-1772003336349607675970.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1406\" height=\"2048\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Trấn Thành tung bộ ảnh chụp cùng dàn diễn viên chính của Thỏ ơi!! gồm Ly Ly, Pháo, Văn Mai Hương, Quốc Anh, Vĩnh Đam - Ảnh: FBNV</p></figcaption></figure><p>Theo số liệu của The Box Office Vietnam, <i>Thỏ ơi!!</i> đang dẫn đầu doanh thu phòng vé kể từ khi ra mắt, thu 303 tỉ đồng sau 9 ngày chiếu rạp, góp mặt trong nhóm 10 phim Việt ăn khách nhất lịch sử.</p><p>Trong khi đó, năm 2025, <i>Bộ tứ báo thủ </i>mất đến 12 ngày mới chạm đến mốc này. Năm 2024, <i>Mai </i>cán mốc 310 tỉ đồng sau 9 ngày ra rạp. Còn năm 2023, <i>Nhà bà Nữ </i>đạt 300 tỉ đồng sau 11 ngày chiếu.</p><h2><i>Thỏ ơi!! </i>liệu có vượt qua thành tích của <i>Mai</i>?</h2><p>Nhìn chung, <i>Thỏ ơi!!</i> đang có mức độ \"nhiệt\" và lượng suất chiếu mỗi ngày hơn 4.000 suất, áp đảo ba phim Việt còn lại gồm <i>Báu vật trời cho, Nhà ba tôi một phòng</i> và <i>Mùi phở.</i></p><p>Chính sự mất cân bằng này và hiệu ứng từ thương hiệu Trấn Thành khiến ngôi vương bảng doanh thu phòng vé trong những ngày Tết Nguyên đán vừa qua không có sự thay đổi.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/tho-oi-1772003700354311279511.png\" id=\"img_208613657600286720\" w=\"1500\" h=\"750\" alt=\"Thỏ ơi - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208613657600286720\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/tho-oi-1772003700354311279511.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1500\" height=\"750\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Vai diễn của Văn Mai Hương trong Thỏ ơi!! nhận cơn mưa lời khen - Ảnh: ĐPCC</p></figcaption></figure><p>Trên Facebook, đạo diễn Trấn Thành không giấu được sự vui mừng, chia sẻ: 300 tỉ rồi. Vui quá bà con ơi. Cả nhà giúp em đẩy <i>Thỏ ơi!! </i>qua mặt <i>Mai</i> luôn giùm em được không? Tới đi cả nhà ơi!\".</p><p>Điều này hoàn toàn có khả thi, nếu <i>Thỏ ơi!! </i>giữ sức hút và độ tăng trưởng như bây giờ. <i>Mai</i> có doanh thu là 551 tỉ đồng, từng là phim Việt ăn khách nhất mọi thời đại. Tuy nhiên thành tích này bị vượt qua bởi phim <i>Mưa đỏ</i> vào tháng 9-2025.</p><p>Trước đó, chỉ trong vòng 24 giờ đầu ra rạp, <i>Thỏ ơi!! </i>cán mốc 45 tỉ đồng doanh thu. Con số này giúp phim xác lập kỷ lục doanh thu ngày đầu cao nhất của điện ảnh Việt, vượt qua thành tích 40 tỉ đồng mà<i> Mưa đỏ </i>từng ghi nhận trong năm 2025.</p><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">Trailer Thỏ ơi!!</p><p>Ngay cả trước khi công chiếu, <i>Thỏ ơi!! </i>sớm tạo nên cơn sốt truyền thông. Trong dịp Tết Nguyên đán, lượng vé đặt trước chạm mốc 130.000 - con số hiếm thấy đối với thị trường nội địa. Thành tích này giúp <i>Thỏ ơi!!</i> thiết lập kỷ lục phim có số vé bán sớm cao nhất mọi thời đại trong mùa Tết.</p>TIN LIÊN QUAN<ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"21/02/2026 11:18\" data-id=\"20260221110305463\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/21/tran-thanh-17716465308701325557915-0-120-675-1200-crop-1771646564320101003338.jpg\" data-url=\"/tran-thanh-xin-ngung-quay-len-phim-tho-oi-xin-moi-nguoi-thuong-em-20260221110305463.htm\" data-title=\"Trấn Thành xin ngừng quay lén phim \'Thỏ ơi!!\': \'Xin mọi người thương em\'\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/21/tran-thanh-17716465308701325557915-0-120-675-1200-crop-1771646564320101003338.jpg\" alt=\"Thỏ ơi!! thu 300 tỉ đồng sau 9 ngày - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title\">Trấn Thành xin ngừng quay lén phim \'Thỏ ơi!!\': \'Xin mọi người thương em\'</h4></li></ul><p>Được Trấn Thành đầu tư kinh phí lên tới 2 triệu USD, <i>Thỏ ơi!! </i>không còn khai thác trực diện nước mắt hay những cao trào drama quen thuộc. Thay vào đó, phim lựa chọn cấu trúc đối chất và thủ pháp giấu thông tin để tạo kịch tính.</p><p>Khởi nguồn từ một câu chuyện tình cảm cá nhân được đưa lên sóng talkshow, <i>Thỏ ơi!!</i> dần mở rộng biên độ thành cuộc tranh luận về đạo đức, niềm tin và quyền phán xét trong không gian công cộng.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/thofstvn-textless25120500004210still028-17720039850911170093252.jpg\" id=\"img_208614254934188032\" w=\"1200\" h=\"604\" alt=\"Thỏ ơi - Ảnh 3.\" title=\"\" rel=\"lightbox\" photoid=\"208614254934188032\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/thofstvn-textless25120500004210still028-17720039850911170093252.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1200\" height=\"604\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Thỏ ơi!! không bị chê dở đến mức như Bộ tứ báo thủ, nên dự kiến doanh thu đường dài sẽ cao hơn.</p></figcaption></figure><p><i>Thỏ ơi!! </i>nhận về nhiều ý kiến trái chiều, song phần đông khán giả đánh giá phim có chất lượng nhỉnh hơn phim top 1 năm ngoái là<i> Bộ tứ báo thủ, </i>nhưng vẫn còn thua xa <i>Mai.</i></p><p>Trấn Thành có sự tiến bộ về tay nghề, nhất là ở khâu dựng phim. Nhưng chất lượng phim vẫn gây tranh cãi, nhiều người cho rằng 1/3 thời lượng cuối phim gây cảm giác \"đầu voi đuôi chuột\". Cái kết bạo lực gây sốc, thiếu lắng đọng.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/23/tran-thanh-17718149683811529474987-60-309-577-1136-crop-17718150077162031741470.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Thỏ ơi!! thu 300 tỉ đồng300 tỷ rồi!!! Vui quá bà con ơi!!! Cả nhà giúp em đẩy nó qua mặt con MAI luô - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Phim Tết 2026: Doanh thu kỷ lục, chất lượng chưa xứng tầm và \'show, don\'t tell\'<p class=\"VCObjectBoxRelatedNewsItemSapo\">Tính đến sáng 23-2, 4 phim Tết của Việt Nam đạt doanh thu 410 tỉ đồng sau 6 ngày Tết. Đây là mức doanh thu kỷ lục, nhiều khả năng vượt xa phim Tết 2025.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/tho-oi-1772003700354311279511-0-138-750-1338-crop-177200373326257778512.png', NULL, NULL, NULL, 'https://tuoitre.vn/tho-oi-thu-300-ti-dong-sau-9-ngay-20260225142134524.htm', NULL, '2026-02-25 14:52:00', '0', '0', '0', '0.45', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":9,\"Gi\\u1ea3i Tr\\u00ed\":4,\"Th\\u1ebf Gi\\u1edbi\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:36', '2026-02-25 10:06:36'),
('137', '2', '3', 'Xổ số miền Nam ngày 25 tháng 2: Lộ diện nhiều vé trúng đài Đồng Nai', 'xo-so-mien-nam-ngay-25-thang-2-lo-dien-nhieu-ve-trung-dai-dong-nai', '\n\n                                        \n\n                                                                                Theo kết quả xổ số miền Nam ngày 25 tháng 2, hàng loạt vé trúng an ủi đài Đồ...', '\n\n                                        \n\n                                                                                <p>Theo kết quả xổ số miền Nam ngày 25 tháng 2, hàng loạt vé trúng an ủi đài Đồng Nai xuất hiện sớm ở một đại lý vé số ở Đồng Nai nhận được sự chú ý của người chơi xổ số.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-164818-17720129132961380723907.png\" id=\"img_208628278406184960\" w=\"1496\" h=\"920\" alt=\"Xổ số miền Nam ngày 25 tháng 2: Bất ngờ vé trúng đài Đồng Nai - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208628278406184960\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-164818-17720129132961380723907.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1496\" height=\"920\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-164818-17720129132961380723907.png 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-164818-17720129132961380723907.png 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Theo kết quả xổ số miền Nam ngày 25 tháng 2, hàng loạt vé trúng an ủi đài Đồng Nai xuất hiện sớm ở một đại lý vé số ở Đồng Nai</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: NVCC</p></figure><p>Cụ thể, những tờ vé có dãy may mắn 222931 trúng xổ số Đồng Nai ngày 25 tháng 2. Trong khi đó, dãy độc đắc của đài này là 222731. Mỗi vé trị giá 6 triệu đồng. \"Giải khuyến khích xuất hiện. Chúc mừng khách em đầu năm có lộc\", chị Trần Ngọc Diễm, phía đại lý chia sẻ.</p><p>Tại TP.HCM (Bình Dương cũ), hàng loạt vé trúng giải sáu đài Đồng Nai xổ số ngày 25 tháng 2 cũng lộ diện. Cụ thể, những tờ vé có dãy số cuối may mắn là 0748. Phía đại lý cũng chúc mừng cho những vị khách may mắn.</p><p>Xổ số ngày 25 tháng 2 còn mở thưởng thêm đài Cần Thơ với dãy số độc đắc 630738 và đài Sóc Trăng với dãy số độc đắc 046969. Nhiều người để lại bình luận mong chờ chủ nhân những tờ vé trúng độc đắc lộ diện.</p><p>Theo kết quả xổ số miền Nam ngày 24 tháng 2, những tờ vé có dãy số cuối là 912 thuộc đài Bến Tre trúng giải bảy. Những tờ có dãy số này tiếp tục trúng thêm giải tám khi có 2 số cuối là 12. Giải bảy mỗi tờ trị giá 200.000 đồng còn giải tám mỗi tờ trị giá 100.000 đồng.</p><p>Trong khi đó, những tờ vé có 2 số cuối 44 trúng giải tám đài Vũng Tàu cũng theo kết quả xổ số ngày 24 tháng 2. Điều này đồng nghĩa với việc những tờ vé có dãy số 444444 cũng trúng giải này chiều qua.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-164818-17720129132961380723907-0-0-920-1472-crop-17720129412781212148182.png', NULL, NULL, NULL, 'https://thanhnien.vn/xo-so-mien-nam-ngay-25-thang-2-lo-dien-nhieu-ve-trung-dai-dong-nai-185260225165057297.htm', NULL, '2026-02-25 17:00:00', '0', '0', '0', '0.35', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":7,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:36', '2026-02-25 10:06:36'),
('138', '2', '2', 'Vé số Tết, hôm nay đã bán cho 2 ngày sau', 've-so-tet-hom-nay-da-ban-cho-2-ngay-sau', '\r\n                Vé số tại miền Tây tiêu thụ rất mạnh vào dịp Tết Nguyên đán - Ảnh: LÊ DÂNNgày 25-2, ông Trung Hiếu - chủ một đại lý vé số tại phường Cái Răng (thành phố Cần Thơ) - cho biết vé số vào...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/ve-so-ledan-17720024434381948410194.jpg\" id=\"img_208610710685241344\" w=\"1848\" h=\"4000\" alt=\"vé số - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208610710685241344\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/ve-so-ledan-17720024434381948410194.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1848\" height=\"4000\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Vé số tại miền Tây tiêu thụ rất mạnh vào dịp Tết Nguyên đán - Ảnh: LÊ DÂN</p></figcaption></figure><p>Ngày 25-2, ông Trung Hiếu - chủ một đại lý vé số tại phường Cái Răng (thành phố Cần Thơ) - cho biết vé số vào dịp Tết Nguyên đán Bính Ngọ luôn trong tình trạng \"cháy hàng\". </p><p>Tới thời điểm này vé số truyền thống vẫn chưa “hết nóng”, hôm nay thứ tư 25-2 người bán dạo đã lấy vé số ngày thứ sáu để bán. “Ngày mai vía Thần Tài càng bán dữ nữa. Ngày Tết người dân thường mua vé số để cầu may, hy vọng trong năm mới”, ông Hiếu cho hay.</p><p>Dẫn chứng về việc vé số hút hàng, ông V.Lộc (phường An Bình, thành phố Cần Thơ) kể Tết ông về quê ở Đồng Tháp đi thăm chúc Tết bà con, dự định mua vé số tặng nhau lấy lộc đầu năm nhưng không gặp người bán vé số dạo.</p><p> “Hỏi ra mới biết mấy ngày Tết người bán vé số dạo chỉ cần đi bán ở chợ hoặc quán xá là đã hết vé số nên không cần đi đến khu vực nông thôn”, ông V.Lộc nói.</p><p>Tại miền Tây, người dân có thói quen đầu năm mới hay mua vé số và mua nhiều hơn ngày thường để tặng nhau lấy lộc đầu năm thay cho lì xì.</p><p>Còn ông Chấn Nam - chủ đại lý vé số tại phường Vị Thanh (thành phố Cần Thơ) - cho hay người bán vé số của đại lý ông mấy ngày Tết luôn hết vé sớm.</p><p>“Sáng giờ có rất nhiều người đến lấy vé số xổ ngày thứ sáu, thậm chí có người lấy ngày thứ bảy để bán. Bán chạy nên nhiều người muốn lấy thêm vé nhưng không được”, ông Nam thông tin.</p><p>Theo ông Nam, những ngày tới vé số vẫn còn tiêu thụ mạnh, không đủ để bán vì người dân vẫn thích vé số truyền thống, nhất là những ngày đầu năm mới.</p><p>Lãnh đạo một công ty xổ số kiến thiết tại miền Tây xác nhận tỉ lệ tiêu thụ vé số của công ty mấy tuần qua đều đạt 100%.</p><p>Tết Nguyên đán Bính Ngọ, các công ty xổ số kiến thiết khu vực miền Nam tăng doanh số phát hành 4 kỳ, gồm 1 kỳ trước Tết và 3 kỳ sau Tết, bắt đầu từ ngày 10-2 đến ngày 9-3 (nhằm ngày 23 tháng chạp đến ngày 21 tháng giêng).</p><p>Mỗi công ty xổ số sẽ phát hành 16 triệu vé (tương đương 160 tỉ đồng) thay vì 14 triệu vé/đợt phát hành như ngày bình thường.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/10/ve-so-tet-1770692448376175797074-472-0-1372-1440-crop-17706924562351531578239.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Vé số Tết, hôm nay đã bán cho 2 ngày sau - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Vé số miền Nam \'bung vé\' dịp Tết, tăng lên 16 triệu vé mỗi kỳ<p class=\"VCObjectBoxRelatedNewsItemSapo\">Từ 10-2, vé số miền Nam sẽ tăng thêm 2 triệu vé, lên 16 triệu vé/kỳ nhằm phục vụ nhu cầu vui chơi có thưởng tăng cao vào dịp Tết.</p> \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/ve-so-177200255585958167887-179-0-1174-1592-crop-1772002564010241509259.png', NULL, NULL, NULL, 'https://tuoitre.vn/ve-so-tet-hom-nay-da-ban-cho-2-ngay-sau-20260225140559467.htm', NULL, '2026-02-25 14:49:00', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":4,\"S\\u1ee9c Kh\\u1ecfe\":3,\"Kinh Doanh\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:37', '2026-02-25 10:06:37'),
('139', '4', '3', 'Toàn cảnh 17h: Lời khai điều dưỡng vụ tử vong sau khi truyền trắng da | Hành hung tài xế trước cửa nhà', 'toan-canh-17h-loi-khai-dieu-duong-vu-tu-vong-sau-khi-truyen-trang-da-hanh-hung-tai-xe-truoc-cua-nha', '\n                        \n                                                                            \n                        Toàn cảnh 17h ngày 25.2.2026 của Báo Thanh Niên có nhiều thông tin đáng c...', '\n                        \n                                                                            \n                        <p data-id-seo=\"paragraphs-0\"><i>Toàn cảnh 17h </i>ngày 25.2.2026 của Báo <i>Thanh Niên </i>có nhiều thông tin đáng chú ý:</p><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">Toàn cảnh 17h ngày 27.2: Lời khai điều dưỡng vụ tử vong sau khi truyền trắng da | Hành hung tài xế trước cửa nhà </p><h2>Vụ cô gái tử vong sau khi truyền trắng da tại nhà: Nữ điều dưỡng khai gì?</h2><p data-id-seo=\"paragraphs-0\">Liên quan vụ cô gái tử vong sau khi làm đẹp bằng phương pháp truyền trắng da, ngày 25.2, nguồn tin của PV Thanh Niên cho biết, cơ quan chức năng đã lấy lời khai với những người liên quan, làm rõ diễn biến vụ việc.</p><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">Vụ cô gái tử vong sau khi truyền trắng da tại nhà: Nữ điều dưỡng khai gì?</p><h2>Mua đồ công nghệ \"secondhand\" nên tránh 6 thiết bị này</h2><p>Khi giá linh kiện điện tử như bộ nhớ hay thiết bị lưu trữ tăng cao, không ngạc nhiên khi nhiều người chuyển sang lựa chọn các thiết bị công nghệ đã qua sử dụng.</p><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">6 thiết bị công nghệ đã qua sử dụng nên tránh mua</p><h2><br></h2><p>Tất cả sẽ có trong bản tin<i> Toàn cảnh 17h,</i> được phát trên <i>thanhnien.vn</i> cùng kênh YouTube Báo <i>Thanh Niên. </i>Kính mời quý vị theo dõi.</p>\n\n                        \n\n\n\n                        \n        \n\n        \n        \n    \n                        \n                        \n\n                        \n\n\n                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/avatar1772012660493-1772012663207321509496.jpeg', NULL, NULL, NULL, 'https://thanhnien.vn/toan-canh-17h-loi-khai-dieu-duong-vu-tu-vong-sau-khi-truyen-trang-da-hanh-hung-tai-xe-truoc-cua-nha-185260225162243413.htm', NULL, '2026-02-25 17:00:00', '0', '0', '0', '0.15', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"C\\u00f4ng Ngh\\u1ec7\":3,\"Th\\u1ebf Gi\\u1edbi\":2,\"Gi\\u1ea3i Tr\\u00ed\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:37', '2026-02-25 10:06:37'),
('140', '2', '2', 'Trần Quyết Chiến, Nguyễn Trần Thanh Tự sẵn sàng chinh phục danh hiệu thế giới', 'tran-quyet-chien-nguyen-tran-thanh-tu-san-sang-chinh-phuc-danh-hieu-the-gioi', '\r\n                Trần Quyết Chiến bắt đầu hành trình chinh phục Giải đồng đội thế giới - Ảnh: UMBSự kết hợp lạ mà quenGiải billiards carom 3 băng đồng đội thế giới là sân chơi đã mang đến nhiều niềm...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/5/23/tran-quyet-chien-world-cup-billiards-tphcm--1748013513077985574852.jpg\" id=\"img_158297885386956800\" w=\"2048\" h=\"1365\" alt=\"Trần Quyết Chiến - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"158297885386956800\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2025/5/23/tran-quyet-chien-world-cup-billiards-tphcm--1748013513077985574852.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2048\" height=\"1365\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Trần Quyết Chiến bắt đầu hành trình chinh phục Giải đồng đội thế giới - Ảnh: UMB</p></figcaption></figure><h2>Sự kết hợp lạ mà quen</h2><p>Giải billiards carom 3 băng đồng đội thế giới là sân chơi đã mang đến nhiều niềm vui cho Trần Quyết Chiến. Cùng với Bao Phương Vinh, bộ đôi này giành chức vô địch lịch sử năm 2024.</p><p>Một năm sau, cặp VĐV này tiếp tục tiến vào đến trận chung kết rồi về nhì khi để thua đôi Dick Jaspers - Jean Paul De Bruijn (Hà Lan). Dù sao thành tích 2 năm liên tiếp vào đến trận tranh chức vô địch của họ cũng đủ khiến người hâm mộ Việt Nam tự hào.</p><p>Năm nay, Trần Quyết Chiến tiếp tục được góp mặt tại Giải billiards carom 3 băng đồng đội thế giới nhờ là người có số điểm cao nhất trong hệ thống quốc gia. Nhưng đồng hành cùng anh không còn là Bao Phương Vinh.</p><p>Thay vào đó thì Nguyễn Trần Thanh Tự - nhà vô địch quốc gia 2025, là cái tên được lựa chọn. Đây là sự kết hợp khá thú vị bởi ngoài đời, hai cơ thủ này khá thân thiết với nhau.</p><p>Do đó Quyết Chiến và Thanh Tự có sự hiểu nhau nhất định, một yếu tố quan trọng ở các giải đồng đội. Dù chưa từng \"bắt cặp\" với nhau ở sân chơi quốc tế thì bộ đôi này vẫn là sự kết hợp không quá xa lạ.</p><h2>Lợi thế lớn của Quyết Chiến - Thanh Tự</h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2024/7/12/nguyen-tran-thanh-tu-billiards-carom-3-bang-porto--17207994647111780636844.jpg\" id=\"img_736249106341421056\" w=\"1294\" h=\"1043\" alt=\"Trần Quyết Chiến, Nguyễn Trần Thanh Tự sẵn sàng chinh phục danh hiệu thế giới - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"736249106341421056\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2024/7/12/nguyen-tran-thanh-tu-billiards-carom-3-bang-porto--17207994647111780636844.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1294\" height=\"1043\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nguyễn Trần Thanh Tự là cơ thủ mạnh trong nước - Ảnh: TTO</p></figcaption></figure><p>Ở các sân chơi quốc tế thì Trần Quyết Chiến đã thuộc vào hàng đẳng cấp thế giới. Bao Phương Vinh thì cũng từng lọt vào top 10, và cũng đã vô địch thế giới và đồng đội thế giới.</p><p>Trong khi đó, Thanh Tự vẫn còn là cái tên xa lạ ở đấu trường thế giới. Tuy nhiên ở trong nước, anh từng nhiều lần đánh bại những đối thủ \"sừng sỏ\", trong đó có cả Trần Quyết Chiến hay Bao Phương Vinh, Trần Thanh Lực, Trần Đức Minh,…</p><p>Một bình luận viên nổi tiếng trong giới billiards ở Việt Nam nhận xét rằng: \"Ở giải đồng đội thế giới, khoảng cách trình độ giữa hai cơ thủ cùng một đội càng nhỏ thì lợi thế càng lớn. Quyết Chiến, Thanh Tự đều là những người có chuyên môn tốt, nên đó sẽ là thuận lợi rất lớn của tuyển Việt Nam. Đây cũng từng là lợi thế khi Quyết Chiến kết hợp với Bao Phương Vinh\".</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"22/12/2025 09:59\" data-id=\"20251222094953526\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/12/22/tran-quyet-chien-blois-3-cushion-challenge-billiards-3-17663716730602007479921-194-0-848-1046-crop-17663717109271238384390.jpeg\" data-url=\"/khong-dau-sea-games-tran-quyet-chien-thang-thuyet-phuc-tai-phap-nhan-gan-1-ti-20251222094953526.htm\" data-title=\"Không đấu SEA Games, Trần Quyết Chiến thắng thuyết phục tại Pháp, nhận gần 1 tỉ\"><h4 class=\"kbwscwlrl-title\">Không đấu SEA Games, Trần Quyết Chiến thắng thuyết phục tại Pháp, nhận gần 1 tỉ</h4></li></ul><p>Ở Giải billiards carom 3 băng đồng đội thế giới sắp tới, Việt Nam nằm tại bảng B cùng với chủ nhà Đức, Pháp và Mexico. </p><p>Trong đó, đội tuyển Pháp chính là cái tên gây lo ngại nhất, khi sở hữu Jeremy Bury và Mikael Devogelaere - hai cơ thủ có trình độ cực kỳ đồng đều.</p><p>Trong khi đó, tuyển Đức sở hữu tượng đài Martin Horn, nhưng lại đánh cặp với người đồng đội ít tên tuổi Amir Ibraimov. Còn Mexico là sự kết hợp của cặp VĐV Christian Hernandez và Alejandro Santiago không quá tiếng tăm.</p>                                      <p>Giải billiards carom 3 băng đồng đội thế giới 2026 diễn ra từ ngày 26-2 đến 1-3 tại Viersen (Đức). Tổng cộng có 16 đội tuyển tranh tài. </p><p>Bảng A gồm Thổ Nhĩ Kỳ, Nhật Bản, Colombia và Jordan. Bảng C được xem là \"bảng tử thần\" với sự góp mặt của đương kim vô địch Hà Lan, Bỉ, Thụy Điển và Hy Lạp. Cuối cùng, bảng D là cuộc cạnh tranh giữa Tây Ban Nha, Hàn Quốc, Mỹ và Ai Cập.</p>                 <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/4/tran-quyet-chien-giai-billiards-dong-doi-vbtl-17671146327521918324536-285-278-1504-2228-crop-1770200511292647750755.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Trần Quyết Chiến, Nguyễn Trần Thanh Tự sẵn sàng chinh phục danh hiệu thế giới - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Xác định đồng đội mới của Trần Quyết Chiến tại Giải đồng đội thế giới<p class=\"VCObjectBoxRelatedNewsItemSapo\">Vào cuối tháng 2, Trần Quyết Chiến sẽ bắt đầu hành trình chinh phục Giải billiards carom 3 băng đồng đội thế giới 2026.</p>                 \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/tran-quyet-chien-world-cup-billiards-tphcm-1748013513077985574852-0-0-1280-2048-crop-1772004204813505608311.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/tran-quyet-chien-nguyen-tran-thanh-tu-san-sang-chinh-phuc-danh-hieu-the-gioi-2026022514245232.htm', NULL, '2026-02-25 14:48:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":25,\"Th\\u1ec3 Thao\":7,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:37', '2026-02-25 10:06:37'),
('141', '3', '3', 'Ông Nguyễn Toàn Thắng: Tập trung gỡ vướng để cấp sổ hồng cho người mua nhà', 'ong-nguyen-toan-thang-tap-trung-go-vuong-de-cap-so-hong-cho-nguoi-mua-nha', '\n\n                                        \n\n                                                                                *Xin ông thông tin một số nội dung về chức năng, nhiệm vụ của Tổ công tác cấ...', '\n\n                                        \n\n                                                                                <p><i>*Xin ông thông tin một số nội dung về chức năng, nhiệm vụ của Tổ công tác cấp sổ hồng trên địa bàn TP.HCM?</i></p><p>-Trước tiên, tôi xin được gửi đến quý độc giả, quý tòa soạn và các phóng viên, biên tập viên của Báo <i>Thanh Niên</i> lời chúc mừng năm mới an lành, mạnh khỏe và hạnh phúc. </p><p>Tổ công tác giải quyết các nội dung liên quan đến công tác cấp giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất (sổ hồng) cho tổ chức, cá nhân tại các dự án nhà ở thương mại trên địa bàn TP.HCM được thành lập theo Quyết định số 5013/2024 và được kiện toàn theo Quyết định số 1645/2025, gọi tắt là Tổ Công tác 1645. </p><p>Tổ công tác do Sở Nông nghiệp và Môi trường làm Tổ trưởng, Sở Xây dựng là Tổ phó và các thành viên gồm Sở Tài chính, Thanh tra Thành phố, Công an Thành phố, Thuế Thành phố và Chủ tịch UBND 168 phường, xã và đặc khu.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/ong-nguyen-toan-thang-copy-3-1772009216459426103892.jpg\" id=\"img_208620523845881856\" w=\"666\" h=\"835\" alt=\"Ông Nguyễn Toàn Thắng: Tập trung gỡ vướng để cấp sổ hồng cho người mua nhà - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208620523845881856\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/ong-nguyen-toan-thang-copy-3-1772009216459426103892.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"666\" height=\"835\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Ông Nguyễn Toàn Thắng cho hay, nhiệm vụ trọng tâm năm 2026 sẽ đẩy mạnh gỡ vướng để cấp sổ hồng cho người mua nhà tại các dự án nhà ở thương mại</p></figcaption></figure><p>Tổ công tác 1645 có sáu nhiệm vụ chính, trong đó nổi bật nhất là xác định rõ nguyên nhân, vướng mắc dẫn đến việc chưa hoàn thành công tác cấp sổ hồng tại các dự án nhà ở thương mại. Từ đó phân nhóm, phân loại, thống kê số liệu, danh sách dự án cụ thể theo từng nhóm, đề ra và thực hiện các giải pháp tháo gỡ vướng mắc, khó khăn theo kế hoạch, lộ trình và thời gian cụ thể.</p><p>Sau đó sẽ tham mưu cho UBND TP.HCM chỉ đạo xuyên suốt, thống nhất và đồng bộ từ TP đến các phường, xã và đặc khu để giải quyết các vướng mắc liên quan đến việc cấp sổ hồng cho người mua nhà.</p><p>Đồng thời theo dõi, đôn đốc, kiểm tra tiến độ thực hiện tháo gỡ khó khăn, vướng mắc và đánh giá toàn diện về tình hình phát triển cũng như công tác cấp sổ hồng tại các dự án phát triển nhà ở thương mại trên địa bàn TP kể từ khi dự án được cấp phép đầu tư xây dựng đến khi nghiệm thu hoàn thành đưa vào sử dụng và cấp sổ hồng liên quan đến công tác cấp sổ tại các dự án nhà ở thương mại.</p><p><i>*Vậy theo ông, đâu là những vướng mắc dẫn đến việc người mua nhà tại các dự án bị \"treo\" sổ hồng suốt nhiều năm trời?</i></p><p>-Sau khi được thành lập, Tổ công tác 1645 đã xác định được sáu nhóm vướng mắc chính thường gặp tại các dự án nhà ở dẫn đến việc người mua nhà chưa được giải quyết thủ tục cấp sổ.  </p><p>Đầu tiên là vướng mắc về việc thực hiện nghĩa vụ của chủ đầu tư về điều tiết nhà ở xã hội, nghĩa vụ nhà ở tái định cư tại các dự án. </p><p>Thứ hai là vướng mắc về việc thực hiện nghĩa vụ tài chính và nghĩa vụ tài chính bổ sung của chủ đầu tư tại các dự án</p><p>Thứ ba là vướng mắc về việc dự án đang trong quá trình thực hiện điều tra, thực hiện kết luận thanh tra, điều tra và thực hiện bản án của Tòa án.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/nguyen-toan-thang-17720096204961470569227.jpg\" id=\"img_208621371423154176\" w=\"2560\" h=\"1828\" alt=\"Ông Nguyễn Toàn Thắng: Tập trung gỡ vướng để cấp sổ hồng cho người mua nhà - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208621371423154176\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/nguyen-toan-thang-17720096204961470569227.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1828\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/nguyen-toan-thang-17720096204961470569227.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/nguyen-toan-thang-17720096204961470569227.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Việc đẩy mạnh cấp sổ hồng cho các tổ chức, cá nhân đã mang lại nhiều kết quả tích cực</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: V.D</p></figure><p>Thứ tư là vướng mắc về việc chưa hoàn tất đầu tư, xây dựng và việc bàn giao hạ tầng kỹ thuật, hạ tầng xã hội tại dự án cho địa phương quản lý.</p><p>Thứ năm là vướng mắc về việc rà soát lại pháp lý trong quá trình thực hiện dự án (ví dụ về ranh mốc thực hiện dự án, việc bồi thường, giải phóng mặt bằng, dự án có tranh chấp giữa cư dân và chủ đầu tư về diện tích sử dụng chung…).</p><p>Cuối cùng là vướng mắc về việc vi phạm hành chính về trật tự xây dựng tại dự án.</p><p><i>*Sau một năm thành lập của Tổ công tác 1645 đến nay đã có bao nhiêu dự án được gỡ vướng để cấp sổ hồng cho người mua nhà thưa ông?</i></p><p>-Bằng rất nhiều nỗ lực, Tổ công tác 1645 đã liên tục tổ chức các cuộc họp nhằm tháo gỡ vướng mắc và giải quyết việc cấp sổ hồng cho người mua nhà tại các dự án với tần suất một lần/tuần. Kết quả sau một năm hoạt động, đến thời điểm ngày 5.11.2025, Tổ công tác 1645 đã tổ chức 44 cuộc họp để xem xét, tháo gỡ vướng mắc cho 207 dự án, với 104.967 sản phẩm bất động sản.</p><p>Thông qua 44 cuộc họp, Tổ công tác đã tháo gỡ vướng mắc cho 173/207 dự án tương đương với 91.332/104.967 sản phẩm bất động sản sẽ được cơ quan đăng ký đất đai giải quyết thủ tục cấp sổ hồng cho người mua nhà tại dự án.</p><p><i>*Đã xác định cụ thể các vướng mắc, </i><i>với vai trò là Tổ trưởng Tổ công tác 1645, xin ông cho biết giải pháp chính mà ông và Tổ công tác đang lựa chọn để thực hiện tháo gỡ đối với từng nhóm vướng mắc trong năm nay là gì?</i></p><p>-Theo Quyết định của UBND TP, mục tiêu hoạt động của Tổ công tác 1645 là thực hiện việc bảo vệ quyền và lợi ích hợp pháp chính đáng của người mua nhà tại các dự án phát triển nhà ở thông qua công tác tháo gỡ khó khăn cho dự án và cấp sổ hồng cho người mua nhà.</p><p>Do đó, xuyên suốt các cuộc họp, với vai trò là Tổ trưởng, tôi đã cùng các thành viên Tổ công tác quán triệt mục tiêu hoạt động của Tổ cũng như thống nhất thực hiện các giải pháp cần thiết để bảo vệ quyền và lợi ích hợp pháp chính đáng của người mua nhà tại các dự án phát triển nhà ở. Đồng thời đảm bảo hài hòa lợi ích của Nhà nước và chủ đầu tư dự án thông qua công tác tháo gỡ khó khăn và cấp sổ hồng.</p><p>Tại các cuộc họp, bên cạnh việc đề nghị cơ quan đăng ký đất đai giải quyết thủ tục cấp sổ hồng cho người mua nhà tại các dự án, Tổ công tác luôn xác định rõ các nội dung vướng mắc nào của dự án phát sinh thuộc trách nhiệm giải quyết của chủ đầu tư, thời điểm phát sinh các vướng mắc nêu trên là trước hay sau khi chủ đầu tư được cơ quan có thẩm quyền cho phép thực hiện bán nhà làm cơ sở đề xuất các nội dung ràng buộc trách nhiệm của chủ đầu tư để hoàn tất các nghĩa vụ đối với Nhà nước và người mua nhà.</p><p><i>*Ông có thể thông tin một số dự án có vướng mắc nổi bật đã được Tổ công tác 1645 tháo gỡ để giải quyết thủ tục cấp trong năm vừa qua?</i></p><p>-Tôi xin nêu năm dự án phát triển nhà ở nhận được nhiều kiến nghị của cư dân, Ban Quản trị và các cơ quan có thẩm quyền liên quan đến việc tháo gỡ vướng mắc và cấp sổ hồng đã được Tổ công tác tháo gỡ.</p><p>Dự án khu căn hộ Saigon Gateway (TP.Thủ Đức cũ) do Công ty cổ phần Bất động sản Hiệp Phú Land làm Chủ đầu tư.</p><p>Dự án chung cư Tam Phú thuộc dự án Khu nhà ở phường Tam Phú (TP.Thủ Đức cũ) do Công ty TNHH Tư vấn và Kinh doanh nhà Đạt Gia làm chủ đầu tư.</p><p>Dự án chung cư Topaz Home số 102 Phan Văn Hớn, P.Đông Hưng Thuận do Công ty cổ phần Dịch vụ Nông nghiệp và Thương mại Thuận Kiều làm chủ đầu tư.</p><p>Dự án chung cư Tín Phong (P.Tân Thới Nhất, Q.12 cũ) do Công ty TNHH Sản xuất Thương mại Xây dựng Tín Phong làm chủ đầu tư.</p><p>Dự án chung cư Hà Đô Centrosa (P.12, Q.10 cũ) do Công ty cổ phần Hà Đô - 756 Sài Gòn làm chủ đầu tư.</p><p><i>*Chỉ sau 1 năm thành lập, Tổ công tác 1645 đã tháo gỡ và cấp sổ hồng cho hơn 91.000 sản phẩm bất động sản, mang lại niềm tin và hy vọng cho hàng vạn người dân. Ông có thể cho biết, mục tiêu cụ thể của năm 2026 này? </i></p><p>-Trong năm 2026, tôi và các thành viên Tổ công tác sẽ tiếp tục thực hiện các nhiệm vụ được UBND TP giao, trong đó tập trung vào bốn nhiệm vụ sau:</p><p>Thứ nhất, tiếp tục tháo gỡ các các nội dung vướng mắc làm cơ sở để giải quyết thủ tục cấp sổ hồng cho người mua nhà tại các dự án phát triển nhà ở thương mại trên địa bàn TP. Trong đó chú trọng mở rộng việc tháo gỡ cho các dự án phát triển nhà ở thương mại trên địa bàn tỉnh Bình Dương và Bà Rịa - Vũng Tàu cũ.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/saigon-gateway-copy-1772010167893193719751.jpg\" id=\"img_208622518150062080\" w=\"1280\" h=\"827\" alt=\"Ông Nguyễn Toàn Thắng: Tập trung gỡ vướng để cấp sổ hồng cho người mua nhà - Ảnh 3.\" title=\"\" rel=\"lightbox\" photoid=\"208622518150062080\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/saigon-gateway-copy-1772010167893193719751.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1280\" height=\"827\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/saigon-gateway-copy-1772010167893193719751.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/saigon-gateway-copy-1772010167893193719751.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Sau nhiều năm mong đợi, hàng trăm khách hàng mua nhà tại chung cư Saigon Gateway đã được cấp sổ hồng</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: ĐÌNH SƠN</p></figure><p>Thứ hai, phối hợp với Sở Xây dựng để kiến nghị UBND TP xem xét, bổ sung chức năng cho Tổ Công tác nhằm tháo gỡ các nội dung vướng mắc liên quan đến công tác cấp sổ hồng cho người nhận chuyển nhượng căn hộ, nhà ở tại các dự án phát triển nhà ở xã hội trên địa bàn TP.</p><p>Thứ ba, thực hiện các giải pháp củng cố, bổ sung, trang bị đối với nguồn lực thực hiện công tác đăng ký cấp sổ nhằm cải thiện chỉ tiêu cấp sổ hồng trên địa bàn TP.HCM sau sắp xếp.</p><p>Thứ tư, hoàn tất việc xây dựng và công bố trang thông tin điện tử nhằm thực hiện thống nhất chế độ công khai thông tin các dự án phát triển nhà ở thương mại trên địa bàn TP.</p><p><i>*Xin trân trọng cám ơn ông!</i></p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/ong-nguyen-toan-thang-copy-3-1772009216459426103892-165-0-581-666-crop-17720092525831910510617.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/ong-nguyen-toan-thang-tap-trung-go-vuong-de-cap-so-hong-cho-nguoi-mua-nha-185260225154737682.htm', NULL, '2026-02-25 16:54:00', '1', '0', '1', '0.65', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":13,\"Th\\u1ebf Gi\\u1edbi\":5,\"Th\\u1eddi S\\u1ef1\":5},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:37', '2026-02-25 10:06:51'),
('142', '2', '2', 'Khánh thành trung tâm điều hành tòa soạn số và không gian làm việc mới của báo Tuổi Trẻ', 'khanh-thanh-trung-tam-dieu-hanh-toa-soan-so-va-khong-gian-lam-viec-moi-cua-bao-tuoi-tre', '\r\n                    Không gian làm việc dành cho các khối nội dung tại tầng 7 báo Tuổi Trẻ - Ảnh: HỮU HẠNHKhông chỉ đơn thuần là sự thay đổi về mặt cơ sở vật chất, đây còn là bước chuyển trong hành...', '\r\n                    <figure class=\"VCSortableInPreviewMode alignCenterOverflow alignCenterOverflow alignCenterOverflow alignCenterOverflow alignCenterOverflow alignCenterOverflow alignCenterOverflow alignCenterOverflow\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/25/2bbaedf5ee3660683927-17720022532251469764014.jpg\" id=\"img_208610310783520768\" w=\"2560\" h=\"857\" alt=\"Tuổi Trẻ - Ảnh 1.\" title=\"Trung tâm điều hành tòa soạn số và không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh 1.\" rel=\"lightbox\" photoid=\"208610310783520768\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/2bbaedf5ee3660683927-17720022532251469764014.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"857\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Không gian làm việc dành cho các khối nội dung tại tầng 7 báo Tuổi Trẻ - Ảnh: HỮU HẠNH</p></figcaption></figure><p class=\"\">Không chỉ đơn thuần là sự thay đổi về mặt cơ sở vật chất, đây còn là bước chuyển trong hành trình xây dựng tòa soạn số năng động, linh hoạt và sáng tạo.</p><h2>Tòa soạn được thiết kế theo hướng mở, đón nhiều ánh sáng tự nhiên, ưu tiên cây xanh</h2><p class=\"\">Ở vị trí trung tâm là màn hình lớn hiển thị các số liệu vận hành theo thời gian thực. Đây sẽ là “trái tim” của các khối nội dung, nơi cập nhật nhịp đập tin tức, theo dõi hiệu suất, phân tích dữ liệu và đưa ra định hướng khai thác nội dung và cũng là khu vực trao đổi ý tưởng, kết nối phòng ban. </p>TIN LIÊN QUAN<ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"18/12/2025 19:51\" data-id=\"20251218192931219\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/12/18/tt2-1766060768542405112317-376-67-965-1009-crop-17660625022601663924135.jpeg\" data-url=\"/bao-tuoi-tre-nam-thu-2-lien-tiep-dat-muc-xuat-sac-chuyen-doi-so-20251218192931219.htm\" data-title=\"Báo Tuổi Trẻ năm thứ 2 liên tiếp đạt mức xuất sắc chuyển đổi số\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/12/18/tt2-1766060768542405112317-376-67-965-1009-crop-17660625022601663924135.jpeg\" alt=\"Trung tâm điều hành tòa soạn số và không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title\">Báo Tuổi Trẻ năm thứ 2 liên tiếp đạt mức xuất sắc chuyển đổi số</h4></li><li class=\"kbwscwlrl\" data-date=\"07/12/2024 09:42\" data-id=\"20241207091125917\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2024/12/7/anh-1-logo-50-nam-bao-tuoi-trefalogooriginal-17335382821981094614716-296-397-1078-1649-crop-17335397092731560840429.jpg\" data-url=\"/cuoc-thi-logo-va-slogan-ky-niem-50-nam-thanh-lap-bao-tuoi-tre-cong-bo-ket-qua-20241207091125917.htm\" data-title=\"Cuộc thi logo và slogan kỷ niệm 50 năm thành lập báo Tuổi Trẻ công bố kết quả\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2024/12/7/anh-1-logo-50-nam-bao-tuoi-trefalogooriginal-17335382821981094614716-296-397-1078-1649-crop-17335397092731560840429.jpg\" alt=\"Trung tâm điều hành tòa soạn số và không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title\">Cuộc thi logo và slogan kỷ niệm 50 năm thành lập báo Tuổi Trẻ công bố kết quả</h4></li><li class=\"kbwscwlrl\" data-date=\"04/06/2025 18:40\" data-id=\"20250604133615242\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/6/4/03abcefadee16abf33f0-1749034783732779408634-76-0-1676-2560-crop-1749035261862727509167-36-69-1233-1983-crop-1749036470919150063898.jpg\" data-url=\"/trao-giai-cho-cac-nhac-si-sang-tac-ca-khuc-ve-bao-tuoi-tre-20250604133615242.htm\" data-title=\"Trao giải cho các nhạc sĩ sáng tác ca khúc về báo Tuổi Trẻ\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/6/4/03abcefadee16abf33f0-1749034783732779408634-76-0-1676-2560-crop-1749035261862727509167-36-69-1233-1983-crop-1749036470919150063898.jpg\" alt=\"Trung tâm điều hành tòa soạn số và không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title\">Trao giải cho các nhạc sĩ sáng tác ca khúc về báo Tuổi Trẻ</h4></li></ul><p class=\"\">Bao quanh khu vực trung tâm là các cụm làm việc của các ban nội dung: Ban Tuổi Trẻ Cười; Ban Chuyên đề; Ban Giáo dục và Giới trẻ; Ban Kinh tế; Ban Chính trị - Xã hội; Ban Văn hóa - Thể thao và Giải trí; Ban Quốc tế - Tuổi Trẻ Tiếng Anh.</p><p class=\"\">Mỗi ban có không gian riêng nhưng không tách biệt, tạo nên sự liền mạch và tương tác linh hoạt. Những ý tưởng có thể được đề xuất từ một ban, phối hợp nhanh với các ban khác, từ đó nhanh chóng định hình và cho ra những sản phẩm báo chí đa nền tảng. </p><p class=\"\">Toàn bộ tòa soạn được thiết kế theo hướng mở, đón nhiều ánh sáng tự nhiên. Cây xanh được ưu tiên bố trí ở các khu vực, mang lại cảm giác tươi mới và dễ chịu. </p><p class=\"\">Dọc theo các khung cửa kính là dãy bàn dài nhìn ra thành phố - không gian lý tưởng để thư giãn, thưởng thức cà phê, hay đơn giản là tìm một khoảng lặng trước khi bắt đầu cho những dòng tin mới. </p><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">Báo Tuổi Trẻ ra mắt Trung tâm điều hành tòa soạn số và không gian làm việc mới dành cho khối nội dung</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/25/nhh01062-177200340084119888971.jpg\" id=\"img_208613039756238848\" w=\"2560\" h=\"1684\" alt=\"Khánh thành trung tâm điều hành tòa soạn số và không gian làm việc mới của báo Tuổi Trẻ - Ảnh 5.\" title=\"\" rel=\"lightbox\" photoid=\"208613039756238848\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01062-177200340084119888971.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1684\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Phóng viên Hoàng Lê và Hoài Phương thuộc Ban Văn hóa - Thể thao và Giải trí đang trao đổi công việc trong không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh: HỮU HẠNH</p></figcaption></figure><figure class=\"media-item\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/nhh01038-1772003400807738950171.jpg\" class=\" visible\" data-originalw=\"2560\" data-originalh=\"1684\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01038-1772003400807738950171.jpg\" data-row=\"0\" data-id=\"208613040116948992\" alt=\"Tuổi Trẻ - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"></figure><figure class=\"media-item\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/nhh01342-1772003400803460635276.jpg\" class=\" visible\" data-originalw=\"2560\" data-originalh=\"1684\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01342-1772003400803460635276.jpg\" data-row=\"0\" data-id=\"208612729647026176\" alt=\"Tuổi Trẻ - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"></figure><figure class=\"media-item\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/nhh01022-17720034008101498389955.jpg\" class=\" visible\" data-originalw=\"2560\" data-originalh=\"1684\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01022-17720034008101498389955.jpg\" data-row=\"0\" data-id=\"208613039898845184\" alt=\"Tuổi Trẻ - Ảnh 5.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"></figure><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh: HỮU HẠNH</p></figcaption><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/25/nhh01425-17720034008181274819400.jpg\" id=\"img_208612720675409920\" w=\"2560\" h=\"1684\" alt=\"Tuổi Trẻ - Ảnh 6.\" title=\"\" rel=\"lightbox\" photoid=\"208612720675409920\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01425-17720034008181274819400.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1684\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh: HỮU HẠNH</p></figcaption></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/25/nhh01351-1772003400826684889676.jpg\" id=\"img_208612719253540864\" w=\"2560\" h=\"1684\" alt=\"Tuổi Trẻ - Ảnh 7.\" title=\"\" rel=\"lightbox\" photoid=\"208612719253540864\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01351-1772003400826684889676.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1684\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh: HỮU HẠNH</p></figcaption></figure><p class=\"\">Thiết kế mới không chỉ tạo điều kiện thuận lợi cho tác nghiệp mà còn nuôi dưỡng tinh thần làm báo trong thời đại số: Kết nối - sáng tạo - phản ứng nhanh - làm việc dựa trên dữ liệu.</p><p class=\"\">Mỗi góc làm việc, mỗi khoảng mở đều hướng tới mục tiêu chung: tạo ra môi trường để phóng viên phát huy tối đa năng lực, cùng nhau kiến tạo những sản phẩm báo chí chất lượng, gần gũi và có sức lan tỏa. Không gian làm việc đổi mới hôm nay không chỉ là một nơi làm việc, đó còn là mong muốn của tinh thần đổi mới để phụng sự bạn đọc. </p><p class=\"\">Từ không gian này, những câu chuyện mới sẽ tiếp tục được viết nên - nhanh hơn, sâu sắc hơn và truyền cảm hứng hơn mỗi ngày.</p>                                                                   <figure class=\"VCSortableInPreviewMode\" type=\"PhotoInContentBox\" style=\"position: relative; left: 0px; top: 0px;\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/25/nhh01216-1772003432299574051189.jpg\" id=\"img_208613094200401920\" w=\"2560\" h=\"1684\" alt=\"Tuổi Trẻ - Ảnh 10.\" title=\"\" rel=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01216-1772003432299574051189.jpg\" photoid=\"208613094200401920\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01216-1772003432299574051189.jpg\" type=\"photo\" style=\"max-width:100%;\" loading=\"lazy\" width=\"2560\" height=\"1684\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Phó tổng biên tập báo Tuổi Trẻ Lê Xuân Trung (bìa phải) trao đổi với các bộ phận trong không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh: HỮU HẠNH</p></figcaption></figure><h2>Đưa vào sử dụng Trung tâm điều hành tòa soạn</h2><p class=\"\">Dịp này, báo <i>Tuổi Trẻ</i> cũng đã đưa vào sử dụng Trung tâm điều hành tòa soạn, một dấu mốc quan trọng trong chiến lược phát triển nội dung lấy dữ liệu làm nền tảng và bạn đọc làm trung tâm.</p><p class=\"\">Đây được xem là \"bộ não dữ liệu\" mang tính chiến lược của toàn bộ hệ sinh thái <i>Tuổi Trẻ</i>, nơi mọi chỉ số được cập nhật, phân tích và chuyển hóa thành định hướng chiến lược cho tòa soạn. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/24/2326637183234749373-17719395760271611439121.jpg\" id=\"img_208478869653311488\" w=\"2560\" h=\"1706\" alt=\"Khánh thành trung tâm điều hành tòa soạn số và không gian làm việc mới của báo Tuổi Trẻ - Ảnh 12.\" title=\"Trung tâm điều hành tòa soạn số và không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh 5.\" rel=\"lightbox\" photoid=\"208478869653311488\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/24/2326637183234749373-17719395760271611439121.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Trung tâm phát triển nội dung số liên tục cập nhật số liệu lên hệ thống</p></figcaption></figure><p class=\"\">Lấy dữ liệu làm nền tảng hoạch định nội dung, Trung tâm điều hành tòa soạn số có nhiệm vụ thu thập và phân tích toàn diện các dữ liệu liên quan đến: </p><p class=\"\">- Tổng số lượng truy cập theo thời gian thực; </p><p class=\"\">- Hành vi và thói quen đọc của người dùng; </p><p class=\"\">- Các luồng nội dung đang được bạn đọc quan tâm; </p><p class=\"\">- Hiệu suất nội dung theo từng phòng ban, bộ phận; </p><p class=\"\">- Mức độ lan tỏa và tương tác trên các nền tảng…</p><p class=\"\">Từ các dữ liệu này, trung tâm sẽ định hình các luồng tuyến nội dung mang tính chiến lược, ứng biến nhanh - kết nối chặt với đội ngũ phóng viên.</p><figure class=\"media-item\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/24/2326637183234749373-2-17719396395562067062104.jpg\" class=\" visible\" data-originalw=\"2560\" data-originalh=\"1706\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/24/2326637183234749373-2-17719396395562067062104.jpg\" data-row=\"0\" data-id=\"208479311130222592\" alt=\"Tuổi Trẻ - Ảnh 9.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"></figure><figure class=\"media-item\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/24/4456169241025981889-17719396395521517892828.jpg\" class=\" visible\" data-originalw=\"2560\" data-originalh=\"1706\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/24/4456169241025981889-17719396395521517892828.jpg\" data-row=\"0\" data-id=\"208479001071341568\" alt=\"Tuổi Trẻ - Ảnh 10.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"></figure><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Bộ phận sáng tạo nội dung theo dõi số liệu từ Trung tâm điều hành tòa soạn số</p></figcaption><p class=\"\">Một trong những điểm nổi bật của Trung tâm điều hành tòa soạn số là khả năng cập nhật và phân tích số liệu theo thời gian thực. Những biến động về hành vi người đọc, các chủ đề đang tăng trưởng đột biến hay những nội dung cần điều chỉnh sẽ được ghi nhận.</p><p class=\"\">Thông tin phân tích từ trung tâm sẽ được chuyển đến đội ngũ phóng viên, biên tập viên, thư ký tòa soạn một cách nhanh chóng, nhằm giúp: </p><p class=\"\">- Điều chỉnh góc tiếp cận đề tài; </p><p class=\"\">- Bổ sung dữ kiện, mở rộng tuyến bài; </p><p class=\"\">- Tối ưu tiêu đề, hình thức thể hiện; </p><p class=\"\">- Gia tăng hiệu quả tiếp cận và tương tác… để hướng tới mỗi tác phẩm báo chí không chỉ đảm bảo giá trị thông tin, mà còn phù hợp hơn với nhu cầu và nhịp đọc của công chúng hiện đại.</p><p class=\"\">Tất cả được vận hành trên nền tảng công nghệ đồng bộ, đảm bảo tính chính xác, minh bạch và kịp thời trong quá trình phân tích - đánh giá - ra quyết định. </p><p class=\"\">Hệ thống dữ liệu trên được xây dựng và vận hành bởi Trung tâm phát triển nội dung số - báo <i>Tuổi Trẻ</i>, với mong muốn thích ứng và phát triển mạnh mẽ hơn nữa trong hành trình phục vụ bạn đọc.</p><figure class=\"VCSortableInPreviewMode\" type=\"PhotoInContentBox\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/25/2597873918526855045-1-17720033772441449442001.jpg\" id=\"img_208612666711494656\" w=\"2560\" h=\"1706\" alt=\"Tuổi Trẻ - Ảnh 10.\" title=\"\" rel=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/2597873918526855045-1-17720033772441449442001.jpg\" photoid=\"208612666711494656\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/2597873918526855045-1-17720033772441449442001.jpg\" type=\"photo\" style=\"max-width:100%;\" loading=\"lazy\" width=\"2560\" height=\"1706\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Lối vào của không gian làm việc mới của khối nội dung báo Tuổi Trẻ - Ảnh: HỮU HẠNH</p></figcaption></figure><p class=\"\"> Trong dòng chảy hối hả của thông tin, văn phòng không chỉ là nơi làm việc, mà còn là \"trạm tiếp năng lượng\" cho những tư duy sắc sảo. Vừa qua, diện mạo mới của tầng 7 - khu vực làm việc của các trưởng bộ phận và đội ngũ phóng viên báo <i>Tuổi Trẻ</i> - đã chính thức hoàn thiện, mang đến một luồng gió mới đầy cảm hứng ngay giữa lòng tòa soạn giàu truyền thống.</p><h3>Dự án tầng 7 báo <i>Tuổi Trẻ</i> tập trung vào sự tối giản</h3><p class=\"p1\">Thấu hiểu đặc thù của nghề báo - nơi mỗi phút giây đều là deadline, Sala đã kiến tạo một không gian mở (open-space) mang tính kết nối đa chiều. Tại đây, ranh giới giữa các phòng ban được xóa nhòa bởi những không gian làm việc mở, hiện đại, linh hoạt nhưng vẫn đảm bảo sự chỉn chu và chính xác.</p><figure class=\"VCSortableInPreviewMode\" type=\"PhotoInContentBox\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/1100/471584752817336320/2026/2/25/nhh01305-17720034008341736461614.jpg\" id=\"img_208613039886262272\" w=\"2560\" h=\"1684\" alt=\"Tuổi Trẻ - Ảnh 10.\" title=\"\" rel=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01305-17720034008341736461614.jpg\" photoid=\"208613039886262272\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/nhh01305-17720034008341736461614.jpg\" type=\"photo\" style=\"max-width:100%;\" loading=\"lazy\" width=\"2560\" height=\"1684\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nơi làm việc còn có không gian cho thư giãn, trò chuyện - Ảnh: HỮU HẠNH</p></figcaption></figure><p class=\"p1\">Dự án tầng 7 báo <i>Tuổi Trẻ</i> tập trung vào sự tối giản với những gam màu trung tính nơi ánh sáng tự nhiên được tính toán và tận dụng tối đa tạo cảm giác điềm tĩnh, nhẹ nhàng để hỗ trợ tối đa cho việc tác nghiệp liên tục.</p><p class=\"p1\">Chúng tôi ưu tiên các vật liệu bền bỉ, có khả năng giảm tiếng ồn, tạo ra khoảng lặng cần thiết cho những bài viết chuyên sâu nhưng vẫn không tách rời khỏi không khí sôi động của tòa soạn.</p><p class=\"p1\">Việc hoàn thành dự án này không chỉ là một công trình thiết kế và thi công nội thất đơn thuần, mà còn là sự đồng hành của Sala cùng báo <i>Tuổi Trẻ </i>trên hành trình đổi mới. </p><p class=\"p1\">Một không gian làm việc chuyên nghiệp chính là nền tảng để những \"chiến sĩ cầm bút\" tiếp tục phụng sự bạn đọc bằng sự nhiệt huyết và tâm thế mới.</p><p class=\"p1\">Hy vọng rằng, tại không gian tầng 7 này, những dòng tin giá trị sẽ tiếp tục được khơi nguồn và lan tỏa.</p><p class=\"p1\" style=\"text-align: right;\"><b>Ông Phạm Trọng Lâm - Tổng giám đốc Công ty Sala</b></p>                                                                                         <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2024/12/25/qdi5309-17349502476871405578896-189-133-1236-1808-crop-17351235194092021877932.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Báo Tuổi Trẻ  - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Báo Tuổi Trẻ đầu tư làm mới tòa soạn chuyển đổi số<p class=\"VCObjectBoxRelatedNewsItemSapo\">Báo Tuổi Trẻ vừa chính thức đưa vào hoạt động tòa soạn chuyển đổi số theo phong cách hiện đại, đa năng và sáng tạo. Đây là cột mốc phát triển mới nhằm truyền cảm hứng cho đội ngũ, đồng thời chào đón 50 năm hình thành và phát triển Tuổi Trẻ.</p>\r\n                ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/nhh01062-177200340084119888971-84-0-1684-2560-crop-1772004954727606932335.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/khanh-thanh-trung-tam-dieu-hanh-toa-soan-so-va-khong-gian-lam-viec-moi-cua-bao-tuoi-tre-20260224202803261.htm', NULL, '2026-02-25 14:45:54', '0', '0', '0', '0.25', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":5,\"Th\\u1eddi S\\u1ef1\":5,\"Gi\\u1ea3i Tr\\u00ed\":3},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:37', '2026-02-25 10:06:37'),
('143', '2', '3', 'Con trai cựu Thủ tướng Canada lên tiếng về chuyện tình của cha với Katy Perry', 'con-trai-cuu-thu-tuong-canada-len-tieng-ve-chuyen-tinh-cua-cha-voi-katy-perry', '\n\n                                        \n\n                                                                                Xavier Trudeau - con trai cả của cựu Thủ tướng Canada Justin Trudeau, mới đâ...', '\n\n                                        \n\n                                                                                <p>Xavier Trudeau - con trai cả của cựu Thủ tướng Canada Justin Trudeau, mới đây đã lên tiếng về mối quan hệ giữa cha mình và nữ ca sĩ Katy Perry. Chia sẻ trong một video đăng tải trên Instagram ngày 21.2, Xavier Trudeau cho biết anh có ấn tượng rất tích cực về giọng ca <i>Dark Horse</i>.</p><h2><b>Gắn kết nhờ có chung niềm đam mê âm nhạc</b></h2><p>\"Cô ấy rất tuyệt, rất thân thiện. Chúng tôi đã trò chuyện hàng giờ liền về âm nhạc của tôi. Cô ấy cho tôi nhiều lời khuyên và định hướng cho những bước đi tiếp theo\", Xavier Trudeau nói.</p><p>Những chia sẻ này được xem là khá bất ngờ trong bối cảnh mối quan hệ của Justin Trudeau và Katy Perry chỉ mới được công khai cách đây 2 tháng, khi nữ ca sĩ chính thức xác nhận chuyện tình cảm trên mạng xã hội.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-2-17720042260461952473993.jpg\" id=\"img_208610053999071232\" w=\"1080\" h=\"1350\" alt=\"Thái độ bất ngờ của con trai cựu Thủ tướng Canada về chuyện tình với Katy Perry - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208610053999071232\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-2-17720042260461952473993.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1080\" height=\"1350\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" data-listener-added_a6225a11=\"true\">Chuyện tình giữa Katy Perry và cựu Thủ tướng Canada Justin Trudeau được con trai cả hết lòng ủng hộ</p></figcaption><p data-placeholder=\"Nhập tác giả\">Ảnh: Instagram katyperry</p></figure><p>Ở tuổi 18, Xavier Trudeau đang theo đuổi sự nghiệp âm nhạc riêng dưới nghệ danh Xav. Trên podcast <i>The Brandon Gonez Show</i> hồi tháng 5.2025, anh từng bày tỏ niềm đam mê sâu sắc với âm nhạc: \"Tôi luôn yêu âm nhạc, dù là sáng tác hay chỉ đơn giản là lắng nghe. Tôi lúc nào cũng có một sự thôi thúc đặc biệt với nó\".</p><p>Justin Trudeau và vợ cũ Sophie Grégoire Trudeau có 3 người con gồm Xavier (18 tuổi), Ella-Grace (17 tuổi) và Hadrien (11 tuổi). Từ nhỏ, Xavier Trudeau đã được tạo điều kiện học nhiều nhạc cụ như trống, guitar và piano. Vài năm trước, anh bắt đầu tự thử nghiệm làm beat và thu âm bằng điện thoại. Từ đó đến nay, Xavier Trudeau theo đuổi dòng nhạc R&amp;B.</p><p>\"Gia đình luôn ủng hộ tôi ngay từ đầu. Mỗi lần đi studio về, tôi đều mở sản phẩm mới cho cả nhà nghe trong bữa tối. Mọi người sẽ góp ý rất thẳng thắn, thích hay không thích chỗ nào\", anh nói. Theo Xavier Trudeau, cha mẹ đều vui khi thấy anh lựa chọn con đường riêng cho cuộc đời mình.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-3-17720042591781489115941.jpg\" id=\"img_208610126083424256\" w=\"1080\" h=\"1080\" alt=\"Thái độ bất ngờ của con trai cựu Thủ tướng Canada về chuyện tình với Katy Perry - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208610126083424256\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-3-17720042591781489115941.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1080\" height=\"1080\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Katy Perry được cho là đã đưa ra nhiều lời khuyên và định hướng cho Xavier Trudeau trên hành trình âm nhạc</p></figcaption><p data-placeholder=\"Nhập tác giả\">Ảnh: Instagram xaviertrudeau</p></figure><p>Âm nhạc từ lâu đã là một phần quan trọng trong gia đình Trudeau. Vì vậy, việc Justin Trudeau xuất hiện và hào hứng theo dõi buổi biểu diễn của Katy Perry tại Montreal (Canada) hồi tháng 7.2025 không khiến nhiều người bất ngờ. Tuy nhiên, bữa tối của hai người trước đó 2 ngày đã làm dấy lên tin đồn về một mối quan hệ tình cảm.</p><p>Dù tin đồn lan rộng, cả Justin Trudeau lẫn Katy Perry đều không lên tiếng cho đến khi nữ ca sĩ chính thức xác nhận mối quan hệ trên Instagram sau đó 5 tháng. Trước đó, Justin Trudeau đã thông báo ly thân vợ vào năm 2023.</p><p>Thời điểm công khai chuyện tình cảm, Katy Perry đang bước vào giai đoạn mới của cuộc sống với vai trò mẹ đơn thân. Cô có con gái Daisy Dove Bloom (4 tuổi), với hôn phu cũ Orlando Bloom. Nam diễn viên của loạt phim <i>The Lord of the Rings</i> khẳng định mối quan hệ giữa anh và Katy Perry vẫn tràn đầy sự tôn trọng và yêu thương.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/anh-2-17720042260461952473993-185-0-860-1080-crop-1772012728373388528002.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/con-trai-cuu-thu-tuong-canada-len-tieng-ve-chuyen-tinh-cua-cha-voi-katy-perry-185260225142608689.htm', NULL, '2026-02-25 16:46:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":14,\"Gi\\u1ea3i Tr\\u00ed\":12,\"\\u0110\\u1eddi S\\u1ed1ng\":11},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:38', '2026-02-25 10:06:38'),
('144', '1', '2', 'Phó thủ tướng: Áp dụng các thuế mới liên quan tài sản, mức phát thải carbon theo thông lệ quốc tế', 'pho-thu-tuong-ap-dung-cac-thue-moi-lien-quan-tai-san-muc-phat-thai-carbon-theo-thong-le-quoc-te', '\r\n                Phó thủ tướng thường trực Chính phủ Nguyễn Hòa Bình - Ảnh: GIA HÂNVề nhiệm vụ đã được thiết kế trong chương trình hành động của Chính phủ đối với 2 nghị quyết, tổng cộng có 230 nhiệm...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/z615803-17720024741381113373460.jpg\" id=\"img_208611084484960256\" w=\"1200\" h=\"831\" alt=\"Phó thủ tướng - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208611084484960256\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/z615803-17720024741381113373460.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1200\" height=\"831\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Phó thủ tướng thường trực Chính phủ Nguyễn Hòa Bình - Ảnh: GIA HÂN</p></figcaption></figure><p>Về nhiệm vụ đã được thiết kế trong chương trình hành động của Chính phủ đối với 2 nghị quyết, tổng cộng có 230 nhiệm vụ. Trong đó, đối với nghị quyết 79 có 99 nhiệm vụ và nghị quyết 80 có 131 nhiệm vụ.</p><h2>Đầu tư, hoàn thiện các thiết chế quy mô quốc gia</h2><p>Với nghị quyết số 80, Phó thủ tướng cho biết cần lồng ghép yêu cầu phát triển văn hóa trong hoạch định chiến lược, xây dựng quy hoạch và xây dựng các dự án phát triển kinh tế - xã hội. </p><p>Cùng với đó, Phó thủ tướng nêu về ban hành nghị quyết của Quốc hội với các đột phá về mô hình hợp tác công - tư trong thiết chế văn hóa; xây dựng quỹ văn hóa, nghệ thuật; cơ chế tài chính ưu tiên (cho đào tạo, công nghệ số, đặt hàng tác phẩm); chính sách đãi ngộ, trọng dụng tài năng nghệ thuật.</p><p>Nhóm nhiệm vụ về xây dựng con người văn hóa và môi trường văn hóa, ông chia sẻ cần triển khai đồng bộ hệ giá trị văn hóa, hệ giá trị quốc gia, hệ giá trị gia đình, chuẩn mực con người Việt Nam. </p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"25/02/2026 09:18\" data-id=\"20260225083703994\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/z615609-1771983265394318610841-47-0-797-1200-crop-1771983338125406835442-17-61-650-1073-crop-1771986725180925245894.jpg\" data-url=\"/ong-trinh-van-quyet-danh-toi-thieu-2-tong-chi-ngan-sach-cho-van-hoa-la-dot-pha-lon-chua-tung-co-20260225083703994.htm\" data-title=\"Ông Trịnh Văn Quyết: Dành tối thiểu 2% tổng chi ngân sách cho văn hóa là \'đột phá lớn, chưa từng có\'\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/z615609-1771983265394318610841-47-0-797-1200-crop-1771983338125406835442-17-61-650-1073-crop-1771986725180925245894.jpg\" alt=\"Phó thủ tướng: Áp dụng các thuế mới liên quan tài sản, mức phát thải carbon theo thông lệ quốc tế - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Ông Trịnh Văn Quyết: Dành tối thiểu 2% tổng chi ngân sách cho văn hóa là \'đột phá lớn, chưa từng có\'ĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Nhóm nhiệm vụ về đổi mới phương thức quản lý và chuyển đổi số, trong đó cần đổi mới phương thức quản lý từ tiền kiểm sang hậu kiểm. </p><p>Theo ông, cần phát triển nền tảng giới thiệu văn hóa Việt Nam, tăng tỉ trọng sản phẩm nội địa; quản trị dữ liệu để bảo vệ sở hữu trí tuệ và chủ quyền văn hóa số; thường xuyên rà quét, ngăn chặn triệt để thông tin xấu, độc trên môi trường mạng…</p><p>Nhóm nhiệm vụ tiếp theo là xây dựng hệ sinh thái sáng tạo văn hóa gắn kết với khởi nghiệp và công nghệ mới. </p><p>Phó thủ tướng định hướng việc áp dụng cơ chế thử nghiệm có kiểm soát trong hoạt động văn hóa; hình thành các trung tâm đổi mới sáng tạo, không gian sáng tạo nội dung số và thị trường sản phẩm liên vùng tại các đô thị lớn.</p><p>Ông cho biết việc huy động tối đa nguồn lực doanh nghiệp tham gia phát triển chuỗi giá trị công nghiệp văn hóa và giải trí; hình thành các đô thị di sản và phát triển kinh tế di sản tại Hà Nội, Quảng Ninh, Ninh Bình, Huế.</p><p>Nhóm nhiệm vụ về công nghiệp văn hóa và thương hiệu quốc gia, trong đó xây dựng đề án phát triển từ 5-10 thương hiệu quốc gia mang tính dẫn dắt.</p><p>Nhóm nhiệm vụ về nguồn lực, hạ tầng và nhân lực, trong đó bố trí tối thiểu 2% tổng chi ngân sách nhà nước hằng năm cho lĩnh vực văn hóa và phân bổ theo hướng đầu tư trọng điểm gắn với hiệu quả đầu ra. </p><p>Ông  nêu nhiệm vụ đầu tư, hoàn thiện các thiết chế quy mô quốc gia bao gồm Bảo tàng quốc gia, Nhà hát quốc gia và Trung tâm nghệ thuật quốc gia. Đáng chú ý, ông cũng thông tin về chương trình đào tạo chuyên sâu 5.000 nhân lực phát triển trò chơi điện tử phục vụ giáo dục lịch sử Việt Nam.</p><p>Nhóm nhiệm vụ về hội nhập quốc tế về văn hóa, ông cho biết mục tiêu cử tùy viên văn hóa, cán bộ phụ trách hợp tác văn hóa tại các cơ quan đại diện ngoại giao ở nước ngoài; hợp tác với UNESCO lập hồ sơ ghi danh thêm 5 di sản văn hóa, thiên nhiên thế giới tiêu biểu.</p><p>Ngoài ra, Việt Nam cũng thành lập mới 1-3 Trung tâm Văn hóa Việt Nam tại các quốc gia đối tác chiến lược như Nga, Mỹ, Trung Quốc, Hàn Quốc, Nhật Bản; nâng cao hiệu quả các trung tâm tại Pháp, Lào...</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/202602250919283683z75617307497612d70bded3252f365b3f3f60dee8d0dbc-1772002592604362038376.jpg\" id=\"img_208611332701773824\" w=\"1200\" h=\"800\" alt=\"Phó thủ tướng - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208611332701773824\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/202602250919283683z75617307497612d70bded3252f365b3f3f60dee8d0dbc-1772002592604362038376.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1200\" height=\"800\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Quang cảnh hội nghị - Ảnh: GIA HÂN</p></figcaption></figure><h2>Cương quyết thu hồi đất bỏ hoang, lãng phí</h2><p>Với nghị quyết 79, Phó thủ tướng cho biết trong nhóm nguồn lực đất đai, tài nguyên cần rà soát, sửa đổi Luật Đất đai hướng tới phân cấp mạnh mẽ, cương quyết thu hồi đất bỏ hoang, lãng phí.</p><p>Tiếp đó là nhóm nguồn lực tài sản kết cấu hạ tầng, trong đó nghiên cứu cơ chế đầu tư hạ tầng trạm đỗ thông minh (Smart Vertiport) theo hướng khuyến khích và ưu đãi đầu tư theo hình thức đối tác công - tư để phát triển hệ thống hạ tầng mặt đất cho kinh tế tầm thấp…</p><p>Nhóm nguồn lực ngân sách nhà nước, Phó thủ tướng nêu rõ việc áp dụng các loại thuế mới liên quan đến tài sản, mức phát thải carbon theo thông lệ quốc tế.</p><p>Nhóm nguồn lực dự trữ quốc gia, quỹ tài chính ngoài ngân sách và vốn nhà nước tại doanh nghiệp, Phó thủ tướng cho biết sẽ sáp nhập, giải thể dứt điểm các quỹ tài chính ngoài ngân sách hoạt động kém hiệu quả, trùng lặp. </p><p>Ủy thác việc quản lý quỹ tài chính nhà nước cho các tổ chức ngân hàng, công ty tài chính chuyên nghiệp. Không hình thành mới các quỹ ngoài ngân sách trừ trường hợp cực kỳ cấp bách…</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"25/02/2026 12:03\" data-id=\"20260225110954935\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/z616312-17719904733531094869396-44-0-794-1200-crop-1771992207221405793858-36-103-589-987-crop-1771997622214796953024.jpg\" data-url=\"/toan-van-phat-bieu-cua-tong-bi-thu-to-lam-tai-hoi-nghi-quan-triet-nghi-quyet-79-80-cua-bo-chinh-tri-20260225110954935.htm\" data-title=\"Toàn văn phát biểu của Tổng Bí thư Tô Lâm tại Hội nghị quán triệt nghị quyết 79, 80 của Bộ Chính trị\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/z616312-17719904733531094869396-44-0-794-1200-crop-1771992207221405793858-36-103-589-987-crop-1771997622214796953024.jpg\" alt=\"Phó thủ tướng: Áp dụng các thuế mới liên quan tài sản, mức phát thải carbon theo thông lệ quốc tế - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Toàn văn phát biểu của Tổng Bí thư Tô Lâm tại Hội nghị quán triệt nghị quyết 79, 80 của Bộ Chính trịĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Nhóm nhiệm vụ về cơ cấu lại vốn và phát triển tập đoàn kinh tế nhà nước, Phó thủ tướng cho biết sẽ có cơ chế chính sách đặc thù cho phép doanh nghiệp có vai trò dẫn dắt được sử dụng toàn bộ nguồn thu từ thoái vốn để tái đầu tư.</p><p>Nhóm nhiệm vụ về thúc đẩy khoa học công nghệ và chuyển đổi số, Phó thủ tướng nêu định hướng thành lập các trung tâm nghiên cứu, quỹ đầu tư mạo hiểm trong doanh nghiệp nhà nước. </p><p>Doanh nghiệp nhà nước tiên phong thực hiện mua bán, sáp nhập gắn với hoạt động chuyển giao công nghệ lõi…</p><p>Các tổ chức tín dụng nhà nước phải số hóa dịch vụ, thực hiện quản lý vốn theo thời gian thực. Phó thủ tướng nêu về việc rà soát, sắp xếp lại mạng lưới hoạt động của các tổ chức tín dụng để nâng cao hiệu quả vận hành.</p><p>Các đơn vị sự nghiệp được chuyển đổi trong lĩnh vực phù hợp sang mô hình doanh nghiệp 100% vốn nhà nước. Ông cũng nêu về sửa đổi quy định cho phép đơn vị tự chủ được chi trả lương, chế độ đãi ngộ chuyên gia như doanh nghiệp.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/z615709-17719856069811603269039-7-0-757-1200-crop-1771985634617760591579.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\" - Ảnh 1.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Ông Nguyễn Thanh Nghị: Ngay trong 2026, xây dựng, ban hành Luật Đất đai sửa đổi<p class=\"VCObjectBoxRelatedNewsItemSapo\">Ông Nguyễn Thanh Nghị nêu rõ lần đầu tiên nội hàm kinh tế nhà nước được xác định một cách đầy đủ, có hệ thống trong một nghị quyết chuyên đề, làm rõ vị trí và mở rộng phạm vi của khu vực này.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/z615803-17720024741381113373460-66-0-816-1200-crop-17720025053641956325666.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/pho-thu-tuong-ap-dung-cac-thue-moi-lien-quan-tai-san-muc-phat-thai-carbon-theo-thong-le-quoc-te-20260225135807445.htm', NULL, '2026-02-25 14:30:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":30,\"Kinh Doanh\":14,\"Th\\u1ebf Gi\\u1edbi\":9},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:38', '2026-02-25 10:06:38'),
('145', '5', '3', 'Diễn viên Thanh Hiền tiết lộ cuộc sống sau khi sinh con thứ hai', 'dien-vien-thanh-hien-tiet-lo-cuoc-song-sau-khi-sinh-con-thu-hai', '\n\n                                        \n\n                                                                                Thanh Hiền cho biết cuộc sống của cô bước sang một chương mới với nhiều niềm...', '\n\n                                        \n\n                                                                                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-143627-17720051273112000026904.png\" id=\"img_208611953261891584\" w=\"1642\" h=\"1050\" alt=\"Diễn viên Thanh Hiền tiết lộ cuộc sống sau khi sinh con thứ hai - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208611953261891584\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-143627-17720051273112000026904.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1642\" height=\"1050\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-143627-17720051273112000026904.png 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-143627-17720051273112000026904.png 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Thanh Hiền cho biết cuộc sống của cô bước sang một chương mới với nhiều niềm vui</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">Ảnh: Chụp màn hình</p></figure><p>Diễn viên Thanh Hiền sinh năm 1989 tại Đà Nẵng, là gương mặt quen thuộc với khán giả truyền hình qua nhiều dự án như <i>Nghiệp sinh tử, Dòng nhớ, Tiệm ăn của quỷ, Trà ma nữ</i>… Sau cuộc hôn nhân đầu đổ vỡ với diễn viên Gia Bảo, cô lựa chọn làm mẹ đơn thân, sống kín tiếng và dành thời gian chăm sóc con gái. Năm 2025, nữ diễn viên khiến nhiều người bất ngờ khi công khai tái hôn và sinh con thứ hai, chính thức bước sang một chương mới của cuộc đời.</p><h2>Thanh Hiền hạnh phúc khi thấy chồng và con gái gắn kết hơn </h2><p>Xuất hiện trong tập 331 chương trình <i>Tâm sự mẹ bỉm sữa</i>, Thanh Hiền có cuộc trò chuyện đầy cảm xúc với MC Maika về hành trình mang thai và sinh con thứ hai. Theo nữ diễn viên, việc có thêm thành viên mới một phần xuất phát từ mong muốn của con gái Grammy. \"Từ khi con nhỏ, bé Grammy đã rất thích có em và lúc nào cũng nói \'má phải sinh em cho con\'. Tôi hứa với con nhưng mãi 8 năm không thực hiện được. Vậy nên khi quyết định có con, tôi xem đó như món quà cho Grammy và cũng là món quà cho gia đình. Khi báo tin có thai, cả chồng và Grammy đều xúc động đến khóc\", cô chia sẻ.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" allow-zoom=\"true\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-134818-17720051273531703901868.png\" id=\"img_208611953176436736\" w=\"1828\" h=\"1058\" alt=\"Diễn viên Thanh Hiền tiết lộ cuộc sống sau khi sinh con thứ hai - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208611953176436736\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-134818-17720051273531703901868.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1828\" height=\"1058\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-134818-17720051273531703901868.png 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-134818-17720051273531703901868.png 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nữ diễn viên rơi nước mắt khi chia sẻ khoảnh khắc đón con thứ hai chào đời</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">Ảnh: Chụp màn hình</p></figure><p>Trong suốt thai kỳ, nữ diễn viên luôn có sự đồng hành của chồng và con gái. Nhờ giữ tinh thần thoải mái, cô không bị nghén hay mệt mỏi nhiều, thậm chí vẫn tham gia quay phim đến tháng thứ 7 mới tạm dừng công việc. Thanh Hiền cho biết cô từng bị tiểu đường thai kỳ nhẹ do thích ăn đồ ngọt nên phải điều chỉnh chế độ ăn uống. \"Tôi chuyển sang ăn kiêng, chú trọng dinh dưỡng hơn. Nhờ vậy cơ thể khỏe mạnh, em bé tăng cân đều\", cô nói. </p><p>Nữ diễn viên cũng xúc động khi chứng kiến chồng và con gái lớn gắn kết hơn trong giai đoạn này. Hai cha con cùng tìm hiểu kiến thức chăm sóc mẹ bầu, thường xuyên nhắc cô ăn uống và nghỉ ngơi hợp lý. Ngày đi sinh trở thành khoảnh khắc đáng nhớ khi bên cạnh cô có chồng, con gái lớn cùng cha mẹ hai bên. Thanh Hiền kể rằng khi nhìn thấy vợ nằm trên bàn mổ, chồng thậm chí đã bật khóc vì lo lắng. Đến lúc em bé chào đời, cả gia đình đều rơi nước mắt vì xúc động. </p><p>Những ngày đầu sau sinh, tổ ấm của Thanh Hiền luôn rộn ràng tiếng cười khi chồng tận tình chăm sóc hai mẹ con, còn con gái lớn thì quấn quýt bên em bé mới chào đời. Ông xã nữ diễn viên chủ động tắm bé, thay tã để cô có thời gian nghỉ ngơi hồi phục. Bên cạnh đó, sự hỗ trợ từ hai bên gia đình giúp Thanh Hiền vơi bớt áp lực trong giai đoạn ở cữ. Dù vẫn phải đối mặt với những đêm thiếu ngủ và nhịp sinh hoạt đảo lộn, nữ diễn viên nói cô cảm thấy trọn vẹn hạnh phúc khi được chứng kiến con lớn lên từng ngày trong vòng tay yêu thương của cả gia đình.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/to-am-17720054135391952561165.jpg\" id=\"img_208612552223182848\" w=\"2048\" h=\"1366\" alt=\"Diễn viên Thanh Hiền tiết lộ cuộc sống sau khi sinh con thứ hai - Ảnh 3.\" title=\"\" rel=\"lightbox\" photoid=\"208612552223182848\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/to-am-17720054135391952561165.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2048\" height=\"1366\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/to-am-17720054135391952561165.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/to-am-17720054135391952561165.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\" data-listener-added_a6225a11=\"true\">Thanh Hiền tận hưởng tổ ấm đủ nếp đủ tẻ, cùng sự gắn kết đặc biệt giữa con gái Grammy và ông xã</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">Ảnh: FBNV</p></figure><p>Khép lại chương trình, diễn viên <i>Tiệm ăn của quỷ </i>gửi lời cảm ơn chân thành đến chồng: \"Cảm ơn anh đã đồng hành, chia sẻ để em luôn nhẹ nhàng trong hành trình mang thai, sinh con và cả hiện tại. Cảm ơn anh đã yêu thương em, Grammy và gia đình mình\". Đồng thời, Thanh Hiền cũng nhắn nhủ đến hai con rằng cô không mong các con trở thành người nổi tiếng hay thành đạt vượt bậc, mà chỉ hy vọng hai chị em luôn yêu thương nhau, sống tử tế, đàng hoàng và có một cuộc đời bình yên.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/anh-man-hinh-2026-02-25-luc-143627-17720051273112000026904-0-0-1026-1642-crop-17720052552101372539672.png', NULL, NULL, NULL, 'https://thanhnien.vn/dien-vien-thanh-hien-tiet-lo-cuoc-song-sau-khi-sinh-con-thu-hai-18526022514575431.htm', NULL, '2026-02-25 16:37:00', '1', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Gi\\u1ea3i Tr\\u00ed\":23,\"\\u0110\\u1eddi S\\u1ed1ng\":11,\"Th\\u1ebf Gi\\u1edbi\":8},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:38', '2026-02-25 10:35:19'),
('146', '2', '2', 'Giới siêu giàu đổ tiền mua biệt thự nghỉ dưỡng trượt tuyết tại Pháp', 'gioi-sieu-giau-do-tien-mua-biet-thu-nghi-duong-truot-tuyet-tai-phap', '\r\n                  Courchevel, một trong những khu nghỉ dưỡng sang trọng nhất vùng núi Alps của Pháp - Ảnh: altibus.comVới sự gia tăng mạnh mẽ của phân khúc cao cấp và siêu cao cấp, thị trường bất độ...', '\r\n                  <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/bds-biet-thu-phap-17720020296161891510154.jpg\" id=\"img_208610151650779136\" w=\"820\" h=\"461\" alt=\"Giới siêu giàu đổ tiền mua biệt thự nghỉ dưỡng trượt tuyết tại Pháp - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208610151650779136\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/bds-biet-thu-phap-17720020296161891510154.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"820\" height=\"461\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Courchevel, một trong những khu nghỉ dưỡng sang trọng nhất vùng núi Alps của Pháp - Ảnh: altibus.com</p></figcaption></figure><p class=\"\">Với sự gia tăng mạnh mẽ của phân khúc cao cấp và siêu cao cấp, thị trường bất động sản vùng núi Pháp những năm gần đây ngày càng mang tính độc quyền, trong bối cảnh nhu cầu sở hữu tài sản “độc bản” của giới siêu giàu tiếp tục duy trì ở mức cao trong khi nguồn cung khan hiếm.</p><p class=\"\">Theo giới chuyên gia, 5 khu nghỉ dưỡng trượt tuyết đắt giá nhất nước Pháp gồm Courchevel, Val d\'Isère, Méribel, Megève và Chamonix tiếp tục giữ vị trí dẫn đầu. Điểm chung của các địa danh này là sức hút quốc tế mạnh mẽ, góp phần đẩy giá bất động sản lên mức cao kỷ lục.</p><p class=\"\">Giá bán tại Courchevel và Val d’Isère có thời điểm đạt tới 55.000 euro/m2, tại Megève và Chamonix ghi nhận các mức đỉnh 22.000 - 25.000 euro/m2.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"12/07/2023 07:40\" data-id=\"20230711134954236\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2023/7/11/can-ho-sieu-sang-nhat-16890649286791041337215-33-0-533-800-crop-16890650210951867012238.jpg\" data-url=\"/gioi-sieu-giau-chop-lay-nhung-can-ho-sieu-sang-o-tokyo-20230711134954236.htm\" data-title=\"Giới siêu giàu chộp lấy những căn hộ siêu sang ở Tokyo\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2023/7/11/can-ho-sieu-sang-nhat-16890649286791041337215-33-0-533-800-crop-16890650210951867012238.jpg\" alt=\"Giới siêu giàu đổ tiền mua biệt thự nghỉ dưỡng trượt tuyết tại Pháp - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Giới siêu giàu chộp lấy những căn hộ siêu sang ở TokyoĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p class=\"\">Dù giá có dấu hiệu chững lại trong năm 2025, các tài sản này vẫn giữ sức hấp dẫn nhờ tính khan hiếm và nhu cầu ổn định.</p><p class=\"\">Giới tài phiệt Pháp và quốc tế, cùng các văn phòng quản lý tài sản gia đình, đã đưa bất động sản nghỉ dưỡng tại các điểm trượt tuyết vào danh mục đầu tư từ nhiều năm nay.</p><p class=\"\">Để đáp ứng yêu cầu ngày càng cao, hệ sinh thái dịch vụ tại các khu nghỉ dưỡng cũng được nâng cấp mạnh, với sự xuất hiện dày đặc của nhà hàng ẩm thực cao cấp và khách sạn hạng sang. Riêng Courchevel dự kiến sớm có 8 khách sạn đạt chuẩn “lâu đài” và 15 khách sạn 5 sao.</p><p class=\"\">Phân khúc bất động sản mới xây chủ yếu hướng tới dòng sản phẩm hạng sang, với căn hộ hoặc nhà nghỉ diện tích trên 300m2, tối thiểu 4 phòng ngủ khép kín, có lối trượt tuyết trực tiếp, không gian mở và tầm nhìn đẹp.</p><p class=\"\">Tại Chamonix, một nhà nghỉ xây năm 2019, rộng 6 phòng ngủ, có spa và bể bơi trong nhà, đã được giao dịch với giá 9 triệu euro.</p><p class=\"\">Ở phân khúc siêu sang, diện tích thường vượt 500m2, tích hợp đầy đủ tiện ích chăm sóc sức khỏe như hồ bơi, phòng xông hơi, phòng tập thể thao cùng dịch vụ cá nhân hóa. Ngân sách của người mua hiện phổ biến ở mức 10-30 triệu euro, cao hơn đáng kể so với 4 năm trước.</p><p class=\"\">Đáng chú ý, tại Val d’Isère, một tòa nhà mới gồm 16 căn hộ với tổng diện tích 1.430m2 đã được một tỉ phú châu Á mua với giá 38 triệu euro để phục vụ nhu cầu gia đình.</p><p class=\"\">Xu hướng nổi bật hiện nay là tìm kiếm các bất động sản “chìa khóa trao tay” hoặc nhà nghỉ diện tích lớn trên 500m2, đi kèm dịch vụ tương đương khách sạn hạng sang như quản gia, nhân viên phục vụ và dịch vụ ẩm thực riêng.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2023/5/19/720-16844912094541376871969-0-0-450-720-crop-1684493415557775688484.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Giới siêu giàu đổ tiền mua biệt thự nghỉ dưỡng trượt tuyết tại Pháp - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Người giàu đổ về London thuê và mua nhà siêu sang<p class=\"VCObjectBoxRelatedNewsItemSapo\">Bất chấp sự suy giảm chung, phân khúc nhà siêu sang có giá trị hơn 5 triệu bảng tại thủ đô London, Anh lại đang được bán khá mạnh.</p><p class=\"\"><br></p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/bds-biet-thu-phap-17720020296161891510154-0-0-461-738-crop-1772002908110914358216.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/gioi-sieu-giau-do-tien-mua-biet-thu-nghi-duong-truot-tuyet-tai-phap-20260225141807043.htm', NULL, '2026-02-25 14:27:36', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":18,\"\\u0110\\u1eddi S\\u1ed1ng\":17,\"Kinh Doanh\":8},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:38', '2026-02-25 10:06:38'),
('147', '2', '3', 'Áp dụng VNeID để quản lý đội tàu, quyết gỡ thẻ vàng', 'ap-dung-vneid-de-quan-ly-doi-tau-quyet-go-the-vang', '\n\n                                        \n\n                                                                                Theo kế hoạch, Đoàn Thanh tra của EU sẽ thực hiện đợt giám sát lần thứ 5 vào...', '\n\n                                        \n\n                                                                                <p>Theo kế hoạch, Đoàn Thanh tra của EU sẽ thực hiện đợt giám sát lần thứ 5 vào đầu tháng 3 liên quan công tác chống khai thác hải sản bất hợp pháp, không báo cáo và không theo quy định (IUU). Đợt kiểm tra lần này có ý nghĩa đặc biệt quan trọng, kết quả của đoàn kiểm tra là yếu tố quyết định đến việc EC gỡ \"thẻ vàng\" hoặc nâng lên cảnh báo \"thẻ đỏ\" đối với thủy sản Việt Nam.<br></p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/4/screen-shot-2026-02-05-at-063251-1770247987647215819735.png\" id=\"img_204926959555870720\" w=\"1256\" h=\"948\" alt=\"Áp dụng VNeID để quản lý đội tàu, gỡ thẻ vàng IUU  - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"204926959555870720\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/4/screen-shot-2026-02-05-at-063251-1770247987647215819735.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1256\" height=\"948\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Đầu tháng 3, EC sẽ cử đoàn công tác sang Việt Nam</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: NGUYỄN LONG</p></figure><p>Do vậy, hôm nay (25.2), thay mặt Chính phủ, Phó thủ tướng Trần Hồng Hà ký Công điện số 18, yêu cầu các bộ ngành địa phương tập trung chuẩn bị làm việc với Đoàn Thanh tra, quyết tâm gỡ cảnh báo \"thẻ vàng\" IUU. Cụ thể, tập trung vào 5 nhóm vấn đề trọng tâm gồm: Thứ nhất là khung pháp lý; thứ 2, quản lý đội tàu; thứ 3, theo dõi, kiểm soát và giám sát tàu cá; thứ 4, truy xuất nguồn gốc khai thác thủy sản và thứ 5 là thực thi pháp luật và xử lý vi phạm theo đúng 5 khuyến cáo của EC.</p><p>Chính phủ yêu cầu các Bộ Tư pháp, Nông nghiệp và Môi trường, Quốc phòng, Công an, Khoa học và Công nghệ, Ngoại giao và các bộ, ngành có liên quan tập trung thực hiện tốt các nhiệm vụ Chính phủ đã giao theo chức năng, nhiệm vụ, thẩm quyền, chịu trách nhiệm về kết quả thực hiện. Trong đó, Bộ Công an chỉ đạo công an các địa phương khẩn trương củng cố hồ sơ, đưa ra truy tố, xét xử các vụ việc vi phạm hình sự trong chống khai thác IUU. Kiểm soát chặt chẽ tàu cá và ngư dân tại nơi cư trú, đảm bảo nắm rõ địa chỉ của mọi chủ tàu, ngư dân và địa bàn hoạt động của tàu cá gắn với cơ sở dữ liệu dân cư quốc gia. Bên cạnh đó, sớm đưa vào áp dụng hệ thống quản lý tàu cá và ngư dân xuất, nhập bến trên nền tảng VNeID để giám sát toàn bộ tàu cá, ngư dân tham gia hoạt động khai thác thủy sản.</p><p>Trong thời gian từ nay đến ngày 9.3, các bộ ngành, địa phương tiếp tục triển khai quyết liệt công tác thanh tra, kiểm tra theo kế hoạch kiểm tra đợt cao điểm việc thực hiện nhiệm vụ chống khai thác hải sản bất hợp pháp, không báo cáo và không theo quy định (IUU) tại 15 địa phương trọng điểm) và các nhiệm vụ giải pháp để thực hiện các nhóm vấn đề trọng tâm theo khuyến cáo của EC.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/screen-shot-2026-02-05-at-063251-1770247987647215819735-85-0-870-1256-crop-1772010620236328115891.png', NULL, NULL, NULL, 'https://thanhnien.vn/ap-dung-vneid-de-quan-ly-doi-tau-quyet-go-the-vang-cho-thuy-san-185260225161103015.htm', NULL, '2026-02-25 16:33:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":15,\"Th\\u1eddi S\\u1ef1\":8,\"Ph\\u00e1p Lu\\u1eadt\":7},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:39', '2026-02-25 10:06:39'),
('148', '3', '2', 'Ông chủ Trung Quốc chi 26 triệu USD thưởng Tết, nhân viên được vơ tiền thỏa thích', 'ong-chu-trung-quoc-chi-26-trieu-usd-thuong-tet-nhan-vien-duoc-vo-tien-thoa-thich', '\r\n                Nhân viên đang đứng đợi tham gia hoạt động đếm tiền của công ty - Ảnh: ZHIHUCEO tên Thôi Bồi Quân của một công ty Trung Quốc đã gây bão mạng xã hội khi trích tới 180 triệu nhân dân t...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/v2-bf84bd0e5271178c8551a8b37d567ae51440w-1772001275473448717799.png\" id=\"img_208608571362861056\" w=\"851\" h=\"1057\" alt=\"Trung Quốc  - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208608571362861056\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/v2-bf84bd0e5271178c8551a8b37d567ae51440w-1772001275473448717799.png\" type=\"photo\" style=\"max-width:100%;\" width=\"851\" height=\"1057\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nhân viên đang đứng đợi tham gia hoạt động đếm tiền của công ty - Ảnh: ZHIHU</p></figcaption></figure><p>CEO tên Thôi Bồi Quân của một công ty Trung Quốc đã gây bão mạng xã hội khi trích tới 180 triệu nhân dân tệ (khoảng 26 triệu USD) từ khoản lợi nhuận 270 triệu nhân dân tệ để thưởng Tết cho nhân viên.</p><p>Theo báo <i>South China Morning Post,</i> ngày 13-2, Công ty Cần trục Kuangshan Hà Nam đã tổ chức tiệc tất niên với màn phát thưởng gây choáng ngợp. </p><p>Hơn 60 triệu nhân dân tệ (8,7 triệu USD) tiền mặt được xếp thành dãy dài trên bàn để trao trực tiếp cho người lao động.</p><p>Bữa tiệc có hơn 800 bàn, phục vụ khoảng 7.000 người. Ngoài việc mời nhân viên lên sân khấu nhận thưởng, công ty còn tổ chức hoạt động tương tác đặc biệt: nhân viên tự tay đếm tiền trong thời gian giới hạn, đếm được bao nhiêu sẽ nhận bấy nhiêu.</p><p>Các video lan truyền trên mạng cho thấy cảnh nhân viên đếm những xấp tiền trải dài trên bàn. Nhiều người ôm chặt những bó tiền lớn, thậm chí không cầm xuể số tiền vừa nhận.</p><p data-placeholder=\"nhập chú thích\">Nhân viên đang trải tiền chuẩn bị cho hoạt động đếm tiền trong thời gian quy định - Nguồn: DOUYIN</p><p>Trong đêm tiệc, ông chủ Thôi Bồi Quân còn trực tiếp yêu cầu bộ phận tài chính tăng thêm tiền thưởng. </p><p>Khi thấy quà tặng là máy giặt, ông nói: \"Sao lại tặng máy giặt? Các anh nghĩ giá vàng tăng rồi à? Những năm trước chúng ta tặng dây chuyền, nhẫn. Cứ mang tiền mặt lên đây, phát thêm cho mỗi người 20.000 nhân dân tệ (2.800 USD) nữa\".</p><p>Tính cả các khoản thưởng chuyển qua tài khoản, tổng chi trả cuối năm vượt 180 triệu nhân dân tệ. </p><p>Với lợi nhuận năm 2025 đạt 270 triệu nhân dân tệ, gần 70% lợi nhuận của công ty đã được chia cho 7.000 nhân viên.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"23/02/2026 21:22\" data-id=\"20260223210345151\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/23/dscf2661-17718549809362065070939-0-0-1280-2048-crop-17718553073531880470566.jpg\" data-url=\"/thuong-tet-gan-9-trieu-dong-nguoi-doanh-nghiep-chay-dua-giu-lao-dong-dau-nam-2026-20260223210345151.htm\" data-title=\"Thưởng Tết gần 9 triệu đồng/người, doanh nghiệp \'chạy đua\' giữ lao động đầu năm 2026\"><h4 class=\"kbwscwlrl-title\">Thưởng Tết gần 9 triệu đồng/người, doanh nghiệp \'chạy đua\' giữ lao động đầu năm 2026</h4></li></ul><p>Thành lập tháng 9-2002, Công ty Cần trục Kuangshan Hà Nam là nhà sản xuất và cung cấp dịch vụ cần cẩu, thiết bị nâng hạ, hoạt động tại hơn 130 quốc gia. Ông Thôi hiện nắm giữ khoảng 98,88% cổ phần doanh nghiệp.</p><p>Đây không phải lần đầu công ty này chịu chi như vậy. Năm 2024, từ lợi nhuận ròng 260 triệu nhân dân tệ, doanh nghiệp đã dành 170 triệu nhân dân tệ để thưởng cho nhân viên.</p><p>Nhân Ngày Quốc tế Phụ nữ tháng 3 năm ngoái, công ty cũng chi gần 1,6 triệu nhân dân tệ để tặng thưởng cho 2.000 lao động nữ.</p><p>Việc liên tục thưởng tiền mặt và phúc lợi hậu hĩnh khiến ông Thôi được cư dân mạng đặt biệt danh là \"ông chủ thích phát tiền nhất Trung Quốc\".</p><p>Phản hồi về danh xưng này, ông chia sẻ: \"Không phải tôi thích phát tiền, mà vì giới trẻ ngày nay đang gánh nhiều áp lực như nợ mua xe, mua nhà. Bất kỳ sự hỗ trợ nào chúng tôi mang lại đều có thể giúp đỡ họ\". </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/xfeuzxpnrtig3h-ihvonl1bgcas-pdijmgvzizbr2q-17720011772641089218464.jpeg\" id=\"img_208608364155854848\" w=\"1280\" h=\"853\" alt=\"Ông chủ Trung Quốc chi 26 triệu USD thưởng Tết, nhân viên được vơ tiền thỏa thích  - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208608364155854848\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/xfeuzxpnrtig3h-ihvonl1bgcas-pdijmgvzizbr2q-17720011772641089218464.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"1280\" height=\"853\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Ông Thôi Bồi Quân được dân mạng ưu ái gọi là ông chủ thích phát tiền nhất Trung Quốc - Ảnh: JIUPAI NEWS</p></figcaption></figure><p>Năm 2004, ông Thôi Bồi Quân thành lập \"Quỹ Hỗ trợ học tập Kuangshan Hà Nam\", mỗi năm quyên góp hơn 1 triệu nhân dân tệ để hỗ trợ sinh viên đại học có hoàn cảnh khó khăn.</p><p>Tháng 1-2016, ông được vinh danh là một trong \"Mười nhân vật kinh tế tiêu biểu của tỉnh Hà Nam năm 2015\". Đến năm 2018, ông được đưa vào \"Bảng xếp hạng người tốt Trung Quốc\". </p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2023/1/4/photo1672820855422-16728208555391576815872.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Ông chủ Trung Quốc chi 26 triệu USD thưởng Tết, nhân viên được vơ tiền thỏa thích trong thời gian  - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Doanh nghiệp dầu khí Hàn Quốc thưởng Tết 120 tháng lương<p class=\"VCObjectBoxRelatedNewsItemSapo\">Hyundai Oilbank, công ty lọc dầu hàng đầu của Hàn Quốc, cho biết chi tiền thưởng Tết cho nhân viên gấp 100 lần mức lương cơ bản, tương đương 120 tháng lương.</p> \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/v2-bf84bd0e5271178c8551a8b37d567ae51440w-1772001275473448717799-314-0-846-851-crop-17720014746001099265168.png', NULL, NULL, NULL, 'https://tuoitre.vn/ong-chu-trung-quoc-chi-26-trieu-usd-thuong-tet-nhan-vien-duoc-vo-tien-thoa-thich-20260225135028179.htm', NULL, '2026-02-25 14:13:00', '0', '0', '0', '0.5', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":10,\"Th\\u1ebf Gi\\u1edbi\":9,\"Gi\\u00e1o D\\u1ee5c\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:39', '2026-02-25 10:06:39'),
('149', '8', '3', 'Sigma International Bilingual School: Mô hình giáo dục song ngữ quốc tế từ nền tảng Iris School', 'sigma-international-bilingual-school-mo-hinh-giao-duc-song-ngu-quoc-te-tu-nen-tang-iris-school', '\n\n                                        \n\n                                                                                Theo kế hoạch, từ năm học 2026 - 2027, nhà trường sẽ phát triển thành Sigma...', '\n\n                                        \n\n                                                                                <p data-id-seo=\"paragraphs-0\">Theo kế hoạch, từ năm học 2026 - 2027, nhà trường sẽ phát triển thành Sigma International Bilingual School - Trường Song ngữ Quốc tế Sigma, hướng tới việc đáp ứng đồng thời các chuẩn mực quốc tế và chương trình quốc gia.</p><p data-id-seo=\"paragraphs-1\">Quá trình chuyển giao không chỉ dừng lại ở sự thay đổi tên gọi hay mô hình quản lý, mà là một bước đi chiến lược nhằm nâng cao chất lượng đào tạo, mở rộng cơ hội học tập và tăng cường khả năng hội nhập cho học sinh tại Thái Nguyên.</p><p data-id-seo=\"paragraphs-2\">Phát biểu tại Lễ ra mắt Sigma International Bilingual School diễn ra tối 30.1 vừa qua, ông Lê Tuấn Dũng - Tổng giám đốc Công ty cổ phần STH Holdings - đại diện đơn vị đầu tư cho biết, Iris School hiện đang trong giai đoạn chuyển giao nhằm từng bước hoàn thiện mô hình Trường Song ngữ Quốc tế Sigma. Lộ trình được triển khai bài bản, đảm bảo sự ổn định trong hoạt động dạy và học hiện tại, đồng thời chuẩn bị đầy đủ các điều kiện về chương trình đào tạo, đội ngũ, cơ sở vật chất và hệ thống quản trị cho giai đoạn phát triển tiếp theo.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/1-17720104363711822661460.jpg\" id=\"img_208623026454958080\" w=\"1400\" h=\"932\" alt=\"Sigma International Bilingual School: Mô hình giáo dục song ngữ quốc tế từ nền tảng Iris School- Ảnh 1.\" title=\"Sigma International Bilingual School: Mô hình giáo dục song ngữ quốc tế từ nền tảng Iris School- Ảnh 1.\" rel=\"lightbox\" photoid=\"208623026454958080\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/1-17720104363711822661460.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1400\" height=\"932\" data-id-seo=\"image-0\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/1-17720104363711822661460.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/1-17720104363711822661460.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Ông Lê Tuấn Dũng - Tổng giám đốc Công ty cổ phần STH Holdings phát biểu tại lễ ra mắt</p></figcaption><p data-placeholder=\"Nhập tác giả ảnh\" class=\"NLPlaceholderShow\"></p></figure><p data-id-seo=\"paragraphs-5\">Theo định hướng, Sigma International Bilingual School sẽ triển khai mô hình giáo dục song ngữ với chuẩn kép đầu ra, đáp ứng yêu cầu của Bộ GD-ĐT Việt Nam cùng với việc giúp học sinh vừa nắm vững kiến thức theo chương trình quốc gia, vừa phát triển năng lực ngoại ngữ, tư duy toàn cầu và khả năng thích ứng trong môi trường học tập đa văn hóa.</p><p data-id-seo=\"paragraphs-6\">Trong lộ trình xây dựng chương trình đào tạo, nhà trường cũng định hướng triển khai chương trình BTEC Level 4 (HNC) ở bậc trung học phổ thông. Theo đó, học sinh lớp 11 và 12 có thể theo học chương trình với 120 tín chỉ, tương đương năm nhất đại học tại Vương quốc Anh, ở các ngành Kinh doanh hoặc Công nghệ Thông tin. Đây là chương trình thuộc hệ thống đào tạo cử nhân thực hành Anh, được công nhận bởi Ofqual (Cơ quan Quản lý chương trình và văn bằng của Chính phủ Anh). Chứng chỉ này cho phép học sinh phân luồng ngành học từ sớm, tích lũy tín chỉ đại học ngay từ bậc phổ thông, đồng thời có thể chuyển tiếp thẳng lên năm hai đại học tại Anh hoặc các chương trình liên kết quốc tế, qua đó rút ngắn thời gian học tập và tối ưu chi phí.</p><p data-id-seo=\"paragraphs-7\">Định hướng phân luồng sớm được xem là một trong những điểm khác biệt nổi bật của mô hình Trường Song ngữ Quốc tế Sigma, giúp học sinh có thêm thời gian khám phá năng lực bản thân, lựa chọn ngành học phù hợp và xây dựng lộ trình học tập hiệu quả sau bậc phổ thông.</p><p data-id-seo=\"paragraphs-8\">Bên cạnh phát triển chương trình đào tạo, Sigma International Bilingual School cũng xây dựng kế hoạch đầu tư đồng bộ về cơ sở vật chất và phát triển đội ngũ giáo viên. Nhà trường chú trọng kiến tạo môi trường học tập hiện đại, linh hoạt, đáp ứng yêu cầu của các phương pháp giảng dạy tiên tiến, đồng thời phát triển đội ngũ giáo viên có chuyên môn vững vàng và kinh nghiệm trong môi trường song ngữ, quốc tế. Nội dung giảng dạy được thiết kế dựa trên năng lực thực tế của học sinh, kết hợp hài hòa giữa kiến thức học thuật, kỹ năng thực hành và các hoạt động trải nghiệm, nhằm hỗ trợ học sinh phát triển toàn diện về trí tuệ, kỹ năng và tư duy độc lập.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/2-1772010436342734219077.jpg\" id=\"img_208623026560860160\" w=\"1400\" h=\"932\" alt=\"Sigma International Bilingual School: Mô hình giáo dục song ngữ quốc tế từ nền tảng Iris School- Ảnh 2.\" title=\"Sigma International Bilingual School: Mô hình giáo dục song ngữ quốc tế từ nền tảng Iris School- Ảnh 2.\" rel=\"lightbox\" photoid=\"208623026560860160\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/2-1772010436342734219077.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1400\" height=\"932\" data-id-seo=\"image-1\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/2-1772010436342734219077.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/2-1772010436342734219077.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Lễ ký kết hợp tác chiến lược Hei Schools và Công ty cổ phần STH Holdings</p></figcaption><p data-placeholder=\"Nhập tác giả ảnh\" class=\"NLPlaceholderShow\"></p></figure><p data-id-seo=\"paragraphs-11\">Cùng với quá trình phát triển mô hình giáo dục phổ thông, STH Holdings cũng triển khai đầu tư trong lĩnh vực mầm non theo định hướng Phần Lan thông qua hợp tác với Hei Schools - hệ thống trường mầm non được phát triển dựa trên nền tảng học thuật của Đại học Helsinki.</p><p data-id-seo=\"paragraphs-12\">Theo kế hoạch, Hei Schools Thái Nguyên sẽ được đầu tư trên quy mô hơn 2 hecta với 20 lớp học tiêu chuẩn Phần Lan, hướng tới xây dựng môi trường học tập đề cao trải nghiệm, cảm xúc và nhịp phát triển tự nhiên của trẻ. Phát triển song song các mô hình từ mầm non đến phổ thông được kỳ vọng sẽ hình thành một hệ thống liền mạch, bền vững và phù hợp với xu hướng giáo dục hiện đại.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/3-1772010436313446093263.jpg\" id=\"img_208623026451472384\" w=\"1400\" h=\"932\" alt=\"Sigma International Bilingual School: Mô hình giáo dục song ngữ quốc tế từ nền tảng Iris School- Ảnh 3.\" title=\"Sigma International Bilingual School: Mô hình giáo dục song ngữ quốc tế từ nền tảng Iris School- Ảnh 3.\" rel=\"lightbox\" photoid=\"208623026451472384\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/3-1772010436313446093263.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1400\" height=\"932\" data-id-seo=\"image-2\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/3-1772010436313446093263.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/3-1772010436313446093263.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Đại diện Phái đoàn Đại sứ quán Phần Lan tại Việt Nam phát biểu tại lễ ký kết</p></figcaption><p data-placeholder=\"Nhập tác giả ảnh\" class=\"NLPlaceholderShow\"></p></figure><p data-id-seo=\"paragraphs-15\">Việc Iris School bước vào giai đoạn chuyển giao để hình thành Trường Song ngữ Quốc tế Sigma phản ánh rõ nét xu hướng đổi mới và hội nhập trong bối cảnh mới. Với lộ trình được xây dựng bài bản và định hướng dài hạn, mô hình này được kỳ vọng sẽ góp phần mở rộng lựa chọn học tập chất lượng cao cho học sinh và phụ huynh tại Thái Nguyên, đồng thời tạo nền tảng cho sự phát triển bền vững của giáo dục địa phương trong những năm tới.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/1-17720104363711822661460-0-0-875-1400-crop-17720107290101991212341.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/sigma-international-bilingual-school-mo-hinh-giao-duc-song-ngu-quoc-te-tu-nen-tang-iris-school-185260225161155483.htm', NULL, '2026-02-25 16:30:00', '1', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Gi\\u00e1o D\\u1ee5c\":21,\"Th\\u1ebf Gi\\u1edbi\":12,\"Th\\u1eddi S\\u1ef1\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:39', '2026-02-25 10:24:54'),
('150', '1', '2', 'Chân dung thủ tướng điển trai, trẻ nhất lịch sử Hà Lan', 'chan-dung-thu-tuong-dien-trai-tre-nhat-lich-su-ha-lan', '\r\n                Ông Rob Jetten dự lễ tuyên thệ nhậm chức thủ tướng tại Cung điện Hoàng gia Huis ten Bosch ở The Hague, Hà Lan ngày 23-2 - Ảnh: APTheo Đài Sky News, ngày 23-2, ông Rob Jetten chính th...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/rob-jetten-17719949380401328823121.png\" id=\"img_208594969040801792\" w=\"980\" h=\"653\" alt=\"Chân dung thủ tướng điển trai, trẻ nhất lịch sử Hà Lan - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208594969040801792\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/rob-jetten-17719949380401328823121.png\" type=\"photo\" style=\"max-width:100%;\" width=\"980\" height=\"653\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Ông Rob Jetten dự lễ tuyên thệ nhậm chức thủ tướng tại Cung điện Hoàng gia Huis ten Bosch ở The Hague, Hà Lan ngày 23-2 - Ảnh: AP</p></figcaption></figure><p>Theo Đài Sky News, ngày 23-2, ông Rob Jetten chính thức kế nhiệm cựu Thủ tướng Dick Schoof, trở thành thủ tướng công khai đồng tính đầu tiên trong lịch sử Hà Lan, đồng thời là nhà lãnh đạo trẻ nhất từng đảm nhiệm cương vị này khi mới 38 tuổi.</p><p>Hãng tin AP cho biết chính phủ liên minh mới do ông Jetten đứng đầu bao gồm Đảng Dân chủ 66 (D66), Đảng Nhân dân vì tự do và dân chủ (VVD) và Đảng Dân chủ Cơ Đốc giáo (CDA).</p><p>Tuy nhiên, liên minh này hiện chỉ nắm giữ 66/150 ghế tại Hạ viện, buộc tân thủ tướng phải tìm kiếm sự ủng hộ từ phe đối lập cho từng dự luật nếu muốn hoàn thành trọn vẹn nhiệm kỳ bốn năm.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/rob-jetten-2-1771995696219899983762.png\" id=\"img_208596559546044416\" w=\"960\" h=\"650\" alt=\"thủ tướng - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208596559546044416\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/rob-jetten-2-1771995696219899983762.png\" type=\"photo\" style=\"max-width:100%;\" width=\"960\" height=\"650\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Quốc vương Willem-Alexander chụp ảnh cùng Thủ tướng Rob Jetten và các thành viên mới của Chính phủ tại Cung điện Huis ten Bosch - Ảnh: AP</p></figcaption></figure><p>Ông Rob Jetten sinh tại Veghel, tốt nghiệp thạc sĩ chuyên ngành hành chính công tại Đại học Radboud Nijmegen. </p><p>Năm 2017, ông được bầu vào Hạ viện Hà Lan và sau đó nhanh chóng khẳng định vị thế khi đảm nhiệm vai trò trưởng nhóm nghị sĩ D66 tại quốc hội.</p><p>Dù sở hữu vẻ ngoài lịch lãm, ông Rob Jetten lại từng bị gán biệt danh \"Robot Jetten\" vì phong thái có phần cứng nhắc trong các lần xuất hiện trên truyền hình. </p><p>Tuy nhiên, gần một thập kỷ sau, ông đã thay đổi hình ảnh theo hướng cởi mở và gần gũi hơn, thường xuyên chia sẻ đời sống cá nhân trên mạng xã hội.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/rob-jetten-boyfriend-1771996048225351698867.png\" id=\"img_208597607699668992\" w=\"1080\" h=\"607\" alt=\"thủ tướng - Ảnh 3.\" title=\"Chân dung thủ tướng điển trai, trẻ nhất lịch sử Hà Lan - Ảnh 3.\" rel=\"lightbox\" photoid=\"208597607699668992\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/rob-jetten-boyfriend-1771996048225351698867.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1080\" height=\"607\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Ông Rob Jetten chia sẻ bức ảnh cùng bạn đời Nicolás Keenan - ngôi sao khúc côn cầu người Argentina - trên mạng xã hội để kỷ niệm lễ đính hôn - Ảnh: INSTAGRAM</p></figcaption></figure><p>Theo Sky News, không chỉ gây ấn tượng bởi yếu tố tuổi tác, tân thủ tướng còn được nhìn nhận như biểu tượng cho sự đa dạng và tinh thần cởi mở trong đời sống chính trị Hà Lan.</p><p>Tổ chức bảo vệ quyền LGBTQ+ hàng đầu Hà Lan COC cho rằng ông Jetten có thể trở thành hình mẫu tích cực cho \"cộng đồng cầu vồng\", khẳng định xu hướng tính dục không phải là rào cản đối với bất kỳ con đường sự nghiệp nào, kể cả vị trí thủ tướng.</p><p>Lễ tuyên thệ của ông Rob Jetten diễn ra tại Cung điện Huis ten Bosch ở The Hague, dưới sự chứng kiến của Quốc vương Willem-Alexander. Quốc vương đã gửi lời chúc nội các mới sẽ vững vàng \"trong những thời điểm bất định\". </p><p>Sau nghi thức tuyên thệ và chụp ảnh truyền thống trên bậc thềm cung điện, các bộ trưởng bước vào phiên họp đầu tiên, chính thức khởi động nhiệm kỳ mới.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/rob-jetten-3-17720005902521438873509.png\" id=\"img_208606823158927360\" w=\"1020\" h=\"683\" alt=\"thủ tướng - Ảnh 4.\" title=\"Chân dung thủ tướng điển trai, trẻ nhất lịch sử Hà Lan - Ảnh 4.\" rel=\"lightbox\" photoid=\"208606823158927360\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/rob-jetten-3-17720005902521438873509.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1020\" height=\"683\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Sau chiến thắng bầu cử, tân Thủ tướng Rob Jetten đã cảm ơn người bạn đời Nicolás Keenan vì sự ủng hộ vô điều kiện suốt chặng đường đã qua - Ảnh: INSTAGRAM</p></figcaption></figure><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/10/14/p2025101378mr6rnv1highresegyptusisraelpalestinianconflict-176042429017938481893-0-0-1600-2560-crop-17604243847311928803506-46-253-986-1756-crop-1760428329491761560614.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Chân dung thủ tướng trẻ nhất lịch sử Hà Lan - Ảnh 1.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Ông Trump gây tranh luận về phân biệt giới tính khi khen Thủ tướng Ý ‘xinh đẹp’<p class=\"VCObjectBoxRelatedNewsItemSapo\">Hôm 13-10, Tổng thống Mỹ Donald Trump gây chú ý khi khen công khai Thủ tướng Ý Giorgia Meloni “xinh đẹp” trong lúc phát biểu tại Hội nghị thượng đỉnh về Gaza tổ chức ở Ai Cập.</p> \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/rob-jetten-1-1771995339317341651621-38-0-651-980-crop-1771995344790642863131.png', NULL, NULL, NULL, 'https://tuoitre.vn/chan-dung-thu-tuong-dien-trai-tre-nhat-lich-su-ha-lan-20260225121015236.htm', NULL, '2026-02-25 14:11:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1eddi S\\u1ef1\":25,\"Th\\u1ebf Gi\\u1edbi\":15,\"Gi\\u00e1o D\\u1ee5c\":3},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:39', '2026-02-25 10:06:39'),
('151', '4', '3', 'Xiaomi sắp tung \'vũ khí\' kết nối mượt mà với iPhone', 'xiaomi-sap-tung-vu-khi-ket-noi-muot-ma-voi-iphone', '\n\n                                        \n\n                                                                                Theo MacRumors, cộng đồng công nghệ đang rỉ tai nhau về một nước đi táo bạo...', '\n\n                                        \n\n                                                                                <p>Theo <em>MacRumors</em>, cộng đồng công nghệ đang rỉ tai nhau về một nước đi táo bạo của Xiaomi. Tại Triển lãm di động toàn cầu (MWC) diễn ra vào tháng tới tại Tây Ban Nha, hãng công nghệ Trung Quốc dự kiến sẽ giới thiệu một bản cập nhật phần mềm mới với khả năng cải thiện đáng kể sự kết nối giữa các thiết bị của hãng và sản phẩm nhà Apple.</p><h2><strong>iOS Bridge: Cầu nối của Xiaomi với hệ sinh thái iOS</strong></h2><p>Bên cạnh tâm điểm là màn ra mắt của dòng flagship Xiaomi 17 series, bản cập nhật phần mềm HyperOS 3.1 được đồn đoán sẽ mang đến một tính năng hoàn toàn mới mang tên iOS Bridge. Mục tiêu của tính năng này là mang lại khả năng tương tác mượt mà chưa từng có giữa hai nền tảng vốn luôn đối đầu nhau.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/copertina-43323-1772004718489-1772004719489828747628.jpg\" id=\"img_208611095703412736\" w=\"1408\" h=\"768\" alt=\"Xiaomi ra mắt tính năng kết nối iOS Bridge cho người dùng iPhone và thiết bị Xiaomi - Ảnh 1.\" title=\"Xiaomi ra mắt tính năng kết nối iOS Bridge cho người dùng iPhone và thiết bị Xiaomi - Ảnh 1.\" rel=\"lightbox\" photoid=\"208611095703412736\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/copertina-43323-1772004718489-1772004719489828747628.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"1408\" height=\"768\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/copertina-43323-1772004718489-1772004719489828747628.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/copertina-43323-1772004718489-1772004719489828747628.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Xiaomi HyperOS 3.1 mang đến khả năng kết nối liền mạch với iOS</p></figcaption><p data-placeholder=\"Nhập tác giả\">ẢNH: CHỤP MÀN HÌNH</p></figure><p>Theo các thông tin rò rỉ từ <em>GizChina</em>, iOS Bridge sẽ mang đến những tính năng đáng kinh ngạc sau:</p><ul><li><strong>Đồng bộ cuộc gọi iPhone</strong>: Hãy tưởng tượng bạn đang có một cuộc gọi đến trên iPhone, nhưng thông báo lại hiển thị ngay trên màn hình máy tính bảng (tablet) hoặc PC Xiaomi. Ngoài ra, bạn còn có thể trực tiếp trả lời hoặc quản lý cuộc gọi đó mà không cần phải chạm tay vào chiếc iPhone.</li><li><strong>Tích hợp AirPods hoàn hảo</strong>: Bạn dùng điện thoại Xiaomi nhưng lại thích tai nghe AirPods? HyperOS 3.1 sẽ giúp AirPods tương thích sâu hơn với thiết bị Xiaomi, cho phép hiển thị mức pin và cung cấp các tùy chọn điều khiển nâng cao, mang lại trải nghiệm mượt mà giống như khi đang ghép nối với thiết bị chính chủ Apple.</li><li><strong>Chia sẻ file nhanh</strong>: Đây có lẽ là tính năng được mong chờ nhất. Tính năng này cho phép chuyển file không dây tốc độ cao trực tiếp giữa iPhone và các thiết bị Xiaomi mà hoàn toàn không cần phải cài đặt hay phụ thuộc vào bất kỳ ứng dụng của bên thứ ba nào (cơ chế hoạt động tương tự như AirDrop).</li></ul><p>Nếu những tính năng này thực sự được trình làng tại Barcelona (Tây Ban Nha) trong khuôn khổ sự kiện MWC (diễn ra từ ngày 2 - 5.3), đây sẽ là một chiến thắng rực rỡ và là tin không thể vui hơn đối với những người dùng \'hệ sinh thái lai\' - những người đang sở hữu đồng thời iPhone, AirPods cùng với điện thoại, laptop hay máy tính bảng của Xiaomi.</p><p>Động thái này cũng cho thấy tham vọng của Xiaomi trong việc giữ chân và thu hút thêm người dùng. Theo dữ liệu từ <em>Omdia</em>, Xiaomi đã nắm giữ tới 16% thị phần thị trường điện thoại thông minh châu Âu trong năm 2025. Việc \'mở rộng vòng tay\' với các thiết bị Apple chắc chắn sẽ giúp hãng gia tăng sức cạnh tranh mạnh mẽ trong thời gian tới.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/copertina-43323-1772004718489-1772004719489828747628-0-87-768-1316-crop-17720047463001314816645.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/xiaomi-sap-tung-vu-khi-ket-noi-muot-ma-voi-iphone-185260225142548586.htm', NULL, '2026-02-25 16:23:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"C\\u00f4ng Ngh\\u1ec7\":25,\"Th\\u1ebf Gi\\u1edbi\":4,\"Kinh Doanh\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:40', '2026-02-25 10:06:40'),
('153', '2', '3', 'Tân binh ELEM FORMULAS chính thức ra mắt: Thách thức chuẩn mực cũ về skincare khoa học', 'tan-binh-elem-formulas-chinh-thuc-ra-mat-thach-thuc-chuan-muc-cu-ve-skincare-khoa-hoc', '\n\n                                        \n\n                                                                                Thách thức chuẩn mực cũ bằng công nghệ thông minhELEM FORMULAS không lựa chọ...', '\n\n                                        \n\n                                                                                <h2 data-id-seo=\"h2-0\"><b>Thách thức chuẩn mực cũ bằng công nghệ thông minh</b></h2><p data-id-seo=\"paragraphs-0\">ELEM FORMULAS không lựa chọn cách tiếp cận truyền thống, mà tập trung nghiên cứu bài bản để mang đến các công thức sáng tạo và khác biệt trong từng sản phẩm. </p><p data-id-seo=\"paragraphs-1\">Điển hình là sự độc đáo của công nghệ nhũ hóa Smart-Lock, giúp làm sạch sâu lỗ chân lông mà không cần nước ấm, phá vỡ giới hạn của các dòng dầu tẩy trang truyền thống.</p><p data-id-seo=\"paragraphs-2\">Sự hiện diện của các hoạt chất đột phá như Cica Exosome™, Melazero hay Bendu 381 không chỉ nâng cao hiệu năng sản phẩm mà còn góp phần khẳng định vị thế của mỹ phẩm nội địa trên bàn cân quốc tế.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/1-1772011432418402802073.png\" id=\"img_208625165475545088\" w=\"1237\" h=\"928\" alt=\"Tân binh ELEM FORMULAS chính thức ra mắt: Thách thức chuẩn mực cũ về skincare khoa học- Ảnh 1.\" title=\"Tân binh ELEM FORMULAS chính thức ra mắt: Thách thức chuẩn mực cũ về skincare khoa học- Ảnh 1.\" rel=\"lightbox\" photoid=\"208625165475545088\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/1-1772011432418402802073.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1237\" height=\"928\" data-id-seo=\"image-0\" data-is-alt-modified=\"true\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Sản phẩm của thương hiệu ELEM FORMULAS được chứng nhận an toàn và hiệu quả tại Trung tâm Ellead (Hàn Quốc)</p></figcaption><p data-placeholder=\"Nhập tác giả ảnh\" class=\"NLPlaceholderShow\"></p></figure><h2 data-id-seo=\"h2-1\">Đề cao tính ứng dụng và hiệu quả thực</h2><p data-id-seo=\"paragraphs-5\">Tính minh bạch và an toàn của các sản phẩm đã được kiểm chứng lâm sàng tại Trung tâm Ellead (Hàn Quốc) với kết quả mức kích ứng không đáng kể (Negligible), phản ánh khả năng dung nạp da lý tưởng.</p><p><b>Thông tin liên hệ: </b></p><ul><li>Website: https://elem.com.vn/</li><li>Hotline:  0946 277 599</li><li>Địa chỉ: Elva Tower, số 211 Trần Não, phường An Khánh, TP.HCM</li></ul>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/1-1772011432418402802073-12-0-785-1237-crop-17720115647541900398187.png', NULL, NULL, NULL, 'https://thanhnien.vn/tan-binh-elem-formulas-chinh-thuc-ra-mat-thach-thuc-chuan-muc-cu-ve-skincare-khoa-hoc-18526022516273762.htm', NULL, '2026-02-25 16:18:00', '0', '0', '0', '0.25', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":5,\"\\u0110\\u1eddi S\\u1ed1ng\":4,\"C\\u00f4ng Ngh\\u1ec7\":3},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:41', '2026-02-25 10:06:41'),
('154', '6', '3', 'Chính thức: Đội tuyển Việt Nam chốt lịch thi đấu giao hữu Bangledesh, làm nóng trước trận đại chiến Malaysia', 'chinh-thuc-doi-tuyen-viet-nam-chot-lich-thi-dau-giao-huu-bangledesh-lam-nong-truoc-tran-dai-chien-malaysia', '\n\n                                        \n\n                                                                                Đội tuyển Việt Nam sẽ gặp Bangladesh ngàyảnh: VFFCơ hội tăng hạng FIFA cho đ...', '\n\n                                        \n\n                                                                                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/friendly-match-17720104048052025537588.png\" id=\"img_208623019545886720\" w=\"1048\" h=\"688\" alt=\"Chính thức: Đội tuyển Việt Nam chốt lịch thi đấu giao hữu Bangledesh, làm nóng trước trận đại chiến Malaysia- Ảnh 1.\" title=\"Chính thức: Đội tuyển Việt Nam chốt lịch thi đấu giao hữu Bangledesh, làm nóng trước trận đại chiến Malaysia- Ảnh 1.\" rel=\"lightbox\" photoid=\"208623019545886720\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/friendly-match-17720104048052025537588.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1048\" height=\"688\" data-id-seo=\"image-0\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Đội tuyển Việt Nam sẽ gặp Bangladesh ngày</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ảnh: VFF</p></figure><h2 data-id-seo=\"h2-0\">Cơ hội tăng hạng FIFA cho đội tuyển Việt Nam</h2><p data-id-seo=\"paragraphs-2\">Đội tuyển Việt Nam đã chốt lịch thi đấu giao hữu quốc tế trong khuôn khổ FIFA Days tháng 3.2026, với đối thủ là đội tuyển Bangladesh đến từ khu vực Nam Á. Trận đấu sẽ diễn ra vào ngày 26.3.</p><p data-id-seo=\"paragraphs-3\">Đây được xem là bước khởi động quan trọng của thầy trò HLV Kim Sang-sik trước cuộc so tài với đội tuyển Malaysia tại vòng loại cuối Asian Cup 2027, tổ chức vào ngày 31.3 trên SVĐ Thiên Trường, tỉnh Ninh Bình.</p><p data-id-seo=\"paragraphs-4\">Đội tuyển Bangladesh, được biết đến với biệt danh \"Những con hổ Bengal\", là một trong những đại diện tiêu biểu của khu vực Nam Á, thường xuyên góp mặt tại các giải đấu do Liên đoàn Bóng đá châu Á (AFC) tổ chức. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"18529704\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/11/19/tuan-hai-goal-lao-0-2-dtvn-tuyen-vn-thuy-an-1763560567758584129182.jpg\" id=\"img_190902423703420928\" w=\"2560\" h=\"1706\" alt=\"Chính thức: Đội tuyển Việt Nam chốt lịch thi đấu giao hữu Bangledesh, làm nóng trước trận đại chiến Malaysia- Ảnh 2.\" title=\"Chính thức: Đội tuyển Việt Nam chốt lịch thi đấu giao hữu Bangledesh, làm nóng trước trận đại chiến Malaysia- Ảnh 2.\" rel=\"lightbox\" photoid=\"190902423703420928\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2025/11/19/tuan-hai-goal-lao-0-2-dtvn-tuyen-vn-thuy-an-1763560567758584129182.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" data-id-seo=\"image-1\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/11/19/tuan-hai-goal-lao-0-2-dtvn-tuyen-vn-thuy-an-1763560567758584129182.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2025/11/19/tuan-hai-goal-lao-0-2-dtvn-tuyen-vn-thuy-an-1763560567758584129182.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Đội tuyển Việt Nam hướng đến 2 chiến thắng trong tháng 3</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ảnh: Thụy An</p></figure><p data-id-seo=\"paragraphs-7\">Với phong độ đang lên trong thời gian gần đây, Bangladesh được xem là đối thủ hứa hẹn mang lại những thử thách cần thiết cho đội tuyển Việt Nam trong giai đoạn chuẩn bị cho trận quyết đấu với Malaysia tại vòng loại cuối Asian Cup 2027. </p><p data-id-seo=\"paragraphs-8\">Ở 2 trận đấu gần đây nhất, Bangladesh đã hòa Nepal 2-2 trong trận giao hữu và thắng Ấn Độ 1-0 ở vòng loại cuối Asian Cup 2027. Theo kế hoạch, đội tuyển Việt Nam sẽ hội quân trở lại vào ngày 17 hoặc 18.3 tới, tập trung chuẩn bị cho 2 trận đấu liên tiếp ở FIFA Day tháng 3.</p><p data-id-seo=\"paragraphs-9\">Việc lựa chọn đội tuyển Bangladesh thi đấu giao hữu được đánh giá phù hợp về chuyên môn, giúp BHL  rà soát lực lượng, thử nghiệm nhân sự trước khi bước vào trận đấu chính thức gặp Malaysia.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/friendly-match-17720104048052025537588-0-0-655-1048-crop-17720106483211508266464.png', NULL, NULL, NULL, 'https://thanhnien.vn/chinh-thuc-doi-tuyen-viet-nam-chot-lich-thi-dau-giao-huu-bangledesh-lam-nong-truoc-tran-dai-chien-malaysia-185260225161428539.htm', NULL, '2026-02-25 16:16:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ec3 Thao\":25,\"Th\\u1ebf Gi\\u1edbi\":3,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:41', '2026-02-25 10:06:41'),
('155', '6', '3', 'Đương kim vô địch Nam Định ‘vùng vẫy’ thoát hiểm, sẽ lâm vào cảnh xuống hạng nếu...', 'duong-kim-vo-dich-nam-dinh-vung-vay-thoat-hiem-se-lam-vao-canh-xuong-hang-neu', '\n\n                                        \n\n                                                                                182 ngày sa sút của CLB Nam Định CLB Nam Định đã nối dài chuỗi ngày không bi...', '\n\n                                        \n\n                                                                                <h2 data-id-seo=\"h2-0\">182 ngày sa sút của CLB Nam Định </h2><p data-id-seo=\"paragraphs-0\">CLB Nam Định đã nối dài chuỗi ngày không biết thắng tại V-League lên con số 182, khi bại trận 0-1 trên sân Thể Công Viettel ở trận đá bù vòng 10 (diễn ra tối 25.2). </p><p data-id-seo=\"paragraphs-1\">Thầy trò HLV Mauro Jeronimo đã chơi đôi công, nỗ lực đẩy cao đội hình pressing tạo sức ép, nhưng để thua từ tình huống phòng ngự mất tập trung giữa hiệp 2. Trận đấu kết thúc bằng những tranh cãi quyết liệt của thủ môn Nguyên Mạnh và tiền đạo Xuân Son với trọng tài, nhưng nhận xét công bằng, đội khách không xứng đáng có điểm.</p><p data-id-seo=\"paragraphs-2\">Trước khối phòng ngự chặt chẽ bậc nhất V-League do Thể Công Viettel giăng ra, CLB Nam Định hoàn toàn bất lực. Mùa trước, Nam Định thắng dễ 2-0 trên sân đội bóng áo lính, song mọi so sánh đều khập khiễn, bởi đội bóng thành Nam mùa này đã khác rất xa.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/the-cong-viettel-nam-dinh-2-17719420603591386952581.jpg\" id=\"img_208479685613150208\" w=\"2560\" h=\"1706\" alt=\"CLB Nam Định - Ảnh 1.\" title=\"CLB Nam Định - Ảnh 1.\" rel=\"lightbox\" photoid=\"208479685613150208\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/the-cong-viettel-nam-dinh-2-17719420603591386952581.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" data-id-seo=\"image-0\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/the-cong-viettel-nam-dinh-2-17719420603591386952581.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/24/the-cong-viettel-nam-dinh-2-17719420603591386952581.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">CLB Nam Định (áo trắng) thụt lùi</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: MINH TÚ</p></figure><p data-id-seo=\"paragraphs-5\">Lần gần nhất Nam Định biết thắng ở V-League, là vào ngày 27.8.2025, khi đội bóng thành Nam hạ PVF-CAND với tỷ số 2-1 tại Thiên Trường. 6 tháng qua, chính xác là 182 ngày, Nam Định trải qua chuỗi 10 trận không thắng (hòa 7, thua 3), giành 7/30 điểm tối đa. Con số đã nói lên tất cả, khi Nam Định là đội thắng ít thứ hai, ghi bàn kém thứ tư và phòng ngự kém thứ sáu tại V-League. Dù lực lượng gần như giữ nguyên từ quân đến \"tướng\", nhưng nhuệ khí hoàn toàn biến mất tại sân Thiên Trường. </p><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">Highlight CLB Thể Công Viettel 1-0 CLB Nam Định: Đương kim vô địch đua trụ hạng</p><p data-id-seo=\"paragraphs-7\">CLB Nam Định chỉ chơi ổn ở ASEAN Club Championship (đoạt ngôi đầu bảng). Còn lại, ở AFC Champions League 2, thầy trò ông Mauro Jeronimo bị loại với vỏn vẹn 9 điểm sau 6 trận. Còn tại V-League, Văn Kiên cùng đồng đội như đoàn tàu mất lái. </p><p data-id-seo=\"paragraphs-8\">Với 12 điểm sau 13 trận, CLB Nam Định đứng hạng 10, chỉ hơn vị trí thứ 13 của PVF-CAND đúng 1 điểm. Đáng lo cho Nam Định, bởi các đối thủ đua trụ hạng như SLNA, HAGL, Thanh Hóa hay PVF-CAND đều đang thể hiện ý chí quật khởi. </p><p data-id-seo=\"paragraphs-9\">Đơn cử, CLB Thanh Hóa chỉ cần 16 người, vẫn hòa Nam Định, đánh bại CLB Công an TP.HCM và khiến CLB Công an Hà Nội (CLB CAHN) trầy trật. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/2/nam-dinh-17699935134891156216040.jpeg\" id=\"img_204393287446593536\" w=\"2048\" h=\"1365\" alt=\"CLB Nam Định - Ảnh 2.\" title=\"CLB Nam Định - Ảnh 2.\" rel=\"lightbox\" photoid=\"204393287446593536\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/2/nam-dinh-17699935134891156216040.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2048\" height=\"1365\" data-id-seo=\"image-1\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/2/nam-dinh-17699935134891156216040.jpeg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/2/nam-dinh-17699935134891156216040.jpeg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">CLB Nam Định đang đua trụ hạng với đội bóng \"nhà nghèo\"</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: ĐÔNG Á THANH HÓA</p></figure><p data-id-seo=\"paragraphs-12\">Đó là sinh khí của những đội bóng tuy không giàu, nhưng có bản sắc địa phương thực thụ. Chính cá tính chiến đấu gai góc sẽ thổi bùng ngọn lửa, giúp HAGL hay Thanh Hóa đứng vững trước nghịch cảnh, luôn tìm được ánh sáng cuối đường hầm. </p><h2 data-id-seo=\"h2-1\">Nghịch lý CLB Nam Định </h2><p data-id-seo=\"paragraphs-13\">Còn CLB Nam Định thì sao?</p><p data-id-seo=\"paragraphs-14\">Một thống kê sẽ khiến nhiều người giật mình: dù vô địch V-League 2 năm liên tiếp, nhưng Nam Định không đóng góp bất cứ tuyển thủ nào cho U.23 và U.20 Việt Nam ở các đợt tập trung dự giải đấu lớn gần nhất. Ở U.17, Nam Định cũng chỉ có một gương mặt, đó là tiền vệ Nguyễn Đại Hiệp Việt Nam. </p><p data-id-seo=\"paragraphs-15\">Trong khi Hà Nội, Thể Công Viettel, HAGL, CLB CAHN, CLB Công an TP.HCM, Ninh Bình, Thanh Hóa, PVF-CAND, Đà Nẵng... dù mạnh hay yếu cũng luôn đảm bảo hệ thống đào tạo trẻ và xây dựng lực lượng kế cận, CLB Nam Định gần như là con số 0 trong việc \"trồng người\".</p><p data-id-seo=\"paragraphs-16\">Công thức vô địch của CLB Nam Định ở 2 mùa giải đã qua, là mua sẵn cầu thủ giỏi ở các đội bóng khác rồi lắp thành đội hình. Cách làm bóng đá kiểu \"mì ăn liền\" này từng diễn ra ở nhiều CLB V-League. Điểm chung của các đội bóng này là không tồn tại được lâu, hoặc nếu có duy trì đến bây giờ, thì gần như chẳng còn dấu ấn trong lòng khán giả. </p><p data-id-seo=\"paragraphs-17\">Bởi xây dựng hệ thống đào tạo trẻ không chỉ để \"tự cung tự cấp\" nhân tài cho đội một, mà còn hình thành bản sắc chơi bóng bền vững, tạo dựng văn hóa CLB, hình thành sợi dây liên kết với địa phương, khẳng định tham vọng làm bóng đá lâu dài thay vì \"ăn xổi\". Những quyền lực bền vững ở V-League như Hà Nội hay Thể Công Viettel đều đi con đường này.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/9/17/nam-dinh-ratchaburi-2-1758114882030237229310.jpg\" id=\"img_179482192846159872\" w=\"2560\" h=\"1706\" alt=\"CLB Nam Định - Ảnh 3.\" title=\"CLB Nam Định - Ảnh 3.\" rel=\"lightbox\" photoid=\"179482192846159872\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2025/9/17/nam-dinh-ratchaburi-2-1758114882030237229310.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" data-id-seo=\"image-2\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/9/17/nam-dinh-ratchaburi-2-1758114882030237229310.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2025/9/17/nam-dinh-ratchaburi-2-1758114882030237229310.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">CLB Nam Định dựa quá nhiều vào ngoại binh, thay vì xây dựng lớp trẻ nội binh bền vững</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: CLB NAM ĐỊNH</p></figure><p data-id-seo=\"paragraphs-20\">Nhưng CLB Nam Định lại đang chọn hướng đi khác. Đội chủ sân Thiên Trường ào ạt mua sao, ký hợp đồng với 13 ngoại binh để đá giải châu Á. Có những trận, Nam Định tung ra sân 9 ngoại binh đá chính. </p><p data-id-seo=\"paragraphs-21\">Chuyện các đội đầu tư mạnh tay cho ngoại binh để tiến sâu ở châu Á là tốt. Thế nhưng, hãy nhìn bài học ở Malaysia hay Indonesia. Khi ngoại binh tràn ngập, nội binh tất yếu phải dự bị, chứ chưa nói đến cầu thủ trẻ.</p><p data-id-seo=\"paragraphs-22\">Trong cơn khủng hoảng trầm trọng, CLB Nam Định chỉ có thể trông cậy ở Xuân Son, người mới trở lại sau chấn thương, cùng những cầu thủ đã chạm ngưỡng 30 như Văn Kiên, Tuấn Anh... Dù đang rất khó khăn, nhưng thầy trò HLV đội Nam Định quyết tâm sẽ vươn lên để sớm thoát khỏi khu vực nguy hiểm.</p><p>Xem LPBank V-League 1-2025-2026 trực tiếp &amp; trọn vẹn trên FPT Play, tại https://fptplay.vn</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/the-cong-viettel-nam-dinh-2-17719420603591386952581-87-391-1011-1869-crop-17720098139631564675893.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/clb-nam-dinh-tro-thanh-duong-kim-vo-dich-dau-tien-xuong-hang-185260225154500676.htm', NULL, '2026-02-25 16:04:00', '0', '0', '0', '0.5', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ec3 Thao\":10,\"Th\\u1ebf Gi\\u1edbi\":4,\"Kinh Doanh\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:42', '2026-02-25 10:06:42'),
('156', '7', '3', 'TP.HCM lấy trụ sở phường làm trạm y tế kiểu mẫu', 'tphcm-lay-tru-so-phuong-lam-tram-y-te-kieu-mau', '\n\n                                        \n\n                                                                                Ngày 25.2, UBND phường Xuân Hòa, TP.HCM cho biết sắp tới sẽ khánh thành trụ...', '\n\n                                        \n\n                                                                                <p data-id-seo=\"paragraphs-0\">Ngày 25.2, UBND phường Xuân Hòa, TP.HCM cho biết sắp tới sẽ khánh thành trụ sở trạm y tế phường và ra mắt mô hình \"Đội chăm sóc sức khỏe liên tục gắn với địa bàn - Y tế gia đình\".</p><p data-id-seo=\"paragraphs-1\">Trạm y tế phường tại số 18 Võ Văn Tần (phường Xuân Hòa) có diện tích 558 m2, tổng diện tích sàn 1.782 m2, tổng mức đầu tư gần 28 tỉ đồng từ ngân sách TP.HCM, bao gồm chi phí xây dựng, trang thiết bị và hạ tầng kỹ thuật đồng bộ. </p><p data-id-seo=\"paragraphs-2\">Ban đầu, công trình này được xây dựng để làm trụ sở UBND phường Võ Thị Sáu, quận 3 cũ. Tuy nhiên, khi sắp xếp lại đơn vị hành chính và bỏ cấp huyện, Đảng ủy, HĐND, UBND phường Xuân Hòa sử dụng trụ sở của Quận ủy, UBND quận 3 cũ làm trụ sở.</p><p data-id-seo=\"paragraphs-3\">Do vậy, công trình tại số 18 Võ Văn Tần trở thành tài sản dôi dư. Sau đó, Đảng ủy, UBND phường Xuân Hòa đề xuất chuyển đổi công năng thành trạm y tế phường.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-1-sy-dong-17720071813922055310966.jpg\" id=\"img_208616260352823296\" w=\"2560\" h=\"1441\" alt=\"TP.HCM lấy trụ sở phường làm trạm y tế kiểu mẫu- Ảnh 1.\" title=\"TP.HCM lấy trụ sở phường làm trạm y tế kiểu mẫu- Ảnh 1.\" rel=\"lightbox\" photoid=\"208616260352823296\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-1-sy-dong-17720071813922055310966.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1441\" data-id-seo=\"image-0\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-1-sy-dong-17720071813922055310966.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-1-sy-dong-17720071813922055310966.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Trụ sở chính của Trạm y tế phường Xuân Hòa (TP.HCM) đặt tại số 18 Võ Văn Tần</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: SỸ ĐÔNG</p></figure><p data-id-seo=\"paragraphs-6\">Lãnh đạo UBND phường Xuân Hòa cho biết trạm y tế được trang bị hệ thống thang máy, máy phát điện dự phòng, hệ thống phòng cháy chữa cháy và các điều kiện kỹ thuật theo quy định. Đây là công trình được đầu tư bài bản, hiện đại, đáp ứng đầy đủ tiêu chuẩn của cơ sở y tế tuyến cơ sở trong giai đoạn mới, tạo nền tảng vững chắc cho việc nâng cao chất lượng khám, chữa bệnh ban đầu cho nhân dân.</p><p data-id-seo=\"paragraphs-7\">Trạm y tế phường gồm 3 phòng quản lý, điều hành và 4 khoa chuyên môn kỹ thuật cùng 2 điểm trạm tiếp cận trực tiếp cộng đồng. Trạm y tế phường có 63 nhân sự, trong đó có 18 bác sĩ đáp ứng đủ các chuyên khoa cơ bản phục vụ nhu cầu chăm sóc sức khỏe ban đầu cho người dân.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-3-sy-dong-177200718810547519210.jpg\" id=\"img_208616271833497600\" w=\"2560\" h=\"1441\" alt=\"TP.HCM lấy trụ sở phường làm trạm y tế kiểu mẫu- Ảnh 2.\" title=\"TP.HCM lấy trụ sở phường làm trạm y tế kiểu mẫu- Ảnh 2.\" rel=\"lightbox\" photoid=\"208616271833497600\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-3-sy-dong-177200718810547519210.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1441\" data-id-seo=\"image-1\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-3-sy-dong-177200718810547519210.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-3-sy-dong-177200718810547519210.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Bên trong Trạm y tế phường Xuân Hòa được đầu tư bài bản, hiện đại, đáp ứng đầy đủ tiêu chuẩn của trạm y tế tuyến cơ sở</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: SỸ ĐÔNG</p></figure><p data-id-seo=\"paragraphs-10\">Bên cạnh khánh thành trụ sở mới, sắp tới Trạm y tế phường Xuân Hòa sẽ thí điểm mô hình \"Đội chăm sóc sức khỏe liên tục gắn với địa bàn - Y tế gia đình\". Đây là bước chuyển quan trọng trong tư duy quản lý và tổ chức hoạt động y tế cơ sở - từ thụ động chờ người bệnh đến khám, sang chủ động quản lý sức khỏe người dân theo hộ gia đình, theo địa bàn phụ trách.</p><p data-id-seo=\"paragraphs-11\">Mô hình này góp phần quản lý tốt bệnh không lây nhiễm, theo dõi sức khỏe người cao tuổi, trẻ em, phụ nữ mang thai, chủ động phòng chống dịch bệnh, giảm tải cho tuyến trên, từng bước xây dựng nền y tế dự phòng vững mạnh ngay từ cơ sở.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-2-sy-dong-1772007188072367889698.jpg\" id=\"img_208616271354302464\" w=\"2560\" h=\"1611\" alt=\"TP.HCM lấy trụ sở phường làm trạm y tế kiểu mẫu- Ảnh 3.\" title=\"TP.HCM lấy trụ sở phường làm trạm y tế kiểu mẫu- Ảnh 3.\" rel=\"lightbox\" photoid=\"208616271354302464\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-2-sy-dong-1772007188072367889698.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1611\" data-id-seo=\"image-2\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-2-sy-dong-1772007188072367889698.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-2-sy-dong-1772007188072367889698.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nhân viên trạm y tế đang gấp rút lau dọn, chuẩn bị đưa cơ sở mới vào vận hành</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: SỸ ĐÔNG</p></figure><p data-id-seo=\"paragraphs-14\">Từ nay đến cuối năm 2026, phường Xuân Hòa đặt mục tiêu trên 90% người dân sinh sống trong khu vực thí điểm được tạo hồ sơ sức khỏe điện tử cá nhân; trên 95% những người thuộc nhóm nguy cơ cao được cập nhật hồ sơ đầy đủ liên tục; trên 70% người mắc tăng huyết áp, đái tháo đường đang điều trị ổn được quản lý, theo dõi và tiếp tục điều trị bởi đội chăm sóc sức khỏe…</p><p data-id-seo=\"paragraphs-15\">Phường Xuân Hòa được sáp nhập từ phường Võ Thị Sáu và một phần phường 4, quận 3 cũ, rộng 2,2 km2, dân số hơn 38.000 người, mật độ dân số đông đúc. Trên địa bàn phường có nhiều cơ quan chính trị, hành chính quan trọng và nhiều bệnh viện lớn.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/tram-y-te-phuong-xuan-hoa-2-sy-dong-1772007188072367889698-204-89-1611-2340-crop-1772007436629463166901.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/tphcm-lay-tru-so-phuong-lam-tram-y-te-kieu-mau-185260225150838581.htm', NULL, '2026-02-25 16:00:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"S\\u1ee9c Kh\\u1ecfe\":30,\"Th\\u1eddi S\\u1ef1\":10,\"\\u0110\\u1eddi S\\u1ed1ng\":5},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:42', '2026-02-25 10:06:42'),
('157', '2', '3', 'Xổ số miền Nam ngày 25 tháng 2 - Kết quả xổ số hôm nay thứ tư', 'xo-so-mien-nam-ngay-25-thang-2-ket-qua-xo-so-hom-nay-thu-tu', '\n\n                                        \n\n                                                                                Báo Thanh Niên cập nhật nhanh nhất kết quả xổ số miền Nam ngày 25 tháng 2; x...', '\n\n                                        \n\n                                                                                <p data-id-seo=\"paragraphs-0\">Báo <i>Thanh Niên</i> cập nhật nhanh nhất kết quả xổ số miền Nam ngày 25 tháng 2; xổ số miền Bắc (XSMB), kết quả xổ số miền Trung (XSMT), số điện toán trực tiếp nhanh nhất hôm nay thứ tư ngày 25.2.2026.</p><p data-id-seo=\"paragraphs-1\">Xổ số Đồng Nai, Cần Thơ, Sóc Trăng, Đà Nẵng, Khánh Hòa...</p><h2 data-id-seo=\"h2-0\">Kết quả xổ số miền Nam ngày 25 tháng 2: Đang cập nhật....</h2>Xổ số miền Nam ngày 25 tháng 2ĐỒNG NAICẦN THƠSÓC TRĂNG<p>ngày 25.2.2026</p><p> </p><p> </p><p> </p>Giải tám<p> </p><p> </p><p> </p>Giải bảy<p> </p><p> </p><p> </p>Giải sáu<p> </p><p> </p><p> </p>Giải năm<p> </p><p> </p><p> </p>Giải tư<p> </p><p> </p><p> </p>Giải ba<p> </p><p> </p><p> </p>Giải nhì<p> </p><p> </p><p> </p>Giải nhất<p> </p><p> </p><p> </p>Giải đặc biệt<p> </p><p> </p><p> </p><h2 data-id-seo=\"h2-1\">Kết quả xổ số miền Trung ngày 25 tháng 2: Đang cập nhật...</h2>XSMT thứ tưĐÀ NẴNGKHÁNH HÒA<p>ngày 25.2.2026</p><p> </p><p> </p>Giải tám<p> </p><p> </p>Giải bảy<p> </p><p> </p>Giải sáu<p> </p><p> </p>Giải năm<p> </p><p> </p>Giải tư<p> </p><p> </p>Giải ba<p> </p><p> </p>Giải nhì<p> </p><p> </p>Giải nhất<p> </p><p> </p>Giải đặc biệt<p> </p><p> </p><h2 data-id-seo=\"h2-2\">Kết quả xổ số miền Bắc ngày 25 tháng 2: Đang cập nhật...</h2>XSMB thứ tư<p>Ký hiệu trúng đặc biệt:</p>Giải đặc biệt<p> </p>Giải nhất<p> </p>Giải nhì<p> </p>Giải ba<p> </p>Giải tư<p> </p>Giải năm<p> </p>Giải sáu<p> </p>Giải bảy<p> </p><h2 data-id-seo=\"h2-3\">Kết quả xổ số điện toán ngày 25 tháng 2: Đang cập nhật...</h2><p data-id-seo=\"paragraphs-3\">Mời bạn đọc xem kết quả xổ số (KQXS) miền Bắc (XSMB), kết quả xổ số miền Nam (XSMN), kết quả xổ số miền Trung (XSMT) được cập nhật trên Báo <i>Thanh Niên</i> mỗi ngày.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2023/2/10/kqxs-formal-16760153917442018849280.png', NULL, NULL, NULL, 'https://thanhnien.vn/xo-so-mien-nam-ngay-25-thang-2-ket-qua-xo-so-hom-nay-thu-tu-185260225145732811.htm', NULL, '2026-02-25 16:00:00', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":1,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:43', '2026-02-25 10:06:43'),
('158', '10', '3', 'Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách', 'nang-tam-than-thai-nho-cap-bai-trung-kinh-mat-va-tui-xach', '\n                    \n                                        Trong thời trang hiện đại, kính mắt và túi xách không chỉ là phụ kiện đi kèm mà còn là yếu tố quyết định thần thái của tổng thể trang phục...', '\n                    \n                                        <p data-id-seo=\"paragraphs-0\">Trong thời trang hiện đại, kính mắt và túi xách không chỉ là phụ kiện đi kèm mà còn là yếu tố quyết định thần thái của tổng thể trang phục. </p><h2 data-id-seo=\"h2-0\">Kính mắt gọng vuông phối túi xách cầm tay</h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/1-1771933993423381603222.jpg\" id=\"img_208462772610224128\" w=\"1100\" h=\"1466\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 1.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 1.\" rel=\"lightbox\" photoid=\"208462772610224128\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/1-1771933993423381603222.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-0\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Kính mắt thời trang gọng trắng khi phối cùng túi xách cầm tay tôn lên phong cách sang trọng. Khánh Vân xuất hiện trong bản phối áo tank top ôm body được sơ vin khéo léo với quần denim dáng đứng khoe trọn sắc vóc. Chiếc kính mắt gọng vuông sắc trắng cài nhẹ trên tóc tạo sự cá tính, chỉ cần thêm một túi xách cầm tay da với sắc xám hiện đại là đã hoàn thiện vẻ ngoài khỏe khoắn để xuống phố</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @KHANHVANNGUYEN25</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/2-17719339934902034609517.jpg\" id=\"img_208462772608126976\" w=\"1080\" h=\"1440\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 2.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 2.\" rel=\"lightbox\" photoid=\"208462772608126976\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/2-17719339934902034609517.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-1\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Chiếc đầm tím nổi bật với họa tiết cổ điển xen lẫn phom dáng hiện đại, khoác bên ngoài bằng chiếc áo sơ mi trắng dài tay tạo sự duyên dáng khó trộn lẫn. Chỉ cần điểm thêm chiếc kính mắt thời trang sắc trắng và túi xách cầm tay tông đen là đã hoàn thiện diện mạo quý phái, thu hút trọn ánh nhìn nơi đông người</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @HUOGGIANGGGG</p></figure><h2 data-id-seo=\"h2-1\">Kính mắt mèo thời trang phối túi xách </h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/3-1771933993529567764558.jpg\" id=\"img_208462772648837120\" w=\"1090\" h=\"1453\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 3.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 3.\" rel=\"lightbox\" photoid=\"208462772648837120\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/3-1771933993529567764558.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-2\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Sự kết hợp giữa kính mắt mèo và túi xách mang đến cho nàng điểm nhấn thời thượng. Diện lên mình chiếc áo polo sweater tông đỏ mận cá tính phối cùng quần shorts cạp cao màu trắng khoe trọn đôi chân thanh mảnh. Chiếc kính mắt mèo dáng lớn phom ôm giúp tôn trọn sống mũi cao thẳng tắp. Hoàn thiện bằng chiếc túi xách họa tiết ca rô tông hồng đỏ đan xen tạo nét nổi bật riêng biệt</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @CHAUBUI_</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/4-1771933993674546924402.jpg\" id=\"img_208462772620529664\" w=\"1080\" h=\"1349\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 4.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 4.\" rel=\"lightbox\" photoid=\"208462772620529664\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/4-1771933993674546924402.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-3\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Chiếc áo cardigan sắc xám khoác nhẹ bên ngoài, phối cùng chiếc chân váy nỉ tone sur tone dáng ngắn giúp tôn chiều cao tự nhiên. Điểm nhấn chính là chiếc kính mắt mèo sắc đen và chiếc túi xách da cầm tay đầy quý phái</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @CHAUBUI_</p></figure><h2 data-id-seo=\"h2-2\">Kính mắt màu nâu phối túi xách dáng hộp </h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/5-1771933993706228361072.jpg\" id=\"img_208462772679430144\" w=\"1080\" h=\"1350\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 5.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 5.\" rel=\"lightbox\" photoid=\"208462772679430144\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/5-1771933993706228361072.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-4\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Xuất hiện trong chiếc đầm trễ vai ôm body với phần chân váy xếp layer xòe nhẹ tạo sự mềm mại cho vóc dáng. Chiếc mắt kính màu nâu dáng oval ngọt ngào cùng chiếc túi xách da mini dáng hộp để tôn lên thần thái sang trọng. Không quên vũ khí của phái đẹp là đôi giày cao gót mũi nhọn để tự tin tỏa sáng tại các buổi dạ tiệc</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @HUOGGIANGGGG</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/6-17719339937721621884448.jpg\" id=\"img_208462772584878080\" w=\"1080\" h=\"1397\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 6.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 6.\" rel=\"lightbox\" photoid=\"208462772584878080\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/6-17719339937721621884448.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-5\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Trẻ trung với chiếc áo len dệt kim sắc trắng với họa tiết dễ thương đầy sắc màu, sánh đôi cùng quần lửng màu đen và xăng đan đế thấp dáng bitis để tạo điểm nhấn riêng biệt. Để nâng tầm bản phối, bạn có thể lựa chọn chiếc kính mắt nâu dáng vuông với họa tiết báo đốm đang nổi đình nổi đám cùng chiếc túi xách cầm tay dáng hộp sắc xanh giúp trang phục màu trung tính bớt phần đơn điệu</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @CHAUBUI_</p></figure><h2 data-id-seo=\"h2-3\">Kính râm thời trang phối túi xách da</h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/7-177193399390991525938.jpg\" id=\"img_208462772600266752\" w=\"1080\" h=\"1440\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 7.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 7.\" rel=\"lightbox\" photoid=\"208462772600266752\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/7-177193399390991525938.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-6\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Kính râm thời trang phối túi xách da dễ dàng ghi dấu ấn thời trang trong mắt người đối diện. Áo crop top ôm body lệch vai đầy nghệ thuật với những lỗ kim loại nhỏ được đính thẳng hàng, phối cùng quần denim tone sur tone ống loe giúp hack dáng cực đỉnh. Chiếc túi da từ thương hiệu nổi tiếng kết hợp với kính râm dễ dàng giúp bạn tôn lên vẻ ngoài sang chảnh</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @CHIPUPU</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/24/8-17719339939721857008506.jpg\" id=\"img_208462772602363904\" w=\"1080\" h=\"1440\" alt=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 8.\" title=\"Nâng tầm thần thái nhờ \'cặp bài trùng\' kính mắt và túi xách- Ảnh 8.\" rel=\"lightbox\" photoid=\"208462772602363904\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/24/8-17719339939721857008506.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"\" height=\"\" data-id-seo=\"image-7\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Sang trọng khi lựa đầm suông dáng ngắn sắc xanh dịu mắt, tôn lên đôi chân dài của người diện mà vẫn thoải mái. Mang theo luồng gió hiện đại khi đeo chiếc kính râm thời trang và túi xách da tông đỏ trầm nổi bật, tạo nên sự kết hợp màu sắc đầy cuốn hút</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: @CHIPUPU</p></figure><p data-id-seo=\"paragraphs-17\"> </p>\n\n                    \n                    \n                                        \n                ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/24/8-17719339939721857008506-125-0-800-1080-crop-17719341731451486664079.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/thoi-trang-tre/nang-tam-than-thai-nho-cap-bai-trung-kinh-mat-va-tui-xach-185260224185822129.htm', NULL, '2026-02-25 16:00:00', '0', '0', '0', '0.4', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"\\u0110\\u1eddi S\\u1ed1ng\":8,\"Th\\u1ebf Gi\\u1edbi\":2,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:43', '2026-02-25 10:06:43'),
('159', '6', '3', 'Chờ đợi gì tại World Cup 2026?', 'cho-doi-gi-tai-world-cup-2026', '\n\n                                        \n\n                                                                                Tây Ban Nha vượt trộiĐương kim vô địch Argentina có thể bảo vệ ngôi vương tạ...', '\n\n                                        \n\n                                                                                <h2 data-id-seo=\"h2-0\">Tây Ban Nha vượt trội</h2><p data-id-seo=\"paragraphs-0\">Đương kim vô địch Argentina có thể bảo vệ ngôi vương tại World Cup kỳ này? Xin được nói ngay là đối với những ai chưa từng xem các kỳ World Cup 1958, 1962, thì việc một đội bóng bảo vệ được chức vô địch World Cup là điều họ chưa hề được chứng kiến trong đời. Sau Argentina thì phần còn lại của thế giới bóng đá bên ngoài châu Âu chỉ còn đúng một đội đáng kể, đó là Brazil. Người ta không bao giờ gạch tên đội này mỗi khi điểm danh các ứng cử viên vô địch World Cup. Nhưng đội tuyển Brazil đã suy yếu và có quá nhiều vấn đề trong thời gian gần đây, đến nỗi phải lần đầu tiên trông cậy vào một HLV nước ngoài (Carlo Ancelotti, người Ý).</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/23/2-17718521773331684389174.jpg\" id=\"img_208291187903913984\" w=\"2560\" h=\"1707\" alt=\"Chờ đợi gì tại World Cup 2026?- Ảnh 1.\" title=\"Chờ đợi gì tại World Cup 2026?- Ảnh 1.\" rel=\"lightbox\" photoid=\"208291187903913984\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/23/2-17718521773331684389174.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" data-id-seo=\"image-0\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/23/2-17718521773331684389174.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/23/2-17718521773331684389174.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Chủ tịch FIFA<i> (trái) </i>tiết lộ toàn bộ vé của World Cup 2026 đã được bán hết</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: REUTERS</p></figure><p data-id-seo=\"paragraphs-3\">Bóng đá châu Âu giờ cũng chỉ còn vài đội vượt trội. Chi tiết lạ đến mức giật gân là kể cả khi VCK World Cup đã được mở rộng đến 48 đội, vẫn chưa biết đội tuyển Ý nổi tiếng có được góp mặt hay không (họ còn phải đá play-off). Anh, Pháp, Đức đều đáng kể, với những điểm mạnh riêng. Nhưng xét tổng thể, nếu trao cúp thế giới theo phương thức bầu chọn, Tây Ban Nha sẽ lên ngôi trong thời điểm này. Nhà vô địch EURO 2024 chính là ứng cử viên vô địch toàn diện nhất hiện thời, từ lối chơi cho đến lực lượng, kinh nghiệm.</p><p data-id-seo=\"paragraphs-4\">Một mặt, bóng đá đỉnh cao đã được \"cào bằng\" đến mức đội tuyển Nhật Bản đã rất nhiều lần thắng Đức, Brazil, Tây Ban Nha trong vài năm nay. Nhưng mặt khác, mỗi khi vũ hội World Cup sôi động thì vinh quang rút cuộc cũng chỉ có thể thuộc về vài đội mạnh đích thực. Cụ thể năm nay chỉ có Tây Ban Nha, Anh, Pháp, Đức, Argentina, Brazil là đáng kể.</p><h2 data-id-seo=\"h2-1\">Vẫn sẽ có những bất ngờ thú vị</h2><p data-id-seo=\"paragraphs-5\">Về mặt số liệu thuần túy, đây là lần đầu tiên VCK World Cup có đến 3 nước chủ nhà, và cũng lần đầu tiên được mở rộng đến con số 48 đội dự giải. Hẳn nhiên, đây là kỳ World Cup lớn nhất trong lịch sử, về nhiều mặt, và nó diễn ra ngay sau kỳ World Cup... nhỏ nhất (xét theo diện tích nước chủ nhà). Diện tích Qatar chỉ là 11.581 km2 và đấy là lý do vì sao tại World Cup 2022 người ta có thể đến sân xem trực tiếp những 4 trận đấu chỉ trong một ngày. Giờ thì ngược lại: một đội bóng có thể sẽ phải di chuyển hàng nghìn cây số giữa hai trận đấu, khi World Cup 2026 diễn ra trên khắp lục địa Bắc Mỹ. Khán giả và các đội bóng trong cuộc sẽ phải chuẩn bị tỉ mỉ, công phu hơn rất nhiều tại kỳ World Cup có đến 104 trận đấu này.</p><p data-id-seo=\"paragraphs-6\">Trước mắt, World Cup 2026 sẽ có ít nhất 4 tân binh: Cape Verde, Curacao, Jordan, Uzbekistan. Nhiều gương mặt mới nữa cũng có thể sẽ xuất hiện sau loạt trận tranh vé vớt vào cuối tháng 3. Sẽ là sai lầm nghiêm trọng nếu các đội bóng danh tiếng khinh địch khi đụng độ các đối thủ mới mẻ trong thời buổi này. Khác biệt lớn nhất của vòng loại World Cup 2026 so với mọi giải đấu trước đây là đẳng cấp chuyên môn của rất nhiều đội bóng nhỏ đã được cải thiện đến mức nhảy vọt, vì một trào lưu chung mang tính toàn cầu: tận dụng nguồn gốc của cầu thủ để triệu tập vào ĐTQG.</p><p data-id-seo=\"paragraphs-7\">Chỉ có một loạt trận rầm rộ để các đội tuyển đá giao hữu, rà soát lực lượng trước World Cup, đó là đợt \"FIFA Days\" cuối tháng 3. Sau đó, mỗi đội sẽ đá tập 1 - 2 trận sát VCK, ngay tại các nước chủ nhà, để làm quen sân bãi và khí hậu trước khi vào cuộc. Chức vô địch World Cup sẽ lại về tay một trong vài \"đại gia\" như đã nêu. Nhưng bất ngờ nhỏ thì chắc sẽ có rất nhiều.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/23/2-17718521773331684389174-107-0-1707-2560-crop-1771852194773292991396.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/cho-doi-gi-tai-world-cup-2026-185260223201112116.htm', NULL, '2026-02-25 15:59:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ec3 Thao\":26,\"Th\\u1ebf Gi\\u1edbi\":14,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:44', '2026-02-25 10:06:44'),
('160', '7', '3', 'Thẻ BHYT hết hạn có thể bị mất quyền lợi 5 năm liên tục', 'the-bhyt-het-han-co-the-bi-mat-quyen-loi-5-nam-lien-tuc', '\n\n                                        \n\n                                                                                Theo Bảo hiểm xã hội (BHXH) Việt Nam, người tham gia BHXH thẻ BHYT còn giá t...', '\n\n                                        \n\n                                                                                <p>Theo Bảo hiểm xã hội (BHXH) Việt Nam, người tham gia BHXH thẻ BHYT còn giá trị sử dụng là căn cứ để quỹ BHYT thanh toán chi phí khám chữa bệnh cho người tham gia.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/3/27/edit-the-bhyt-giay-17430665290681689764819.jpeg\" id=\"img_147923306328383488\" w=\"1000\" h=\"563\" alt=\"Thẻ BHYT hết hạn và quyền lợi khám chữa bệnh trong 5 năm liên tục - Ảnh 1.\" title=\"Thẻ BHYT hết hạn và quyền lợi khám chữa bệnh trong 5 năm liên tục - Ảnh 1.\" rel=\"lightbox\" photoid=\"147923306328383488\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2025/3/27/edit-the-bhyt-giay-17430665290681689764819.jpeg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"1000\" height=\"563\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Người tham gia BHYT cần chủ động kiểm tra thẻ BHYT sắp hết hạn hoặc đã hết hạn để sớm thực hiện thủ tục gia hạn thẻ</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: HOÀNG MẠNH</p></figure><p>Trong trường hợp người tham gia vô tình để thẻ BHYT hết hạn, nếu không may gặp bất trắc về sức khỏe sẽ phải tự chi trả toàn bộ chi phí khám chữa bệnh.</p><p>Để bảo đảm quyền lợi khám chữa bệnh BHYT của bản thân, BHXH Việt Nam lưu ý người tham gia cần chủ động kiểm tra thời hạn thẻ BHYT và kịp thời gia hạn thẻ khi sắp hết hạn, tránh gián đoạn quyền lợi khám chữa bệnh chính đáng và không mất quyền lợi tham gia 5 năm liên tục.</p><p>Hiện nay, BHXH Việt Nam đã triển khai nhiều kênh tra cứu thời hạn thẻ BHYT thuận tiện, cho phép người tham gia kiểm tra thông tin thẻ BHYT mọi lúc, mọi nơi. </p><p>Người tham gia có thể tra cứu trên ứng dụng VNeID bằng cách đăng nhập tài khoản, vào mục \"Ví giấy tờ\", chọn \"Thẻ BHYT\" để xem thời hạn sử dụng.</p><p>Cách thứ hai, có thể tra cứu trên ứng dụng VssID - BHXH số. Sau khi đăng nhập vào ứng dụng, chọn mục \"Thẻ BHYT\" để kiểm tra giá trị sử dụng, thời điểm đủ 5 năm liên tục và quyền lợi hưởng. Hình ảnh thẻ BHYT trên ứng dụng có thể xuất trình khi đi khám chữa bệnh thay cho thẻ BHYT giấy.</p><p>Cạnh đó, người dân truy cập trên Cổng Thông tin điện tử BHXH Việt Nam tại địa chỉ: https://baohiemxahoi.gov.vn/tracuu/Pages/tra-cuu-thoi-han-su-dung-the-bhyt.aspx, chọn mục \"Tra cứu giá trị sử dụng BHYT\", nhập mã số BHYT, họ tên, ngày tháng năm sinh theo yêu cầu để kiểm tra thời hạn thẻ.</p><p>Cách thứ tư, tra cứu qua Tổng đài chăm sóc khách hàng của BHXH Việt Nam. Người dân có thể gọi điện thoại tới số 19009068 (cước phí 1.000 đồng/phút), cung cấp mã số BHYT, họ tên và ngày sinh theo hướng dẫn để được hỗ trợ tra cứu thời hạn và quá trình tham gia BHYT.</p><p>Trong trường hợp thẻ BHYT sắp hết hạn hoặc đã hết hạn, người tham gia cần sớm thực hiện thủ tục gia hạn thẻ BHYT. Việc kiểm tra và gia hạn thẻ BHYT kịp thời giúp bảo đảm quyền lợi khám chữa bệnh BHYT theo quy định của người tham gia, tránh gián đoạn hoặc phát sinh chi phí khám chữa bệnh không đáng phải chi trả nếu thẻ BHYT còn hiệu lực.</p><p>Thủ tục đổi thẻ BHYT hết hạn không quá phức tạp và có thể thực hiện qua nhiều hình thức khác nhau. Quan trọng nhất là người tham gia cần kiểm tra thời hạn thẻ BHYT của mình và chuẩn bị đầy đủ giấy tờ cần thiết để đảm bảo quyền lợi khi sử dụng thẻ trong quá trình khám chữa bệnh.</p><p>Theo điểm c, điều 22, luật BHYT quy định về mức hưởng BHYT nêu rõ: người tham gia BHYT đủ 5 năm liên tục trở lên sẽ được hưởng 100% chi phí khám, chữa bệnh khi số tiền cùng chi trả chi phí khám, chữa bệnh trong năm lớn hơn 6 tháng lương cơ sở, trừ trường hợp tự đi khám, chữa bệnh không đúng tuyến.</p><p>Luật BHYT cho phép người tham gia được đóng gián đoạn BHYT tối đa không quá 3 tháng mà vẫn được tính vào thời gian đóng BHYT 5 năm liên tục. Ngược lại, người tham gia ngừng đóng BHYT (quá 3 tháng) thì quá trình tính 5 năm liên tục sẽ bị ngắt quãng. Người tham gia mất quyền lợi hưởng các ưu đãi và khi tham gia BHYT trở lại, thời gian tham gia BHYT tính hưởng 5 năm liên tục phải tính lại từ đầu.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/edit-the-bhyt-giay-17430665290681689764819-0-0-563-901-crop-17720073598741860001377.jpeg', NULL, NULL, NULL, 'https://thanhnien.vn/the-bhyt-het-han-co-the-bi-mat-quyen-loi-5-nam-lien-tuc-185260225152002658.htm', NULL, '2026-02-25 15:54:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"S\\u1ee9c Kh\\u1ecfe\":34,\"C\\u00f4ng Ngh\\u1ec7\":4,\"Th\\u1eddi S\\u1ef1\":3},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:44', '2026-02-25 10:06:44'),
('161', '9', '3', 'Đồng Nai: Truy bắt nhóm người mang súng, bình xịt hơi cay đi đòi nợ', 'dong-nai-truy-bat-nhom-nguoi-mang-sung-binh-xit-hoi-cay-di-doi-no', '\n\n                                        \n\n                                                                                Ngày 25.2, Cơ quan Cảnh sát điều tra Công an tỉnh Đồng Nai cho biết đã khởi...', '\n\n                                        \n\n                                                                                <p class=\"\">Ngày 25.2, Cơ quan Cảnh sát điều tra Công an tỉnh Đồng Nai cho biết đã khởi tố vụ án, khởi tố bị can và bắt tạm giam Nguyễn Mạnh Cường (38 tuổi, ở phường Bình Phước, tỉnh Đồng Nai) để điều tra về hành vi cố ý gây thương tích. Cường là một trong 3 nghi phạm liên quan vụ mang súng, bình xịt hơi cay đi đòi nợ.</p><p class=\"\">Theo kết quả điều tra ban đầu, xuất phát từ việc ông Đ.H.H (54 tuổi, ở thôn Cây Da, xã Phú Nghĩa) có nợ Nguyễn Thanh Nam 120 triệu đồng, nên người này đã rủ Nguyễn Văn Bình và Nguyễn Mạnh Cường cùng lên xã Phú Nghĩa đòi nợ.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/doi-tuong-17720023459721462070821.jpg\" id=\"img_208606117416357888\" w=\"1024\" h=\"896\" alt=\"Đồng Nai: Truy bắt nhóm người mang súng, bình xịt hơi cay đi đòi nợ - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208606117416357888\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/doi-tuong-17720023459721462070821.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1024\" height=\"896\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nguyễn Mạnh Cường thời điểm bị bắt giữ</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: CÔNG AN ĐỒNG NAI</p></figure><p class=\"\">Ngày 13.2, Nam, Bình và Cường cùng đến nhà một người quen của ông Đ.H.H (ở thôn Cây Da) để nói chuyện, giải quyết tiền bạc. Khi không đạt được thỏa thuận, nhóm này đã dùng tay chân đánh ông Đ.H.H. Đáng chú ý, Cường còn lấy bình xịt hơi cay  đánh vào vùng đầu nạn nhân.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/binh-xit-hoi-cay-1772002346039514440745.jpg\" id=\"img_208606117525938176\" w=\"1440\" h=\"1080\" alt=\"Đồng Nai: Truy bắt nhóm người mang súng, bình xịt hơi cay đi đòi nợ - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208606117525938176\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/binh-xit-hoi-cay-1772002346039514440745.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1440\" height=\"1080\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/binh-xit-hoi-cay-1772002346039514440745.jpg 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/25/binh-xit-hoi-cay-1772002346039514440745.jpg 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nguyễn Mạnh Cường chuẩn bị đánh nạn nhân bằng bình xịt hơi cay được camera ghi lại</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: CÔNG AN ĐỒNG NAI</p></figure><p class=\"\">Khi thấy nạn nhân chống trả, nhóm này chạy ra ngoài sân. Nguyễn Văn Bình sau đó dùng một khẩu súng (sau giám định được xác định là công cụ hỗ trợ) bắn một phát về phía ông Đ.H.H rồi cùng cả nhóm lên xe ô tô bỏ chạy khỏi hiện trường.</p><figure class=\"media-item\" data-originalw=\"1387\" data-originalh=\"1040\" style=\"width:calc((100% - 5px) * 0.49986755908336444)\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/25/hien-truong-1-17720023459141770323236.jpg\" class=\"\" data-originalw=\"1387\" data-originalh=\"1040\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/hien-truong-1-17720023459141770323236.jpg\" data-row=\"0\" data-id=\"208606117577838592\" alt=\"Đồng Nai: Truy bắt nhóm người mang súng, bình xịt hơi cay đi đòi nợ - Ảnh 3.\" title=\"\"></figure><figure class=\"media-item\" data-originalw=\"866\" data-originalh=\"649\" style=\"width:calc((100% - 5px) * 0.5001324409166354)\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/25/sung-2-1772002449502218325056.jpg\" class=\"\" data-originalw=\"866\" data-originalh=\"649\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/sung-2-1772002449502218325056.jpg\" data-row=\"0\" data-id=\"208606332959363072\" alt=\"Đồng Nai: Truy bắt nhóm người mang súng, bình xịt hơi cay đi đòi nợ - Ảnh 4.\" title=\"\"></figure><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Khẩu súng được công an thu giữ</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: CÔNG AN ĐỒNG NAI</p><p class=\"\">Quá trình truy xét, Công an xã Phú Nghĩa đã bắt giữ Cường khi đang trên đường tẩu thoát, đưa về trụ sở làm việc. Trong khi đó, Nguyễn Văn Bình và Nguyễn Thanh Nam vẫn đang bỏ trốn.</p><p class=\"\">Cơ quan Cảnh sát điều tra Công an tỉnh Đồng Nai kêu gọi Nguyễn Thanh Nam và Nguyễn Văn Bình đầu thú để được hưởng sự khoan hồng của pháp luật.</p><p class=\"\">Cơ quan công an đề nghị cá nhân, tổ chức không bao che, chứa chấp hoặc tạo điều kiện cho 2 nghi can trên lẩn trốn. Mọi hành vi che giấu, giúp sức cho đối tượng trốn tránh sự truy bắt của cơ quan chức năng sẽ bị xử lý nghiêm theo quy định của pháp luật.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/doi-tuong-17720023459721462070821-50-0-690-1024-crop-17720034391581882438582.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/dong-nai-truy-bat-nhom-nguoi-mang-sung-binh-xit-hoi-cay-di-doi-no-185260225141154577.htm', NULL, '2026-02-25 15:53:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":23,\"Th\\u1ebf Gi\\u1edbi\":4,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:45', '2026-02-25 10:06:45'),
('162', '2', '3', 'Quy định mới về cấp lại thẻ căn cước áp dụng từ ngày 15.3', 'quy-dinh-moi-ve-cap-lai-the-can-cuoc-ap-dung-tu-ngay-153', '\n\n                                        \n\n                                                                                Chính phủ mới đây ban hành Nghị định 58/2026 để sửa đổi, bổ sung một số nghị...', '\n\n                                        \n\n                                                                                <p data-id-seo=\"paragraphs-0\">Chính phủ mới đây ban hành Nghị định 58/2026 để sửa đổi, bổ sung một số nghị định, trong đó có Nghị định 70/2024 quy định chi tiết một số điều và biện pháp thi hành luật Căn cước.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/1/31/can-cuoc-cong-dan2-17383000570841103938248.jpeg\" id=\"img_137927291320684544\" w=\"1200\" h=\"800\" alt=\"Quy định mới về cấp lại thẻ căn cước áp dụng từ ngày 15.3- Ảnh 1.\" title=\"Quy định mới về cấp lại thẻ căn cước áp dụng từ ngày 15.3- Ảnh 1.\" rel=\"lightbox\" photoid=\"137927291320684544\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2025/1/31/can-cuoc-cong-dan2-17383000570841103938248.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"1200\" height=\"800\" data-id-seo=\"image-0\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Chính phủ ban hành Nghị định 58/2026 sửa đổi, bổ sung một số quy định về căn cước (ảnh minh họa)</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"\">ẢNH: T.N</p></figure><p data-id-seo=\"paragraphs-3\">Nghị định 58/2026 sửa đổi, bổ sung quy định về trình tự, thủ tục cấp, cấp đổi, cấp lại thẻ căn cước thông qua Cổng dịch vụ công quốc gia hoặc Ứng dụng định danh quốc gia (VNeID).</p><p data-id-seo=\"paragraphs-4\">Theo đó, công dân lựa chọn thủ tục, kiểm tra thông tin của mình được khai thác trong Cơ sở dữ liệu quốc gia về dân cư.</p><p data-id-seo=\"paragraphs-5\">Trường hợp thông tin chính xác thì đăng ký thời gian và cơ quan quản lý căn cước để thực hiện thủ tục, hệ thống sẽ xác nhận và tự động chuyển đề nghị của công dân đến cơ quan quản lý căn cước nơi công dân đề nghị cấp, cấp đổi, cấp lại thẻ căn cước.</p><p data-id-seo=\"paragraphs-6\">Công dân đến cơ quan quản lý căn cước theo thời gian, địa điểm đã đăng ký để thực hiện thủ tục cấp, cấp đổi, cấp lại thẻ căn cước theo trình tự, thủ tục đã quy định.</p><p class=\"\" data-placeholder=\"nhập chú thích\" style=\"text-align: center;\">Quy định mới về cấp lại thẻ căn cước áp dụng từ ngày 15.3</p><p data-id-seo=\"paragraphs-7\">Riêng trường hợp bị mất thẻ căn cước hoặc thẻ căn cước bị hư hỏng không sử dụng được hoặc cấp đổi thẻ căn cước do có thay đổi về địa giới hành chính thì lựa chọn thủ tục cấp lại, kiểm tra thông tin của mình được khai thác trong Cơ sở dữ liệu quốc gia về dân cư.</p><p data-id-seo=\"paragraphs-8\">Trường hợp thông tin chính xác thì xác nhận chuyển hồ sơ đề nghị cấp lại thẻ căn cước đến cơ quan quản lý căn cước xem xét, giải quyết việc cấp lại thẻ căn cước theo quy định tại khoản 4 điều 25 luật Căn cước.</p><p data-id-seo=\"paragraphs-9\">Đối với trường hợp người đại diện hợp pháp thực hiện thủ tục cấp, cấp đổi, cấp lại thẻ căn cước cho người dưới 6 tuổi thì lựa chọn thủ tục, kiểm tra thông tin của người dưới 6 tuổi trong Cơ sở dữ liệu quốc gia về dân cư. </p><p data-id-seo=\"paragraphs-10\">Trường hợp thông tin chính xác thì người đại diện hợp pháp xác nhận chuyển hồ sơ đề nghị đến cơ quan quản lý căn cước xem xét, giải quyết việc cấp, cấp đổi, cấp lại thẻ căn cước.</p><h2 data-id-seo=\"h2-0\"><b>Thu hồi thẻ căn cước với người bị tước quốc tịch</b></h2><p data-id-seo=\"paragraphs-11\">Nghị định 58/2026 cũng sửa đổi, bổ sung quy định về trình tự, thủ tục thu hồi thẻ căn cước đối với công dân bị tước quốc tịch Việt Nam, cho thôi quốc tịch Việt Nam, bị hủy bỏ quyết định cho nhập quốc tịch Việt Nam, bị hủy bỏ quyết định cho trở lại quốc tịch Việt Nam.</p><p data-id-seo=\"paragraphs-12\">Theo đó, cơ quan tiếp nhận, trả kết quả khi thực hiện một trong các thủ tục nêu trên tiến hành lập biên bản về việc thu hồi thẻ căn cước đối với người bị tước quốc tịch Việt Nam, cho thôi quốc tịch Việt Nam, bị hủy bỏ quyết định cho nhập quốc tịch Việt Nam hoặc bị hủy bỏ quyết định cho trở lại quốc tịch Việt Nam.</p><p data-id-seo=\"paragraphs-13\">Trong thời hạn 10 ngày kể từ ngày có quyết định, Bộ Tư pháp gửi văn bản thông báo kèm thẻ căn cước đã bị thu hồi đến cơ quan quản lý căn cước của Bộ Công an.</p><p data-id-seo=\"paragraphs-14\">Trường hợp cơ quan tiếp nhận, trả kết quả khi thực hiện các thủ tục này không thu hồi được thẻ căn cước thì phải nêu rõ trong văn bản thông báo gửi cơ quan quản lý căn cước của Bộ Công an để cơ quan quản lý căn cước của Bộ Công an tiến hành xác minh, thu hồi thẻ căn cước theo quy định.</p><p data-id-seo=\"paragraphs-15\">Trong thời hạn 3 ngày làm việc kể từ ngày nhận được văn bản thông báo của Bộ Tư pháp, cơ quan quản lý căn cước của Bộ Công an có trách nhiệm hủy giá trị sử dụng của thẻ căn cước và cập nhật thông tin người có quyết định vào Cơ sở dữ liệu quốc gia về dân cư, Cơ sở dữ liệu căn cước.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/can-cuoc-cong-dan2-17383000570841103938248-50-0-800-1200-crop-17720079910881287134351.jpeg', NULL, NULL, NULL, 'https://thanhnien.vn/quy-dinh-moi-ve-cap-lai-the-can-cuoc-ap-dung-tu-ngay-153-185260225152647494.htm', NULL, '2026-02-25 15:52:00', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":14,\"Th\\u1eddi S\\u1ef1\":10,\"Ph\\u00e1p Lu\\u1eadt\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-25 10:06:45', '2026-02-25 10:06:45'),
('163', '6', '1', 'Nam Định thay HLV Bồ Đào Nha sau 104 ngày', 'nam-dinh-thay-hlv-bo-dao-nha-sau-104-ngay', 'Nam Định chia tay HLV Mauro Jerorimo sau hơn 3 tháng dẫn dắt, để đưa ông Vũ Hồng Việt trở lại.', 'Nam Định chia tay HLV Mauro Jerorimo sau hơn 3 tháng dẫn dắt, để đưa ông Vũ Hồng Việt trở lại.', 'https://i1-thethao.vnecdn.net/2026/02/26/screenshot-2026-02-26-at-09-37-9594-6459-1772073533.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=-NIlSkTSYCb-3-m1sBqfQg', NULL, NULL, NULL, 'https://vnexpress.net/nam-dinh-thay-hlv-bo-dao-nha-sau-104-ngay-5044228.html', NULL, '2026-02-26 09:41:22', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ec3 Thao\":4,\"Gi\\u1ea3i Tr\\u00ed\":1,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:53', '2026-02-26 03:10:53'),
('164', '2', '1', 'Từ nào thêm hay bỏ dấu huyền đều khiến mọi người mê mệt?', 'tu-nao-them-hay-bo-dau-huyen-deu-khien-moi-nguoi-me-met', 'Chỉ cần thêm hoặc bỏ một dấu huyền, ý nghĩa của từ thay đổi hoàn toàn nhưng sức hấp dẫn thì vẫn giữ nguyên.', 'Chỉ cần thêm hoặc bỏ một dấu huyền, ý nghĩa của từ thay đổi hoàn toàn nhưng sức hấp dẫn thì vẫn giữ nguyên.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/untitled-1-1772004485-17720044-5708-6335-1772004746.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=WSrMUcHj2N5C9ZDjqbEzPg', NULL, NULL, NULL, 'https://vnexpress.net/cau-do-tieng-viet-do-chu-day-la-chu-gi-tu-nao-them-hay-bo-dau-huyen-deu-khien-moi-nguoi-me-met-5043978.html', NULL, '2026-02-26 09:31:00', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":1,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:53', '2026-02-26 03:10:53'),
('165', '2', '1', 'Xếp hàng từ mờ sáng mua vàng, bạc ngày Thần Tài', 'xep-hang-tu-mo-sang-mua-vang-bac-ngay-than-tai', '\n\n\n\n\n\n\n\n\n\n\n\nTại Hà Nội, tương tự ngày vía Thần Tài những năm trước, hàng trăm người xếp hàng chờ đợi trước các tiệm vàng trên phố Trần Nhân Tông từ sáng sớm dù 6h mới bắt đầu giao dịch. Thậm chí, một...', '\n\n\n\n<img src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh11-1772069417-1772071627-1772074487-1772074503-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=XOhRz3s0xoNmQeWFrnZ76A\">\n\n\n\n\n\n\n\n<p class=\"Normal\">Tại Hà Nội, tương tự ngày vía Thần Tài những năm trước, hàng trăm người xếp hàng chờ đợi trước các tiệm vàng trên phố Trần Nhân Tông từ sáng sớm dù 6h mới bắt đầu giao dịch. Thậm chí, một số khách còn đến từ 1-2h sáng.</p>\n\n\n\n\n\n<img src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh22-1772069427-1772071627-1772074488-1772074513-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=5uIOQCUAGFOvGaGzVHPlbQ\">\n\n\n\n\n\n\n\n<p class=\"Normal\">Tại Hà Nội, tương tự ngày vía Thần Tài những năm trước, hàng trăm người xếp hàng chờ đợi trước các tiệm vàng trên phố Trần Nhân Tông từ sáng sớm dù 6h mới bắt đầu giao dịch. Thậm chí, một số khách còn đến từ 1-2h sáng.</p>\n\n\n \n\n<figure>\n\n\n\n\n\n<img class=\"img_pc\" src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh11-1772069417-1772071627-1772074487-1772074503-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=XOhRz3s0xoNmQeWFrnZ76A\" data-caption=\'&lt;p class=\"Normal\"&gt;Tại Hà Nội, tương tự ngày vía Thần Tài những năm trước, hàng trăm người xếp hàng chờ đợi trước các tiệm vàng trên phố Trần Nhân Tông từ sáng sớm dù 6h mới bắt đầu giao dịch. Thậm chí, một số khách còn đến từ 1-2&lt;span class=\"nanospell-typo nanospell-typo-1\"&gt;h&lt;/span&gt; sáng.&lt;/p&gt;\' alt=\"\" data-mobile-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh11-1772069417-1772071627-1772074487-1772074503-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=XOhRz3s0xoNmQeWFrnZ76A\" data-desktop-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh11-1772069417-1772071627-1772074487-1772074503-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=XOhRz3s0xoNmQeWFrnZ76A\">\n\n\n\n<img class=\"img_pc\" src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh22-1772069427-1772071627-1772074488-1772074513-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=5uIOQCUAGFOvGaGzVHPlbQ\" data-caption=\'&lt;p class=\"Normal\"&gt;Tại Hà Nội, tương tự ngày vía Thần Tài những năm trước, hàng trăm người xếp hàng chờ đợi trước các tiệm vàng trên phố Trần Nhân Tông từ sáng sớm dù 6h mới bắt đầu giao dịch. Thậm chí, một số khách còn đến từ 1-2&lt;span class=\"nanospell-typo nanospell-typo-1\"&gt;h&lt;/span&gt; sáng.&lt;/p&gt;\' alt=\"\" data-mobile-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh22-1772069427-1772071627-1772074488-1772074513-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=5uIOQCUAGFOvGaGzVHPlbQ\" data-desktop-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh22-1772069427-1772071627-1772074488-1772074513-1772074563.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=5uIOQCUAGFOvGaGzVHPlbQ\">\n\n \n\n<p class=\"Normal\">Tại Hà Nội, tương tự ngày vía Thần Tài những năm trước, hàng trăm người xếp hàng chờ đợi trước các tiệm vàng trên phố Trần Nhân Tông từ sáng sớm dù 6h mới bắt đầu giao dịch. Thậm chí, một số khách còn đến từ 1-2h sáng.</p>\n\n\n\n</figure>\n\n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy lazy-blur\" src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh3-1772069642-1772074957-1772075064.jpg?w=220&amp;h=0&amp;q=80&amp;dpr=1&amp;fit=crop&amp;s=Vm9lQ87TUeV1t-saf6VNZg\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh3-1772069642-1772074957-1772075064.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=1NsPKJfGrKx5r8hbN9ueGA\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Anh Đỗ Văn Huân - một trong những khách hàng đến sớm nhất hôm nay từ 2h sáng. Anh mua một chỉ vàng có biểu tượng hình con ngựa để lấy may với giá 18,48 triệu đồng.</p>\n<p class=\"Normal\">Đầu giờ sáng nay, Công ty Vàng bạc đá quý Sài Gòn (SJC) niêm yết giá vàng miếng tại 182 - 185 triệu đồng một lượng, giảm 300.000 đồng so với cuối ngày hôm qua. Nhẫn trơn tại Bảo Tín Minh Châu và Công ty Vàng bạc đá quý Phú Nhuận (PNJ) đồng giá 181,8 - 184,8 triệu một lượng. Tập đoàn Vàng bạc đá quý DOJI mua bán nhẫn trơn quanh 181,9 - 184,9 triệu đồng.</p> \n\n\n<p class=\"Normal\">Anh Đỗ Văn Huân - một trong những khách hàng đến sớm nhất hôm nay từ 2h sáng. Anh mua một chỉ vàng có biểu tượng hình con ngựa để lấy may với giá 18,48 triệu đồng.</p>\n<p class=\"Normal\">Đầu giờ sáng nay, Công ty Vàng bạc đá quý Sài Gòn (SJC) niêm yết giá vàng miếng tại 182 - 185 triệu đồng một lượng, giảm 300.000 đồng so với cuối ngày hôm qua. Nhẫn trơn tại Bảo Tín Minh Châu và Công ty Vàng bạc đá quý Phú Nhuận (PNJ) đồng giá 181,8 - 184,8 triệu một lượng. Tập đoàn Vàng bạc đá quý DOJI mua bán nhẫn trơn quanh 181,9 - 184,9 triệu đồng.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy lazy-blur\" src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh4-1772069773-1772074977-1772075064.jpg?w=220&amp;h=0&amp;q=80&amp;dpr=1&amp;fit=crop&amp;s=WY1U5hc6NruGvgjPDgo_ZQ\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh4-1772069773-1772074977-1772075064.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=yZBcgnu3ZH3oEH5o8QIhgQ\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Cũng xếp hàng từ mờ sáng, Nguyễn Tiến Dũng, trú tại phường Bách Khoa, chọn mua bạc. Từ dịp vía Thần Tài năm ngoái, nhiều khách hàng, nhất là các bạn trẻ bắt đầu có xu hướng mua bạc để cầu may.</p>\n<p class=\"Normal\">Từ lúc mở cửa đến 8h30, Phú Quý đã điều chỉnh giá bạc hơn 15 lần. Giá bán ra mỗi cân bạc của thương hiệu này tăng từ 90,85 triệu lên trên 92,2 triệu đồng. Tại cửa hàng của Doji ở Trần Nhân Tông, sau 8h, bạc cũng hết hàng.</p> \n\n\n<p class=\"Normal\">Cũng xếp hàng từ mờ sáng, Nguyễn Tiến Dũng, trú tại phường Bách Khoa, chọn mua bạc. Từ dịp vía Thần Tài năm ngoái, nhiều khách hàng, nhất là các bạn trẻ bắt đầu có xu hướng mua bạc để cầu may.</p>\n<p class=\"Normal\">Từ lúc mở cửa đến 8h30, Phú Quý đã điều chỉnh giá bạc hơn 15 lần. Giá bán ra mỗi cân bạc của thương hiệu này tăng từ 90,85 triệu lên trên 92,2 triệu đồng. Tại cửa hàng của Doji ở Trần Nhân Tông, sau 8h, bạc cũng hết hàng.</p> \n\n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/a-nh-5-1772070242-1772075014-1772075065.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=JISHxZ0yOHsYYI0sSCCI1Q\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Năm nay, Bảo Tín Minh Châu trang bị thêm máy mua, bán vàng tự động tại toàn bộ các cơ sở. Người mua có thể thao tác, thanh toán qua thiết bị này để giảm bớt áp lực lên kênh mua, bán truyền thống tại quầy. Sau khi thanh toán, lấy hóa đơn xong, khách hàng sẽ được hướng dẫn để nhận vàng tại khu vực phía bên trong quầy thu ngân.</p> \n\n\n<p class=\"Normal\">Năm nay, Bảo Tín Minh Châu trang bị thêm máy mua, bán vàng tự động tại toàn bộ các cơ sở. Người mua có thể thao tác, thanh toán qua thiết bị này để giảm bớt áp lực lên kênh mua, bán truyền thống tại quầy. Sau khi thanh toán, lấy hóa đơn xong, khách hàng sẽ được hướng dẫn để nhận vàng tại khu vực phía bên trong quầy thu ngân.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh6-1772070558-1772075028-1772075065.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=vh2x2viTCrqZxpEF0CHnwg\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Quầy thu ngân tại các tiệm vàng ở Hà Nội hoạt động hết công suất đầu giờ sáng nay. Hầu hết khách hàng đến mua vàng, không có người đến bán. Tại Doji, đơn vị này không giới hạn lượng vàng tối đa mỗi khách được mua và sẽ bán đến khi hết hàng. Bảo Tín Minh Châu cũng không giới hạn, nhưng chỉ giao trước tối đa 3 lượng vàng, sau 12/3 sẽ trả phần còn lại.</p> \n\n\n<p class=\"Normal\">Quầy thu ngân tại các tiệm vàng ở Hà Nội hoạt động hết công suất đầu giờ sáng nay. Hầu hết khách hàng đến mua vàng, không có người đến bán. Tại Doji, đơn vị này không giới hạn lượng vàng tối đa mỗi khách được mua và sẽ bán đến khi hết hàng. Bảo Tín Minh Châu cũng không giới hạn, nhưng chỉ giao trước tối đa 3 lượng vàng, sau 12/3 sẽ trả phần còn lại.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/viathantai-5-1772071628.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=ySEYlfW2s63lxv96dRvB5A\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Cảnh mua vàng nhộn nhịp cũng tương tự tại các cửa hàng ở TP HCM từ sáng sớm nay. Trong ảnh là hàng trăm người đổ về tiệm vàng Mi Hồng, quận Bình Thạnh cũ. Mi Hồng sáng nay mua bán nhẫn trơn tại 182,2 - 185 triệu một lượng, giảm nhẹ so với hôm qua.</p> \n\n\n<p class=\"Normal\">Cảnh mua vàng nhộn nhịp cũng tương tự tại các cửa hàng ở TP HCM từ sáng sớm nay. Trong ảnh là hàng trăm người đổ về tiệm vàng Mi Hồng, quận Bình Thạnh cũ. Mi Hồng sáng nay mua bán nhẫn trơn tại 182,2 - 185 triệu một lượng, giảm nhẹ so với hôm qua.</p> \n\n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/viathantai-12-1772071630.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=w8EIsz5bdi9G8UEQBKsnQA\">\n \n\n\n\n\n\n\n<p class=\"Normal\">\"Giá vàng ngày càng cao, nên tôi chỉ mua 2 phân vàng (0,2 chỉ) đầu năm cầu may mắn\", chị Nguyễn Thanh Trà My chia sẻ.</p>\n<p class=\"Normal\">Năm nay, trong bối cảnh nguồn cung hạn chế, nhiều doanh nghiệp cũng đẩy mạnh vàng mini dưới 1 chỉ để đáp ứng nhu cầu lấy may của người dân dịp vía Thần Tài. Trong đó, nhiều khách hàng trẻ, nhất là genZ cũng chuộng mua vàng \"nhẹ\" hơn.</p> \n\n\n<p class=\"Normal\">\"Giá vàng ngày càng cao, nên tôi chỉ mua 2 phân vàng (0,2 chỉ) đầu năm cầu may mắn\", chị Nguyễn Thanh Trà My chia sẻ.</p>\n<p class=\"Normal\">Năm nay, trong bối cảnh nguồn cung hạn chế, nhiều doanh nghiệp cũng đẩy mạnh vàng mini dưới 1 chỉ để đáp ứng nhu cầu lấy may của người dân dịp vía Thần Tài. Trong đó, nhiều khách hàng trẻ, nhất là genZ cũng chuộng mua vàng \"nhẹ\" hơn.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/viathantai-16-1772071632.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=9eBp5yocJpzdWV65hiBmYA\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Cửa hàng SJC tại đường Nguyễn Thị Minh Khai cũng đông kín khách sáng nay.</p> \n\n\n<p class=\"Normal\">Cửa hàng SJC tại đường Nguyễn Thị Minh Khai cũng đông kín khách sáng nay.</p> \n\n\n\n\n\n\n\n\n<img itemprop=\"contentUrl\" style=\"transform: translateX(-50%); left: 50%;\" loading=\"lazy\" intrinsicsize=\"1200x0\" alt=\"\" class=\"lazy\" src=\"data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==\" data-src=\"https://i1-kinhdoanh.vnecdn.net/2026/02/26/viathantai-21-1772072101.jpg?w=1200&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=dht4UGYQ0WarXmuhSxk_aw\">\n \n\n\n\n\n\n\n<p class=\"Normal\">Năm nay, bên cạnh những sản phẩm truyền thống như vàng miếng, nhẫn, các thương hiệu đều chế tác vàng có hình ngựa để tượng trưng cho năm Bính Ngọ.</p>\n<p class=\"Normal\">Theo các doanh nghiệp, nhu cầu mua vàng dịp vía Thần Tài năm nay vẫn duy trì ở mức cao và tăng nhẹ so với ngày thường. Tuy nhiên, xu hướng mua sắm đã thay đổi khi khách không còn dồn vào đúng ngày chính lễ mà mua rải rác từ cuối năm và ngay sau kỳ nghỉ Tết.</p> \n\n\n<p class=\"Normal\">Năm nay, bên cạnh những sản phẩm truyền thống như vàng miếng, nhẫn, các thương hiệu đều chế tác vàng có hình ngựa để tượng trưng cho năm Bính Ngọ.</p>\n<p class=\"Normal\">Theo các doanh nghiệp, nhu cầu mua vàng dịp vía Thần Tài năm nay vẫn duy trì ở mức cao và tăng nhẹ so với ngày thường. Tuy nhiên, xu hướng mua sắm đã thay đổi khi khách không còn dồn vào đúng ngày chính lễ mà mua rải rác từ cuối năm và ngay sau kỳ nghỉ Tết.</p> \n\n\n\n<p class=\"Normal\" style=\"text-align:right;\"><strong>Giang Huy - Thanh Tùng</strong></p>	\n', 'https://i1-kinhdoanh.vnecdn.net/2026/02/26/anh1-1772072095.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=eCzoyw-sNlmV7GPTNhgdOQ', NULL, NULL, NULL, 'https://vnexpress.net/xep-hang-tu-mo-sang-mua-vang-bac-ngay-than-tai-5044207.html', NULL, '2026-02-26 09:28:49', '0', '0', '0', '0.5', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":10,\"Kinh Doanh\":2,\"\\u0110\\u1eddi S\\u1ed1ng\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:53', '2026-02-26 03:10:53'),
('166', '9', '1', 'Ba tai nạn liên tiếp trên cao tốc Dầu Giây - Phan Thiết', 'ba-tai-nan-lien-tiep-tren-cao-toc-dau-giay-phan-thiet', 'Ba vụ va chạm gần nhau liên quan 7 ôtô trên cao tốc Dầu Giây – Phan Thiết đoạn qua xã Tân Lập khiến giao thông ùn tắc nhiều giờ, sáng 26/2.', 'Ba vụ va chạm gần nhau liên quan 7 ôtô trên cao tốc Dầu Giây – Phan Thiết đoạn qua xã Tân Lập khiến giao thông ùn tắc nhiều giờ, sáng 26/2.', 'https://i1-vnexpress.vnecdn.net/2026/02/26/tai-nan-phan-thiet-dau-giay-02-9554-4885-1772071873.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=v2sObnKpL888GFDUSYYmUg', NULL, NULL, NULL, 'https://vnexpress.net/ba-tai-nan-lien-tiep-tren-cao-toc-dau-giay-phan-thiet-5044200.html', NULL, '2026-02-26 09:11:38', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":1,\"Gi\\u1ea3i Tr\\u00ed\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:54', '2026-02-26 03:10:54'),
('167', '1', '1', 'Thu nhập tháng 200 triệu đồng, có nên đánh đổi nhiều thứ để tiến xa hơn', 'thu-nhap-thang-200-trieu-dong-co-nen-danh-doi-nhieu-thu-de-tien-xa-hon', 'Việc thăng cấp có thể giúp tôi tăng thêm vài chục % thu nhập, nhưng sẽ hao tổn nhiều sức lực và thời gian, cây càng cao gió càng lớn.', 'Việc thăng cấp có thể giúp tôi tăng thêm vài chục % thu nhập, nhưng sẽ hao tổn nhiều sức lực và thời gian, cây càng cao gió càng lớn.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/GeminiGeneratedImage6y3fy96y3f-3973-9661-1772010937.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=zEwzhXAMp4rDz5qyKzu7JQ', NULL, NULL, NULL, 'https://vnexpress.net/tuoi-42-co-25-ty-va-luong-200-trieu-toi-phan-van-co-nen-tu-choi-thang-chuc-de-giu-cuoc-song-binh-yen-5043986.html', NULL, '2026-02-26 09:00:00', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0,\"Th\\u1ebf Gi\\u1edbi\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:54', '2026-02-26 03:10:54'),
('168', '4', '1', 'Robot hình người \'mini\' phô diễn khả năng thăng bằng', 'robot-hinh-nguoi-mini-pho-dien-kha-nang-thang-bang', 'EngineAI PM01 được đánh giá một trong những robot hình người cỡ nhỏ nhanh nhẹn nhất khi thực hiện động tác khó một cách linh hoạt, giữ thăng bằng tốt.', 'EngineAI PM01 được đánh giá một trong những robot hình người cỡ nhỏ nhanh nhẹn nhất khi thực hiện động tác khó một cách linh hoạt, giữ thăng bằng tốt.', 'https://i1-vnexpress.vnecdn.net/2026/02/25/s-1771989738-6894-1771989973.gif?w=1200&h=0&q=100&dpr=1&fit=crop&s=13vR-Wm8Z0curdt13VHH1w&t=image', NULL, NULL, NULL, 'https://vnexpress.net/robot-hinh-nguoi-mini-pho-dien-kha-nang-thang-bang-5043840.html', NULL, '2026-02-26 09:00:00', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"C\\u00f4ng Ngh\\u1ec7\":4,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:54', '2026-02-26 03:10:54'),
('169', '4', '1', 'Samsung: AI tạo cuộc \'cách mạng\' cho thị trường smartphone', 'samsung-ai-tao-cuoc-cach-mang-cho-thi-truong-smartphone', 'Trước sự phát triển của AI, thị trường smartphone ghi nhận những xu hướng mới, kéo theo loạt nâng cấp mang tính nhảy vọt về phần cứng lẫn phần mềm trên Galaxy S26 series, theo Tổng giám đốc Hyung Bin...', 'Trước sự phát triển của AI, thị trường smartphone ghi nhận những xu hướng mới, kéo theo loạt nâng cấp mang tính nhảy vọt về phần cứng lẫn phần mềm trên Galaxy S26 series, theo Tổng giám đốc Hyung Bin Joo.', 'https://i1-vnexpress.vnecdn.net/2026/02/26/mm1-1772070921-1772071156-4343-1772071307.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=1nu1ZXXwqsQV6nDSko2U7w', NULL, NULL, NULL, 'https://vnexpress.net/samsung-ai-tao-cuoc-cach-mang-cho-thi-truong-smartphone-5044205.html', NULL, '2026-02-26 09:00:00', '0', '0', '0', '0.25', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"C\\u00f4ng Ngh\\u1ec7\":5,\"Kinh Doanh\":4,\"\\u0110\\u1eddi S\\u1ed1ng\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:54', '2026-02-26 03:10:54'),
('170', '10', '1', 'Kia Carnival Hybrid nhận ưu đãi hơn 100 triệu đồng', 'kia-carnival-hybrid-nhan-uu-dai-hon-100-trieu-dong', 'Kia Việt Nam áp dụng ưu đãi cho nhiều dòng xe sau dịp Tết Nguyên đán, mức cao nhất hơn 100 triệu đồng cho mẫu xe gia đình Carnival phiên bản hybrid, từ 23/2.', 'Kia Việt Nam áp dụng ưu đãi cho nhiều dòng xe sau dịp Tết Nguyên đán, mức cao nhất hơn 100 triệu đồng cho mẫu xe gia đình Carnival phiên bản hybrid, từ 23/2.', 'https://i1-vnexpress.vnecdn.net/2026/02/26/1-1772067590-1772067606-1158-1772067678.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=AVtulTQpBiKGjmD2RsS5CA', NULL, NULL, NULL, 'https://vnexpress.net/kia-carnival-hybrid-nhan-uu-dai-hon-100-trieu-dong-5044179.html', NULL, '2026-02-26 09:00:00', '0', '0', '0', '0.05', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"\\u0110\\u1eddi S\\u1ed1ng\":1,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:55', '2026-02-26 03:10:55'),
('171', '3', '1', 'Vikki Bank triển khai gói tín dụng ưu đãi 10.000 tỷ', 'vikki-bank-trien-khai-goi-tin-dung-uu-dai-10000-ty', 'Gói tín dụng 10.000 tỷ đồng của Vikki Bank áp dụng đến hết 31/3, tập trung giảm lãi suất cho vay, miễn phí dịch vụ ngân hàng và tăng ưu đãi tiết kiệm.', 'Gói tín dụng 10.000 tỷ đồng của Vikki Bank áp dụng đến hết 31/3, tập trung giảm lãi suất cho vay, miễn phí dịch vụ ngân hàng và tăng ưu đãi tiết kiệm.', 'https://i1-kinhdoanh.vnecdn.net/2026/02/25/anh-viki-1772038442-1772038483-9608-1772038530.jpg?w=1200&h=0&q=100&dpr=1&fit=crop&s=yqyF2Fy9cdjP8qFF7W-LYg', NULL, NULL, NULL, 'https://vnexpress.net/vikki-bank-trien-khai-goi-tin-dung-uu-dai-10-000-ty-5044147.html', NULL, '2026-02-26 09:00:00', '0', '0', '0', '0.3', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":6,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:55', '2026-02-26 03:10:55'),
('172', '8', '1', 'Phỏng vấn học bổng trung học với giám đốc tuyển sinh trường nội trú Mỹ', 'phong-van-hoc-bong-trung-hoc-voi-giam-doc-tuyen-sinh-truong-noi-tru-my', 'Wisconsin Lutheran High School phối hợp cùng Capstone Vietnam tổ chức chuỗi sự kiện xét học bổng, cung cấp thông tin về chương trình học, lộ trình tuyển sinh.', 'Wisconsin Lutheran High School phối hợp cùng Capstone Vietnam tổ chức chuỗi sự kiện xét học bổng, cung cấp thông tin về chương trình học, lộ trình tuyển sinh.', 'https://i1-vnexpress.vnecdn.net/2026/02/13/image005-1770976018-1770976136-4095-1770976181.png?w=1200&h=0&q=100&dpr=1&fit=crop&s=sgH1cl2bT-08JLld85M0gA', NULL, NULL, NULL, 'https://vnexpress.net/phong-van-hoc-bong-trung-hoc-voi-giam-doc-tuyen-sinh-truong-noi-tru-my-5040959.html', NULL, '2026-02-26 09:00:00', '0', '0', '0', '0.4', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Gi\\u00e1o D\\u1ee5c\":8,\"Ph\\u00e1p Lu\\u1eadt\":0,\"Gi\\u1ea3i Tr\\u00ed\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:55', '2026-02-26 03:10:55'),
('173', '2', '2', 'Đội mưa đi mua vàng ngày vía Thần tài', 'doi-mua-di-mua-vang-ngay-via-than-tai', '\r\n                Từ sáng sớm nhiều người đã đến mua vàng tại tiệm vàng Mi Hồng trên đường Bùi Hữu Nghĩa, phường Gia Định, TP.HCM - Ảnh: QUANG ĐỊNHTP.HCM: Đông người mua vàng ngày vía Thần Tài bất chấ...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/mi-hong-xep-hang-2-1772073406006721072406.jpg\" id=\"img_208759839022604288\" w=\"2560\" h=\"1706\" alt=\"mua vàng - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208759839022604288\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/mi-hong-xep-hang-2-1772073406006721072406.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Từ sáng sớm nhiều người đã đến mua vàng tại tiệm vàng Mi Hồng trên đường Bùi Hữu Nghĩa, phường Gia Định, TP.HCM - Ảnh: QUANG ĐỊNH</p></figcaption></figure><h2><b>TP.HCM: Đông người mua vàng ngày vía Thần Tài bất chấp trời mưa </b></h2><p>Sáng sớm 26-2, nhiều người đã xếp hàng chờ mua vàng tại tiệm vàng Mi Hồng trên đường Bùi Hữu Nghĩa, phường Gia Định, TP.HCM. 6h cửa hàng mới mở cửa nhưng nhiều người đã đến từ rất sớm. </p><p>Cô K.T., một người mua vàng, cho biết hôm nay được mua mỗi người 1 chỉ nên cô tranh thủ mua để về kịp giờ cúng lấy may đầu năm.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"26/02/2026 06:39\" data-id=\"20260226062742693\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/dsc06050-1772061016080623304206-17-0-1027-1616-crop-1772061677790312516418.jpg\" data-url=\"/do-lua-xuyen-dem-nuong-hang-ngan-ca-loc-cho-ngay-via-than-tai-20260226062742693.htm\" data-title=\"Đỏ lửa xuyên đêm nướng hàng ngàn cá lóc cho ngày vía Thần Tài\"><h4 class=\"kbwscwlrl-title\">Đỏ lửa xuyên đêm nướng hàng ngàn cá lóc cho ngày vía Thần Tài</h4></li></ul><p>Trong số những người xếp hàng cũng có những người đến để chốt lời, có trường hợp đã chốt lời hôm qua nhưng nay thấy giá giảm nhẹ cũng mua một chỉ hoặc vài phân.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/mi-hong-xep-hang-17720734698971843253610.jpg\" id=\"img_208759663795916800\" w=\"2560\" h=\"1706\" alt=\"mua vàng - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208759663795916800\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/mi-hong-xep-hang-17720734698971843253610.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nhiều người xếp hàng chờ đến lượt - Ảnh: QUANG ĐỊNH</p></figcaption></figure><p>Tại cửa hàng Công ty vàng bạc đá quý Phú Nhuận (PNJ) trên đường Hai Bà Trưng, phường Tân Định, TP.HCM, nhiều người vẫn tranh thủ ghé mua vàng từ sáng sớm mặc trời mưa. Trong đó ưa chuộng nhất là sản phẩm vàng nhẫn 1 chỉ ép vỉ.</p><p>Những sản phẩm vàng 99,99% loại 0,1 như đồng vàng Kuromi, Doraemon, Hello Kitty… dù có giá cao hơn so với sản phẩm vàng cùng hàm lượng nhưng lại được nhiều người lựa chọn vì tính thẩm mỹ và \"nhẹ ví\".  </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/pnj-2-17720735490842043855648.jpg\" id=\"img_208759829391233024\" w=\"2560\" h=\"1706\" alt=\"mua vàng - Ảnh 3.\" title=\"\" rel=\"lightbox\" photoid=\"208759829391233024\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/pnj-2-17720735490842043855648.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Nhiều người mua vàng cầu may tại cửa hàng Công ty vàng bạc đá quý Phú Nhuận (PNJ) trên đường Hai Bà Trưng, Phường Tân Định, TP.HCM - Ảnh: QUANG ĐỊNH</p></figcaption></figure><p>Theo ghi nhận, nếu mọi năm các công ty vàng chỉ làm các sản phẩm 0,5 - 1 chỉ, thì năm nay các sản phẩm vàng mini với trọng lượng 0,1 chỉ lên ngôi do giá vàng quá cao, 1 chỉ lên đến hơn 18 triệu đồng nên các công ty vàng phải hạ trọng lượng vàng trên mỗi sản phẩm để khách hàng dễ tiếp cận hơn, nhất là khách hàng trẻ.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/anh-man-hinh-2026-02-26-luc-093334-17720736223391623321576.png\" id=\"img_208760292844199936\" w=\"1086\" h=\"806\" alt=\"Đội mưa đi mua vàng ngày vía Thần Tài - Ảnh 4.\" title=\"\" rel=\"lightbox\" photoid=\"208760292844199936\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/anh-man-hinh-2026-02-26-luc-093334-17720736223391623321576.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1086\" height=\"806\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Những sản phẩm đồng vàng Kuromi, Doraemon, Hello Kitty… dù có giá cao hơn so với sản phẩm vàng cùng hàm lượng nhưng lại được nhiều người lựa chọn - Ảnh: P.Q.</p></figcaption></figure><p>Các sản phẩm vàng Tiểu Kim Cát 99,99% loại 0,1 chỉ của Bảo Tín Minh Hải cũng được nhiều người mua vì phù hợp với túi tiền.</p><h2><b>Hà Nội: Tiệm vàng lắp cả máy bán vàng tự động dịp vía Thần Tài</b></h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/may-ban-vang--1772073713211378780516.jpg\" id=\"img_208760482902794240\" w=\"1276\" h=\"956\" alt=\"mua vàng - Ảnh 5.\" title=\"\" rel=\"lightbox\" photoid=\"208760482902794240\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/may-ban-vang--1772073713211378780516.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1276\" height=\"956\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Khách mua vàng tự động tại máy bán hàng của Bảo Tín Minh Châu - Ảnh: LÊ THANH</p></figcaption></figure><p>Tại các cửa hàng vàng trên phố Trần Nhân Tông - nơi được xem là phố bán vàng ở Hà Nội, khách hàng xếp hàng mua từ 7h sáng. Thậm chí, một số cửa hàng 5h sáng đã có khách cầm ô mặc chờ mở cửa để giao dịch. </p><p>Ghi nhận lúc 9h, khách đến ngày càng đông. Ai cũng mong muốn mua được vàng đúng ngày Vía Thần Tài để có lộc may mắn cho cả năm.</p><p>Do nhu cầu mua - bán vàng tăng cao dịp vía Thần Tài, năm nay Bảo Tín Minh Châu lần đầu đưa vào vận hành máy mua, bán vàng tự động nhằm giảm tải thời gian chờ cho khách hàng.</p><p>Bà Hoàng Thị Thúy Vân, Phó trưởng phòng Kinh doanh vàng trao đổi, cho biết điểm mới năm nay là doanh nghiệp phục vụ thêm máy bán hàng tự động để khách không phải chờ đợi lâu. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/doi-mua-di-mua-vang-hn-17720737606641350082832.jpg\" id=\"img_208760582884515840\" w=\"2560\" h=\"1843\" alt=\"mua vàng - Ảnh 6.\" title=\"\" rel=\"lightbox\" photoid=\"208760582884515840\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/doi-mua-di-mua-vang-hn-17720737606641350082832.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1843\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Dù trời mua, nhưng nhiều người vẫn đội ô để chờ mua vàng - Ảnh: LÊ THANH</p></figcaption></figure><p>Người mua chỉ cần chuẩn bị căn cước công dân, điện thoại thông minh có kết nối internet. Với thao tác trên máy bán hàng chỉ trong 1-2 phút, giao dịch thành công. </p><p>\"Khách mua theo nhu cầu, không bị hạn chế số lượng\" - Bà Vân cho hay. </p><p>Tại thị trường Hà Nội, giá vàng 9999 bán ra 184,80 triệu đồng/lượng, mua vào 181,80 triệu đồng/ lượng, giảm nhẹ khoảng 500.000 đồng/lượng so với hôm qua 25-2.</p><p>Đáng nói, chênh lệch giá mua vào - bán ra vẫn được các doanh nghiệp kinh doanh vàng nới rộng là 3 triệu đồng/lượng để hạn chế rủi ro trong bối cảnh giá vàng có nhiều biến động. </p><p>Giao dịch trên thị trường, ghi nhận của <i>Tuổi Trẻ Online</i>, lượng khách mua vào là chủ yếu. Tuy nhiên sản phẩm được lựa chọn chủ yếu 0,5-1 chỉ, thậm chí sản phẩm 0,05 chỉ. </p><p>Bà Nguyễn Thị Nghĩa (ngụ Cầu Giấy) cho biết do giá vàng tăng quá cao nên mua 0,05 chỉ với kỳ vọng lấy may cho cả năm. </p><p>\"Năm nay, mua vàng không phải chờ đợi như mấy năm trước. Tôi cũng chỉ mua chút để cầu may mắn cho năm nay. Và với 0,05 chỉ, có lẽ để làm kỷ niệm thôi\",  bà Nghĩa nói.</p><h2><b>Không</b><b> chỉ vàng mà mua cả bạc</b></h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/ancarat-phat-phieu--1772073801749214732585.jpg\" id=\"img_208760358913724416\" w=\"2334\" h=\"1579\" alt=\"mua vàng - Ảnh 7.\" title=\"\" rel=\"lightbox\" photoid=\"208760358913724416\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/ancarat-phat-phieu--1772073801749214732585.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2334\" height=\"1579\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Tại cửa hàng Ancarat trên đường Nguyễn Trãi, Phường Cầu Ông Lãnh, người đến mua hàng khá đông và nhân viên phát số từ 6g sáng - Ảnh: H.H</p></figcaption></figure><p>Tại cửa hàng Ancarat trên đường Nguyễn Trãi, phường Cầu Ông Lãnh, người đến mua hàng khá đông, nhân viên phát số từ 6h sáng. </p><p>Chị Kim Anh, một khách hàng mua, cho biết do năm nay giá vàng tăng cao nên chị chuyển qua mua bạc để phù hợp hơn với túi tiền.</p><p>Ancarat đã đưa ra quy định mỗi cửa hàng chỉ bán 200 sản phẩm, mỗi khách hàng bốc số thứ tự và chỉ được mua 1 sản phẩm. </p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/than-tai-an-1772073830110854910438.jpg\" id=\"img_208760728256995328\" w=\"2560\" h=\"1706\" alt=\"mua vàng - Ảnh 8.\" title=\"\" rel=\"lightbox\" photoid=\"208760728256995328\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/than-tai-an-1772073830110854910438.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1706\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Ancarat cho biết công ty vẫn đảm bảo người dân có thể mua bạc và sở hữu ngay tại cửa hàng, nhưng giới hạn mỗi người chỉ mua 1 sản phẩm - Ảnh: H.H</p></figcaption></figure><p>Ông Nguyễn Trung Anh, Chủ tịch Công ty Kim loại Quý Ancarat, cho biết công ty vẫn đảm bảo người dân có thể mua bạc và sở hữu ngay tại cửa hàng, nhưng giới hạn mỗi người chỉ mua 1 sản phẩm nhất định để hạn chế tình trạng đầu cơ và giúp mọi người đều có cơ hội sở hữu sản phẩm cầu may vào dịp đặc biệt này.</p><p>Ngày vía Thần tài năm nay các ngân hàng cũng \"nhập cuộc\". </p><p>Tại BVBank, khi khách hàng đến gửi tiết kiệm từ 500 triệu đồng, kỳ hạn gửi từ 6 tháng trở lên, khách hàng được cấp mã cào để tham gia cào điện tử trúng thưởng các giải thưởng bằng tiền mặt từ 100.000 đồng tới 1 triệu đồng, giải nhất với 3 chỉ vàng 999,9. </p><p>Ngoài ra khách hàng còn có cơ hội quay số trúng thưởng cuối kỳ. </p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/21/nph-5975-1-177166584178088026161-0-102-1147-1937-crop-1771665851661859849343.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Đội mưa đi mua vàng ngày vía Thần tài  - Ảnh 9.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Giá vàng thế giới tăng 110 USD/ounce sau tin tức mới về thuế quan<p class=\"VCObjectBoxRelatedNewsItemSapo\">Ngày 21-2, chốt phiên giao dịch cuối tuần, giá vàng thế giới đã tăng đến 110,7 USD/ounce và vượt mốc 5.100 USD/ounce - cũng là mức cao nhất trong hơn 3 tuần qua.</p><p><br></p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/doi-mua-di-mua-vang-hn-1772073345631938913042-57-0-1307-2000-crop-17720733531561928588663.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/doi-mua-di-mua-vang-ngay-via-than-tai-20260226095014015.htm', NULL, '2026-02-26 10:02:45', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":4,\"Kinh Doanh\":3,\"C\\u00f4ng Ngh\\u1ec7\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:56', '2026-02-26 03:10:56'),
('174', '4', '2', 'Claude Code Security: AI bắt đầu \'soi\' lỗ hổng ngay từ khi viết mã', 'claude-code-security-ai-bat-dau-soi-lo-hong-ngay-tu-khi-viet-ma', '\r\n                Claude Code Security thay thế con người tìm ra các lỗ hỏng bảo mật - Ảnh: BITCOIN NEWSAnthropic đã phát triển một công cụ trí tuệ nhân tạo (AI) mới mang tên Claude Code Security, man...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/image-photoroom-1771993170323723481538.png\" id=\"img_208591122507517952\" w=\"1280\" h=\"720\" alt=\"Claude Code Security: AI bắt đầu \'soi\' lỗ hổng ngay từ khi viết mã - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208591122507517952\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/image-photoroom-1771993170323723481538.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1280\" height=\"720\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Claude Code Security thay thế con người tìm ra các lỗ hỏng bảo mật - Ảnh: BITCOIN NEWS</p></figcaption></figure><p>Anthropic đã phát triển một công cụ trí tuệ nhân tạo (AI) mới mang tên Claude Code Security, mang đến một hướng tiếp cận mới trong lĩnh vực an ninh mạng. Thay vì chờ phần mềm đi vào vận hành rồi mới vá lỗi, công cụ này hướng đến việc phát hiện sớm các lỗ hổng bảo mật ngay từ giai đoạn phát triển.</p><p>Claude Code Security không được định vị như một hệ thống bảo mật toàn diện. Vai trò của công cụ này tập trung vào một khâu nền tảng nhưng có tác động lâu dài: nâng cao chất lượng và độ an toàn của mã nguồn, nơi nhiều rủi ro bảo mật bắt đầu hình thành nhưng thường chỉ bị phát hiện khi đã gây ra sự cố.</p><h2>AI phân tích cách phần mềm vận hành, không chỉ tìm lỗi có sẵn</h2><p>Theo Anthropic, Claude Code Security được thiết kế để vượt qua giới hạn của các công cụ kiểm tra bảo mật truyền thống. Thay vì chỉ dò tìm những lỗ hổng đã được ghi nhận trước đó, hệ thống AI này phân tích cách dữ liệu di chuyển, được xử lý và tương tác trong toàn bộ ứng dụng.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"20/02/2026 16:39\" data-id=\"2026022015061796\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/20/chatgpt-image-150340-20-thg-2-2026-1771574649662638459096-13-0-973-1536-crop-1771575272102860598142.png\" data-url=\"/trung-quoc-ra-mat-bac-si-ai-dau-tien-biet-giai-thich-chan-doan-benh-hiem-2026022015061796.htm\" data-title=\"Trung Quốc ra mắt \'bác sĩ AI\' đầu tiên biết giải thích, chẩn đoán bệnh hiếm\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/20/chatgpt-image-150340-20-thg-2-2026-1771574649662638459096-13-0-973-1536-crop-1771575272102860598142.png\" alt=\'Claude Code Security: AI bắt đầu \"soi\" lỗ hổng phần mềm từ gốc - Ảnh 2.\' title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Trung Quốc ra mắt \'bác sĩ AI\' đầu tiên biết giải thích, chẩn đoán bệnh hiếmĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Bằng việc theo dõi mối quan hệ giữa các thành phần phần mềm, Claude Code Security có thể nhận diện những lỗi logic tiềm ẩn, các điểm yếu không nằm trong danh sách cảnh báo phổ biến nhưng vẫn có khả năng bị khai thác khi phần mềm vận hành thực tế. Đây là nhóm rủi ro thường chỉ bộc lộ khi đã xảy ra tấn công hoặc sự cố nghiêm trọng.</p><p>Trong các thử nghiệm nội bộ, Anthropic cho biết công cụ này đã phát hiện hàng trăm lỗ hổng chưa từng được công bố trong nhiều dự án phần mềm được sử dụng rộng rãi suốt nhiều năm. </p><p>Kết quả này cho thấy AI có thể \"nhìn\" sâu hơn vào bản chất vận hành của phần mềm, thay vì chỉ kiểm tra bề mặt như các phương pháp truyền thống.</p><h2>Phát hiện sớm, nhưng con người vẫn quyết định</h2><p>Dù có khả năng phân tích sâu, Claude Code Security không tự động sửa mã hay triển khai các thay đổi. Mỗi cảnh báo đều được đưa ra dưới dạng khuyến nghị, và lập trình viên vẫn là người đánh giá mức độ rủi ro cũng như quyết định cách xử lý phù hợp.</p><p>Cách tiếp cận này phản ánh quan điểm thận trọng trong việc ứng dụng AI vào bảo mật: AI hỗ trợ con người ra quyết định tốt hơn, chứ không thay thế hoàn toàn trách nhiệm kỹ thuật. Điều này đặc biệt quan trọng trong bối cảnh các hệ thống phần mềm ngày càng phức tạp, nơi một thay đổi nhỏ trong mã nguồn cũng có thể kéo theo những hệ quả khó lường.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"13/01/2026 15:31\" data-id=\"2026011217304633\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/1/12/edit-anninhmang-ia-1768213641387152494351-266-0-894-1004-crop-1768213723734285283428.png\" data-url=\"/ai-doi-dau-ai-tren-dau-truong-moi-cua-an-ninh-mang-2026011217304633.htm\" data-title=\"AI đối đầu AI trên đấu trường mới của an ninh mạng\"><h4 class=\"kbwscwlrl-title\">AI đối đầu AI trên đấu trường mới của an ninh mạng</h4></li></ul><p>Bên cạnh giới kỹ thuật, sự xuất hiện của Claude Code Security cũng nhanh chóng tác động đến tâm lý thị trường. Thông tin về công cụ AI này từng khiến cổ phiếu của một số doanh nghiệp an ninh mạng biến động mạnh, phản ánh lo ngại rằng AI có thể làm thay đổi vai trò của các giải pháp bảo mật truyền thống.</p><p>Tuy nhiên, nhiều nhà phân tích cho rằng phản ứng này mang tính ngắn hạn, bởi Claude Code Security chỉ giải quyết một lát cắt hẹp trong chuỗi an ninh mạng. Thay vì thay thế, công cụ AI này được nhìn nhận là yếu tố bổ sung, giúp cải thiện chất lượng phần mềm từ sớm, trong khi các hệ thống bảo mật toàn diện vẫn giữ vai trò không thể thiếu khi phần mềm đi vào vận hành.</p><h2>Bước tiến mới, nhưng không phải \"lá chắn\" toàn diện</h2><p>Việc Claude Code Security ra mắt đã khiến nhiều người đặt câu hỏi liệu AI có thể làm thay đổi toàn bộ ngành an ninh mạng hay không. Tuy nhiên, giới chuyên môn cho rằng cần nhìn nhận công cụ này đúng vai trò của nó.</p><p>Claude Code Security không giám sát tấn công theo thời gian thực, không bảo vệ thiết bị đầu cuối, không quản lý quyền truy cập và cũng không can thiệp khi sự cố đang xảy ra. Thay vào đó, công cụ này hoạt động ở giai đoạn rất sớm của vòng đời phần mềm, giúp giảm thiểu rủi ro ngay từ gốc.</p><p>Trong bối cảnh doanh nghiệp ngày càng phụ thuộc vào phần mềm và các hệ thống tự động, cách tiếp cận \"đưa bảo mật lên sớm\" đang trở thành xu hướng rõ rệt. Claude Code Security vì thế được xem là một mảnh ghép mới trong bức tranh an ninh mạng, nơi AI đóng vai trò hỗ trợ phân tích, còn con người vẫn giữ quyền kiểm soát cuối cùng.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/1/13/anh-minh-hoa-1-17682894902351308444210-0-197-1002-1800-crop-17682912225141477925156.png\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\'Claude Code Security: AI bắt đầu \"soi\" lỗ hổng phần mềm từ gốc - Ảnh 3.\' title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Lỗ hổng nào của tổ chức, doanh nghiệp mà tin tặc nhắm tới trong năm 2026?<p class=\"VCObjectBoxRelatedNewsItemSapo\">Trong bối cảnh Việt Nam đang đẩy mạnh chuyển đổi số, các trung tâm dữ liệu và thông tin sẽ là tài sản giá trị nhất mà tin tặc nhắm tới.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/25/image-photoroom-1-17719936571101271109054-0-34-360-610-crop-17719936634511642930633.png', NULL, NULL, NULL, 'https://tuoitre.vn/claude-code-security-ai-bat-dau-soi-lo-hong-ngay-tu-khi-viet-ma-20260225112850239.htm', NULL, '2026-02-26 09:58:20', '1', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"C\\u00f4ng Ngh\\u1ec7\":24,\"Th\\u1ebf Gi\\u1edbi\":6,\"Kinh Doanh\":4},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:56', '2026-02-26 03:11:09'),
('175', '9', '2', 'CSGT dùng xe đặc chủng mở đường đưa bé trai 12 tuổi ngã từ trên cây đi cấp cứu', 'csgt-dung-xe-dac-chung-mo-duong-dua-be-trai-12-tuoi-nga-tu-tren-cay-di-cap-cuu', '\r\n                Lực lượng cảnh sát giao thông đưa bé P. đến bệnh viện cấp cứu - Ảnh: C08Ngày 26-2, Đội cảnh sát giao thông đường bộ cao tốc số 7, thuộc Cục Cảnh sát giao thông, Bộ Công an cho biết t...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/z7564984273484-f099cfed2886b0bcd6425711ba7ed421-1772071371488128542402.jpg\" id=\"img_208755262595289088\" w=\"1105\" h=\"1484\" alt=\"CSGT dùng xe đặc chủng mở đường đưa bé trai 12 tuổi ngã từ trên cây đi cấp cứu - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208755262595289088\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/z7564984273484-f099cfed2886b0bcd6425711ba7ed421-1772071371488128542402.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1105\" height=\"1484\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Lực lượng cảnh sát giao thông đưa bé P. đến bệnh viện cấp cứu - Ảnh: C08</p></figcaption></figure><p>Ngày 26-2, Đội cảnh sát giao thông đường bộ cao tốc số 7, thuộc Cục Cảnh sát giao thông, Bộ Công an cho biết trong lúc tuần tra trên tuyến cao tốc TP.HCM - Trung Lương - Mỹ Thuận - Cần Thơ, tổ cảnh sát giao thông nhận tin khẩn cấp của một người phụ nữ đề nghị hỗ trợ đưa con trai đi cấp cứu do bị ngã từ trên cây cao xuống đất.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"26/03/2021 22:27\" data-id=\"20210326220117185\" data-avatar=\"https://cdn2.tuoitre.vn/2021/3/26/20210326201024-copy-1616770287326516798175-crop-16167703489421151993704.jpg\" data-url=\"/csgt-hu-coi-mo-duong-cho-xe-cho-san-phu-den-benh-vien-noi-gi-20210326220117185.htm\" data-title=\"CSGT hú còi ‘mở đường’ cho xe chở sản phụ đến bệnh viện nói gì?\"><h4 class=\"kbwscwlrl-title\">CSGT hú còi ‘mở đường’ cho xe chở sản phụ đến bệnh viện nói gì?</h4></li></ul><p>Khoảng 17h45 ngày 25-2, chị Hà Thị Ch. (31 tuổi, quê tỉnh Vĩnh Long) gọi vào đường dây nóng Đội cảnh sát giao thông đường bộ cao tốc số 7, đề nghị hỗ trợ khẩn cấp đưa con trai là cháu P.T.P. (12 tuổi, ngụ phường Long Đức, tỉnh Vĩnh Long) đi cấp cứu do bị ngã cắm đầu từ trên cây cao xuống đất.</p><p>Lúc này ô tô chở bé trai đang đi trên cao tốc vào đúng giờ cao điểm, xe cộ lưu thông đông, việc tự di chuyển bằng ô tô gia đình gặp nhiều khó khăn, nguy cơ chậm trễ, ảnh hưởng đến sức khỏe cháu bé.</p><p>Ngay khi tiếp nhận thông tin, lãnh đạo Đội cảnh sát giao thông đường bộ cao tốc số 7 đã phân công tổ công tác do thiếu tá Phan Văn Lượng (Phó đội trưởng) làm tổ trưởng cùng 2 đại úy Hoàng Tiến Dũng, Trịnh Đức Anh và 1 cán bộ cảnh sát cơ động sử dụng xe đặc chủng chuyên dụng tổ chức dẫn đường, ưu tiên tối đa để đưa bé trai đến Bệnh viện Triều An (TP.HCM) trong thời gian nhanh nhất.</p><p>Nhờ sự hỗ trợ kịp thời, cháu bé đã nhập viện cấp cứu và hiện đang được các bác sĩ theo dõi, chăm sóc tích cực.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/base64-1772072877150696451747.jpeg\" id=\"img_208758187073753088\" w=\"960\" h=\"1280\" alt=\"bé trai - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208758187073753088\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/base64-1772072877150696451747.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"960\" height=\"1280\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Các bác sĩ đang khám cho bé trai - Ảnh: C08</p></figcaption></figure><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2024/12/19/csgt-17346007285021926276197-276-0-876-960-crop-17346008470771323478093.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"CSGT dùng xe đặc chủng mở đường đưa bé trai 12 tuổi ngã từ trên cây cao xuống đến bệnh viện - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Dùng xe đặc chủng CSGT chở bệnh nhi đi cấp cứu kịp thời<p class=\"VCObjectBoxRelatedNewsItemSapo\">Cảnh sát giao thông (CSGT) đang làm nhiệm vụ trên đường cao tốc TP.HCM - Trung Lương thì nhận được lời đề nghị giúp đỡ từ người dân, ngay sau đó các chiến sĩ đã dùng xe đặc chủng CSGT chở bệnh nhi vào bệnh viện cấp cứu kịp thời.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/z7564984273484-f099cfed2886b0bcd6425711ba7ed421-1772071371488128542402-98-0-789-1105-crop-177207139315162545767.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/csgt-dung-xe-dac-chung-mo-duong-dua-be-trai-12-tuoi-nga-tu-tren-cay-di-cap-cuu-20260226093047921.htm', NULL, '2026-02-26 09:56:09', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Ph\\u00e1p Lu\\u1eadt\":16,\"S\\u1ee9c Kh\\u1ecfe\":16,\"Th\\u1ebf Gi\\u1edbi\":5},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:57', '2026-02-26 03:10:57'),
('176', '2', '2', 'Có hay không tô phở giá 346.000 đồng ở sân bay Cam Ranh?', 'co-hay-khong-to-pho-gia-346000-dong-o-san-bay-cam-ranh', '\r\n                Hình ảnh tô phở bò giá 346.000 đồng tại sân bay Cam Ranh được anh T. chụp lại - Ảnh: Q.T.Ngày 26-2, trao đổi với Tuổi Trẻ Online, ông Cung Quỳnh Anh - Phó giám đốc Sở Văn hóa, Thể th...', '\r\n                <figure class=\"VCSortableInPreviewMode small-img\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/screenshot-2026-02-26-091340-1772072089832339585700.jpg\" id=\"img_208757099114487808\" w=\"448\" h=\"559\" alt=\"sân bay Cam Ranh - Ảnh 1.\" title=\"Có hay không tô phở gần 400.000 đồng ở sân bay Cam Ranh? - Ảnh 1.\" rel=\"lightbox\" photoid=\"208757099114487808\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/screenshot-2026-02-26-091340-1772072089832339585700.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"448\" height=\"559\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Hình ảnh tô phở bò giá 346.000 đồng tại sân bay Cam Ranh được anh T. chụp lại - Ảnh: Q.T.</p></figcaption></figure><p>Ngày 26-2, trao đổi với <i>Tuổi Trẻ Online</i>, ông Cung Quỳnh Anh - Phó giám đốc Sở Văn hóa, Thể thao và Du lịch tỉnh Khánh Hòa - cho biết Phòng Quản lý thông tin báo chí và xuất bản của Sở và các đơn vị liên quan đang xác minh thông tin đăng tải trên một số báo điện tử về việc một hành khách từ Hà Nội bay đến sân bay Cam Ranh và ăn một tô phở với giá 346.000 đồng tại sân bay này.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"09/12/2024 13:06\" data-id=\"20241209105438973\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2024/12/9/1-17337161633761010070674-0-0-481-770-crop-17337161709051443078393.jpg\" data-url=\"/thuc-hu-thong-tin-du-khach-han-quoc-bi-moc-tui-xach-mat-50-trieu-o-san-bay-cam-ranh-20241209105438973.htm\" data-title=\"Thực hư thông tin du khách Hàn Quốc bị móc túi xách mất 50 triệu ở sân bay Cam Ranh\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2024/12/9/1-17337161633761010070674-0-0-481-770-crop-17337161709051443078393.jpg\" alt=\"Có hay không tô phở gần 400.000 đồng ở sân bay Cam Ranh? - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Thực hư thông tin du khách Hàn Quốc bị móc túi xách mất 50 triệu ở sân bay Cam RanhĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Theo thông tin đăng tải, khoảng 23h ngày 23-2, sau khi đáp chuyến bay từ Hà Nội xuống sân bay Cam Ranh (tỉnh Khánh Hòa), anh N.Q.T. cảm thấy mệt và đói bụng.</p><p>Lên tầng 2 của nhà ga, anh T. tìm thấy một quán phở vẫn mở cửa. Không để ý tới việc quán có niêm yết giá hay không, anh T. chỉ xem lướt qua có những món gì để gọi luôn.</p><p>Vị khách này thấy quán có các món phở cơ bản gồm phở bò, phở gà và phở đặc biệt. Từng ăn phở ở hàng chục sân bay  khác trên thế giới, anh T. nghĩ mức giá chắc sẽ không chênh lệch với bên ngoài quá nhiều, nên không hỏi giá trước.</p><p>Sau khi ăn xong và ra quầy thanh toán, anh T. được báo tô phở có giá 346.000 đồng. Anh T. tưởng nghe nhầm, phải hỏi lại xem con số này đã chuẩn chưa.</p><p>Cũng theo thông tin đăng tải, không muốn đôi co thắc mắc vì thời điểm này cũng là ngày đầu năm, anh T. tính tiền cho xong, nhưng trong lòng thấy không thoải mái.</p><p>Kèm các bài viết về sự việc trên là hình ảnh một tô phở được đặt trên bàn do anh T. chụp lại và cho rằng đây là tô phở bán ở sân bay Cam Ranh, ngoài ra không đề cập chi tiết tên hàng quán nào, cũng như hình ảnh hóa đơn tính tiền.</p><p>Liên quan đến vụ việc này, lãnh đạo Cảng hàng không quốc tế Cam Ranh cho biết đang tiến hành rà soát theo quy định.</p><p>Theo vị này, giá cả các món ăn, thức uống tại các khu vực khuôn viên sân bay Cam Ranh đều được niêm yết, trong khi giá cả tại các phòng chờ ở sân bay đều phải tuân thủ quy định của Bộ Tài chính.</p><p>\"Thông tin bài viết phản ánh nên nêu cụ thể quán nào ở trong sân bay Cam Ranh, hoặc đăng tải hóa đơn thanh toán, từ đó chúng tôi có thể nhanh chóng xác định cụ thể vi phạm nếu có\" - vị này cho hay.</p><p>Cũng theo ông, sân bay Cam Ranh luôn khuyến khích khách hàng góp ý về thái độ phục vụ cũng như giá cả hàng hóa để cải thiện chất lượng, đây là các dịch vụ của những đơn vị phi hàng không ở sân bay, họ đều quy định giá cả rất chặt chẽ, kể cả việc an toàn vệ sinh thực phẩm.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2024/12/26/1-17351772439521538628927-54-0-664-976-crop-17351773316431016713419-13-47-486-803-crop-17351901249021461866928.png\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Có hay không tô phở gần 400.000 đồng ở sân bay Cam Ranh? - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Vì sao taxi Mai Linh bị chấm dứt hoạt động tại sân bay Cam Ranh?<p class=\"VCObjectBoxRelatedNewsItemSapo\">Cảng hàng không quốc tế Cam Ranh (tỉnh Khánh Hòa) đã có thông báo chấm dứt hoạt động của hãng taxi Mai Linh tại nhà ga hành khách T1, vì sao như vậy?</p> \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/screenshot-2026-02-26-091340-1772072089832339585700-157-0-437-448-crop-1772072432603377546547.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/co-hay-khong-to-pho-gia-346-000-dong-o-san-bay-cam-ranh-20260226093719392.htm', NULL, '2026-02-26 09:55:43', '0', '0', '0', '0.35', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":7,\"\\u0110\\u1eddi S\\u1ed1ng\":2,\"Kinh Doanh\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:57', '2026-02-26 03:10:57'),
('177', '6', '2', 'Vĩnh biệt người hết lòng với bóng đá Việt Nam', 'vinh-biet-nguoi-het-long-voi-bong-da-viet-nam', '\r\n                Ông Nguyễn Văn Vinh cùng BLV Ngô Quang Tùng trong chuyến bình luận World Cup 2010 cho Đài VTC tại Nam Phi - Ảnh: NVCCÔng Nguyễn Văn Vinh là người có nhiều đóng góp cho bóng đá Việt N...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/blv-ngo-quang-tung-va-chuyen-gia-nguyen-van-vinh-read-only-1772064523410524689317.jpg\" id=\"img_208740901726212096\" w=\"960\" h=\"540\" alt=\"bóng đá - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208740901726212096\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/blv-ngo-quang-tung-va-chuyen-gia-nguyen-van-vinh-read-only-1772064523410524689317.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"960\" height=\"540\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Ông Nguyễn Văn Vinh cùng BLV Ngô Quang Tùng trong chuyến bình luận World Cup 2010 cho Đài VTC tại Nam Phi - Ảnh: NVCC</p></figcaption></figure><p>Ông Nguyễn Văn Vinh là người có nhiều đóng góp cho bóng đá Việt Nam trên nhiều cương vị khác nhau. Ông có sự nghiệp thi đấu khá lẫy lừng khi khoác áo CLB Thể Công. Trong giai đoạn hoàng kim của CLB Hoàng Anh Gia Lai những năm 2000, ông cũng để lại dấu ấn đậm nét trong vai trò giám đốc kỹ thuật.</p><h2><b>Sự nghiệp huấn luyện trắc trở nhưng trọn vẹn</b></h2><p>\"Thương tiếc một tiền bối đã gắn bó với biết bao kỷ niệm và những bài học, một người học trò - người đàn em yêu quý của bố Quýnh. Mong bố Vinh \"Tàu\" được yên nghỉ. Thể Công sẽ luôn nhớ bố, phần còn lại của bóng đá Việt Nam cũng vậy\", bình luận viên (BLV) Ngô Quang Tùng viết trên trang Facebook cá nhân.</p><p>Là con trai của cố cựu danh thủ Ngô Xuân Quýnh của CLB Thể Công, BLV Ngô Quang Tùng từ nhỏ đã được nghe bố kể nhiều về cậu học trò yêu mến của mình. Ông Vinh được tuyển vào từ khi là cậu thanh niên Hà Nội và rồi trở thành tiền vệ trụ cột của CLB Thể Công.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"25/02/2026 12:40\" data-id=\"20260225122552295\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/641606800265492837146769027467655840845478766n-1771996786620687267939-0-0-1280-2048-crop-17719969353991693970089.jpg\" data-url=\"/cuu-danh-thu-kiatisak-tiec-thuong-ong-nguyen-van-vinh-20260225122552295.htm\" data-title=\"Cựu danh thủ Kiatisak tiếc thương ông Nguyễn Văn Vinh\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/641606800265492837146769027467655840845478766n-1771996786620687267939-0-0-1280-2048-crop-17719969353991693970089.jpg\" alt=\"Vĩnh biệt người hết lòng với bóng đá Việt Nam - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Cựu danh thủ Kiatisak tiếc thương ông Nguyễn Văn VinhĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Ông Vinh không chỉ mang băng đội trưởng của đội mà sau đó còn trở thành HLV gặt hái nhiều thành công những năm 1970. Đến năm 1978, vị HLV người Việt gốc Hoa đã rời khỏi CLB Thể Công.</p><p>Vào TP.HCM sinh sống, ông Vinh dẫn dắt nhiều CLB khác nhau như Công nghiệp Thực phẩm TP.HCM, Công An TP.HCM, Tiền Giang, Đà Nẵng. Nhưng tất cả đều gần như không thành công mà lý do chính là sự thẳng thẳn của mình, không thỏa hiệp trong giai đoạn \"tranh tối tranh sáng\" của bóng đá Việt Nam.</p><p>Chỉ khi được ông bầu Đoàn Nguyên Đức mời về CLB Hoàng Anh Gia Lai (HAGL) với vai trò giám đốc kỹ thuật vào năm 2000, ông Vinh mới được làm bóng đá đúng nghĩa và thành công trọn vẹn.</p><p>Ông Vinh đưa CLB HAGL giành chức vô địch quốc gia hai năm liên tiếp 2023 và 2024 ngay sau khi giành quyền thăng hạng, đoạt Siêu cúp quốc gia và đại diện Việt Nam tham dự Cúp C1 Đông Nam Á tại Indonesia. Học viện HAGL Arsenal - JMG ra đời đình đám năm 2007 cũng có nhiều đóng góp của ông Vinh, trước khi ông chia tay vào năm 2009.</p><p>Trưởng thành từ đào tạo trẻ ở Thể Công, nên ông Vinh hiểu CLB Hoàng Anh Gia Lai cần phải đào tạo trẻ thay vì vung tiền mua cầu thủ giỏi. Chính tư vấn của ông Vinh đã góp phần cho ra đời Học viện HAGL Arsenal - JMG và tạo ra lứa Tuấn Anh, Công Phượng, Xuân Trường...</p><p>\"20 năm gắn bó với CLB Thể Công là một giai đoạn đáng nhớ với ông Vinh. Ông sau đó đã có một sự nghiệp huấn luyện trắc trở nhưng đã kết thúc khá trọn vẹn khi thành công cùng CLB HAGL\", BLV Ngô Quang Tùng nhìn nhận.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/base64-17720646086341552820326.jpeg\" id=\"img_208741212300992512\" w=\"1299\" h=\"1365\" alt=\"bóng đá - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208741212300992512\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/base64-17720646086341552820326.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"1299\" height=\"1365\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Ông Nguyễn Văn Vinh cùng Kiatisak năm 2002 - Ảnh: FBNV</p></figcaption></figure><h2><b>Người đặt nền móng cho CLB Hoàng Anh Gia Lai</b></h2><p>Từ đề xuất tăng cường lực lượng để thực hiện mục tiêu thăng hạng của ông Vinh, bầu Đức đã đem về tiền đạo ngôi sao của bóng đá Đông Nam Á Kiatisak Senamuang cùng các tuyển thủ Thái Lan khác vào năm 2002. Chính sự đối đãi thân tình mà ông Vinh dành cho Kiatisak đã khiến cựu danh thủ Thái Lan này nhớ mãi và dành lời tiếc thương chân thành khi nghe tin ông qua đời.</p><p>Kiatisak đã chia sẻ rất nhiều hình ảnh với ông Vinh trên Facebook cá nhân và viết đầy cảm động: \"Yên nghỉ nhé thầy Vinh. Cảm ơn thầy đã chăm sóc tốt cho em cả trong và ngoài sân cỏ. Thầy đã là người cho em lời khuyên và giúp đỡ ngay từ ngày đầu tiên, bước đầu tiên đến sân bay Việt Nam. Chúng ta cùng nhau tạo ra thành công, hy sinh và truyền cả năng lượng, động lực cho CLB HAGL. Em sẽ luôn nhớ đến thầy\".</p><p>Không chỉ Kiatisak, những học trò cũ của ông Vinh nghe tin ông mất cũng dành những lời tiếc thương từ tận đáy lòng. HLV Nguyễn Văn Đàn, hiện đang dẫn dắt CLB Quảng Ninh ở Giải hạng nhất 2025 - 2026, chia sẻ: \"Tôi vô cùng thương tiếc khi nghe thông tin chú Vinh mất. Nó khiến tôi nhớ về kỷ niệm ngày đầu với chú, người đã đặt nền móng cho sự phát triển vượt bậc của CLB HAGL sau này. Chú là người đạo đức, sống trọn với công việc và là người khiến tôi cũng như các cầu thủ khác luôn kính trọng\".</p><p>\"Dấu ấn của chú Vinh ở CLB HAGL là rất lớn. Chú từng là cầu thủ nổi tiếng, làm việc ở nhiều đội bóng lớn, về tỉnh lẻ như Gia Lai để dẫn dắt đội đã mang đến sự thay đổi lớn. Chú áp dụng tư duy, chiến thuật mới để cầu thủ chúng tôi vượt qua chính mình, nâng tầm đội bóng và gặt hái thành công.</p><p>Ở ngoài đời, chú là người rất vui vẻ, hòa đồng và chia sẻ với tất cả mọi người, cho dù là chú bảo vệ hay cô nấu bếp. Tất cả những điều đó đã tạo sự đoàn kết cho các cầu thủ. Tôi đã học nhiều từ chú cho công tác huấn luyện sau này\", HLV Nguyễn Văn Đàn nói thêm.</p><p>Giờ thì người đàn ông hết lòng với bóng đá Việt Nam ấy đã không còn nữa. Xin nghiêng mình tiễn biệt ông.</p>                                      <h3>Một chuyên gia bóng đá sâu sắc</h3><p>Nhưng không chỉ giới bóng đá, cánh phóng viên cũng nhớ đến chú Vinh như là một chuyên gia bóng đá sắc sảo và sẵn lòng giúp đỡ mỗi khi họ cần. Từ cú điện thoại hỏi về vấn đề nóng của bóng đá Việt Nam cho báo giấy hay online, đến mời tham dự bình luận trên sóng truyền hình ở các giải bóng đá lớn của Việt Nam và thế giới, ông đều sẵn lòng chia sẻ.</p>                 <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/25/ong-vinh-17719945581301675182653-0-204-432-895-crop-1771994581156562807015.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Vĩnh biệt người hết lòng với bóng đá Việt Nam - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Cựu danh thủ Nguyễn Văn Vinh qua đời<p class=\"VCObjectBoxRelatedNewsItemSapo\">Cựu danh thủ Nguyễn Văn Vinh - người có nhiều đóng góp cho bóng đá Việt Nam trên nhiều cương vị khác nhau đã qua đời ở tuổi 85.</p>                 \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/ong-vinh-va-kiatisak-read-only-1772064523427501226708-57-0-869-1299-crop-17720668879281791902271.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/vinh-biet-nguoi-het-long-voi-bong-da-viet-nam-2026022607133978.htm', NULL, '2026-02-26 09:44:57', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ec3 Thao\":14,\"Th\\u1ebf Gi\\u1edbi\":5,\"Gi\\u00e1o D\\u1ee5c\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:57', '2026-02-26 03:10:57'),
('178', '7', '2', 'Về nước điều trị cột sống sau 30 năm xa quê, Việt kiều từ Anh hồi phục ngoạn mục', 've-nuoc-dieu-tri-cot-song-sau-30-nam-xa-que-viet-kieu-tu-anh-hoi-phuc-ngoan-muc', '\r\n                Hình ảnh cộng hưởng từ cho thấy người bệnh bị hẹp ống sống cổ đa tầng (C4-C6) - Ảnh: BVCCDù đã thăm khám tại nhiều cơ sở y tế ở Anh và Singapore, tình trạng bệnh của ông P. (58 tuổi)...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/img5323-17720688728891732710559.jpg\" id=\"img_208750134326743040\" w=\"2560\" h=\"1920\" alt=\"điều trị cột sống - Ảnh 1.\" title=\"Về nước điều trị cột sống sau 30 năm xa quê, Việt kiều Vương quốc Anh hồi phục ngoạn mục - Ảnh 1.\" rel=\"lightbox\" photoid=\"208750134326743040\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/img5323-17720688728891732710559.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1920\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Hình ảnh cộng hưởng từ cho thấy người bệnh bị hẹp ống sống cổ đa tầng (C4-C6) - Ảnh: BVCC</p></figcaption></figure><p class=\"\">Dù đã thăm khám tại nhiều cơ sở y tế ở Anh và Singapore, tình trạng bệnh của ông P. (58 tuổi) vẫn tiến triển nặng trong suốt 7 tháng gần đây.</p><p class=\"\">Ông P. chia sẻ hai tuần trước đã quyết định bay về Việt Nam để điều trị bệnh. Sau khi được nhiều người giới thiệu ông đã đến Bệnh viện Hữu nghị Việt Đức để thăm khám.</p><p class=\"\">Tại Bệnh viện Hữu nghị Việt Đức, kết quả chụp cộng hưởng từ cho thấy người bệnh bị hẹp ống sống cổ đa tầng (C4-C6) do thoái hóa đốt sống và đĩa đệm, gây chèn ép tủy cổ nghiêm trọng. Đáng chú ý, vị trí hẹp nhất của ống sống chỉ còn 3 - 4mm, nguy cơ cao dẫn đến liệt nếu không can thiệp kịp thời.</p><p class=\"\">PGS.TS Đinh Ngọc Sơn - Trưởng khoa phẫu thuật cột sống, Bệnh viện Hữu nghị Việt Đức - chia sẻ trước tổn thương phức tạp và nguy cơ phù tủy trong mổ, ê kíp đã lựa chọn phương pháp cắt thân đốt sống cổ, ghép xương và cố định cột sống (ACCF) kết hợp phẫu thuật dưới kính hiển vi giúp phóng đại rõ cấu trúc thần kinh - mạch máu, thao tác chính xác trong không gian hẹp.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"25/06/2025 15:00\" data-id=\"20250625135838716\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/6/25/photo-1750834071061-17508340711481714210517-90-59-760-1131-crop-17508385427131811922420.jpg\" data-url=\"/viet-nam-trong-cuoc-choi-y-te-du-lich-20250625135838716.htm\" data-title=\"Việt Nam trong cuộc chơi y tế du lịch\"><h4 class=\"kbwscwlrl-title\">Việt Nam trong cuộc chơi y tế du lịch</h4></li></ul><p class=\"\">Cùng với hệ thống theo dõi thần kinh trong mổ (IONM) cho phép theo dõi liên tục dẫn truyền thần kinh, cảnh báo sớm nguy cơ tổn thương tủy.</p>     <p class=\"\">Sự phối hợp đồng bộ giữa kỹ thuật vi phẫu và công nghệ theo dõi thần kinh hiện đại giúp tối ưu độ an toàn trong suốt quá trình phẫu thuật.</p><figure class=\"VCSortableInPreviewMode small-img\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/base64-17720686870611104006200.jpeg\" id=\"img_208749779705880576\" w=\"396\" h=\"594\" alt=\"Về nước điều trị cột sống sau 30 năm xa quê, Việt kiều từ Anh hồi phục ngoạn mục - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208749779705880576\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/base64-17720686870611104006200.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"396\" height=\"594\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">PGS.TS Đinh Ngọc Sơn cùng ê kip phẫu thuật dưới kính hiển vi và ứng dụng hệ thống theo dõi thần kinh trong mổ (IONM)</p></figcaption></figure><p class=\"\">Ngay sau phẫu thuật, người bệnh tỉnh táo, có thể ngồi dậy sớm. Các triệu chứng yếu liệt và mất thăng bằng cải thiện rõ rệt. Người bệnh sẽ tiếp tục chương trình phục hồi chức năng để sớm trở lại sinh hoạt và công việc thường ngày.</p><p class=\"\">Ông P. chia sẻ sau ca phẫu thuật khoảng 24 tiếng ông đã đi lại được, ăn uống cũng đã bình thường. \"Tôi không mệt, không sốt… không có cảm giác gì là mổ ngày hôm qua\", ông nói.</p>     <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/img5306-17720688728931110800809.jpg\" id=\"img_208750132915359744\" w=\"2560\" h=\"1920\" alt=\"điều trị cột sống - Ảnh 3.\" title=\"Về nước điều trị cột sống sau 30 năm xa quê, Việt kiều từ Vương quốc Anh hồi phục ngoạn mục - Ảnh 3.\" rel=\"lightbox\" photoid=\"208750132915359744\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/img5306-17720688728931110800809.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1920\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Sau mổ, người bệnh tỉnh táo, có thể ngồi dậy sớm, các triệu chứng yếu liệt và mất thăng bằng cải thiện rõ rệt</p></figcaption></figure><p class=\"\">Ca phẫu thuật thành công chứng minh cho năng lực làm chủ các kỹ thuật chuyên sâu trong điều trị bệnh lý cột sống tại Bệnh viện Hữu nghị Việt Đức, tiệm cận tiêu chuẩn của các trung tâm lớn trong khu vực và quốc tế.</p>     <p class=\"\">Việc người bệnh từ Anh tin tưởng trở về điều trị và đạt kết quả tích cực tiếp tục khẳng định chất lượng chuyên môn và uy tín của y tế Việt Nam trong xử lý các ca bệnh phức tạp.<br></p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/1/15/z623000892480264868a212cbc2a1bd5de2ec14d72b6a4-1736912455443702345818-55-0-1305-2000-crop-1736912620135953657410.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Về nước điều trị cột sống sau 30 năm xa quê, Việt kiều Vương quốc Anh hồi phục ngoạn mục - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Phẫu thuật gãy cột sống cổ phức tạp chỉ qua đường mổ 1cm<p class=\"VCObjectBoxRelatedNewsItemSapo\">Bị chấn thương gãy cột sống cổ phức tạp sau tai nạn giao thông, thay vì phương pháp mổ mở truyền thống với nhiều nguy cơ, nam thanh niên 25 tuổi được thực hiện phương pháp mổ nội soi với nhiều ưu điểm, hồi phục nhanh chóng.</p>     \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/img5306-17720688728931110800809-162-0-1762-2560-crop-1772069087017101266432.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/ve-nuoc-dieu-tri-cot-song-sau-30-nam-xa-que-viet-kieu-tu-anh-hoi-phuc-ngoan-muc-20260226082618416.htm', NULL, '2026-02-26 09:42:41', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"S\\u1ee9c Kh\\u1ecfe\":15,\"Th\\u1ebf Gi\\u1edbi\":11,\"C\\u00f4ng Ngh\\u1ec7\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:58', '2026-02-26 03:10:58'),
('179', '10', '2', 'Nỗi cô đơn của người già sau những ngày Tết đoàn viên', 'noi-co-don-cua-nguoi-gia-sau-nhung-ngay-tet-doan-vien', '\r\n                Tết sum vầy của ông bà đã trôi qua khi con cháu rời nhà trở lại với việc học, việc làm ở nơi xa - Minh họa AINông thôn Việt Nam gần đây đã có những bước chuyển mình mạnh mẽ về kinh t...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/tet-cua-nguoi-gia-1772072902568309789653.jpg\" id=\"img_208758472632455168\" w=\"2424\" h=\"1536\" alt=\"Nỗi cô đơn của người già sau những ngày Tết đoàn viên - Ảnh 1.\" title=\"Nỗi cô đơn của người già sau những ngày Tết đoàn viên - Ảnh 1.\" rel=\"lightbox\" photoid=\"208758472632455168\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/tet-cua-nguoi-gia-1772072902568309789653.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2424\" height=\"1536\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Tết sum vầy của ông bà đã trôi qua khi con cháu rời nhà trở lại với việc học, việc làm ở nơi xa - Minh họa AI</p></figcaption></figure><p>Nông thôn Việt Nam gần đây đã có những bước chuyển mình mạnh mẽ về kinh tế. Thêm những ngôi nhà cao tầng, đường sá bê tông hóa khang trang. Thế nhưng đằng sau vẻ ngoài khởi sắc đó lại là những khoảng trống trong đời sống tinh thần và vật chất của người cao tuổi. </p><p>Sau mỗi dịp sum vầy lễ Tết là lúc ông bà quay về với những nỗi niềm riêng lắm khi không muốn bày tỏ hoặc không thể bày tỏ cùng ai.</p><h2>Những ngôi nhà \"khuyết\" thế hệ giữa</h2><p>Hiện nay tại nhiều làng quê, cấu trúc gia đình truyền thống \"tam đại đồng đường\" đang dần bị thay thế bởi mô hình \"ông bà và cháu nhỏ\". Những người trong độ tuổi lao động, trụ cột của gia đình, buộc phải rời quê hương để tìm kiếm cơ hội tại các khu công nghiệp, đô thị lớn. </p><p>Nhiều nhà khác con cái như những cánh chim nay xa quê rồi ở lại đô thị, lễ Tết mới về quê mấy hôm.</p><p>Hệ quả là, việc xưa nay \"già cậy con\" trở nên khó hơn. Với những nhà gửi con ở quê với ông bà, mối quan hệ ông bà - cha mẹ - cháu cũng lỏng lẻo hơn. Nhiều gia đình trẻ vừa phải lo bươn chải kiếm sống vừa lo nuôi dạy con cái từ xa, việc cận kề chăm sóc cha mẹ già trở thành một điều quá khó.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"04/02/2025 14:59\" data-id=\"20250203123945212\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/2/3/img5898-17385604434781463269699-209-0-1459-2000-crop-17385609850771739001727.jpg\" data-url=\"/sau-nhung-ngay-ve-que-an-tet-co-mot-cau-hoi-cua-cha-me-lam-nhieu-nguoi-con-ua-nuoc-mat-20250203123945212.htm\" data-title=\"Sau những ngày về quê ăn Tết, có một câu hỏi của cha mẹ làm nhiều người con ứa nước mắt\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/2/3/img5898-17385604434781463269699-209-0-1459-2000-crop-17385609850771739001727.jpg\" alt=\"Nỗi cô đơn của người già sau những ngày Tết đoàn viên - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Sau những ngày về quê ăn Tết, có một câu hỏi của cha mẹ làm nhiều người con ứa nước mắtĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Một trong những thách thức lớn nhất chính là tâm lý \"sợ làm phiền\" của người già. Nhiều ông bà khi buồn lòng hoặc đau ốm thường có xu hướng giấu kín, không muốn cho con cái biết vì sợ chúng lo lắng hoặc phải bỏ việc về thăm. </p><p>\"Bệnh nhẹ thì tự ra trạm xá, nặng chút thì tự đi viện trong ngày rồi về. Con cái ở xa hàng ngàn cây số, xin nghỉ một ngày là mất tiền công, có khi còn ảnh hưởng đến vị trí việc làm và công việc\" - bác họ của tôi hay nói vậy.</p><p>Đối với những công nhân làm việc tại các khu công nghiệp với quy định giờ giấc khắt khe, việc vượt hàng trăm, hàng ngàn cây số về chăm cha mẹ ốm là một bài toán kinh tế và thời gian đầy nan giải. </p><p>Trong những lúc ấy, sự chăm sóc thường chỉ còn trông cậy vào tình làng nghĩa xóm, đây là một điểm tựa quý báu nhưng cũng không thể thay thế hoàn toàn được tình thân ruột thịt.</p><h2>Chào tạm biệt, ông bà giấu nỗi niềm riêng</h2><p>Việt Nam đang bước vào giai đoạn già hóa dân số với tốc độ nhanh. Kinh tế phát triển mang lại đời sống vật chất tốt hơn nhưng lại làm đời sống tinh thần tuổi xế chiều đầy lo âu với người già. </p><p>Niềm vui lớn nhất của người cao tuổi ở nông thôn có lẽ là những ngày lễ, Tết. Đó là lúc gia đình quây quần, con cháu đầy đủ, tiếng cười rộn rã bên mâm cơm đoàn viên. Niềm vui ấy ngắn ngủi vài hôm. </p><p>Song có những gia đình trẻ vì mưu sinh mà Tết cũng không thể về, để lại những đôi mắt già nua mòn mỏi ngóng chờ, nén nỗi buồn vào lòng và hy vọng lần sau sum vầy...</p><p>Những lời thắt lòng vẫn xuất hiện: \"Chúng đi làm ăn xa, lúc đau ốm tủi thân chẳng thấy đứa nào. Vui được mấy ngày Tết rồi chúng lại đi hết...\". Một nỗi niềm đau đáu. Một khoảng trống về việc chăm sóc người già.</p><p>Chăm sóc người già không chỉ là trách nhiệm đạo đức mà còn là thước đo sự an sinh của một xã hội. Làm thế nào để những người đã cống hiến cả cuộc đời cho con cháu được hưởng một tuổi già trọn vẹn và không đơn độc? Điều này cũng khó khi con cái họ đi làm xa và cha mẹ, vì nhiều lẽ, không tiện ở cùng các con.</p><p>Cần có chính sách khuyến khích phát triển kinh tế, tạo việc làm tại địa phương để người lao động \"ly nông bất ly hương\", vừa có thể làm việc vừa chăm sóc gia đình. Đó là điều ước muốn từ thực tế nhưng cũng không dễ làm tốt được trong điều kiện thực tế hiện nay, khi ngày càng ít đi những gia đình ba thế hệ.</p><p>Xây dựng các mạng lưới hỗ trợ người già neo đơn, nâng cao năng lực y tế cơ sở tại các vùng nông thôn cũng là một yêu cầu từ thực tế để người già không neo đơn, có nhiều hoạt động xã hội để sống vui sống khỏe hơn.</p>                                      <p>Ở lại quê nhà, nhiều người cao tuổi không có lương hưu, nguồn thu nhập khác cũng còn hạn chế. Nhiều người có điều kiện kinh tế khá hơn cũng không khỏi buồn vì cô đơn và nhiều vấn đề sức khỏe.</p>                 <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/8/20/agnes-ex1-read-only-1755673470388518790766-43-0-1593-2480-crop-1755673891057970608185.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Nỗi cô đơn của người già sau những ngày Tết đoàn viên - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Phải làm người già, mới thấu tuổi già<p class=\"VCObjectBoxRelatedNewsItemSapo\">TTCT - Ngoại hình có thể cho thấy một người đã cao tuổi, nhưng ta không thể biết họ thực sự cảm thấy thế nào bên trong. Tuổi già giống như một cơn đau: ta không thể miêu tả trọn vẹn, chỉ có thể so sánh, kiểu \"đau như thể là…\"</p>                 \r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/tet-cua-nguoi-gia-1772072902568309789653-21-0-1536-2424-crop-177207299135366942851.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/noi-co-don-cua-nguoi-gia-sau-nhung-ngay-tet-doan-vien-20260226093218589.htm', NULL, '2026-02-26 09:42:12', '0', '0', '0', '0.55', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"\\u0110\\u1eddi S\\u1ed1ng\":11,\"Th\\u1ebf Gi\\u1edbi\":8,\"S\\u1ee9c Kh\\u1ecfe\":5},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:58', '2026-02-26 03:10:58'),
('180', '2', '2', 'Dân \'kêu\' giá nền tái định cư cao, dù họ đã nhường đất làm đường', 'dan-keu-gia-nen-tai-dinh-cu-cao-du-ho-da-nhuong-dat-lam-duong', '\r\n                Đường Mậu Thân, phường Châu Đốc, tỉnh An Giang được người dân hiến đất làm đường nhưng việc bố trí tái định cư còn chậm khiến bà con bức xúc - Ảnh: BỬU ĐẤUMỏi mòn chờ tái định cưTuyê...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/base64-1772070475324576096127.jpeg\" id=\"img_208753348496547840\" w=\"2560\" h=\"1441\" alt=\"giá nền tái định cư - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208753348496547840\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/base64-1772070475324576096127.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1441\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Đường Mậu Thân, phường Châu Đốc, tỉnh An Giang được người dân hiến đất làm đường nhưng việc bố trí tái định cư còn chậm khiến bà con bức xúc - Ảnh: BỬU ĐẤU</p></figcaption></figure><h2><b>Mỏi mòn chờ tái định cư</b></h2><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"23/10/2025 10:01\" data-id=\"20251023094333557\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/10/23/ong-nguyen-van-tam-3-17611776315571813255025-72-0-1672-2560-crop-1761177675891885933427-0-201-1065-1905-crop-17611891170571753992166.jpg\" data-url=\"/tuyen-duong-cu-ong-87-tuoi-o-cu-chi-hien-400m-dat-de-lam-duong-20251023094333557.htm\" data-title=\"Tuyên dương cụ ông 87 tuổi ở Củ Chi hiến 400m² đất để làm đường\"><h4 class=\"kbwscwlrl-title\">Tuyên dương cụ ông 87 tuổi ở Củ Chi hiến 400m² đất để làm đường</h4></li><li class=\"kbwscwlrl\" data-date=\"21/11/2025 16:06\" data-id=\"20251121142256826\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/11/21/tai-dinh-cu-an-giang-buu-dau-1-1763709219542877279318-157-0-1757-2560-crop-1763709612366422694638.jpg\" data-url=\"/dan-buc-xuc-khi-hien-dat-lam-duong-lai-thanh-khu-tai-dinh-cu-20251121142256826.htm\" data-title=\"Dân bức xúc khi hiến đất làm đường lại thành khu tái định cư?\"><h4 class=\"kbwscwlrl-title\">Dân bức xúc khi hiến đất làm đường lại thành khu tái định cư?</h4></li><li class=\"kbwscwlrl\" data-date=\"30/11/2024 08:21\" data-id=\"20241129230317623\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2024/11/29/hien-dat-1732895926646176137974-0-0-730-1168-crop-1732895958259684275659.jpg\" data-url=\"/thu-tuc-hien-dat-lam-duong-de-tach-thua-nhu-the-nao-20241129230317623.htm\" data-title=\"Thủ tục hiến đất làm đường để tách thửa như thế nào?\"><h4 class=\"kbwscwlrl-title\">Thủ tục hiến đất làm đường để tách thửa như thế nào?</h4></li></ul><p>Bà Trần Thị Ngà (73 tuổi, ngụ phường Châu Đốc, tỉnh An Giang) cho biết sau khi di dời căn nhà khoảng 56m² để nhường đất cho dự án, vợ chồng bà phải sống tạm bợ ven ruộng lúa. </p><p>Khi thu hồi đất, gia đình được bồi thường 39 triệu đồng do phần đất được xác định là đất nông nghiệp. Theo bà Ngà, thời điểm vận động giao đất, chính quyền thông tin chủ trương làm đường và cho biết các hộ đủ điều kiện sẽ được mua nền tái định cư.</p><p>Ban đầu bà con chỉ được thông tin \"nói miệng\" về việc hỗ trợ tái định cư, không có văn bản cụ thể về giá bán nền. Một số hộ được thông tin giá nền khoảng 80-90 triệu đồng. Tuy nhiên, sau nhiều năm chờ đợi, giá nền tái định cư được thông báo tăng lên gần 800 triệu đồng/nền, khiến nhiều hộ bức xúc.</p><p>\"Tôi giao đất, nhận tiền bồi thường mấy chục triệu đồng. Nay nghe giá nền (90m2) khoảng 700-800 triệu đồng, gia đình tôi không biết lấy đâu ra tiền để mua\", bà Ngà nói và cho rằng mức giá này vượt quá khả năng của nhiều hộ dân.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/base64-17720704753471744270726.jpeg\" id=\"img_208753395380477952\" w=\"2560\" h=\"1441\" alt=\"Dân \'kêu\' giá nền tái định cư cao, dù họ đã nhường đất làm đường - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208753395380477952\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/base64-17720704753471744270726.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1441\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Một chòm nhà ở tạm ven cánh đồng lúa để chờ vào ở khu tái định cư - Ảnh: BỬU ĐẤU</p></figcaption></figure><p>Theo hồ sơ <i>Tuổi Trẻ</i> có được, năm 2021, ông Phạm Văn Phúc - Phó chủ tịch UBND TP Châu Đốc thời điểm đó - ký quyết định về việc bồi thường, hỗ trợ và tái định cư cho bà Trần Thị Ngà để thực hiện dự án đầu tư xây dựng công trình đường đê kênh Hòa Bình, với tổng kinh phí hơn 481,3 triệu đồng.</p><p>Theo quyết định, bà Trần Thị Ngà được xem xét giao 1 nền đất ở có thu tiền sử dụng đất diện tích 90m² tại khu tái định cư thuộc dự án đường kênh Hòa Bình mà không nói rõ số tiền.</p><h3><b>Ghi nhận, xem xét giải quyết</b></h3><p>Mới đây, UBND phường Châu Đốc tổ chức đối thoại với 10 hộ được xét cấp nền tái định cư nhưng chưa được giao đất. Theo đó, khu tái định cư có quy mô khoảng 88 nền, dự kiến bố trí khoảng 19 nền cho các hộ bị ảnh hưởng trực tiếp.</p><p>Tuy nhiên, quá trình thực hiện phải chờ kết quả giải quyết khiếu nại của một số trường hợp liên quan đến đất đai nên đến nay chưa thể giao nền tái định cư. Đồng thời, dự án còn vướng thủ tục giao đất theo quy định pháp luật. </p><p>Đến nay ban quản lý dự án đã chi trả tiền hỗ trợ thuê nhà cho 19 hộ dân đến hết tháng 12-2025, với tổng số tiền hơn 1,3 tỉ đồng. Việc hỗ trợ sẽ tiếp tục được thực hiện cho đến khi các hộ được giao nền tái định cư theo quy định.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/base64-1772070475366638765920.jpeg\" id=\"img_208753118123151360\" w=\"2560\" h=\"1441\" alt=\"Dân \'kêu\' giá nền tái định cư cao, dù họ đã nhường đất làm đường - Ảnh 3.\" title=\"\" rel=\"lightbox\" photoid=\"208753118123151360\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/base64-1772070475366638765920.jpeg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1441\" loading=\"lazy\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"\">Người dân được bố trí tái định cư trong dự án đường Mậu Thân bức xúc vì giá nền cao, gây khó khăn cho bà con - Ảnh: BỬU ĐẤU</p></figcaption></figure><p>Lãnh đạo UBND phường Châu Đốc xác nhận đã tiếp nhận ý kiến, kiến nghị của các hộ dân. Theo giải thích của UBND phường Châu Đốc, việc bố trí tái định cư chậm trễ do phải chờ giải quyết khiếu nại liên quan; một số hộ chưa thống nhất nộp giấy chứng nhận quyền sử dụng đất để điều chỉnh diện tích theo phương án bồi thường đã phê duyệt; đồng thời còn vướng mắc trong hoàn thiện thủ tục pháp lý về giao đất tái định cư.</p><p>\"Các ý kiến của bà con được UBND phường Châu Đốc ghi nhận. Giá nền nhà đó là căn cứ theo quy định giá đất hiện hành. Đơn vị đang báo cáo giá giao nền tái định cư lên cấp trên xem xét\", lãnh đạo UBND phường Châu Đốc nói.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/1/30/2026130-cang-quy-nhon-17697676178772127444476-714-116-1781-1823-crop-17697676694881059904012.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Dân Châu Đốc \'kêu\' giá nền tái định cư cao, dù họ đã nhường đất làm đường  - Ảnh 4.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Vụ dân không chịu giải tỏa để mở rộng cảng Quy Nhơn: Không di dời sẽ thu hồi đất tái định cư<p class=\"VCObjectBoxRelatedNewsItemSapo\">Liên quan vụ thu hồi đất khu tập thể công nhân cảng Quy Nhơn (phường Quy Nhơn, Gia Lai), tới nay vẫn còn 5 hộ dân chưa đồng ý phương án thu hồi đất và không chấp hành giao trả mặt bằng.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/tai-dinh-cu-an-giang-buu-dau-4-17720703981571643385953-0-0-1600-2560-crop-1772070401859136697038.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/dan-keu-gia-nen-tai-dinh-cu-cao-du-ho-da-nhuong-dat-lam-duong-20260226084812557.htm', NULL, '2026-02-26 09:42:02', '0', '0', '0', '0.45', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":9,\"Th\\u1eddi S\\u1ef1\":5,\"\\u0110\\u1eddi S\\u1ed1ng\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:58', '2026-02-26 03:10:58'),
('181', '3', '2', 'Giá bán căn hộ chung cư Nhật Bản tăng cao kỷ lục năm thứ 9 liên tiếp', 'gia-ban-can-ho-chung-cu-nhat-ban-tang-cao-ky-luc-nam-thu-9-lien-tiep', '\r\n                Các tòa nhà chung cư cao tầng tại khu vực ven sông thuộc quận Chuo, Tokyo - Ảnh: AsahiNgày 25-2, Viện Nghiên cứu kinh tế bất động sản Nhật Bản công bố báo cáo cho thấy giá bán trung...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/chung-cu-nhat-ban-asahi-17720722270591120384993.jpg\" id=\"img_208757056195022848\" w=\"820\" h=\"547\" alt=\"căn hộ - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208757056195022848\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/chung-cu-nhat-ban-asahi-17720722270591120384993.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"820\" height=\"547\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Các tòa nhà chung cư cao tầng tại khu vực ven sông thuộc quận Chuo, Tokyo - Ảnh: Asahi</p></figcaption></figure><p>Ngày 25-2, Viện Nghiên cứu kinh tế bất động sản Nhật Bản công bố báo cáo cho thấy giá bán trung bình căn hộ chung cư mới ở nước này tiếp tục tăng, đạt mức cao kỷ lục trong năm thứ 9 liên tiếp vào năm 2025.</p><p>Chi phí xây dựng tăng cao đã đẩy giá chung cư tăng 7,8% so với năm trước đó, lên trung bình 65,56 triệu yen (khoảng 10,9 tỉ đồng)/căn hộ.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"07/03/2025 15:46\" data-id=\"20250307153935289\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2025/3/7/nha-o-nhat-ban-17413355203741944561022-0-80-343-630-crop-17413367979921156837072.jpg\" data-url=\"/gia-can-ho-chung-cu-moi-tang-manh-tai-nhat-ban-20250307153935289.htm\" data-title=\"Giá căn hộ chung cư mới tăng mạnh tại Nhật Bản\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/3/7/nha-o-nhat-ban-17413355203741944561022-0-80-343-630-crop-17413367979921156837072.jpg\" alt=\"Giá bán căn hộ chung cư Nhật Bản tăng cao kỷ lục năm thứ 9 liên tiếp - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Giá căn hộ chung cư mới tăng mạnh tại Nhật BảnĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Theo báo cáo, số lượng căn hộ bán ra trong năm ngoái trên toàn Nhật Bản cũng đã tăng nhẹ 0,8%, lên 59.940 căn hộ, đánh dấu lần tăng trưởng đầu tiên kể từ năm 2021.</p><p>Riêng tại thủ đô Tokyo và khu vực lân cận, giá chung cư trung bình tăng 17,4% lên 91,82 triệu yen/căn hộ (hơn 15,2 tỉ đồng), lần đầu tiên vượt ngưỡng 90 triệu yen/căn hộ (khoảng 14,98 tỉ đồng). </p><p>Ngược lại, giá chung cư trung bình tại khu vực Kinki, trong đó tính cả thành phố Osaka ở miền tây Nhật Bản, lại giảm nhẹ 0,5% xuống, 53,28 triệu yen/căn hộ (khoảng 8,87 tỉ đồng).</p><p>Trong số các thành phố lớn, giá chung cư trung bình tại Sapporo trên đảo Hokkaido, phía bắc Nhật Bản, tăng 17%, lên 60,22 triệu yen/căn hộ (khoảng hơn 10 tỉ đồng).</p><p>Trong khi đó, tại các thành phố Sendai, Nagoya, Hiroshima và Fukuoka, giá chung cư đều giảm do nguồn cung các căn hộ diện tích nhỏ và giá rẻ tăng lên.</p><p>Viện Nghiên cứu kinh tế bất động sản dự báo trong năm nay, doanh số bán các căn hộ chung cư trên toàn Nhật Bản có thể tăng 3,4%, lên 62.000 căn hộ, dẫn đầu là thủ đô Tokyo và khu vực lân cận, cũng như khu vực Kyushu và Okinawa ở phía tây nam.</p><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2024/2/29/bat-dong-san-nhat-ban-17091957837331708175646-27-0-446-670-crop-17091965728181681434153.jpg\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Giá bán căn hộ chung cư Nhật Bản tăng cao kỷ lục năm thứ 9 liên tiếp - Ảnh 3.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Giá căn hộ mới tại Nhật Bản tăng lên mức cao kỷ lục 7 năm liên tiếp<p class=\"VCObjectBoxRelatedNewsItemSapo\">Trên toàn Nhật Bản, số lượng căn hộ bán ra giảm 10,8% xuống còn 65.075 căn, giảm năm thứ hai liên tiếp do khó khăn trong việc tìm được đất phù hợp cho nhà chung cư ở khu vực thành thị.</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/chung-cu-nhat-ban-asahi-17720722270591120384993-35-0-547-820-crop-17720725347281441319648.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/gia-ban-can-ho-chung-cu-nhat-ban-tang-cao-ky-luc-nam-thu-9-lien-tiep-20260226092438544.htm', NULL, '2026-02-26 09:38:43', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Kinh Doanh\":18,\"Th\\u1ebf Gi\\u1edbi\":14,\"Ph\\u00e1p Lu\\u1eadt\":0},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:58', '2026-02-26 03:10:58'),
('182', '2', '2', 'Kênh đào Panama: Tâm bão cạnh tranh Mỹ - Trung ở Mỹ Latin', 'kenh-dao-panama-tam-bao-canh-tranh-my-trung-o-my-latin', '\r\n                Kênh đào Panama trở thành bài trắc nghiệm then chốt với chính sách an ninh mới của ông Trump - Ảnh: CNNĐằng sau tranh chấp tài sản tưởng như đơn thuần này là cuộc đối đầu địa chính t...', '\r\n                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/26/panama-canal-trump-17720668291371179764900.jpg\" id=\"img_208746045665927168\" w=\"1480\" h=\"833\" alt=\"Kênh đào Panama - Ảnh 1.\" title=\"Kênh đào Panama: Tâm bão cạnh tranh Mỹ - Trung ở Mỹ Latin - Ảnh 1.\" rel=\"lightbox\" photoid=\"208746045665927168\" data-original=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/26/panama-canal-trump-17720668291371179764900.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"1480\" height=\"833\" fetchpriority=\"high\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Kênh đào Panama trở thành bài trắc nghiệm then chốt với chính sách an ninh mới của ông Trump - Ảnh: CNN</p></figcaption></figure><p>Đằng sau tranh chấp tài sản tưởng như đơn thuần này là cuộc đối đầu địa chính trị ngày càng quyết liệt giữa Mỹ và Trung Quốc.</p><p>Ngày 23-2, chính quyền Panama tiếp quản quyền kiểm soát hai cảng Balboa và Cristobal, hai đầu mối quan trọng bậc nhất trên kênh đào nối Thái Bình Dương với Đại Tây Dương, từ tay Công ty Cảng Panama (PPC) - công ty con của Tập đoàn CK Hutchison (Hong Kong). </p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"16/02/2026 14:25\" data-id=\"20260216140511693\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/16/china-visa-17712245103381902658489-91-34-639-911-crop-1771224561502448802182.png\" data-url=\"/trung-quoc-mien-visa-cho-cac-nuoc-trong-nhom-five-eyes-tru-my-20260216140511693.htm\" data-title=\"Trung Quốc miễn visa cho các nước trong nhóm Five Eyes, trừ Mỹ\"><img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2026/2/16/china-visa-17712245103381902658489-91-34-639-911-crop-1771224561502448802182.png\" alt=\"Kênh đào Panama: Tâm bão cạnh tranh Mỹ - Trung ở Mỹ Latin - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"100%\" height=\"auto\"><h4 class=\"kbwscwlrl-title clearfix\">Trung Quốc miễn visa cho các nước trong nhóm Five Eyes, trừ MỹĐỌC NGAY<i class=\"fi fi-arrow-right\"></i></h4></li></ul><p>Động thái này lập tức thổi bùng căng thẳng ngoại giao, biến kênh đào Panama thành tâm bão trong cuộc cạnh tranh chiến lược Mỹ - Trung tại Tây Bán cầu.</p><h2>Bắc Kinh phản ứng gay gắt</h2><p>Ngày 24-2, Đặc khu hành chính Hong Kong (Trung Quốc) gửi văn bản \"phản đối mạnh mẽ\" tới Panama. </p><p>Cục trưởng Phát triển kinh tế và Thương mại Hong Kong Khâu Ứng Hoa đã trực tiếp chuyển văn kiện này cho Tổng lãnh sự Panama tại Hong Kong.</p><p>Chính quyền Hong Kong lên án việc tiếp quản mang tính \"cưỡng chế\", \"bất chấp sự thật và bội tín\", đồng thời khẳng định sẽ \"kiên quyết ủng hộ và bảo vệ\" quyền lợi hợp pháp của doanh nghiệp Hong Kong.</p><p>Cùng ngày, người phát ngôn Bộ Ngoại giao Trung Quốc Mao Ninh tuyên bố lập trường Bắc Kinh là \"rõ ràng và dứt khoát\" rằng Trung Quốc sẽ \"kiên quyết bảo vệ các quyền và lợi ích hợp pháp của các doanh nghiệp mình\", theo China Daily ngày 25-2.</p><p>Về phía CK Hutchison, tập đoàn này xác nhận PPC đã ngừng hoạt động tại hai cảng từ ngày 23-2 sau khi đại diện Chính phủ Panama xuất hiện \"không được mời\" và thông báo hợp đồng nhượng quyền \"không còn giá trị\", yêu cầu dừng mọi hoạt động ngay lập tức. PPC đã khởi động thủ tục trọng tài quốc tế từ đầu tháng 2.</p><p>Căn cứ pháp lý cho động thái của Panama là phán quyết của Tòa án tối cao nước này vào tháng 1-2026, tuyên bố hợp đồng giữa PPC và chính phủ về vận hành hai cảng là vi hiến. </p><p>Theo thông báo chính thức, Chính phủ Panama đã tiếp quản toàn bộ cơ sở hạ tầng - gồm cần cẩu, xe cộ, hệ thống máy tính và phần mềm - theo một sắc lệnh nhằm đảm bảo hoạt động không gián đoạn.</p><p>Trong thời gian chờ hoàn tất hợp đồng nhượng quyền mới, dự kiến kéo dài 18 tháng, hãng vận tải Đan Mạch A.P. Moller-Maersk tạm vận hành cảng Balboa, còn Công ty vận tải biển Địa Trung Hải (MSC, Thụy Sĩ) đảm trách cảng Cristobal.</p><h2>Thế cờ lớn hơn tài sản</h2><p>Tranh chấp này không đơn thuần là câu chuyện doanh nghiệp. Trung Quốc đã theo đuổi chiến lược thâm nhập có hệ thống vào khu vực Mỹ Latin và Caribe, với kim ngạch thương mại hai chiều vượt 500 tỉ USD mỗi năm và hàng loạt tập đoàn nhà nước lẫn tư nhân bám rễ sâu trong mạng lưới hạ tầng lưới điện, viễn thông, cảng biển và hầm mỏ. </p><p>Theo dữ liệu Liên hợp quốc, Trung Quốc đã vượt Mỹ để trở thành đối tác thương mại lớn nhất của Panama từ năm 2019.</p><ul class=\"kbwscwlr-list\"><li class=\"kbwscwlrl\" data-date=\"25/02/2026 22:50\" data-id=\"20260225222729188\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/25/hinh-anh-25-2-26-luc-2220-1772032831098663453585-61-0-940-1406-crop-1772033033983276528251.png\" data-url=\"/dai-dien-my-washington-muon-giu-nguyen-muc-thue-voi-bac-kinh-de-tranh-leo-thang-20260225222729188.htm\" data-title=\"Mỹ muốn giữ nguyên mức thuế 35-50% với hàng Trung Quốc để tránh leo thang\"><h4 class=\"kbwscwlrl-title\">Mỹ muốn giữ nguyên mức thuế 35-50% với hàng Trung Quốc để tránh leo thang</h4></li><li class=\"kbwscwlrl\" data-date=\"24/02/2026 20:19\" data-id=\"2026022419581608\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/24/bn32xgs7tbjrtff3p7hoassq6y-1771937259754282259305.jpg\" data-url=\"/iran-sap-so-huu-ten-lua-sieu-thanh-cua-trung-quoc-thach-thuc-my-2026022419581608.htm\" data-title=\"Iran sắp sở hữu tên lửa siêu thanh của Trung Quốc, thách thức Mỹ?\"><h4 class=\"kbwscwlrl-title\">Iran sắp sở hữu tên lửa siêu thanh của Trung Quốc, thách thức Mỹ?</h4></li><li class=\"kbwscwlrl\" data-date=\"21/02/2026 18:15\" data-id=\"20260221175555962\" data-avatar=\"https://cdn2.tuoitre.vn/471584752817336320/2026/2/21/tq-1771671202703165625100-27-0-565-860-crop-1771671373549319700685.jpg\" data-url=\"/tinh-bao-my-trung-quoc-bi-mat-thu-the-he-vu-khi-hat-nhan-moi-20260221175555962.htm\" data-title=\"Tình báo Mỹ: Trung Quốc bí mật thử thế hệ vũ khí hạt nhân mới\"><h4 class=\"kbwscwlrl-title\">Tình báo Mỹ: Trung Quốc bí mật thử thế hệ vũ khí hạt nhân mới</h4></li></ul><p>Trong khi đó, chính quyền Tổng thống Donald Trump tuyên bố sẽ không để các đối thủ nắm giữ \"các tài sản chiến lược quan trọng\" ở Tây Bán cầu. </p><p>Năm 2025, ông Trump từng cáo buộc Trung Quốc \"điều hành kênh đào Panama\" và đòi lấy lại quyền kiểm soát. </p><p>Trước sức ép đó, CK Hutchison đã đàm phán thỏa thuận 23 tỉ USD để bán các tài sản cảng ngoài Trung Quốc cho liên minh do BlackRock dẫn đầu, nhưng Bắc Kinh lập tức can thiệp, đình chỉ giao dịch với lý do cần \"thực hiện tổng rà soát và giám sát\" các tài sản này.</p><p>Trong tuyên bố ngày 24-2, Bắc Kinh cảnh báo Panama sẽ \"gánh chịu hậu quả\" với nguy cơ \"thiệt hại sâu sắc\" cho môi trường kinh doanh. </p><p>Song Trung Quốc cũng có lý do để kiềm chế. Bắc Kinh lâu nay xây dựng hình ảnh đối tác \"không can thiệp nội bộ\", đối lập với những gì họ gọi là chủ nghĩa đế quốc của Mỹ tại châu Mỹ. </p><p>Nếu mạnh tay với Panama, hình ảnh đó sẽ bị xói mòn, làm suy yếu nỗ lực định vị Bắc Kinh là lựa chọn thay thế cho Washington, đặc biệt với các nền kinh tế mới nổi. </p><p>Ngoài ra, Trung Quốc cũng có thể không muốn gây quá nhiều xáo trộn trước chuyến thăm dự kiến của ông Trump tới nước này trong năm nay.</p><p>\"Dù thế nào đi nữa, chúng ta nên kỳ vọng doanh nghiệp Trung Quốc sẽ ngày càng thận trọng trong các cam kết đầu tư chiến lược ở vùng lân cận của Mỹ, xét việc ông Trump dường như rất tha thiết khẳng định quyền kiểm soát với các nút thắt địa lý và vị trí chiến lược\", CNN dẫn lời ông Brian Wong - nhà phân tích địa chính trị tại Đại học Hong Kong.</p>                                      <h3 style=\"text-align: center;\">Panama không nhượng bộ, Trung Quốc không im lặng</h3><p>Tổng thống Panama Jose Raul Mulino khẳng định việc tiếp quản \"không phải là một sự trưng thu\", mà chỉ là chuyển giao tạm thời để xác định \"giá trị thực\" của các cảng trước khi có đền bù tài chính tương ứng cho CK Hutchison. </p><p>Về phía Bắc Kinh, ngay từ đầu tháng 2, Trung Quốc đã yêu cầu các công ty nhà nước dừng mọi dự án mới tại Panama - một quyết định Bloomberg ước tính trị giá nhiều tỉ USD. </p><p>Bắc Kinh cũng yêu cầu các hãng vận tải xem xét chuyển hướng hàng hóa qua các cảng khác nếu không làm tăng chi phí quá cao, đồng thời siết chặt kiểm soát hàng nhập khẩu từ Panama, chủ yếu là chuối và cà phê.</p>                 <img src=\"https://cdn2.tuoitre.vn/thumb_w/730/471584752817336320/2025/4/9/bqpmytto-1744168458992456120419-29-49-1165-1866-crop-17441685888092032144430.png\" style=\"float: left; width: 150px; height: 120px; margin-right: 10px;\" alt=\"Kênh đào Panama: Tâm bão cạnh tranh Mỹ - Trung ở Mỹ Latin - Ảnh 2.\" title=\"\" loading=\"lazy\" width=\"150\" height=\"120\">Mỹ tuyên bố sẽ lấy lại kênh đào Panama khỏi ảnh hưởng từ Trung Quốc<p class=\"VCObjectBoxRelatedNewsItemSapo\">Trong chuyến thăm của Bộ trưởng Quốc phòng Mỹ Pete Hegseth tới Panama ngày 8-4, ông khẳng định Mỹ \"sẽ lấy lại kênh đào Panama khỏi ảnh hưởng từ Trung Quốc\".</p>\r\n                \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Đọc tiếp\r\n                    \r\n                    \r\n                        \r\n                            \r\n                            \r\n                                \r\n                                    \r\n                                \r\n                                \r\n                            \r\n                        \r\n                        Về trang Chủ đề\r\n                    \r\n                \r\n            ', 'https://cdn2.tuoitre.vn/thumb_w/1200/471584752817336320/2026/2/26/panama-canal-trump-17720668291371179764900-160-235-803-1263-crop-1772073679299126481562.jpg', NULL, NULL, NULL, 'https://tuoitre.vn/kenh-dao-panama-tam-bao-canh-tranh-my-trung-o-my-latin-20260226075008506.htm', NULL, '2026-02-26 09:38:26', '0', '0', '1', '0.7', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":36,\"Th\\u1eddi S\\u1ef1\":10,\"Kinh Doanh\":8},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:59', '2026-02-26 03:10:59'),
('183', '2', '3', 'Tự tin sải bước tới văn phòng cùng set đồ công sở', 'tu-tin-sai-buoc-toi-van-phong-cung-set-do-cong-so', '\n                    \n                                        Giữa nhịp sống công sở ngày càng đề cao hình ảnh cá nhân, một set đồ được lựa chọn tinh tế không chỉ giúp phái đẹp ghi điểm về diện mạo mà...', '\n                    \n                                        <p data-id-seo=\"paragraphs-0\">Giữa nhịp sống công sở ngày càng đề cao hình ảnh cá nhân, một set đồ được lựa chọn tinh tế không chỉ giúp phái đẹp ghi điểm về diện mạo mà còn góp phần thể hiện phong thái chuyên nghiệp và sự tự tin nơi công sở. </p><h2 data-id-seo=\"h2-0\">Áo sơ mi và chân váy midi</h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/1-1772010972783209436464.jpg\" id=\"img_208624206076739584\" w=\"1458\" h=\"1945\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 1.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 1.\" rel=\"lightbox\" photoid=\"208624206076739584\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/1-1772010972783209436464.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-0\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Khởi đầu cho tủ đồ công sở thanh lịch chính là sự kết hợp kinh điển giữa áo sơ mi và chân váy midi. Chiếc áo sơ mi cổ đức tay dài sắc xanh pastel được sơ vin gọn gàng, kết hợp cùng chân váy midi tone sur tone điểm xuyết chi tiết nơ nhỏ. Khi phối cùng giày cao gót sắc kem và túi xách da cầm tay màu xanh ngọc tôn lên phong thái chuyên nghiệp và khẳng định năng lực trong môi trường công sở</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: JM DRESS</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/2-1772010972824511312415.jpg\" id=\"img_208624206051237888\" w=\"850\" h=\"1274\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 2.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 2.\" rel=\"lightbox\" photoid=\"208624206051237888\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/2-1772010972824511312415.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-1\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Ghi điểm với áo sơ mi cộc tay xanh lá pastel sở hữu thiết kế cổ phối màu tinh tế. Sơ vin cùng chân váy midi sắc nâu be, được nhấn nhá bằng thắt lưng da dáng mảnh, khéo léo tôn lên vóc dáng chỉn chu. Hoàn thiện bản phối bằng túi xách cầm tay cùng khuyên tai đính đá, tổng thể toát lên phong thái chuyên nghiệp khi làm việc</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: LAMER FASHION</p></figure><h2 data-id-seo=\"h2-1\">Set vest công sở</h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/3-177201097283348740491.jpg\" id=\"img_208624206042320896\" w=\"1600\" h=\"2400\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 3.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 3.\" rel=\"lightbox\" photoid=\"208624206042320896\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/3-177201097283348740491.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-2\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Set vest đứng phom trở thành điểm nhấn tinh tế giúp phái đẹp tự tin chinh phục những buổi họp quan trọng. Áo gile sắc xám cổ chữ V được khoác ngoài bằng áo vest tone sur tone, phối cùng quần suông xếp ly vừa giúp che khuyết điểm vóc dáng, vừa mang lại diện mạo chỉn chu</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: IVY MODA</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/4-17720109728591627399635.jpg\" id=\"img_208624206037946368\" w=\"900\" h=\"1350\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 4.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 4.\" rel=\"lightbox\" photoid=\"208624206037946368\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/4-17720109728591627399635.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-3\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Set vest với sắc be nhã nhặn, áo vest ôm vừa vặn khoác ngoài giúp tôn lên vóc dáng thanh tao, kết hợp cùng áo cúp ngực sắc trắng bên trong, khéo léo khoe trọn xương quai xanh thanh mảnh. Khi phối cùng quần suông tone sur tone, cả bộ trang phục màu trắng gợi sự tinh khôi mà vẫn chuyên nghiệp</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: LAMIA DESIGN</p></figure><h2 data-id-seo=\"h2-2\">Đầm polo dáng xòe</h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/5-17720109728971827115519.jpg\" id=\"img_208624206036029440\" w=\"1154\" h=\"1731\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 5.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 5.\" rel=\"lightbox\" photoid=\"208624206036029440\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/5-17720109728971827115519.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-4\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Đầm polo màu ghi với phần chiết đai tinh tế, trong khi chân váy xếp ly được xử lý tỉ mỉ tạo độ xòe tự nhiên, mang lại vẻ năng động. Đôi giày cao gót mũi nhọn màu trắng và khuyên tai đính đá giúp nàng tự tin thể hiện phong cách riêng, phù hợp môi trường công sở</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: JM DRESS</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/6-17720109729391783923333.jpg\" id=\"img_208624206040223744\" w=\"1154\" h=\"1731\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 6.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 6.\" rel=\"lightbox\" photoid=\"208624206040223744\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/6-17720109729391783923333.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-5\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Đầm polo xám ghi với điểm nhấn nằm ở thiết kế cổ trắng kết hợp hàng nơ nhỏ đính trước ngực, tạo nét chấm phá mềm mại. Dáng đầm xòe nhẹ mang đến vẻ đẹp ngọt ngào, phù hợp để nàng tự tin xuất hiện nơi công sở hay những buổi gặp gỡ nhẹ nhàng</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: JM DRESS</p></figure><h2 data-id-seo=\"h2-3\">Áo sơ mi và quần suông</h2><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/7-1772010972983918461972.jpg\" id=\"img_208624206054723584\" w=\"1000\" h=\"1500\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 7.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 7.\" rel=\"lightbox\" photoid=\"208624206054723584\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/7-1772010972983918461972.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-6\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Đối với những quý cô yêu thích phong cách tối giản nhưng vẫn muốn giữ vẻ chuyên nghiệp, combo áo sơ mi và quần suông luôn là lựa chọn đáng tin cậy. Áo sơ mi cổ đức tay dài được khoác ngoài bằng áo len họa tiết kẻ sọc tạo điểm nhấn năng động. Khi sơ vin gọn gàng cùng quần suông cạp cao xếp ly sắc xám, hoàn hảo cho những ngày làm việc cần sự thoải mái</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: GUMAC</p></figure><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/25/8-1772010973020247847895.jpg\" id=\"img_208624206088278016\" w=\"1000\" h=\"1500\" alt=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 8.\" title=\"Tự tin sải bước tới văn phòng cùng set đồ công sở- Ảnh 8.\" rel=\"lightbox\" photoid=\"208624206088278016\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/25/8-1772010973020247847895.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"\" height=\"\" data-id-seo=\"image-7\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Áo sơ mi lụa dài tay sắc đen mang vẻ đẹp cổ điển, được nhấn nhá bằng chi tiết cổ tay lệch vạt tinh tế. Sơ vin cùng quần suông cạp cao xếp ly sắc nâu, kết nối bằng thắt lưng da dáng mảnh, giúp tôn lên phong thái chỉn chu</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: GUMAC</p></figure><p data-id-seo=\"paragraphs-17\"> </p>\n\n                    \n                    \n                                        \n                ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/25/3-177201097283348740491-202-0-1202-1600-crop-17720112863951903963039.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/thoi-trang-tre/tu-tin-sai-buoc-toi-van-phong-cung-set-do-cong-so-185260225162213966.htm', NULL, '2026-02-26 10:00:00', '0', '0', '0', '0.2', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":4,\"Th\\u1eddi S\\u1ef1\":2,\"\\u0110\\u1eddi S\\u1ed1ng\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:10:59', '2026-02-26 03:10:59'),
('184', '2', '3', 'Bill Gates thừa nhận ngoại tình, phủ nhận liên quan tội ác của Jeffrey Epstein', 'bill-gates-thua-nhan-ngoai-tinh-phu-nhan-lien-quan-toi-ac-cua-jeffrey-epstein', '\n\n                                        \n\n                                                                                Hình ảnh tỉ phú Bill Gates và một phụ nữ nằm trong bộ hồ sơ được phe Dân chủ...', '\n\n                                        \n\n                                                                                <figure class=\"VCSortableInPreviewMode\" type=\"Photo\" allow-zoom=\"true\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/26/anh-man-hinh-2026-02-26-luc-100355-17720751269861366643589.png\" id=\"img_208758750081409024\" w=\"884\" h=\"1172\" alt=\"Bill Gates thừa nhận ngoại tình, phủ nhận liên quan tội ác của Jeffrey Epstein - Ảnh 1.\" title=\"\" rel=\"lightbox\" photoid=\"208758750081409024\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/anh-man-hinh-2026-02-26-luc-100355-17720751269861366643589.png\" type=\"photo\" style=\"max-width:100%;\" width=\"884\" height=\"1172\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Hình ảnh tỉ phú Bill Gates và một phụ nữ nằm trong bộ hồ sơ được phe Dân chủ thuộc Ủy ban Giám sát Hạ viện Mỹ công bố hồi tháng 12.2025</p></figcaption><p data-placeholder=\"Nhập tác giả\">ẢNH: REUTERS</p></figure><p>Theo <i>The Wall Street Journal</i>, tại cuộc họp diễn ra hôm 24.2 ở Gates Foundation, Bill Gates đã gửi lời xin lỗi đến các nhân viên quỹ từ thiện của mình vì những hệ lụy phát sinh từ mối quan hệ giữa ông và Jeffrey Epstein. Ông đồng thời thừa nhận có hai mối quan hệ ngoài luồng, song nhấn mạnh bản thân không tham gia vào bất kỳ hành vi phạm pháp nào của Epstein - người từng bị kết án tội môi giới mại dâm trẻ vị thành niên.</p><h2>Bill Gates thừa nhận sai lầm</h2><p>Trong đoạn ghi âm được tờ báo này tiếp cận, Bill Gates nói ông \"xin lỗi những người đã bị cuốn vào câu chuyện vì sai lầm của mình\". Ông cũng thừa nhận đã dành thời gian gặp Epstein và thậm chí đưa một số lãnh đạo của Quỹ Gates tham dự các cuộc gặp, điều mà ông nhìn nhận là quyết định sai lầm.</p><p>Mối quan hệ giữa hai người thời gian qua bị \"đào\" trở lại sau khi Bộ Tư pháp Mỹ công bố thêm tài liệu liên quan Epstein. Trong đó có email do Epstein tự viết, với nội dung cáo buộc Gates mắc bệnh lây truyền qua đường tình dục và tìm cách che giấu với vợ cũ. Gates đã bác bỏ thông tin này.</p><p>Các tài liệu cũng bao gồm hình ảnh Gates chụp cùng một số phụ nữ (khuôn mặt đã bị làm mờ). Tại buổi họp, ông cho biết chính Epstein đề nghị chụp các bức ảnh này cùng trợ lý của mình. \"Tôi xin nói rõ, tôi chưa từng dành thời gian với các nạn nhân hay những phụ nữ xung quanh ông ta\", Gates khẳng định.</p><p>Dù vậy, tỉ phú này thừa nhận mối quan hệ với Epstein hoàn toàn \"đi ngược lại giá trị và mục tiêu của quỹ\". Ông cho rằng uy tín đóng vai trò sống còn đối với các hoạt động từ thiện toàn cầu mà quỹ đang theo đuổi, bởi đối tác có thể lựa chọn hợp tác hoặc không dựa trên niềm tin dành cho tổ chức.</p><figure class=\"VCSortableInPreviewMode\" type=\"Photo\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/26/anh-man-hinh-2026-02-26-luc-100419-17720750859251271600342.png\" id=\"img_208758661469917184\" w=\"1412\" h=\"936\" alt=\"Bill Gates thừa nhận ngoại tình, phủ nhận liên quan tội ác của Jeffrey Epstein - Ảnh 2.\" title=\"\" rel=\"lightbox\" photoid=\"208758661469917184\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/anh-man-hinh-2026-02-26-luc-100419-17720750859251271600342.png\" type=\"photo\" style=\"max-width:100%;\" width=\"1412\" height=\"936\" srcset=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2026/2/26/anh-man-hinh-2026-02-26-luc-100419-17720750859251271600342.png 1x,https://images2.thanhnien.vn/528068263637045248/2026/2/26/anh-man-hinh-2026-02-26-luc-100419-17720750859251271600342.png 2x\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\">Hình ảnh tỉ phú Bill Gates (phải) và ông Jeffrey Epstein trong một cuộc gặp trong hồ sơ được Bộ Tư pháp Mỹ công bố gần đây</p></figcaption><p data-placeholder=\"Nhập tác giả\">ẢNH: BỘ TƯ PHÁP MỸ</p></figure><p>Người phát ngôn của quỹ cho biết Bill Gates tổ chức họp ở Gates Foundation hai lần mỗi năm và tại cuộc họp gần đây, ông đã trao đổi thẳng thắn, giải đáp chi tiết các câu hỏi và nhận trách nhiệm về hành động cá nhân.</p><p>Gates cho biết ông bắt đầu gặp Epstein từ năm 2011, sau khi Epstein đã nhận tội vào năm 2008 và chịu bản án gây nhiều tranh cãi. Ông nói mình biết về \"thỏa thuận 18 tháng\" hạn chế đi lại đối với Epstein, song thừa nhận việc đánh giá khi đó là thiếu thận trọng.</p><p>Ngoài ra, Gates cũng xác nhận từng có quan hệ tình cảm với một nữ vận động viên người Nga và một nhà vật lý hạt nhân người Nga quen qua công việc. Trước đó, năm 2023, <i>The Wall Street Journal </i>đưa tin Epstein từng tìm cách gây sức ép với Bill Gates liên quan mối quan hệ với vận động viên Mila Antonova sau khi không thuyết phục được ông tham gia một quỹ từ thiện trị giá hàng tỉ USD.</p><p>Theo Bill Gates, Epstein thường nói về mối quan hệ thân thiết với nhiều tỉ phú, đặc biệt trong giới tài chính Phố Wall, và tuyên bố có thể hỗ trợ gây quỹ cho các sáng kiến y tế toàn cầu. Sự xuất hiện của những nhân vật có uy tín tại các cuộc gặp khi đó khiến ông \"cảm thấy đây là tình huống bình thường\", điều mà nay ông nhìn nhận là một đánh giá sai lầm.</p>\n                                        \n\n\n                                        \n                                        \n        \n\n        \n        \n    \n                                        \n                                        \n\n                                        \n\n                                    ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/26/anh-man-hinh-2026-02-26-luc-100355-17720751269861366643589-290-0-843-884-crop-17720751678142089957588.png', NULL, NULL, NULL, 'https://thanhnien.vn/bill-gates-thua-nhan-ngoai-tinh-phu-nhan-lien-quan-toi-ac-cua-jeffrey-epstein-185260226095810909.htm', NULL, '2026-02-26 09:58:00', '0', '0', '1', '0.65', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":13,\"\\u0110\\u1eddi S\\u1ed1ng\":7,\"Th\\u1ec3 Thao\":2},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:11:00', '2026-02-26 03:11:00'),
('185', '2', '3', 'Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài', 'xep-hang-xuyen-dem-mua-vang-cau-may-ngay-via-than-tai', '\n                                    \n\n                                                                                                                \n                                    Xếp hàng xuy...', '\n                                    \n\n                                                                                                                \n                                    <h2 data-id-seo=\"h2-0\">Xếp hàng xuyên đêm đợi mua vàng</h2><p data-id-seo=\"paragraphs-0\">Ngày 10 tháng Giêng âm lịch hàng năm được xem là ngày vía Thần tài. Dân gian xem đây là ngày đẹp nhất để mua vàng, sắm sửa lễ vật cúng Thần tài, cầu mong một năm bình an, gặp nhiều tài lộc.</p><figure class=\"VCSortableInPreviewMode alignCenterOverflow\" type=\"Photo\" data-style=\"align-center-overflow\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/xep-hang-mua-vang-22-1772069401153489049302.jpg\" id=\"img_208746775673077760\" w=\"2121\" h=\"1414\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 1.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 1.\" rel=\"lightbox\" photoid=\"208746775673077760\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/xep-hang-mua-vang-22-1772069401153489049302.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"2121\" height=\"1414\" data-id-seo=\"image-0\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Người dân xếp hàng chờ mua vàng trên phố Trần Nhân Tông sáng sớm nay</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: ĐÌNH HUY</p></figure><p data-id-seo=\"paragraphs-3\">Theo ghi nhận của<i> Thanh Niên</i> vào sáng sớm cùng ngày, rất đông người dân đã có mặt tại phố vàng Trần Nhân Tông (P.Hai Bà Trưng, Hà Nội), xếp hàng chờ mua vàng lấy may. Thậm chí, dù nhiều thời điểm có mưa nhưng họ vẫn xếp hàng dài trên vỉa hè, kiên nhẫn đợi đến lượt mua vàng.</p><p data-id-seo=\"paragraphs-4\">Là người nhận số thứ tự sớm nhất, ông Tô Hòa Bình (70 tuổi, trú P.Đống Đa) cho biết, để có được vị trí mua vàng đầu tiên, ông đã phải xếp hàng từ 21 giờ đêm qua (25.2), khi nhiều hàng quán tại khu phố Trần Nhân Tông vẫn chưa đóng cửa.</p><p data-id-seo=\"paragraphs-5\">\"Mọi năm tôi thường đến xếp hàng vào khoảng 2 - 3 giờ sáng nhưng năm nay do thấy ngày thường đã đông người đến xếp hàng rồi nên tôi phải đi sớm, thức xuyên đêm trước tiệm vàng để đợi\", ông Bình nói và cho rằng, ông đến sớm xếp hàng vì không muốn là người thứ hai mua vàng trong ngày vía Thần tài.</p><figure class=\"VCSortableInPreviewMode alignCenterOverflow\" type=\"Photo\" data-style=\"align-center-overflow\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/29f76ae8-16ae-4166-aa27-4bc34dd9ac8f-1772069454400217520316.jpg\" id=\"img_208746886685818880\" w=\"840\" h=\"543\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 2.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 2.\" rel=\"lightbox\" photoid=\"208746886685818880\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/29f76ae8-16ae-4166-aa27-4bc34dd9ac8f-1772069454400217520316.jpg\" type=\"photo\" style=\"max-width:100%;\" data-is-alt-modified=\"true\" width=\"840\" height=\"543\" data-id-seo=\"image-1\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Ông Tô Hòa Bình luôn là những người đến sớm nhất trong hàng chục năm qua</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: ĐÌNH HUY</p></figure><p data-id-seo=\"paragraphs-8\">Ông Bình cho biết thêm, đây là năm thứ 16 ông xếp hàng và hầu như năm nào ông cũng là người đầu tiên được mua vàng. </p><p data-id-seo=\"paragraphs-9\">Ngày vía Thần tài năm nay, giá vàng đã cao hơn 2 lần so với thời điểm vía Thần Tài năm ngoái, ông Bình tiết lộ sẽ mua nhiều hơn thay vì 2 chỉ vàng như mọi lần. \"Tôi mua khoảng 3 - 4 chỉ và không quan tâm đến giá vì mua để lấy may cho gia đình, ông Bình nói tiếp.</p><p data-id-seo=\"paragraphs-12\">Đối diện với địa điểm ông Bình xếp hàng là tiệm vàng Phú Quý. Khác với mọi năm, năm nay, lượng khách đổ về đây xếp hàng cũng tăng vọt buộc nhân viên phải căng dây phân luồng, hướng dẫn người dân ổn định vị trí và xếp hàng trật tự. Phần lớn người dân đến để lựa chọn mua bạc. Họ cho rằng, tuy giá bạc tăng giảm thất thường nhưng vẫn là một kênh để tích lũy, cầu may thay vì mua vàng.</p><h2 data-id-seo=\"h2-1\">Vàng mini lên ngôi dịp vía Thần Tài năm nay</h2><p data-id-seo=\"paragraphs-13\">Sáng nay, các doanh nghiệp kinh doanh vàng, bạc đều hoạt động khá sớm, cập nhật giá ngày từ khoảng 6 giờ 30 đến hơn 7 giờ. </p><p data-id-seo=\"paragraphs-14\">Giá mỗi lượng vàng miếng SJC được Công ty Vàng bạc đá quý Sài Gòn (SJC) niêm yết ở mức mua vào và bán ra như sau: 182 triệu đồng - 185 triệu đồng/lượng, đều giảm 300.000 đồng so với chốt ngày 25.2. Vàng nhẫn 4 số 9 tại SJC cũng giảm 300.000 đồng, hiện ở mức mua vào 181,5 triệu đồng/lượng và bán ra 184,5 triệu đồng/lượng.</p><p data-id-seo=\"paragraphs-15\">Công ty Bảo Tín Minh Châu mua vào và bán ra nhẫn tròn trơn ở mức 181,8 triệu đồng - 184,8 triệu đồng mỗi lượng, giảm 500.000 đồng so với chốt ngày 25.2. Mỗi lượng vàng nhẫn tròn trơn được Công ty Vàng bạc đá quý Phú Quý niêm yết mua vào ở 181,5 triệu đồng và bán ra 184,5 triệu đồng, đều giảm 300.000 đồng so với chốt ngày 25.2…</p><figure class=\"media-item\" data-alt=\"Alt SEO:  - Ảnh 4.\" title=\" - Ảnh 4.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/26/edit-xep-hang-mua-vang-17720699098561416427940.jpeg\" class=\" visible\" data-originalw=\"1504\" data-originalh=\"1062\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/edit-xep-hang-mua-vang-17720699098561416427940.jpeg\" data-row=\"0\" data-id=\"208747842476658688\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 3.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 3.\" data-is-alt-modified=\"true\" data-id-seo=\"image-3\"></figure><figure class=\"media-item\" data-alt=\"Alt SEO:  - Ảnh 5.\" title=\" - Ảnh 5.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/26/xep-hang-mua-vang-27-1772069401184936272967.jpg\" class=\" visible\" data-originalw=\"2121\" data-originalh=\"1414\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/xep-hang-mua-vang-27-1772069401184936272967.jpg\" data-row=\"0\" data-id=\"208746775586050048\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 4.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 4.\" data-is-alt-modified=\"true\" data-id-seo=\"image-4\"></figure><figure class=\"media-item\" data-alt=\"Alt SEO:  - Ảnh 6.\" title=\" - Ảnh 6.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/26/xep-hang-mua-vang-5-17720694010851392318247.jpg\" class=\" visible\" data-originalw=\"2121\" data-originalh=\"1414\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/xep-hang-mua-vang-5-17720694010851392318247.jpg\" data-row=\"0\" data-id=\"208746775563689984\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 5.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 5.\" data-is-alt-modified=\"true\" data-id-seo=\"image-5\"></figure><figure class=\"media-item\" data-alt=\"Alt SEO:  - Ảnh 7.\" title=\" - Ảnh 7.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/26/6a9d0623-97f2-4992-8627-d379d7bc3e73-1772069389283325451487.jpg\" class=\" visible\" data-originalw=\"1536\" data-originalh=\"1059\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/6a9d0623-97f2-4992-8627-d379d7bc3e73-1772069389283325451487.jpg\" data-row=\"1\" data-id=\"208746750135721984\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 6.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 6.\" data-is-alt-modified=\"true\" data-id-seo=\"image-6\"></figure><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Một số thời điểm trời mưa nhưng người dân vẫn kiên nhẫn chờ đợi mua vàng</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: ĐÌNH HUY</p><p data-id-seo=\"paragraphs-18\">Trao đổi với <i>Thanh Niên</i>, TS Đào Lê Trang Anh, giảng viên cấp cao ngành tài chính, Đại học RMIT Việt Nam, phân tích, ngày vía Thần tài luôn là dịp nhu cầu mua vàng tăng đột biến do yếu tố văn hóa tâm linh kết hợp với tâm lý “mua lấy may” đầu năm.</p><p data-id-seo=\"paragraphs-19\">Các doanh nghiệp kinh doanh vàng bạc cũng thừa nhận rằng vào ngày này, lượng khách có thể tăng hàng chục lần so với ngày thường, bất chấp việc giá vàng đang ở xu hướng cao. Thực tế nhiều năm cho thấy số lượng sản phẩm vàng bán ra dịp vía Thần tài thường tăng qua từng năm.</p><p data-id-seo=\"paragraphs-20\">Hiện nay, thị trường quốc tế vẫn chịu tác động từ bất định địa chính trị, biến động lãi suất và nhu cầu trú ẩn gia tăng, mặt bằng giá vàng và bạc đang ở vùng cao. Vì vậy, nếu người dân mua vàng, bạc với mục đích tích lũy dài hạn hoặc mang ý nghĩa tâm linh, nên lựa chọn sản phẩm có tính thanh khoản cao và cân nhắc mua vào thời điểm phù hợp để tránh chênh lệch giá quá lớn.</p><p data-id-seo=\"paragraphs-21\">“Còn nếu mục tiêu là đầu tư ngắn hạn, cần thận trọng với rủi ro điều chỉnh sau cao điểm, tránh tâm lý chạy theo đám đông khi giá đã bị đẩy lên quá cao”, bà Trang Anh nói.</p><p data-id-seo=\"paragraphs-22\">Từ góc độ doanh nghiệp, ông Trương Quang Đạt, Chánh văn phòng HĐQT Công ty Bảo Tín Mạnh Hải, cho biết tuần lễ quanh dịp vía Thần tài năm nay, hành vi tiêu dùng của khách hàng có sự chuyển dịch rõ rệt khi bản vị nhỏ “lên ngôi”.</p><figure class=\"media-item\" data-originalw=\"2560\" data-originalh=\"1707\" style=\"width:calc((100% - 5px) * 0.5)\" data-alt=\"Alt SEO:  - Ảnh 8.\" title=\" - Ảnh 8.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/26/dsc09384-17720699676361075328504.jpg\" class=\"\" data-originalw=\"2560\" data-originalh=\"1707\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/dsc09384-17720699676361075328504.jpg\" data-row=\"0\" data-id=\"208747966412914688\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 7.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 7.\" data-is-alt-modified=\"true\" data-id-seo=\"image-7\"></figure><figure class=\"media-item\" data-originalw=\"2560\" data-originalh=\"1707\" style=\"width:calc((100% - 5px) * 0.5)\" data-alt=\"Alt SEO:  - Ảnh 9.\" title=\" - Ảnh 9.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/thumb_w/660/528068263637045248/2026/2/26/dsc09852-17720699676682024069289.jpg\" class=\"\" data-originalw=\"2560\" data-originalh=\"1707\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/dsc09852-17720699676682024069289.jpg\" data-row=\"0\" data-id=\"208747969956057088\" alt=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 8.\" title=\"Xếp hàng xuyên đêm mua vàng cầu may ngày vía Thần tài- Ảnh 8.\" data-is-alt-modified=\"true\" data-id-seo=\"image-8\"></figure><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Nhiều người dân lựa chọn mua vàng bản vị nhỏ dịp vía Thần tài năm nay</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: NGUYỄN THANH</p><p data-id-seo=\"paragraphs-25\">Thay vì mua số lượng lớn, khách hàng ưu tiên các bản vị nhỏ như Tiểu Kim Cát 0,1 chỉ và Kim Gia Bảo 1 chỉ. Điều này cho thấy vàng đã trở thành sản phẩm tích lũy quốc dân, phù hợp với mọi túi tiền từ gen Z đến các gia đình trẻ. </p><p data-id-seo=\"paragraphs-26\">Cạnh đó, khách hàng không chỉ mua vàng miếng thô cứng mà tìm kiếm những sản phẩm có tính thẩm mỹ và phong thủy cao. Họ mua để “rước vía” an yên cho cả 4 mùa trong năm.</p><p data-id-seo=\"paragraphs-27\">Theo đại diện Công ty cổ phần kim loại quý Ancarat Việt Nam, dịp vía Thần tài năm nay diễn ra trong bối cảnh thị trường kim loại quý, đặc biệt là vàng và bạc, giá cả biến động mạnh, nhu cầu tăng cao. Doanh nghiệp liên tục phải tăng ca sản xuất, song lượng hàng giao ngay không quá nhiều. </p><p data-id-seo=\"paragraphs-28\">Ancarat khuyến cáo khách hàng tìm hiểu thông tin thị trường kỹ, đầu tư tiết kiệm hoặc tích lũy chứ không chạy theo đám đông đầu cơ tích trữ đẩy giá vô lý.</p>\n\n                                    \n\n\n                                    \n        \n\n        \n        \n                                        \n                                    \n\n                                    \n                                ', 'https://images2.thanhnien.vn/zoom/600_315/528068263637045248/2026/2/26/29f76ae8-16ae-4166-aa27-4bc34dd9ac8f-1772069454400217520316-16-0-535-830-crop-1772070333644510648629.jpg', NULL, NULL, NULL, 'https://thanhnien.vn/xep-hang-xuyen-dem-mua-vang-cau-may-ngay-via-than-tai-185260226084732075.htm', NULL, '2026-02-26 09:58:00', '0', '0', '0', '0.15', '{\"sentiment\":\"neutral\",\"classification_method\":\"keyword_fallback\",\"keyword_scores\":{\"Th\\u1ebf Gi\\u1edbi\":3,\"Kinh Doanh\":3,\"\\u0110\\u1eddi S\\u1ed1ng\":1},\"ai_provider\":\"none\"}', NULL, '2026-02-26 03:11:00', '2026-02-26 03:11:00'),
('186', '2', '3', 'Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài', 'day-tu-to-mo-sang-san-tuong-ngua-bang-vang-trong-ngay-via-than-tai', '\n                                    \n\n                                                                                                                \n                                    Theo ghi nhậ...', '\n                                    \n\n                                                                                                                \n                                    <figure class=\"VCSortableInPreviewMode alignCenterOverflow\" type=\"Photo\" data-style=\"align-center-overflow\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-22-17720701605071373733199.jpg\" id=\"img_208748335492792320\" w=\"2560\" h=\"1707\" alt=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 1.\" title=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 1.\" rel=\"lightbox\" photoid=\"208748335492792320\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-22-17720701605071373733199.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" data-id-seo=\"image-0\" data-is-alt-modified=\"true\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Theo ghi nhận của <i>Thanh Niên</i>, từ 5 giờ sáng, dù thời tiết Hà Nội mưa phùn và lạnh nhưng nhiều khách hàng đã có mặt tại cơ sở kinh doanh vàng bạc đá quý trên đường Cầu Giấy (P.Cầu Giấy, Hà Nội) đợi tới lượt mua vàng</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: TUẤN MINH</p></figure><figure class=\"media-item\" data-originalw=\"2560\" data-originalh=\"1707\" style=\"width:calc((100% - 0px) * 1)\" data-alt=\"Alt SEO: Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 2.\" title=\"Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 2.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-17720701610251088810879.jpg\" class=\"\" data-originalw=\"2560\" data-originalh=\"1707\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-17720701610251088810879.jpg\" data-row=\"0\" data-id=\"208748336893353984\" alt=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 2.\" title=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 2.\" data-id-seo=\"image-1\" data-is-alt-modified=\"true\"></figure><figure class=\"media-item\" data-originalw=\"2560\" data-originalh=\"1707\" style=\"width:calc((100% - 5px) * 0.4998535013184881)\" data-alt=\"Alt SEO: Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 3.\" title=\"Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 3.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-2-17720701610101867512955.jpg\" class=\"\" data-originalw=\"2560\" data-originalh=\"1707\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-2-17720701610101867512955.jpg\" data-row=\"1\" data-id=\"208748340935954432\" alt=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 3.\" title=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 3.\" data-id-seo=\"image-2\" data-is-alt-modified=\"true\"></figure><figure class=\"media-item\" data-originalw=\"2560\" data-originalh=\"1706\" style=\"width:calc((100% - 5px) * 0.5001464986815118)\" data-alt=\"Alt SEO: Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 4.\" title=\"Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 4.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-24-1772070160433144627168.jpg\" class=\"\" data-originalw=\"2560\" data-originalh=\"1706\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-24-1772070160433144627168.jpg\" data-row=\"1\" data-id=\"208748334593114112\" alt=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 4.\" title=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 4.\" data-id-seo=\"image-3\" data-is-alt-modified=\"true\"></figure><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\"> Để hỗ trợ giao dịch thuận tiện hơn, năm nay, cơ sở kinh doanh này đã cho lắp đặt hệ thống máy mua bán vàng tự động dành cho khách hàng có nhu cầu mua vàng nhẫn</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: TUẤN MINH</p><figure class=\"VCSortableInPreviewMode alignCenterOverflow\" type=\"Photo\" data-style=\"align-center-overflow\" style=\"\"><img loading=\"lazy\" data-author=\"\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-3-17720701609912039548210.jpg\" id=\"img_208748336098533376\" w=\"2560\" h=\"1707\" alt=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 5.\" title=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 5.\" rel=\"lightbox\" photoid=\"208748336098533376\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-3-17720701609912039548210.jpg\" type=\"photo\" style=\"max-width:100%;\" width=\"2560\" height=\"1707\" data-id-seo=\"image-4\" data-is-alt-modified=\"true\"><figcaption class=\"PhotoCMS_Caption\"><p data-placeholder=\"Nhập chú thích ảnh\" class=\"NLPlaceholderShow\">Anh Đào Công Đức (31 tuổi, P.Từ Liêm) là người đầu tiên xếp hàng mua vàng ở cơ sở này. \"Năm nào cũng vậy, tôi có mặt ở đây từ 2 giờ sáng. Tôi dự định sẽ mua 2 chỉ vàng để lấy vía trong ngày Thần tài\", anh Đức chia sẻ</p></figcaption><p data-placeholder=\"Nhập tác giả\" class=\"NLPlaceholderShow\">ẢNH: TUẤN MINH</p></figure><figure class=\"media-item\" data-originalw=\"2560\" data-originalh=\"1706\" style=\"width:calc((100% - 0px) * 1)\" data-alt=\"Alt SEO: Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 6.\" title=\"Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 6.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-7-1772070160904878098231.jpg\" class=\"\" data-originalw=\"2560\" data-originalh=\"1706\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-7-1772070160904878098231.jpg\" data-row=\"0\" data-id=\"208748336538226688\" alt=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 6.\" title=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 6.\" data-id-seo=\"image-5\" data-is-alt-modified=\"true\"></figure><figure class=\"media-item\" data-originalw=\"2560\" data-originalh=\"1707\" style=\"width:calc((100% - 5px) * 0.5)\" data-alt=\"Alt SEO: Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 7.\" title=\"Dậy từ sáng sớm săn tượng ngựa vàng ngày vía Thần tài 2026 - Ảnh 7.\" data-is-must-clean-attr=\"true\"><img loading=\"lazy\" src=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-29-17720701602901201712225.jpg\" class=\"\" data-originalw=\"2560\" data-originalh=\"1707\" data-original=\"https://images2.thanhnien.vn/528068263637045248/2026/2/26/via-than-tai-26022026-29-17720701602901201712225.jpg\" data-row=\"1\" data-id=\"208748336930574336\" alt=\"Dậy từ tờ mờ sáng \'săn\' tượng ngựa bằng vàng trong ngày vía Thần tài- Ảnh 7.\" title=\"Dậy từ tờ mờ sáng \'săn\' tư